// WS-0 (TASK_16 wave 2): shared canvas context for the split SpaceCanvas modules. Owner: WS-A
// (others request a field). Moved verbatim from space-canvas.tsx: constants, box types, the pure hit-test,
// the client->canvas point mapper. CanvasCtx = props + state + derived + snap; CanvasHandlers = gestures.
// Module map (owner in wave 2):
//   use-canvas-state.ts, use-canvas-model.ts, canvas-ctx.ts ............ WS-A
//   canvas-parts.tsx (ports, title editor, clamped toolbar, glide) ...... none
//   gestures/use-wheel-pan.ts (wheel + startPan/marquee/tool draws) ...... WS-A
//   gestures/use-snap-gesture.ts ........................................ none (WS-B reads)
//   gestures/use-arrow-gestures.ts, gestures/use-dock-drag.ts ........... none
//   gestures/use-tile-gestures.ts ....................................... WS-A (move helper for nudge)
//   gestures/use-sticky-gestures.ts ..................................... WS-C
//   keyboard/use-canvas-keys.ts, selection/use-selection-actions.ts ..... WS-A
//   selection/use-clipboard.ts .......................................... WS-E
//   layers/ArrowLayer.tsx, ArrowLabelLayer.tsx, StickyLayer.tsx ......... WS-C
//   layers/TileLayer.tsx, TileHeader.tsx, DrawPreview.tsx ............... none
//   overlays/MultiSelectBar.tsx ......................................... WS-B
//   overlays/ItemInspector.tsx, overlays/ContextMenus.tsx ............... WS-E
//   overlays/Dock.tsx, overlays/DockGhost.tsx ........................... none
//   overlays/HistoryZoomControls.tsx .................................... WS-A
import { toCanvas, type Point, type View } from '../core/space'
import type { SpaceCanvas } from '../space-canvas'
import type { ArrowGestures } from './gestures/use-arrow-gestures'
import type { DockDrag } from './gestures/use-dock-drag'
import type { NodeGestures } from './gestures/use-node-gestures'
import type { CanvasSnap } from './gestures/use-snap-gesture'
import type { StickyGestures } from './gestures/use-sticky-gestures'
import type { TileGestures } from './gestures/use-tile-gestures'
import type { useStartPan } from './gestures/use-wheel-pan'
import type { SelectionActions } from './selection/use-selection-actions'
import type { CanvasModel } from './use-canvas-model'
import type { CanvasState } from './use-canvas-state'

export const GLIDE_MS = 400
export const DEFAULT_ARROW_STROKE = '#38bdf8'
export const SNAP_MARGIN = 26
export const PAN_SPEED_MULTIPLIER = 1.25
export type Box = { left: number; top: number; spaceKey: string }
export type BoxRect = { x: number; y: number; w: number; h: number }

/** Pure geometric hit-test in canvas coordinates with a magnetic snap margin. */
export function findBoxAtPoint(
  pt: Point,
  boxMap: ReadonlyMap<string, BoxRect>,
  excludeId?: string,
  margin = SNAP_MARGIN
): string | undefined {
  let bestInsideId: string | undefined
  let bestInsideArea = Number.POSITIVE_INFINITY
  let bestSnapId: string | undefined
  let bestSnapDist = Number.POSITIVE_INFINITY

  for (const [id, box] of boxMap.entries()) {
    if (id === excludeId) {
      continue
    }
    const insideX = pt.x >= box.x && pt.x <= box.x + box.w
    const insideY = pt.y >= box.y && pt.y <= box.y + box.h
    if (insideX && insideY) {
      const area = box.w * box.h
      if (area < bestInsideArea) {
        bestInsideArea = area
        bestInsideId = id
      }
      continue
    }
    const clampedX = Math.max(box.x, Math.min(box.x + box.w, pt.x))
    const clampedY = Math.max(box.y, Math.min(box.y + box.h, pt.y))
    const dist = Math.hypot(pt.x - clampedX, pt.y - clampedY)
    if (dist <= margin && dist < bestSnapDist) {
      bestSnapDist = dist
      bestSnapId = id
    }
  }
  return bestInsideId ?? bestSnapId
}

/** Canvas point under a client (screen) point; same closure as before, built once per render. */
export function makeClientToCanvasPoint(
  rootRef: React.RefObject<HTMLDivElement | null>,
  view: View
): (clientX: number, clientY: number) => Point {
  const clientToCanvasPoint = (clientX: number, clientY: number): Point => {
    const rect = rootRef.current?.getBoundingClientRect()
    if (!rect) {
      return { x: 160, y: 120 }
    }
    return toCanvas({ x: clientX - rect.left, y: clientY - rect.top }, view)
  }
  return clientToCanvasPoint
}

/** Everything the split canvas modules read: SpaceCanvas props (defaults applied), local state + refs,
 *  derived data, the snap gesture and the point mapper. Built with useMemo in SpaceCanvas, passed as an
 *  argument (no React context). */
type SpaceCanvasProps = React.ComponentProps<typeof SpaceCanvas>
/** Props with SpaceCanvas's destructuring defaults applied (those are always set inside). */
type DefaultedProp =
  | 'inspectedAgentId'
  | 'toolMode'
  | 'selectedModelId'
  | 'askModelOnDrop'
  | 'canUndo'
  | 'canRedo'
  | 'pendingEditStickyId'
  | 'dark'
  | 'showProjectHeader'
export type CanvasProps = Omit<SpaceCanvasProps, DefaultedProp> &
  Required<Pick<SpaceCanvasProps, DefaultedProp>>
export type CanvasCtx = CanvasProps &
  CanvasState &
  CanvasModel &
  CanvasSnap & {
    clientToCanvasPoint: (clientX: number, clientY: number) => Point
  }

/** The gesture starters and selection actions the layers and overlays call (one object per render). */
export type CanvasHandlers = SelectionActions &
  ArrowGestures &
  ReturnType<typeof useStartPan> &
  TileGestures &
  StickyGestures &
  NodeGestures &
  DockDrag

// WS-0 (TASK_16 wave 2): small canvas parts moved verbatim from space-canvas.tsx.
// Quick-connect ports, image-drop helpers, reduced-motion + glide hooks, title editor, clamped toolbar.

import React, { useEffect, useLayoutEffect, useRef, useState } from 'react'
import { isImeOwnedKeyboardEvent } from '../core/ime-guard'
import { BENCH_KEY, CARDINAL_PORTS, type View } from '../core/space'
import { GLIDE_MS, type Box, type BoxRect } from './canvas-ctx'

/** 4-side AFFiNE-style magnetic quick-connect port dots around Cards, Text, and Space tiles. */
export function QuickConnectPorts({
  visible,
  hoverClass,
  onStartArrow
}: {
  visible: boolean
  hoverClass: string
  onStartArrow: (event: React.PointerEvent) => void
}): React.JSX.Element {
  return (
    <>
      {CARDINAL_PORTS.map((port) => {
        const posClass =
          port.side === 'top'
            ? 'left-1/2 -top-2 -translate-x-1/2'
            : port.side === 'right'
              ? '-right-2 top-1/2 -translate-y-1/2'
              : port.side === 'bottom'
                ? 'left-1/2 -bottom-2 -translate-x-1/2'
                : '-left-2 top-1/2 -translate-y-1/2'
        return (
          // A drag grip (pointer only), like the resize corners: not a button, not a tab stop.
          // Keyboard users connect with the Connector tool (C).
          <span
            key={port.side}
            aria-hidden="true"
            data-quick-port={port.side}
            title={`Drag to connect arrow (${port.side})`}
            onPointerDown={onStartArrow}
            className={`pointer-events-auto absolute z-30 flex size-3.5 cursor-crosshair items-center justify-center rounded-full border border-sky-300 bg-zinc-950 shadow-md transition-all hover:scale-150 hover:bg-sky-400 ${posClass} ${
              visible ? 'opacity-95' : `opacity-0 ${hoverClass}`
            }`}
          >
            <span className="size-1.5 rounded-full bg-sky-400" />
          </span>
        )
      })}
    </>
  )
}

export function firstImageFile(transfer: DataTransfer | null): File | null {
  const file = transfer?.files?.[0]
  return file && file.type.startsWith('image/') ? file : null
}

/** During dragover the file list is hidden; the item kinds and MIME types are not. */
export function hasImageFile(transfer: DataTransfer | null): boolean {
  if (!transfer) {
    return false
  }
  return Array.from(transfer.items ?? []).some(
    (item) => item.kind === 'file' && item.type.startsWith('image/')
  )
}

export function usePrefersReducedMotion(): boolean {
  const [reduced, setReduced] = useState<boolean>(() =>
    typeof window === 'undefined'
      ? false
      : Boolean(window.matchMedia?.('(prefers-reduced-motion: reduce)').matches)
  )
  useEffect(() => {
    if (typeof window === 'undefined' || !window.matchMedia) {
      return
    }
    const query = window.matchMedia('(prefers-reduced-motion: reduce)')
    const sync = (): void => setReduced(query.matches)
    sync()
    query.addEventListener?.('change', sync)
    return () => query.removeEventListener?.('change', sync)
  }, [])
  return reduced
}

export function useGlide(
  rootRef: React.RefObject<HTMLDivElement | null>,
  placements: Record<string, string>
): void {
  const previousRef = useRef<Map<string, Box>>(new Map())
  useLayoutEffect(() => {
    const root = rootRef.current
    if (!root) {
      return
    }
    const reduced =
      typeof window !== 'undefined' &&
      window.matchMedia?.('(prefers-reduced-motion: reduce)').matches
    const next = new Map<string, Box>()
    for (const element of root.querySelectorAll<HTMLElement>('[data-space-card]')) {
      const id = element.dataset.spaceCard
      const spaceKey = element.dataset.spaceIn || BENCH_KEY
      if (!id) {
        continue
      }
      const rect = element.getBoundingClientRect()
      const previous = previousRef.current.get(id)
      next.set(id, { left: rect.left, top: rect.top, spaceKey })
      if (!reduced && previous && previous.spaceKey !== spaceKey && element.animate) {
        const dx = previous.left - rect.left
        const dy = previous.top - rect.top
        if (Math.abs(dx) > 2 || Math.abs(dy) > 2) {
          element.animate(
            [{ transform: `translate(${dx}px, ${dy}px)` }, { transform: 'translate(0, 0)' }],
            { duration: GLIDE_MS, easing: 'cubic-bezier(0.22, 1, 0.36, 1)' }
          )
        }
      }
    }
    previousRef.current = next
  }, [placements, rootRef])
}

export function TitleText({
  value,
  placeholder,
  fontSize = 16,
  isLightBg = false,
  onSave
}: {
  value: string
  placeholder: string
  fontSize?: number
  isLightBg?: boolean
  onSave: (value: string) => void
}): React.JSX.Element {
  const [editing, setEditing] = useState(false)
  const [draft, setDraft] = useState(value)

  useEffect(() => {
    if (!editing) {
      setDraft(value)
    }
  }, [editing, value])

  if (!editing) {
    return (
      <span
        data-title-edit="true"
        onDoubleClick={(event) => {
          event.stopPropagation()
          setDraft(value)
          setEditing(true)
        }}
        title="Double-click to rename Space"
        style={{ fontSize: `${fontSize}px`, lineHeight: 1.24 }}
        className={`min-w-0 flex-1 cursor-text line-clamp-2 break-words font-semibold tracking-tight ${
          isLightBg ? 'text-slate-900' : 'text-foreground'
        }`}
      >
        {value || (
          <span className={`font-normal ${isLightBg ? 'text-slate-500' : 'text-muted-foreground'}`}>
            {placeholder}
          </span>
        )}
      </span>
    )
  }

  const commit = (): void => {
    setEditing(false)
    const trimmed = draft.trim()
    if (trimmed !== value) {
      onSave(trimmed)
    }
  }

  return (
    <input
      autoFocus
      value={draft}
      placeholder={placeholder}
      onChange={(event) => setDraft(event.target.value)}
      onFocus={(event) => event.currentTarget.select()}
      onPointerDown={(event) => event.stopPropagation()}
      onClick={(event) => event.stopPropagation()}
      onBlur={commit}
      onKeyDown={(event) => {
        if (isImeOwnedKeyboardEvent(event)) {
          return
        }
        if (event.key === 'Enter') {
          commit()
        }
        if (event.key === 'Escape') {
          setEditing(false)
        }
      }}
      style={{ fontSize: `${fontSize}px` }}
      className="min-w-0 flex-1 rounded-lg border border-primary/50 bg-background px-2 py-0.5 font-semibold text-foreground outline-none"
    />
  )
}

export function ClampedFloatingToolbar({
  anchorRect,
  view,
  containerRef,
  children
}: {
  anchorRect: BoxRect
  view: View
  containerRef: React.RefObject<HTMLDivElement | null>
  children: React.ReactNode
}): React.JSX.Element {
  const wrapRef = useRef<HTMLDivElement | null>(null)
  const [size, setSize] = useState<{ w: number; h: number }>({ w: 540, h: 68 })

  useLayoutEffect(() => {
    const el = wrapRef.current
    if (!el) {
      return
    }
    const measure = (): void => {
      const w = el.offsetWidth
      const h = el.offsetHeight
      if (w > 0 && h > 0) {
        setSize((prev) => (prev.w === w && prev.h === h ? prev : { w, h }))
      }
    }
    measure()
    if (typeof ResizeObserver === 'undefined') {
      return
    }
    const ro = new ResizeObserver(measure)
    ro.observe(el)
    return () => ro.disconnect()
  }, [children])

  const rootW = containerRef.current?.clientWidth || 1184
  const rootH = containerRef.current?.clientHeight || 860
  const screenCenterX = anchorRect.x * view.scale + view.x + (anchorRect.w * view.scale) / 2
  const screenTop = anchorRect.y * view.scale + view.y
  const screenBottom = (anchorRect.y + anchorRect.h) * view.scale + view.y

  const halfW = size.w / 2
  const minLeft = Math.min(rootW / 2, 12 + halfW)
  const maxLeft = Math.max(minLeft, rootW - 12 - halfW)
  const clampedLeft = Math.round(Math.max(minLeft, Math.min(maxLeft, screenCenterX)))

  const placeBelow = screenTop < size.h + 24
  const clampedTop = placeBelow
    ? Math.round(Math.min(Math.max(24, rootH - size.h - 90), Math.max(12, screenBottom + 14)))
    : Math.round(Math.max(12 + size.h, screenTop - 14))

  return (
    <div
      ref={wrapRef}
      style={{
        left: clampedLeft,
        top: clampedTop,
        transform: placeBelow ? 'translate(-50%, 0)' : 'translate(-50%, -100%)'
      }}
      className="pointer-events-none absolute z-30 flex max-w-[calc(100%-24px)] justify-center"
    >
      {children}
    </div>
  )
}

// WS-E (TASK_16 wave 2): fill colour + opacity for the floating item inspector. Idea from G_app-Data's
// library ColorPicker / NumericInput (themselves from Penpot's ui/workspace/colorpicker/* and
// ds/controls/numeric_input.cljs); re-implemented here because Orca cannot import G_app-Data. The colour
// maths are the MPL port in shared/orca-plus/penpot-mpl/colors.ts (imported, not copied).
// A note's colour is one of the board's named colours (SpaceStickyNote.color), so a picked or typed
// colour snaps to the nearest named one. Opacity is SpaceStickyNote.opacity (0–1), shown as 0–100 %.
// No buttons (inputs only): the native colour well is the picker. No x / y / w / h fields.
import { useEffect, useState } from 'react'
import { isImeOwnedKeyboardEvent } from '../../core/ime-guard'
import { STICKY_COLOR_STYLE, STICKY_COLORS, type StickyColor } from '../../core/space'
import { hexToRgb, parse, rgbToHsv } from '../../penpot-mpl/colors'

export function stickyColorHex(color: StickyColor): string {
  return parse(STICKY_COLOR_STYLE[color]?.stroke) ?? '#fbbf24'
}

/** Nearest named colour to any colour text ("#f43f5e", "f00", "rgb(0,200,255)"); null if unreadable.
 *  Distance in RGB plus a hue term, so a dark or light variant still lands on its own hue. */
export function nearestStickyColor(input: string): StickyColor | null {
  const hex = parse(input)
  if (!hex) {
    return null
  }
  const rgb = hexToRgb(hex)
  const [h, s] = rgbToHsv(rgb)
  let best: StickyColor | null = null
  let bestD = Number.POSITIVE_INFINITY
  for (const c of STICKY_COLORS) {
    const crgb = hexToRgb(stickyColorHex(c))
    const [ch, cs] = rgbToHsv(crgb)
    const rgbD = Math.hypot(rgb[0] - crgb[0], rgb[1] - crgb[1], rgb[2] - crgb[2])
    const hueGap = Math.min(Math.abs(h - ch), 360 - Math.abs(h - ch))
    // Hue only counts when both colours have colour in them (greys have no hue).
    const hueD = s > 0.25 && cs > 0.25 ? hueGap * 1.5 : 0
    const d = rgbD + hueD
    if (d < bestD) {
      bestD = d
      best = c
    }
  }
  return best
}

/** Typed opacity percent ("40" or "40%") → 0–1, clamped and rounded to whole percents; null if not a number. */
export function parseOpacityPercent(text: string): number | null {
  const t = text.trim().replace(/%$/, '').trim()
  if (!/^-?\d+(\.\d+)?$/.test(t)) {
    return null
  }
  const n = Number(t)
  return Number.isFinite(n) ? Math.max(0, Math.min(100, Math.round(n))) / 100 : null
}

export const opacityPercent = (opacity: number | undefined): number =>
  Math.round((opacity ?? 1) * 100)

const stop = (event: React.SyntheticEvent): void => event.stopPropagation()

export function ColorField({
  color,
  opacity,
  onChangeColor,
  onChangeOpacity
}: {
  color: StickyColor
  opacity: number | undefined
  onChangeColor: (color: StickyColor) => void
  onChangeOpacity: (opacity: number) => void
}): React.JSX.Element {
  const hex = stickyColorHex(color)
  const [hexText, setHexText] = useState(hex)
  const [opText, setOpText] = useState(String(opacityPercent(opacity)))
  useEffect(() => setHexText(hex), [hex])
  useEffect(() => setOpText(String(opacityPercent(opacity))), [opacity])

  const commitHex = (text: string): void => {
    const next = nearestStickyColor(text)
    if (next && next !== color) {
      onChangeColor(next)
    } else {
      setHexText(hex)
    }
  }
  const commitOpacity = (value: number | null): void => {
    if (value === null) {
      setOpText(String(opacityPercent(opacity)))
      return
    }
    setOpText(String(Math.round(value * 100)))
    if (value !== (opacity ?? 1)) {
      onChangeOpacity(value)
    }
  }

  return (
    <div
      data-whiteboard-inspector="style"
      onPointerDown={stop}
      onDoubleClick={(event) => event.stopPropagation()}
      className="pointer-events-auto flex items-center gap-2 rounded-xl border border-white/15 bg-zinc-950/96 px-2.5 py-1 text-[11px] text-zinc-300 shadow-xl backdrop-blur-xl"
    >
      <label className="flex items-center gap-1.5">
        <span>Fill</span>
        <input
          type="color"
          aria-label="Fill colour"
          value={hex}
          onChange={(event) => {
            const next = nearestStickyColor(event.target.value)
            if (next && next !== color) {
              onChangeColor(next)
            }
          }}
          style={{ opacity: opacity ?? 1 }}
          className="size-5 cursor-pointer rounded border border-white/20 bg-transparent p-0"
        />
        <input
          type="text"
          aria-label="Fill colour hex"
          spellCheck={false}
          value={hexText}
          onChange={(event) => setHexText(event.target.value)}
          onBlur={(event) => commitHex(event.target.value)}
          onKeyDown={(event) => {
            if (isImeOwnedKeyboardEvent(event.nativeEvent)) {
              return
            }
            if (event.key === 'Enter') {
              commitHex(event.currentTarget.value)
            } else if (event.key === 'Escape') {
              setHexText(hex)
              event.currentTarget.blur()
            }
          }}
          className="w-[68px] rounded border border-white/15 bg-zinc-900 px-1 py-0.5 font-mono text-zinc-100 focus:border-sky-400 focus:outline-none"
        />
      </label>
      <label className="flex items-center gap-1.5">
        <span>Opacity</span>
        <input
          type="text"
          inputMode="numeric"
          role="spinbutton"
          aria-label="Opacity percent"
          aria-valuemin={0}
          aria-valuemax={100}
          aria-valuenow={opacityPercent(opacity)}
          value={opText}
          onChange={(event) => setOpText(event.target.value)}
          onBlur={(event) => commitOpacity(parseOpacityPercent(event.target.value))}
          onKeyDown={(event) => {
            if (isImeOwnedKeyboardEvent(event.nativeEvent)) {
              return
            }
            // NumericInput idea: ↑ / ↓ step 1, Shift = 10, Enter commits, Esc reverts.
            if (event.key === 'ArrowUp' || event.key === 'ArrowDown') {
              event.preventDefault()
              const base = parseOpacityPercent(event.currentTarget.value) ?? opacity ?? 1
              const step = (event.shiftKey ? 10 : 1) * (event.key === 'ArrowUp' ? 1 : -1)
              commitOpacity(Math.max(0, Math.min(100, Math.round(base * 100) + step)) / 100)
            } else if (event.key === 'Enter') {
              commitOpacity(parseOpacityPercent(event.currentTarget.value))
            } else if (event.key === 'Escape') {
              setOpText(String(opacityPercent(opacity)))
              event.currentTarget.blur()
            }
          }}
          className="w-[42px] rounded border border-white/15 bg-zinc-900 px-1 py-0.5 text-right tabular-nums text-zinc-100 focus:border-sky-400 focus:outline-none"
        />
        <span>%</span>
      </label>
    </div>
  )
}

// U-37 (UX review): where the bottom corner pills live, and what the centre dock and Fit leave free.
// Why: undo/redo + zoom sat on the right end of the whiteboard toolbar and cut its note / shape tools.
// One column in the bottom-right corner, with the dock told to stop before it.
export const CORNER_W = 148
export const CORNER_GAP = 12
/** Free space the dock keeps on EACH side so it stays centred and never meets a corner cluster. */
export const DOCK_SIDE_RESERVE = CORNER_W + CORNER_GAP * 2
export const dockMaxWidth = `calc(100% - ${DOCK_SIDE_RESERVE * 2}px)`

/** Screen px the canvas overlays cover, used by Fit so tiles are centred in what is left. */
export const FIT_TOP_INSET = 56 // Copilot chip + ask pill row
export const FIT_BOTTOM_INSET = 104 // whiteboard toolbar + its tooltip row
export const FIT_SIDE_INSET = 16

/** Below this canvas width the toolbar (about 560 px compact) and the corner column cannot sit side by side. */
export const SIDE_BY_SIDE_MIN_CANVAS = 560 + DOCK_SIDE_RESERVE * 2
/** Corner `bottom` when stacked: clear of the toolbar row (about 72 px) and its tooltip. */
export const CORNER_STACKED_BOTTOM = 92

/** Narrow canvas: the zoom / undo column goes ABOVE the toolbar's right end, the toolbar keeps the width. */
export function cornerStacked(canvasWidth: number): boolean {
  return canvasWidth > 0 && canvasWidth < SIDE_BY_SIDE_MIN_CANVAS
}
export function dockMaxWidthFor(canvasWidth: number): string {
  return cornerStacked(canvasWidth) ? `calc(100% - ${CORNER_GAP * 2}px)` : dockMaxWidth
}
export function cornerBottomFor(canvasWidth: number): number {
  return cornerStacked(canvasWidth) ? CORNER_STACKED_BOTTOM : CORNER_GAP
}

// WS-0 (TASK_16 wave 2): arrow draw, endpoint reconnect, bend handle and eraser swipe,
// moved verbatim from space-canvas.tsx. Owner: none.
import type { CanvasCtx } from '../canvas-ctx'
import { resolveArrowConnectionEffect } from '../../core/canvas-nodes'
import { type DragModifiers, NO_GUIDES, snapPointTo } from '../../core/whiteboard-snap-drag'
import {
  type Point,
  type SpaceArrow,
  computeSignedBendFromPoint,
  snapPointAngle15Deg
} from '../../core/space'
import type { SnapGuide } from '../../core/whiteboard-snap'
import { findBoxAtPoint } from '../canvas-ctx'

export function useArrowGestures(ctx: CanvasCtx) {
  const {
    activeArrowDash,
    activeArrowRouting,
    beginSnapGesture,
    boxMapRef,
    clientToCanvasPoint,
    endSnapGesture,
    host,
    nodesById,
    onAddArrow,
    onChangeToolMode,
    onDeleteArrow,
    onDeleteNode,
    onDeleteStickyNote,
    onNotify,
    onUpdateArrow,
    onUpdateNode,
    setArrowSnapTargetId,
    setBendingArrow,
    setDrawingArrow,
    setReconnectingArrow,
    setSelectedArrowId,
    setSelectedNodeIds,
    setSelectedStickyIds,
    showSnapGuides,
    snapIndexOf,
    stickiesById,
    toolMode,
    view
  } = ctx

  const applyMagneticArrowSemantics = (fromId?: string, toId?: string): void => {
    const effect = resolveArrowConnectionEffect(fromId, toId, nodesById)
    if (!effect) {
      return
    }
    if (effect.kind === 'bind-project') {
      onUpdateNode?.(effect.targetNodeId, { projectSlug: effect.projectSlug })
      host?.onBindProjectToNode?.(effect.targetNodeId, effect.projectSlug)
      onNotify?.(`Bound C02 project "${effect.projectSlug}" to ${effect.toNode.title}`)
    } else {
      host?.onConnectNodes?.(effect.fromId, effect.toId)
    }
  }
  const startArrowDrag = (
    event: React.PointerEvent,
    explicitFromId?: string,
    explicitFromPoint?: Point
  ): void => {
    if (event.button !== 0) {
      return
    }
    event.stopPropagation()
    const startPt = explicitFromPoint ?? clientToCanvasPoint(event.clientX, event.clientY)
    const detectedFromId = explicitFromId ?? findBoxAtPoint(startPt, boxMapRef.current)
    const fromBox = detectedFromId ? boxMapRef.current.get(detectedFromId) : undefined
    const angleOrigin = fromBox
      ? { x: fromBox.x + fromBox.w / 2, y: fromBox.y + fromBox.h / 2 }
      : startPt
    setDrawingArrow({
      ...(detectedFromId ? { fromId: detectedFromId } : {}),
      fromPoint: startPt,
      currentPoint: startPt
    })
    setArrowSnapTargetId(null)
    const snap = beginSnapGesture([])
    /** Free end: Shift = 15° angle snap; otherwise it snaps to box edges / centers (⌘ = off). */
    const freeEnd = (
      rawPt: Point,
      mods: DragModifiers
    ): Point & { guides: readonly SnapGuide[] } =>
      mods.shiftKey
        ? { ...snapPointAngle15Deg(angleOrigin, rawPt), guides: NO_GUIDES }
        : snapPointTo(rawPt, snapIndexOf(snap), view.scale, mods)

    const onMove = (move: PointerEvent): void => {
      const rawPt = clientToCanvasPoint(move.clientX, move.clientY)
      const snapId = findBoxAtPoint(rawPt, boxMapRef.current, detectedFromId)
      const free = snapId ? null : freeEnd(rawPt, move)
      const nextPt = free ? { x: free.x, y: free.y } : rawPt
      showSnapGuides(free?.guides ?? NO_GUIDES)
      setArrowSnapTargetId(snapId ?? null)
      setDrawingArrow((cur) => (cur ? { ...cur, toId: snapId, currentPoint: nextPt } : null))
    }
    const onUp = (up: PointerEvent): void => {
      window.removeEventListener('pointermove', onMove)
      window.removeEventListener('pointerup', onUp)
      const rawEnd = clientToCanvasPoint(up.clientX, up.clientY)
      const toId = findBoxAtPoint(rawEnd, boxMapRef.current, detectedFromId)
      const free = toId ? null : freeEnd(rawEnd, up)
      const endPt = free ? { x: free.x, y: free.y } : rawEnd
      endSnapGesture(snap)
      setArrowSnapTargetId(null)
      const styleExtras: Partial<SpaceArrow> = {
        routing: activeArrowRouting,
        ...(activeArrowDash === 'dashed' ? { dash: 'dashed' as const } : {})
      }
      if (toId && toId !== detectedFromId) {
        onAddArrow?.({
          ...(detectedFromId ? { fromId: detectedFromId } : { fromPoint: startPt }),
          toId,
          ...styleExtras
        })
        applyMagneticArrowSemantics(detectedFromId, toId)
      } else if (Math.hypot(endPt.x - startPt.x, endPt.y - startPt.y) > 20) {
        onAddArrow?.({
          ...(detectedFromId ? { fromId: detectedFromId } : { fromPoint: startPt }),
          toPoint: endPt,
          ...styleExtras
        })
      }
      setDrawingArrow(null)
      if (toolMode === 'arrow' && !up.shiftKey) {
        onChangeToolMode?.('select')
      }
    }
    window.addEventListener('pointermove', onMove)
    window.addEventListener('pointerup', onUp)
  }

  /** Click or swipe across unlocked whiteboard items and arrows in Eraser mode (`E`). */
  const startEraserSwipe = (event: React.PointerEvent): void => {
    if (event.button !== 0) {
      return
    }
    event.preventDefault()
    event.stopPropagation()
    const erasedIds = new Set<string>()
    const eraseAt = (clientX: number, clientY: number): void => {
      const stack = document.elementsFromPoint(clientX, clientY)
      for (const el of stack) {
        if (el.hasAttribute('data-space-dock')) {
          return
        }
        const stickyId = el.closest<HTMLElement>('[data-space-sticky]')?.dataset.spaceSticky
        if (stickyId && !erasedIds.has(stickyId)) {
          const item = stickiesById.get(stickyId)
          if (item && !item.locked) {
            erasedIds.add(stickyId)
            onDeleteStickyNote?.(stickyId)
            setSelectedStickyIds((cur) => cur.filter((id) => id !== stickyId))
          }
        }
        const nodeId = el.closest<HTMLElement>('[data-space-node]')?.dataset.spaceNode
        if (nodeId && !erasedIds.has(nodeId)) {
          const node = nodesById.get(nodeId)
          if (node && !node.locked) {
            erasedIds.add(nodeId)
            onDeleteNode?.(nodeId)
            setSelectedNodeIds((cur) => cur.filter((id) => id !== nodeId))
          }
        }
        const arrowId = el.closest<HTMLElement>('[data-space-arrow]')?.dataset.spaceArrow
        if (arrowId && !erasedIds.has(arrowId)) {
          erasedIds.add(arrowId)
          onDeleteArrow?.(arrowId)
          setSelectedArrowId((cur) => (cur === arrowId ? null : cur))
        }
      }
    }
    eraseAt(event.clientX, event.clientY)
    const onMove = (move: PointerEvent): void => {
      eraseAt(move.clientX, move.clientY)
    }
    const onUp = (): void => {
      window.removeEventListener('pointermove', onMove)
      window.removeEventListener('pointerup', onUp)
    }
    window.addEventListener('pointermove', onMove)
    window.addEventListener('pointerup', onUp)
  }

  /** Drag either endpoint ('from' or 'to') of an existing arrow to reconnect it to any Space, Note, Text, Shape, or point. */
  const startArrowEndpointDrag =
    (arrow: SpaceArrow, end: 'from' | 'to') =>
    (event: React.PointerEvent): void => {
      if (event.button !== 0) {
        return
      }
      event.preventDefault()
      event.stopPropagation()
      setSelectedArrowId(arrow.id)
      const startPt = clientToCanvasPoint(event.clientX, event.clientY)
      const otherEndId = end === 'from' ? arrow.toId : arrow.fromId
      const otherBox = otherEndId ? boxMapRef.current.get(otherEndId) : undefined
      const angleOrigin = otherBox
        ? { x: otherBox.x + otherBox.w / 2, y: otherBox.y + otherBox.h / 2 }
        : ((end === 'from' ? arrow.toPoint : arrow.fromPoint) ?? startPt)
      setReconnectingArrow({ arrowId: arrow.id, end, point: startPt })
      const snap = beginSnapGesture([])
      const freeEnd = (
        rawPt: Point,
        mods: DragModifiers
      ): Point & { guides: readonly SnapGuide[] } =>
        mods.shiftKey
          ? { ...snapPointAngle15Deg(angleOrigin, rawPt), guides: NO_GUIDES }
          : snapPointTo(rawPt, snapIndexOf(snap), view.scale, mods)

      const onMove = (move: PointerEvent): void => {
        const rawPt = clientToCanvasPoint(move.clientX, move.clientY)
        const snapId = findBoxAtPoint(rawPt, boxMapRef.current, otherEndId)
        const free = snapId ? null : freeEnd(rawPt, move)
        const nextPt = free ? { x: free.x, y: free.y } : rawPt
        showSnapGuides(free?.guides ?? NO_GUIDES)
        setArrowSnapTargetId(snapId ?? null)
        setReconnectingArrow({
          arrowId: arrow.id,
          end,
          point: nextPt,
          ...(snapId ? { snapId } : {})
        })
      }

      const onUp = (up: PointerEvent): void => {
        window.removeEventListener('pointermove', onMove)
        window.removeEventListener('pointerup', onUp)
        const rawEnd = clientToCanvasPoint(up.clientX, up.clientY)
        const snapId = findBoxAtPoint(rawEnd, boxMapRef.current, otherEndId)
        const free = snapId ? null : freeEnd(rawEnd, up)
        const endPt = free ? { x: free.x, y: free.y } : rawEnd
        endSnapGesture(snap)
        setArrowSnapTargetId(null)
        setReconnectingArrow(null)
        if (end === 'from') {
          onUpdateArrow?.(
            arrow.id,
            snapId
              ? { fromId: snapId, fromPoint: undefined }
              : {
                  fromId: undefined,
                  fromPoint: { x: Math.round(endPt.x), y: Math.round(endPt.y) }
                }
          )
          if (snapId && arrow.toId) {
            applyMagneticArrowSemantics(snapId, arrow.toId)
          }
        } else {
          onUpdateArrow?.(
            arrow.id,
            snapId
              ? { toId: snapId, toPoint: undefined }
              : {
                  toId: undefined,
                  toPoint: { x: Math.round(endPt.x), y: Math.round(endPt.y) }
                }
          )
          if (arrow.fromId && snapId) {
            applyMagneticArrowSemantics(arrow.fromId, snapId)
          }
        }
      }

      window.addEventListener('pointermove', onMove)
      window.addEventListener('pointerup', onUp)
    }

  /** Quickdraw midpoint bend handle: drag perpendicular to chord to bend any arrow smoothly. */
  const startArrowBendDrag =
    (arrow: SpaceArrow, start: Point, end: Point) =>
    (event: React.PointerEvent): void => {
      if (event.button !== 0) {
        return
      }
      event.preventDefault()
      event.stopPropagation()
      setSelectedArrowId(arrow.id)
      let latestBend = arrow.bend ?? 0
      setBendingArrow({ arrowId: arrow.id, bend: latestBend })

      const onMove = (move: PointerEvent): void => {
        const pt = clientToCanvasPoint(move.clientX, move.clientY)
        latestBend = computeSignedBendFromPoint(start, end, pt, 8 / Math.max(0.25, view.scale))
        setBendingArrow({ arrowId: arrow.id, bend: latestBend })
      }

      const onUp = (): void => {
        window.removeEventListener('pointermove', onMove)
        window.removeEventListener('pointerup', onUp)
        setBendingArrow(null)
        onUpdateArrow?.(arrow.id, { bend: latestBend === 0 ? undefined : latestBend })
      }

      window.addEventListener('pointermove', onMove)
      window.addEventListener('pointerup', onUp)
    }
  return {
    startArrowDrag,
    startEraserSwipe,
    startArrowEndpointDrag,
    startArrowBendDrag
  }
}

export type ArrowGestures = ReturnType<typeof useArrowGestures>

// WS-0 (TASK_16 wave 2): drag an item out of the bottom dock and drop it on the canvas,
// moved verbatim from space-canvas.tsx. Owner: none.
import type { CanvasCtx } from '../canvas-ctx'
import {
  TOOLBAR_TEXT_PRESETS,
  type ToolbarDockDragOptions,
  type ToolbarDockItemKind
} from '../../whiteboard-toolbar'
import { toCanvas } from '../../core/space'
import { useCallback } from 'react'

export function useDockDrag(ctx: CanvasCtx) {
  const {
    activeFillStyle,
    activeShapeColor,
    activeShapeType,
    activeTextPreset,
    dockNoteColor,
    dockSpaceLevel,
    onAddStickyNote,
    onChangeToolMode,
    onCreateSpaceAt,
    rootRef,
    setActiveFillStyle,
    setActiveShapeColor,
    setActiveShapeType,
    setActiveTextPreset,
    setDockDrag,
    setDockNoteColor,
    setDockSpaceLevel,
    setEditingStickyId,
    setSelectedArrowId,
    setSelectedStickyIds,
    view
  } = ctx
  /** Tactile bottom-dock drag-and-drop for Space frames, Sticky Notes, Geometric Shapes, and Backed-Text Cards. */
  const handleStartDockItemDrag = useCallback(
    (
      kind: ToolbarDockItemKind,
      event: React.PointerEvent,
      options: ToolbarDockDragOptions = {}
    ): void => {
      if (event.button !== 0) {
        return
      }
      const origin = { x: event.clientX, y: event.clientY }
      let dragged = false

      const cleanup = (): void => {
        window.removeEventListener('pointermove', onMove)
        window.removeEventListener('pointerup', onUp)
        window.removeEventListener('pointercancel', onCancel)
      }

      const onMove = (move: PointerEvent): void => {
        if (!dragged && Math.hypot(move.clientX - origin.x, move.clientY - origin.y) >= 4) {
          dragged = true
        }
        if (dragged) {
          setDockDrag({
            kind,
            options,
            clientX: move.clientX,
            clientY: move.clientY
          })
        }
      }

      const onUp = (up: PointerEvent): void => {
        cleanup()
        setDockDrag(null)
        if (!dragged) {
          return
        }
        const stack = document.elementsFromPoint(up.clientX, up.clientY)
        const overDock = stack.some((el) => el.hasAttribute('data-space-dock'))
        const overCanvas = stack.some((el) => el.hasAttribute('data-space-canvas'))
        if (!overCanvas || overDock) {
          return
        }
        const rect = rootRef.current?.getBoundingClientRect()
        const pt = rect
          ? toCanvas({ x: up.clientX - rect.left, y: up.clientY - rect.top }, view)
          : { x: 160, y: 120 }
        setSelectedArrowId(null)

        if (kind === 'space') {
          const lvl = options.spaceLevel ?? dockSpaceLevel
          setDockSpaceLevel(lvl)
          onCreateSpaceAt?.(lvl, {
            x: Math.round(pt.x - 170),
            y: Math.round(pt.y - 110),
            w: 340,
            h: 220
          })
        } else if (kind === 'note') {
          const color = options.color ?? dockNoteColor
          setDockNoteColor(color)
          const createdId = onAddStickyNote?.(
            { x: Math.round(pt.x - 110), y: Math.round(pt.y - 70) },
            color,
            'note',
            '',
            {
              fillStyle: options.fillStyle ?? 'soft',
              borderStyle: 'solid'
            }
          )
          if (typeof createdId === 'string') {
            setSelectedStickyIds([createdId])
            setEditingStickyId(createdId)
          }
        } else if (kind === 'shape') {
          const shapeType = options.shapeType ?? activeShapeType
          const color = options.color ?? activeShapeColor
          const fillStyle = options.fillStyle ?? activeFillStyle
          setActiveShapeType(shapeType)
          setActiveShapeColor(color)
          setActiveFillStyle(fillStyle)
          const isSym = shapeType === 'ellipse' || shapeType === 'diamond'
          const w = isSym ? 150 : 196
          const h = isSym ? 150 : 96
          const createdId = onAddStickyNote?.(
            { x: Math.round(pt.x - w / 2), y: Math.round(pt.y - h / 2) },
            color,
            'shape',
            '',
            {
              w,
              h,
              shapeType,
              fillStyle,
              borderStyle: options.borderStyle ?? 'solid',
              textAlign: 'center',
              fontSize: options.fontSize ?? 16
            }
          )
          if (typeof createdId === 'string') {
            setSelectedStickyIds([createdId])
            setEditingStickyId(createdId)
          }
        } else if (kind === 'text-card') {
          const preset =
            TOOLBAR_TEXT_PRESETS.find(
              (p) => p.id === (options.textCardPreset ?? activeTextPreset)
            ) ?? TOOLBAR_TEXT_PRESETS[0]!
          if (options.textCardPreset) {
            setActiveTextPreset(options.textCardPreset)
          }
          const fillStyle = options.fillStyle ?? preset.fillStyle
          const borderStyle = options.borderStyle ?? preset.borderStyle
          const color = options.color ?? preset.color
          const fontFamily = options.fontFamily ?? preset.fontFamily
          const fontSize = options.fontSize ?? preset.fontSize
          const bold = options.bold ?? preset.bold
          const createdId = onAddStickyNote?.(
            { x: Math.round(pt.x - 76), y: Math.round(pt.y - 26) },
            color,
            'text',
            '',
            {
              fillStyle,
              borderStyle,
              fontFamily,
              fontSize,
              fontWeight: bold ? 'bold' : 'normal',
              textAlign: 'left',
              autosize: true
            }
          )
          if (typeof createdId === 'string') {
            setSelectedStickyIds([createdId])
            setEditingStickyId(createdId)
          }
        }
        onChangeToolMode?.('select')
      }

      const onCancel = (): void => {
        cleanup()
        setDockDrag(null)
      }

      window.addEventListener('pointermove', onMove)
      window.addEventListener('pointerup', onUp)
      window.addEventListener('pointercancel', onCancel)
    },
    [
      activeFillStyle,
      activeShapeColor,
      activeShapeType,
      activeTextPreset,
      dockNoteColor,
      dockSpaceLevel,
      onAddStickyNote,
      onChangeToolMode,
      onCreateSpaceAt,
      rootRef,
      setActiveFillStyle,
      setActiveShapeColor,
      setActiveShapeType,
      setActiveTextPreset,
      setDockDrag,
      setDockNoteColor,
      setDockSpaceLevel,
      setEditingStickyId,
      setSelectedArrowId,
      setSelectedStickyIds,
      view
    ]
  )
  return {
    handleStartDockItemDrag
  }
}

export type DockDrag = ReturnType<typeof useDockDrag>

import { useCallback } from 'react'
import { clampCanvasNodeBox } from '../../core/canvas-nodes'
import { getCardinalPortPoints, type CardinalSide } from '../../core/whiteboard-kit'
import type { SnapKind } from '../../core/whiteboard-snap'
import {
  NO_GUIDES,
  snapMoveDelta,
  snapResizeDelta,
  unionRect
} from '../../core/whiteboard-snap-drag'
import {
  PENPOT_DRAG_THRESHOLD,
  passedDragThreshold,
  passedResizeThreshold
} from '../../penpot-mpl/drag-threshold'
import { resizeRect, type Handler } from '../../penpot-mpl/resize-handles'
import type { CanvasCtx } from '../canvas-ctx'
import type { ArrowGestures } from './use-arrow-gestures'

function handlerToSnapKind(handler: Handler): Exclude<SnapKind, 'move'> {
  switch (handler) {
    case 'top':
      return 'n'
    case 'bottom':
      return 's'
    case 'left':
      return 'w'
    case 'right':
      return 'e'
    case 'top-left':
      return 'nw'
    case 'top-right':
      return 'ne'
    case 'bottom-left':
      return 'sw'
    case 'bottom-right':
      return 'se'
  }
}

export function useNodeGestures(ctx: CanvasCtx, arrowGestures: ArrowGestures) {
  const {
    beginSnapGesture,
    boxMapRef,
    clientToCanvasPoint,
    effectiveSelectedNodeIds,
    endSnapGesture,
    nodesById,
    onDeleteNode,
    onUpdateNode,
    onWhiteboardTransaction,
    selectedNodeIdSet,
    setMultiNodeDragDelta,
    setNodeOffset,
    setNodeSizeOverride,
    setSelectedArrowId,
    setSelectedNodeIds,
    setSelectedStickyIds,
    showSnapGuides,
    snapIndexOf,
    spaceHeldRef,
    view
  } = ctx
  const { startArrowDrag } = arrowGestures

  const selectNode = useCallback(
    (nodeId: string, additive: boolean): void => {
      setSelectedArrowId(null)
      if (!additive) {
        setSelectedStickyIds([])
        setSelectedNodeIds([nodeId])
        return
      }
      setSelectedNodeIds((cur) =>
        cur.includes(nodeId) ? cur.filter((id) => id !== nodeId) : [...cur, nodeId]
      )
    },
    [setSelectedArrowId, setSelectedNodeIds, setSelectedStickyIds]
  )

  const startNodeDrag = useCallback(
    (nodeId: string, event: React.PointerEvent): void => {
      if (event.button !== 0 || spaceHeldRef.current) {
        return
      }
      const node = nodesById.get(nodeId)
      if (!node || node.locked) {
        return
      }
      const startCanvas = clientToCanvasPoint(event.clientX, event.clientY)
      const movingIds =
        selectedNodeIdSet.has(nodeId) && effectiveSelectedNodeIds.length > 1
          ? effectiveSelectedNodeIds.filter((id) => !nodesById.get(id)?.locked)
          : [nodeId]
      const initialBoxes = movingIds.flatMap((id) => {
        const b = boxMapRef.current.get(id)
        return b ? [{ id, ...b }] : []
      })
      const bounds = unionRect(initialBoxes) ?? { x: node.x, y: node.y, w: node.w, h: node.h }
      const snap = beginSnapGesture(movingIds)
      let started = false
      let endTxn: (() => void) | null = null
      let latestDelta = { x: 0, y: 0 }

      const onMove = (move: PointerEvent): void => {
        const curCanvas = clientToCanvasPoint(move.clientX, move.clientY)
        if (!started) {
          if (!passedDragThreshold(startCanvas, curCanvas, PENPOT_DRAG_THRESHOLD, view.scale)) {
            return
          }
          started = true
          endTxn = onWhiteboardTransaction ? onWhiteboardTransaction() : null
        }
        const rawDx = curCanvas.x - startCanvas.x
        const rawDy = curCanvas.y - startCanvas.y
        const snapped = snapMoveDelta(bounds, rawDx, rawDy, snapIndexOf(snap), view.scale, move)
        latestDelta = { x: Math.round(snapped.dx), y: Math.round(snapped.dy) }
        showSnapGuides(snapped.guides)
        if (movingIds.length > 1) {
          setMultiNodeDragDelta(latestDelta)
        } else {
          setNodeOffset({ id: nodeId, dx: latestDelta.x, dy: latestDelta.y })
        }
      }

      const onUp = (): void => {
        window.removeEventListener('pointermove', onMove)
        window.removeEventListener('pointerup', onUp)
        endSnapGesture(snap)
        showSnapGuides(NO_GUIDES)
        setNodeOffset(null)
        setMultiNodeDragDelta(null)
        if (started && (latestDelta.x !== 0 || latestDelta.y !== 0)) {
          for (const item of initialBoxes) {
            onUpdateNode?.(item.id, {
              x: Math.round(item.x + latestDelta.x),
              y: Math.round(item.y + latestDelta.y)
            })
          }
        }
        endTxn?.()
      }

      window.addEventListener('pointermove', onMove)
      window.addEventListener('pointerup', onUp)
    },
    [
      beginSnapGesture,
      boxMapRef,
      clientToCanvasPoint,
      effectiveSelectedNodeIds,
      endSnapGesture,
      nodesById,
      onUpdateNode,
      onWhiteboardTransaction,
      selectedNodeIdSet,
      setMultiNodeDragDelta,
      setNodeOffset,
      showSnapGuides,
      snapIndexOf,
      spaceHeldRef,
      view.scale
    ]
  )

  const startNodeResize = useCallback(
    (nodeId: string, handle: Handler, event: React.PointerEvent): void => {
      if (event.button !== 0) {
        return
      }
      const node = nodesById.get(nodeId)
      if (!node || node.locked) {
        return
      }
      const origin = { x: node.x, y: node.y, w: node.w, h: node.h }
      const penpotOrigin = { x: node.x, y: node.y, width: node.w, height: node.h }
      const startCanvas = clientToCanvasPoint(event.clientX, event.clientY)
      const snapKind = handlerToSnapKind(handle)
      const snap = beginSnapGesture([nodeId])
      let started = false
      let endTxn: (() => void) | null = null
      let latestBox = origin

      const onMove = (move: PointerEvent): void => {
        const curCanvas = clientToCanvasPoint(move.clientX, move.clientY)
        if (!started) {
          if (!passedResizeThreshold(startCanvas, curCanvas, view.scale)) {
            return
          }
          started = true
          endTxn = onWhiteboardTransaction ? onWhiteboardTransaction() : null
        }
        const rawDx = curCanvas.x - startCanvas.x
        const rawDy = curCanvas.y - startCanvas.y
        const computeCandidate = (dx: number, dy: number) => {
          const r = resizeRect(
            penpotOrigin,
            handle,
            startCanvas,
            { x: startCanvas.x + dx, y: startCanvas.y + dy },
            { lock: move.shiftKey, center: move.altKey }
          )
          return clampCanvasNodeBox({ x: r.x, y: r.y, w: r.width, h: r.height })
        }
        const snapped = snapResizeDelta(
          rawDx,
          rawDy,
          snapKind,
          computeCandidate,
          snapIndexOf(snap),
          view.scale,
          move
        )
        showSnapGuides(snapped.guides)
        latestBox = computeCandidate(snapped.dx, snapped.dy)
        setNodeSizeOverride({ id: nodeId, ...latestBox })
      }

      const onUp = (): void => {
        window.removeEventListener('pointermove', onMove)
        window.removeEventListener('pointerup', onUp)
        endSnapGesture(snap)
        showSnapGuides(NO_GUIDES)
        setNodeSizeOverride(null)
        if (started) {
          onUpdateNode?.(nodeId, latestBox)
        }
        endTxn?.()
      }

      window.addEventListener('pointermove', onMove)
      window.addEventListener('pointerup', onUp)
    },
    [
      beginSnapGesture,
      clientToCanvasPoint,
      endSnapGesture,
      nodesById,
      onUpdateNode,
      onWhiteboardTransaction,
      setNodeSizeOverride,
      showSnapGuides,
      snapIndexOf,
      view.scale
    ]
  )

  const startNodePortArrow = useCallback(
    (nodeId: string, side: CardinalSide, event: React.PointerEvent): void => {
      const box = boxMapRef.current.get(nodeId)
      const hit = box ? getCardinalPortPoints(box).find((p) => p.side === side) : undefined
      startArrowDrag(event, nodeId, hit ? { x: hit.x, y: hit.y } : undefined)
    },
    [boxMapRef, startArrowDrag]
  )

  const eraseNode = useCallback(
    (nodeId: string): void => {
      const node = nodesById.get(nodeId)
      if (!node || node.locked) {
        return
      }
      onDeleteNode?.(nodeId)
      setSelectedNodeIds((cur) => cur.filter((id) => id !== nodeId))
    },
    [nodesById, onDeleteNode, setSelectedNodeIds]
  )

  return {
    selectNode,
    startNodeDrag,
    startNodeResize,
    startNodePortArrow,
    eraseNode
  }
}

export type NodeGestures = ReturnType<typeof useNodeGestures>

// WS-0 (TASK_16 wave 2): smart-guide snap gesture + guides state, moved verbatim from space-canvas.tsx.
// Owner: none (WS-B reads it).
import { NO_GUIDES } from '../../core/whiteboard-snap-drag'
import {
  type SnapGuide,
  type SnapIndex,
  type SnapRect,
  createSnapIndex
} from '../../core/whiteboard-snap'
import { useCallback, useEffect, useRef, useState } from 'react'
import type { CanvasState } from '../use-canvas-state'
import type { CanvasModel } from '../use-canvas-model'

export function useSnapGesture({ rootRef, view }: CanvasState, { boxMapRef }: CanvasModel) {
  // Smart-guide snapping (TASK_16 WS2b): one index per drag gesture, guides drawn in screen space.
  const [snapGuides, setSnapGuides] = useState<readonly SnapGuide[]>(NO_GUIDES)
  const snapGestureRef = useRef<{ index: SnapIndex; off: boolean } | null>(null)
  const showSnapGuides = useCallback((guides: readonly SnapGuide[]): void => {
    setSnapGuides((cur) => (cur.length === 0 && guides.length === 0 ? cur : guides))
  }, [])
  /** Pointer down: every box except the moving ones, inside the visible viewport for gap search. */
  const beginSnapGesture = (exclude: Iterable<string>): { index: SnapIndex; off: boolean } => {
    const skip = new Set(exclude)
    const others: SnapRect[] = []
    for (const [id, box] of boxMapRef.current) {
      if (!skip.has(id)) {
        others.push(box)
      }
    }
    const rect = rootRef.current?.getBoundingClientRect()
    const scale = view.scale || 1
    const bounds =
      rect && rect.width > 0 && rect.height > 0
        ? { x: -view.x / scale, y: -view.y / scale, w: rect.width / scale, h: rect.height / scale }
        : undefined
    const gesture = { index: createSnapIndex(others, bounds ? { bounds } : {}), off: false }
    snapGestureRef.current = gesture
    return gesture
  }
  /** The index to snap against, or null once Escape / pointercancel turned this gesture's snap off. */
  const snapIndexOf = (gesture: { index: SnapIndex; off: boolean }): SnapIndex | null =>
    gesture.off ? null : gesture.index
  const endSnapGesture = (gesture: { index: SnapIndex; off: boolean }): void => {
    if (snapGestureRef.current === gesture) {
      snapGestureRef.current = null
    }
    showSnapGuides(NO_GUIDES)
  }
  useEffect(() => {
    const stop = (): void => {
      if (snapGestureRef.current) {
        snapGestureRef.current.off = true
        showSnapGuides(NO_GUIDES)
      }
    }
    const onKey = (event: KeyboardEvent): void => {
      if (event.key === 'Escape') {
        stop()
      }
    }
    window.addEventListener('keydown', onKey, true)
    window.addEventListener('pointercancel', stop)
    return () => {
      window.removeEventListener('keydown', onKey, true)
      window.removeEventListener('pointercancel', stop)
    }
  }, [showSnapGuides])
  return {
    snapGuides,
    setSnapGuides,
    snapGestureRef,
    showSnapGuides,
    beginSnapGesture,
    snapIndexOf,
    endSnapGesture
  }
}

export type CanvasSnap = ReturnType<typeof useSnapGesture>

// WS-0 (TASK_16 wave 2): note / shape / text drag (single, group, Alt-copy), resize / scale, and the
// textarea commit-on-blur, moved verbatim from space-canvas.tsx. Owner: WS-C.
// WS-C groups (idea from Penpot's data/workspace/selection.cljs, re-implemented): a click on a group
// member selects and drags the whole group; ⌘/Ctrl-click or a double-click selects only that member.
import type { CanvasCtx } from '../canvas-ctx'
import type { ArrowGestures } from './use-arrow-gestures'
import {
  NO_GUIDES,
  snapMoveDelta,
  snapResizeDelta,
  unionRect
} from '../../core/whiteboard-snap-drag'
import { type SpaceStickyNote, computeAutoTextDimensions } from '../../core/space'
import { groupSelectionFor, remapCopiedGroups } from '../../core/whiteboard-groups'

export function useStickyGestures(ctx: CanvasCtx, arrowGestures: ArrowGestures) {
  const {
    beginSnapGesture,
    boxMapRef,
    editingStickyId,
    effectiveSelectedIds,
    endSnapGesture,
    onBatchDuplicateStickyNotes,
    onBatchUpdateStickyNotes,
    onDeleteStickyNote,
    onDuplicateStickyNote,
    onUpdateStickyNote,
    selectedStickyIdSet,
    setEditingStickyId,
    setSelectedArrowId,
    setSelectedStickyIds,
    setStickyOffset,
    setStickySizeOverride,
    showSnapGuides,
    singleSelectedStickyId,
    snapIndexOf,
    spaceHeldRef,
    stickies,
    stickiesById,
    toolMode,
    view
  } = ctx
  const { startArrowDrag, startEraserSwipe } = arrowGestures
  const commitStickyEdit = (sticky: SpaceStickyNote): void => {
    setEditingStickyId((cur) => (cur === sticky.id ? null : cur))
    // Empty shapes, sticky notes, and backed text cards stay intact; only transparent headings evaporate if left blank
    const hasBg = Boolean(sticky.fillStyle && sticky.fillStyle !== 'none')
    if (sticky.kind === 'text' && !hasBg && !sticky.text.trim()) {
      onDeleteStickyNote?.(sticky.id)
      setSelectedStickyIds((cur) => cur.filter((id) => id !== sticky.id))
    }
  }

  const handleStickyTextareaBlur = (
    sticky: SpaceStickyNote,
    event: React.FocusEvent<HTMLTextAreaElement>
  ): void => {
    const next = event.relatedTarget as HTMLElement | null
    if (
      next &&
      next.closest('[data-whiteboard-inspector], [data-space-dock], [data-whiteboard-multiselect]')
    ) {
      event.currentTarget.focus()
      return
    }
    commitStickyEdit(sticky)
  }

  /** Drag anywhere on a Shape, Sticky Note, or Canvas Text block to move single or multi-selected items. */
  const startStickyDrag =
    (sticky: SpaceStickyNote) =>
    (event: React.PointerEvent): void => {
      if (event.button !== 0 || spaceHeldRef.current) {
        return
      }
      const target = event.target as HTMLElement
      if (target.closest('button, input, [data-sticky-resize], [data-quick-port]')) {
        return
      }
      if (editingStickyId === sticky.id && target.closest('textarea')) {
        return
      }
      if (toolMode === 'eraser') {
        startEraserSwipe(event)
        return
      }
      if (toolMode === 'arrow') {
        startArrowDrag(event, sticky.id)
        return
      }
      event.stopPropagation()
      setSelectedArrowId(null)

      if (sticky.locked) {
        setSelectedStickyIds([sticky.id])
        setEditingStickyId(null)
        return
      }

      const deepSelect = event.metaKey || event.ctrlKey
      if (event.shiftKey && !event.altKey) {
        setEditingStickyId(null)
        // WS-C: Shift toggles the whole group (just [sticky.id] when it has none, or with ⌘/Ctrl).
        const toggled = new Set(deepSelect ? [sticky.id] : groupSelectionFor(stickies, sticky.id))
        if (selectedStickyIdSet.has(sticky.id)) {
          setSelectedStickyIds(effectiveSelectedIds.filter((id) => !toggled.has(id)))
        } else {
          setSelectedStickyIds([
            ...effectiveSelectedIds,
            ...[...toggled].filter((id) => !selectedStickyIdSet.has(id))
          ])
        }
        return
      }

      // Group Multi-Drag when dragging an item inside an active multi-selection
      if (selectedStickyIdSet.has(sticky.id) && effectiveSelectedIds.length >= 2) {
        startMultiDrag(event, effectiveSelectedIds)
        return
      }

      // WS-C: a member of a group (2+ visible members) picks up the whole group, unless ⌘/Ctrl is held.
      const groupMembers = deepSelect ? [sticky.id] : groupSelectionFor(stickies, sticky.id)
      if (groupMembers.length >= 2) {
        setSelectedStickyIds(groupMembers)
        startMultiDrag(event, groupMembers)
        return
      }

      startSingleDrag(event, sticky)
    }

  /** Moves every unlocked id in `selection` as one box (Alt = copy first). One batch write on release. */
  const startMultiDrag = (event: React.PointerEvent, selection: readonly string[]): void => {
    setEditingStickyId(null)
    const sourceIds = selection.filter((id) => !stickiesById.get(id)?.locked)
    if (sourceIds.length === 0) {
      return
    }
    const sourcePositions = sourceIds.map((id) => {
      const item = stickiesById.get(id)
      return { x: item?.x ?? 0, y: item?.y ?? 0 }
    })
    let movingIds = sourceIds
    // WS-C: an Alt copy of a group is a NEW group (the board's copy keeps the source groupId).
    let copyGroupIds: (string | undefined)[] = []
    if (event.altKey && onBatchDuplicateStickyNotes && sourceIds.length >= 2) {
      const clonedIds = onBatchDuplicateStickyNotes(sourceIds, { x: 0, y: 0 })
      if (Array.isArray(clonedIds) && clonedIds.length === sourceIds.length) {
        movingIds = clonedIds
        setSelectedStickyIds(clonedIds)
        copyGroupIds = remapCopiedGroups(
          sourceIds.map((id) => ({ groupId: stickiesById.get(id)?.groupId }))
        ).map((c) => c.groupId)
      }
    }
    const origin = { x: event.clientX, y: event.clientY }
    // The selection moves as one box (an Alt copy starts exactly on the originals).
    const groupBox = unionRect(
      sourceIds.flatMap((id) => {
        const b = boxMapRef.current.get(id)
        return b ? [b] : []
      })
    )
    // Alt-copy: the originals stay put and are fair targets (the copy can line up with them).
    const snap = beginSnapGesture(movingIds === sourceIds ? sourceIds : movingIds)
    let delta = { x: 0, y: 0 }
    let guides = NO_GUIDES
    let rafId = 0
    const onMove = (move: PointerEvent): void => {
      const rawDx = (move.clientX - origin.x) / view.scale
      const rawDy = (move.clientY - origin.y) / view.scale
      const snapped = groupBox
        ? snapMoveDelta(groupBox, rawDx, rawDy, snapIndexOf(snap), view.scale, move)
        : snapMoveDelta({ x: 0, y: 0, w: 0, h: 0 }, rawDx, rawDy, null, view.scale, move)
      delta = { x: snapped.dx, y: snapped.dy }
      guides = snapped.guides
      if (rafId !== 0) {
        return
      }
      rafId = window.requestAnimationFrame(() => {
        rafId = 0
        showSnapGuides(snapIndexOf(snap) ? guides : NO_GUIDES)
        setStickyOffset((current) => {
          const next = { ...current }
          for (const id of movingIds) {
            next[id] = delta
          }
          return next
        })
      })
    }
    const onUp = (): void => {
      if (rafId !== 0) {
        window.cancelAnimationFrame(rafId)
        rafId = 0
      }
      window.removeEventListener('pointermove', onMove)
      window.removeEventListener('pointerup', onUp)
      endSnapGesture(snap)
      setStickyOffset((current) => {
        const next = { ...current }
        for (const id of movingIds) {
          delete next[id]
        }
        return next
      })
      const moved = Math.hypot(delta.x, delta.y) > 3
      const regroup = copyGroupIds.some(Boolean)
      if (moved || regroup) {
        const patches: Record<string, Partial<SpaceStickyNote>> = {}
        movingIds.forEach((id, idx) => {
          const base = sourcePositions[idx]
          if (!base) {
            return
          }
          patches[id] = {
            ...(moved ? { x: Math.round(base.x + delta.x), y: Math.round(base.y + delta.y) } : {}),
            ...(copyGroupIds[idx] ? { groupId: copyGroupIds[idx] } : {})
          }
        })
        onBatchUpdateStickyNotes?.(patches)
      }
    }
    window.addEventListener('pointermove', onMove)
    window.addEventListener('pointerup', onUp)
  }

  /** Moves one sticky (Alt = copy first); a click with no move on the selected sticky starts editing. */
  const startSingleDrag = (event: React.PointerEvent, sticky: SpaceStickyNote): void => {
    const wasAlreadySingleSelected =
      singleSelectedStickyId === sticky.id && editingStickyId !== sticky.id
    let activeId = sticky.id
    const baseX = sticky.x
    const baseY = sticky.y
    let cloned = false

    if (event.altKey && onDuplicateStickyNote) {
      const clonedId = onDuplicateStickyNote(sticky.id, { x: 0, y: 0 })
      if (typeof clonedId === 'string') {
        activeId = clonedId
        cloned = true
      }
    }

    setSelectedStickyIds([activeId])
    const origin = { x: event.clientX, y: event.clientY }
    const liveBox = boxMapRef.current.get(sticky.id)
    const startBox = { x: baseX, y: baseY, w: liveBox?.w ?? 0, h: liveBox?.h ?? 0 }
    // Alt-copy: the original stays put and is a fair target; only the moving copy is left out.
    const snap = beginSnapGesture(cloned ? [activeId] : [sticky.id])
    let delta = { x: 0, y: 0 }
    let guides = NO_GUIDES
    let rafId = 0
    const onMove = (move: PointerEvent): void => {
      const rawDx = (move.clientX - origin.x) / view.scale
      const rawDy = (move.clientY - origin.y) / view.scale
      const snapped = snapMoveDelta(startBox, rawDx, rawDy, snapIndexOf(snap), view.scale, move)
      delta = { x: snapped.dx, y: snapped.dy }
      guides = snapped.guides
      if (rafId !== 0) {
        return
      }
      rafId = window.requestAnimationFrame(() => {
        rafId = 0
        showSnapGuides(snapIndexOf(snap) ? guides : NO_GUIDES)
        setStickyOffset((current) => ({ ...current, [activeId]: delta }))
      })
    }
    const onUp = (): void => {
      if (rafId !== 0) {
        window.cancelAnimationFrame(rafId)
        rafId = 0
      }
      window.removeEventListener('pointermove', onMove)
      window.removeEventListener('pointerup', onUp)
      endSnapGesture(snap)
      setStickyOffset((current) => {
        const next = { ...current }
        delete next[activeId]
        return next
      })
      if (Math.hypot(delta.x, delta.y) > 3) {
        onUpdateStickyNote?.(activeId, {
          x: Math.round(baseX + delta.x),
          y: Math.round(baseY + delta.y)
        })
      } else if (!cloned && wasAlreadySingleSelected) {
        setEditingStickyId(activeId)
      }
    }
    window.addEventListener('pointermove', onMove)
    window.addEventListener('pointerup', onUp)
  }

  /** Smooth multi-mode resize/scale handle for Shapes, Sticky Notes, and Canvas Text. */
  const startStickyResize =
    (sticky: SpaceStickyNote, mode: 'scale' | 'width' | 'se' | 'e' | 's' = 'se') =>
    (event: React.PointerEvent): void => {
      if (event.button !== 0 || sticky.locked) {
        return
      }
      event.preventDefault()
      event.stopPropagation()
      setSelectedStickyIds([sticky.id])
      const kind = sticky.kind ?? 'note'
      const isText = kind === 'text'
      const isShape = kind === 'shape'
      const hasBg = Boolean(sticky.fillStyle && sticky.fillStyle !== 'none')
      const manualWidthResize = isText && (mode === 'width' || mode === 'e')
      const origin = { x: event.clientX, y: event.clientY }
      const liveBox = boxMapRef.current.get(sticky.id)
      const startW = liveBox?.w ?? (sticky.w || (isText ? 240 : isShape ? 196 : 220))
      const startH = liveBox?.h ?? (sticky.h || (isText ? 76 : isShape ? 96 : 140))
      const startFont = sticky.fontSize ?? (isText ? (hasBg ? 18 : 36) : isShape ? 16 : 14)
      let latestW = startW
      let latestH = startH
      let latestFont = startFont
      let rafId = 0
      let guides = NO_GUIDES
      // Which edge snaps: a manual text width = the right edge; note / shape grips = their own edges.
      // Text font scaling has no edge to snap.
      const snapKind: 'se' | 'e' | 's' | null = manualWidthResize
        ? 'e'
        : !isText && (mode === 'se' || mode === 'e' || mode === 's')
          ? mode
          : null
      const startX = liveBox?.x ?? sticky.x
      const startY = liveBox?.y ?? sticky.y
      const snap = beginSnapGesture([sticky.id])
      // The one size rule (clamp + round) for both the snap check and the live size.
      const [minW, maxW] = isText ? [90, 1400] : isShape ? [64, 1600] : [150, 1100]
      const [minH, maxH] = isShape ? [44, 1600] : [96, 950]
      const sizeW = (d: number): number => Math.max(minW, Math.min(maxW, Math.round(startW + d)))
      const sizeH = (d: number): number => Math.max(minH, Math.min(maxH, Math.round(startH + d)))

      const onMove = (move: PointerEvent): void => {
        let dx = (move.clientX - origin.x) / view.scale
        let dy = (move.clientY - origin.y) / view.scale
        // Shift on a shape's corner keeps its aspect: no edge snap then.
        if (snapKind && !(isShape && move.shiftKey && mode === 'se')) {
          const snapped = snapResizeDelta(
            dx,
            dy,
            snapKind,
            (ddx, ddy) => ({
              x: startX,
              y: startY,
              w: sizeW(ddx),
              h: isText ? startH : sizeH(ddy)
            }),
            snapIndexOf(snap),
            view.scale,
            move
          )
          dx = snapped.dx
          dy = snapped.dy
          guides = snapped.guides
        } else {
          guides = NO_GUIDES
        }
        if (isText) {
          if (manualWidthResize) {
            latestW = sizeW(dx)
            latestH = computeAutoTextDimensions(
              sticky.text,
              startFont,
              latestW,
              false,
              920,
              hasBg
            ).h
          } else {
            const deltaScale = (dx + dy * 0.85) * 0.38
            latestFont = Math.max(12, Math.min(180, Math.round(startFont + deltaScale)))
            const ratio = latestFont / Math.max(12, startFont)
            if (sticky.autosize !== false) {
              const autoDims = computeAutoTextDimensions(
                sticky.text,
                latestFont,
                startW,
                true,
                920,
                hasBg
              )
              latestW = autoDims.w
              latestH = autoDims.h
            } else {
              latestW = Math.max(90, Math.min(1400, Math.round(startW * ratio)))
              latestH = computeAutoTextDimensions(
                sticky.text,
                latestFont,
                latestW,
                false,
                920,
                hasBg
              ).h
            }
          }
        } else if (isShape) {
          if (move.shiftKey && mode === 'se') {
            const aspect = startH / Math.max(1, startW)
            latestW = sizeW(dx)
            latestH = Math.max(44, Math.min(1600, Math.round(latestW * aspect)))
          } else {
            if (mode === 'se' || mode === 'e') {
              latestW = sizeW(dx)
            }
            if (mode === 'se' || mode === 's') {
              latestH = sizeH(dy)
            }
          }
        } else {
          if (mode === 'se' || mode === 'e') {
            latestW = sizeW(dx)
          }
          if (mode === 'se' || mode === 's') {
            latestH = sizeH(dy)
          }
        }
        if (rafId !== 0) {
          return
        }
        rafId = window.requestAnimationFrame(() => {
          rafId = 0
          showSnapGuides(snapIndexOf(snap) ? guides : NO_GUIDES)
          setStickySizeOverride((current) => ({
            ...current,
            [sticky.id]: {
              w: latestW,
              h: latestH,
              ...(isText ? { fontSize: latestFont } : {})
            }
          }))
        })
      }

      const onUp = (): void => {
        if (rafId !== 0) {
          window.cancelAnimationFrame(rafId)
          rafId = 0
        }
        window.removeEventListener('pointermove', onMove)
        window.removeEventListener('pointerup', onUp)
        endSnapGesture(snap)
        setStickySizeOverride((current) => {
          const next = { ...current }
          delete next[sticky.id]
          return next
        })
        onUpdateStickyNote?.(sticky.id, {
          w: latestW,
          h: latestH,
          ...(isText ? { fontSize: latestFont } : {}),
          ...(manualWidthResize ? { autosize: false } : {})
        })
      }

      window.addEventListener('pointermove', onMove)
      window.addEventListener('pointerup', onUp)
    }
  /** Double-click: on a selected group, enter it (select only this member); otherwise edit as before. */
  const onStickyDoubleClick =
    (sticky: SpaceStickyNote) =>
    (event: React.MouseEvent): void => {
      event.stopPropagation()
      const entersGroup =
        effectiveSelectedIds.length >= 2 &&
        selectedStickyIdSet.has(sticky.id) &&
        groupSelectionFor(stickies, sticky.id).length >= 2
      setSelectedStickyIds([sticky.id])
      if (!sticky.locked && !entersGroup) {
        setEditingStickyId(sticky.id)
      }
    }

  return {
    commitStickyEdit,
    handleStickyTextareaBlur,
    onStickyDoubleClick,
    startStickyDrag,
    startStickyResize
  }
}

export type StickyGestures = ReturnType<typeof useStickyGestures>

// WS-0 (TASK_16 wave 2): Space tile drag + edge / corner resize, moved verbatim from space-canvas.tsx.
// Owner: WS-A (adds the move helper for nudge).
import type { CanvasCtx } from '../canvas-ctx'
import type { ArrowGestures } from './use-arrow-gestures'
import { NO_GUIDES, snapMoveDelta, snapResizeDelta } from '../../core/whiteboard-snap-drag'
import { type SpaceTile, type TileResizeHandle, resizeTileLayout } from '../../core/space'

/** WS-A move helper (keyboard nudge): the tile's layout moved by (dx, dy), size kept, same rounding as a drag. */
export function movedTileLayout(
  layout: { x: number; y: number; w: number; h: number },
  dx: number,
  dy: number
): { x: number; y: number; w: number; h: number } {
  const x = Math.round(layout.x + dx)
  const y = Math.round(layout.y + dy)
  return {
    x: Number.isFinite(x) ? x : layout.x,
    y: Number.isFinite(y) ? y : layout.y,
    w: layout.w,
    h: layout.h
  }
}

export function useTileGestures(ctx: CanvasCtx, arrowGestures: ArrowGestures) {
  const {
    beginSnapGesture,
    boxMapRef,
    endSnapGesture,
    onMoveTile,
    setTileOffset,
    setTileSizeOverride,
    showSnapGuides,
    snapIndexOf,
    spaceHeldRef,
    toolMode,
    view
  } = ctx
  const { startArrowDrag } = arrowGestures
  const startTileDrag =
    (tile: SpaceTile) =>
    (event: React.PointerEvent): void => {
      if (event.button !== 0) {
        return
      }
      const target = event.target as HTMLElement
      if (
        target.closest(
          'button, input, textarea, [data-space-card], [data-emoji-picker], [data-bg-picker], [data-level-picker], [data-tile-resize], [data-title-edit], [data-quick-port]'
        )
      ) {
        return
      }
      if (spaceHeldRef.current || toolMode === 'eraser') {
        return
      }
      if (toolMode === 'arrow') {
        startArrowDrag(event, tile.key)
        return
      }
      event.stopPropagation()
      const origin = { x: event.clientX, y: event.clientY }
      const startBox = boxMapRef.current.get(tile.key) ?? tile
      const snap = beginSnapGesture([tile.key])
      let delta = { x: 0, y: 0 }
      let guides = NO_GUIDES
      let rafId = 0
      const onMove = (move: PointerEvent): void => {
        const rawDx = (move.clientX - origin.x) / view.scale
        const rawDy = (move.clientY - origin.y) / view.scale
        const snapped = snapMoveDelta(startBox, rawDx, rawDy, snapIndexOf(snap), view.scale, move)
        delta = { x: snapped.dx, y: snapped.dy }
        guides = snapped.guides
        if (rafId !== 0) {
          return
        }
        rafId = window.requestAnimationFrame(() => {
          rafId = 0
          setTileOffset((current) => ({ ...current, [tile.key]: delta }))
          showSnapGuides(snapIndexOf(snap) ? guides : NO_GUIDES)
        })
      }
      const onUp = (): void => {
        if (rafId !== 0) {
          window.cancelAnimationFrame(rafId)
          rafId = 0
        }
        window.removeEventListener('pointermove', onMove)
        window.removeEventListener('pointerup', onUp)
        endSnapGesture(snap)
        setTileOffset((current) => {
          const next = { ...current }
          delete next[tile.key]
          return next
        })
        if (Math.hypot(delta.x, delta.y) > 4) {
          onMoveTile(tile.key, {
            x: Math.round(tile.x + delta.x),
            y: Math.round(tile.y + delta.y),
            w: tile.w,
            h: tile.h
          })
        }
      }
      window.addEventListener('pointermove', onMove)
      window.addEventListener('pointerup', onUp)
    }

  /** Corner (nw / ne / sw / se, OpenMausBot parity) and edge (e / s) resize for any Space or Bench tile. */
  const startTileResize =
    (tile: SpaceTile, handle: TileResizeHandle = 'se') =>
    (event: React.PointerEvent): void => {
      if (event.button !== 0) {
        return
      }
      event.preventDefault()
      event.stopPropagation()
      const origin = { x: event.clientX, y: event.clientY }
      const liveBox = boxMapRef.current.get(tile.key)
      const startBox = {
        x: liveBox?.x ?? tile.x,
        y: liveBox?.y ?? tile.y,
        w: liveBox?.w ?? tile.w,
        h: liveBox?.h ?? tile.h
      }
      let latest = startBox
      let guides = NO_GUIDES
      let rafId = 0
      const snap = beginSnapGesture([tile.key])

      const onMove = (move: PointerEvent): void => {
        const rawDx = (move.clientX - origin.x) / view.scale
        const rawDy = (move.clientY - origin.y) / view.scale
        // Only the dragged edge(s) snap; resizeTileLayout keeps its clamps on the snapped delta.
        const snapped = snapResizeDelta(
          rawDx,
          rawDy,
          handle,
          (dx, dy) => resizeTileLayout(startBox, handle, dx, dy),
          snapIndexOf(snap),
          view.scale,
          move
        )
        latest = resizeTileLayout(startBox, handle, snapped.dx, snapped.dy)
        guides = snapped.guides
        if (rafId !== 0) {
          return
        }
        rafId = window.requestAnimationFrame(() => {
          rafId = 0
          showSnapGuides(snapIndexOf(snap) ? guides : NO_GUIDES)
          setTileSizeOverride((current) => ({
            ...current,
            [tile.key]: { w: latest.w, h: latest.h }
          }))
          if (latest.x !== tile.x || latest.y !== tile.y) {
            setTileOffset((current) => ({
              ...current,
              [tile.key]: { x: latest.x - tile.x, y: latest.y - tile.y }
            }))
          }
        })
      }

      const onUp = (): void => {
        if (rafId !== 0) {
          window.cancelAnimationFrame(rafId)
          rafId = 0
        }
        window.removeEventListener('pointermove', onMove)
        window.removeEventListener('pointerup', onUp)
        endSnapGesture(snap)
        setTileSizeOverride((current) => {
          const next = { ...current }
          delete next[tile.key]
          return next
        })
        setTileOffset((current) => {
          if (!current[tile.key]) {
            return current
          }
          const next = { ...current }
          delete next[tile.key]
          return next
        })
        if (
          Math.abs(latest.w - startBox.w) > 2 ||
          Math.abs(latest.h - startBox.h) > 2 ||
          latest.x !== startBox.x ||
          latest.y !== startBox.y
        ) {
          onMoveTile(tile.key, latest)
        }
      }

      window.addEventListener('pointermove', onMove)
      window.addEventListener('pointerup', onUp)
    }
  return {
    startTileDrag,
    startTileResize
  }
}

export type TileGestures = ReturnType<typeof useTileGestures>

// WS-0 (TASK_16 wave 2): wheel pan/zoom effect + empty-canvas pointer gestures (pan, marquee, tool draws),
// moved verbatim from space-canvas.tsx. Owner: WS-A (since WS-C: a marquee selects whole groups).
import { useEffect } from 'react'
import type { CanvasState } from '../use-canvas-state'
import type { CanvasCtx } from '../canvas-ctx'
import type { ArrowGestures } from './use-arrow-gestures'
import { ZOOM_WHEEL_SENSITIVITY_IN, ZOOM_WHEEL_SENSITIVITY_OUT, zoomAt } from '../../core/space'
import { createWheelBatcher, decideWheel, normalizeWheel } from '../../core/space-viewport'
import { PAN_SPEED_MULTIPLIER } from '../canvas-ctx'
import { type StickyColor, normalizeMarqueeRect, rectIntersectsBox } from '../../core/space'
import { snapPointTo } from '../../core/whiteboard-snap-drag'
import { expandToGroups } from '../../core/whiteboard-groups'

export function useWheelPan({ rootRef, markZoomTween, setView }: CanvasState): void {
  useEffect(() => {
    const element = rootRef.current
    if (!element) {
      return
    }
    // Penpot-style: only a wheel on the canvas surface pans/zooms; panels keep theirs.
    // Deltas are summed and applied once per animation frame.
    const batcher = createWheelBatcher(({ dx, dy, factor, focal }) => {
      if (factor !== 1) {
        markZoomTween()
      }
      setView((current) => {
        const panned = {
          ...current,
          x: current.x - dx * PAN_SPEED_MULTIPLIER,
          y: current.y - dy * PAN_SPEED_MULTIPLIER
        }
        return factor !== 1 && focal ? zoomAt(panned, panned.scale * factor, focal) : panned
      })
    })
    const onWheel = (event: WheelEvent): void => {
      const decision = decideWheel(event, { root: element })
      if (decision === 'ignore') {
        return
      }
      event.preventDefault()
      if (decision === 'block') {
        return
      }
      const { dx, dy } = normalizeWheel(event)
      if (decision === 'zoom') {
        // Pinch / ctrl+wheel: 1.5x faster sensitivity in both directions.
        const sensitivity = dy > 0 ? ZOOM_WHEEL_SENSITIVITY_OUT : ZOOM_WHEEL_SENSITIVITY_IN
        const rect = element.getBoundingClientRect()
        batcher.zoom(Math.exp(-dy * sensitivity), {
          x: event.clientX - rect.left,
          y: event.clientY - rect.top
        })
      } else {
        // +25% faster pan/move speed across the Space canvas
        batcher.pan(dx, dy)
      }
    }
    element.addEventListener('wheel', onWheel, { passive: false })
    return () => {
      element.removeEventListener('wheel', onWheel)
      batcher.dispose()
    }
  }, [markZoomTween, rootRef, setView])
}

/** Pointer down on the canvas surface: pan, marquee, eraser, and the shape / frame / text / arrow tools. */
export function useStartPan(ctx: CanvasCtx, arrowGestures: ArrowGestures) {
  const {
    activeFillStyle,
    activeShapeColor,
    activeShapeType,
    beginSnapGesture,
    boxMapRef,
    clientToCanvasPoint,
    dockSpaceLevel,
    effectiveSelectedIds,
    effectiveSelectedNodeIds,
    emojiPickerGoalId,
    endSnapGesture,
    levelPickerGoalId,
    nodes,
    onAddStickyNote,
    onChangeToolMode,
    onCreateSpaceAt,
    setDrawingFrameRect,
    setDrawingShapeRect,
    setEditingStickyId,
    setEmojiPickerGoalId,
    setLevelPickerGoalId,
    setMarqueeRect,
    setPanning,
    setSelectedArrowId,
    setSelectedNodeIds,
    setSelectedStickyIds,
    setView,
    showSnapGuides,
    snapIndexOf,
    spaceHeldRef,
    stickies,
    toolMode,
    view
  } = ctx
  const { startArrowDrag, startEraserSwipe } = arrowGestures
  const startPan = (event: React.PointerEvent<HTMLDivElement>): void => {
    if (event.button !== 0) {
      return
    }
    const target = event.target as HTMLElement
    if (emojiPickerGoalId && !target.closest('[data-emoji-picker]')) {
      setEmojiPickerGoalId(null)
    }
    if (levelPickerGoalId && !target.closest('[data-level-picker]')) {
      setLevelPickerGoalId(null)
    }
    if (
      target.closest(
        '[data-space-dock], [data-space-drawer], [data-whiteboard-inspector], [data-whiteboard-multiselect], [data-whiteboard-history]'
      )
    ) {
      return
    }
    if (!spaceHeldRef.current && toolMode === 'eraser') {
      if (
        !target.closest(
          'button, input, textarea, [data-space-card], [data-quick-port], [data-node-port]'
        )
      ) {
        startEraserSwipe(event)
        return
      }
    }
    if (!target.closest('[data-space-sticky]')) {
      if (!event.shiftKey) {
        setSelectedStickyIds([])
      }
      setEditingStickyId(null)
    }
    if (!target.closest('[data-space-node]')) {
      if (!event.shiftKey) {
        setSelectedNodeIds([])
      }
    }
    const onEmptyCanvas = !target.closest(
      '[data-space-tile], [data-space-card], [data-space-sticky], [data-space-node], [data-space-arrow], button, input, textarea'
    )
    if (!spaceHeldRef.current && onEmptyCanvas && toolMode === 'shape') {
      setSelectedArrowId(null)
      setSelectedStickyIds([])
      const startPt = clientToCanvasPoint(event.clientX, event.clientY)
      const originClient = { x: event.clientX, y: event.clientY }
      const shapeType = activeShapeType
      const color = activeShapeColor
      const fillStyle = activeFillStyle
      setDrawingShapeRect({ start: startPt, current: startPt, shapeType, color, fillStyle })
      const snap = beginSnapGesture([])
      const onMove = (move: PointerEvent): void => {
        const raw = clientToCanvasPoint(move.clientX, move.clientY)
        const hit = snapPointTo(raw, snapIndexOf(snap), view.scale, move)
        const curPt = { x: hit.x, y: hit.y }
        showSnapGuides(hit.guides)
        setDrawingShapeRect((cur) => (cur ? { ...cur, current: curPt } : null))
      }
      const onUp = (up: PointerEvent): void => {
        window.removeEventListener('pointermove', onMove)
        window.removeEventListener('pointerup', onUp)
        setDrawingShapeRect(null)
        const endHit = snapPointTo(
          clientToCanvasPoint(up.clientX, up.clientY),
          snapIndexOf(snap),
          view.scale,
          up
        )
        endSnapGesture(snap)
        const dragDist = Math.hypot(up.clientX - originClient.x, up.clientY - originClient.y)
        const isSym = shapeType === 'ellipse' || shapeType === 'diamond'
        let x: number
        let y: number
        let w: number
        let h: number
        if (dragDist < 12) {
          w = isSym ? 150 : 196
          h = isSym ? 150 : 96
          x = Math.round(startPt.x - w / 2)
          y = Math.round(startPt.y - h / 2)
        } else {
          const rect = normalizeMarqueeRect(startPt, { x: endHit.x, y: endHit.y })
          w = Math.max(80, Math.round(rect.w))
          h = Math.max(52, Math.round(rect.h))
          x = Math.round(rect.x)
          y = Math.round(rect.y)
        }
        const createdId = onAddStickyNote?.({ x, y }, color, 'shape', '', {
          w,
          h,
          shapeType,
          fillStyle,
          borderStyle: 'solid',
          textAlign: 'center',
          fontSize: 16
        })
        if (typeof createdId === 'string') {
          setSelectedStickyIds([createdId])
          setEditingStickyId(createdId)
        }
        if (!up.shiftKey) {
          onChangeToolMode?.('select')
        }
      }
      window.addEventListener('pointermove', onMove)
      window.addEventListener('pointerup', onUp)
      return
    }
    if (!spaceHeldRef.current && onEmptyCanvas && toolMode === 'frame') {
      setSelectedArrowId(null)
      setSelectedStickyIds([])
      const startPt = clientToCanvasPoint(event.clientX, event.clientY)
      const originClient = { x: event.clientX, y: event.clientY }
      const level = dockSpaceLevel
      setDrawingFrameRect({ start: startPt, current: startPt, level })
      const snap = beginSnapGesture([])
      const onMove = (move: PointerEvent): void => {
        const raw = clientToCanvasPoint(move.clientX, move.clientY)
        const hit = snapPointTo(raw, snapIndexOf(snap), view.scale, move)
        const curPt = { x: hit.x, y: hit.y }
        showSnapGuides(hit.guides)
        setDrawingFrameRect((cur) => (cur ? { ...cur, current: curPt } : null))
      }
      const onUp = (up: PointerEvent): void => {
        window.removeEventListener('pointermove', onMove)
        window.removeEventListener('pointerup', onUp)
        setDrawingFrameRect(null)
        const endHit = snapPointTo(
          clientToCanvasPoint(up.clientX, up.clientY),
          snapIndexOf(snap),
          view.scale,
          up
        )
        endSnapGesture(snap)
        const dragDist = Math.hypot(up.clientX - originClient.x, up.clientY - originClient.y)
        if (dragDist < 12) {
          onCreateSpaceAt?.(level, {
            x: Math.round(startPt.x - 170),
            y: Math.round(startPt.y - 110),
            w: 340,
            h: 220
          })
        } else {
          const rect = normalizeMarqueeRect(startPt, { x: endHit.x, y: endHit.y })
          onCreateSpaceAt?.(level, {
            x: Math.round(rect.x),
            y: Math.round(rect.y),
            w: Math.max(320, Math.round(rect.w)),
            h: Math.max(200, Math.round(rect.h))
          })
        }
        if (!up.shiftKey) {
          onChangeToolMode?.('select')
        }
      }
      window.addEventListener('pointermove', onMove)
      window.addEventListener('pointerup', onUp)
      return
    }
    if (!spaceHeldRef.current && onEmptyCanvas && toolMode === 'text') {
      const pt = clientToCanvasPoint(event.clientX, event.clientY)
      const hasBg = activeFillStyle !== 'none'
      const color: StickyColor =
        activeFillStyle === 'paper' || activeFillStyle === 'paper-light'
          ? 'paper'
          : hasBg
            ? activeShapeColor
            : 'zinc'
      const fontSize = hasBg ? 18 : 36
      const createdId = onAddStickyNote?.(
        { x: Math.round(pt.x - (hasBg ? 64 : 16)), y: Math.round(pt.y - 24) },
        color,
        'text',
        '',
        {
          fillStyle: activeFillStyle,
          borderStyle: hasBg ? 'solid' : 'none',
          fontSize,
          fontWeight: hasBg ? 'semibold' : 'bold',
          textAlign: 'left',
          autosize: true
        }
      )
      if (typeof createdId === 'string') {
        setSelectedStickyIds([createdId])
        setEditingStickyId(createdId)
      }
      onChangeToolMode?.('select')
      return
    }
    if (!spaceHeldRef.current && toolMode === 'arrow') {
      if (
        !target.closest(
          'button, input, textarea, [data-space-card], [data-quick-port], [data-node-port]'
        )
      ) {
        const fromTile = target.closest<HTMLElement>('[data-space-tile]')?.dataset.spaceTile
        const fromSticky = target.closest<HTMLElement>('[data-space-sticky]')?.dataset.spaceSticky
        const fromNode = target.closest<HTMLElement>('[data-space-node]')?.dataset.spaceNode
        startArrowDrag(event, fromNode || fromSticky || fromTile)
        return
      }
    }
    if (
      !spaceHeldRef.current &&
      onEmptyCanvas &&
      (toolMode === 'marquee' || (toolMode === 'select' && event.shiftKey))
    ) {
      setSelectedArrowId(null)
      setEditingStickyId(null)
      const startPt = clientToCanvasPoint(event.clientX, event.clientY)
      const baseSet = event.shiftKey ? new Set(effectiveSelectedIds) : new Set<string>()
      const baseNodeSet = event.shiftKey ? new Set(effectiveSelectedNodeIds) : new Set<string>()
      setMarqueeRect({ start: startPt, current: startPt })
      const onMove = (move: PointerEvent): void => {
        const curPt = clientToCanvasPoint(move.clientX, move.clientY)
        setMarqueeRect({ start: startPt, current: curPt })
        const mRect = normalizeMarqueeRect(startPt, curPt)
        const nextIds = new Set<string>(baseSet)
        for (const s of stickies) {
          if (s.locked) {
            continue
          }
          const b = boxMapRef.current.get(s.id)
          if (b && rectIntersectsBox(mRect, b)) {
            nextIds.add(s.id)
          }
        }
        const nextNodeIds = new Set<string>(baseNodeSet)
        for (const n of nodes) {
          if (n.locked || n.hidden) {
            continue
          }
          const b = boxMapRef.current.get(n.id)
          if (b && rectIntersectsBox(mRect, b)) {
            nextNodeIds.add(n.id)
          }
        }
        // A marquee touching one member selects its whole (visible) group, like a click.
        setSelectedStickyIds(expandToGroups(stickies, Array.from(nextIds)))
        setSelectedNodeIds(Array.from(nextNodeIds))
      }
      const onUp = (): void => {
        window.removeEventListener('pointermove', onMove)
        window.removeEventListener('pointerup', onUp)
        setMarqueeRect(null)
      }
      window.addEventListener('pointermove', onMove)
      window.addEventListener('pointerup', onUp)
      return
    }
    if (!spaceHeldRef.current && !onEmptyCanvas) {
      return
    }
    setSelectedArrowId(null)
    const originClient = { x: event.clientX, y: event.clientY }
    const originView = { x: view.x, y: view.y }
    let rafId = 0
    let latestX = event.clientX
    let latestY = event.clientY
    setPanning(true)
    const onMove = (move: PointerEvent): void => {
      latestX = move.clientX
      latestY = move.clientY
      if (rafId !== 0) {
        return
      }
      rafId = window.requestAnimationFrame(() => {
        rafId = 0
        setView((c) => ({
          ...c,
          x: originView.x + (latestX - originClient.x) * PAN_SPEED_MULTIPLIER,
          y: originView.y + (latestY - originClient.y) * PAN_SPEED_MULTIPLIER
        }))
      })
    }
    const onUp = (): void => {
      if (rafId !== 0) {
        window.cancelAnimationFrame(rafId)
        rafId = 0
      }
      setPanning(false)
      window.removeEventListener('pointermove', onMove)
      window.removeEventListener('pointerup', onUp)
    }
    window.addEventListener('pointermove', onMove)
    window.addEventListener('pointerup', onUp)
  }
  return {
    startPan
  }
}

// WS-A (TASK_16 wave 2): which live Space canvas gets the keys. Orca mounts one board per tab group
// (tab-bands.tsx), so two canvases can listen to the same window keydown. The last canvas the person
// pointed at or focused is active; with one canvas mounted it always wins. Module state = one renderer.
const live: HTMLElement[] = []
let active: HTMLElement | null = null

export function addLiveCanvas(root: HTMLElement): () => void {
  live.push(root)
  const activate = (): void => {
    active = root
  }
  root.addEventListener('pointerdown', activate, true)
  root.addEventListener('pointerenter', activate)
  root.addEventListener('focusin', activate)
  return () => {
    root.removeEventListener('pointerdown', activate, true)
    root.removeEventListener('pointerenter', activate)
    root.removeEventListener('focusin', activate)
    const i = live.indexOf(root)
    if (i !== -1) {
      live.splice(i, 1)
    }
    if (active === root) {
      active = null
    }
  }
}

const visible = (el: HTMLElement): boolean => el.isConnected && el.clientWidth > 0

/** True when `root` should handle this key: the only canvas, the active one, else the first visible. */
export function isKeyCanvas(root: HTMLElement | null): boolean {
  if (!root || live.length <= 1) {
    return true
  }
  if (active && live.includes(active) && visible(active)) {
    return active === root
  }
  return (live.find(visible) ?? live[0]) === root
}

// WS-A (TASK_16 wave 2): the ONE shortcut table of the Spaces canvas. The key effect (use-canvas-keys.ts)
// looks a keydown up here; the `?` help (overlays/ShortcutHelp.tsx) and the WS-E context menu read the
// same rows for their labels. Idea from Penpot's keyboard map (data/workspace/shortcuts.cljs: one map of
// id -> command + fn) and its shortcuts panel; re-implemented, no Penpot code.
//
// Row = id · label · group · scope · keys (chords: event.key and/or physical event.code + modifiers)
//       · display · when (enabled) · run (true = preventDefault).
// A matched row always ends the lookup, even when `when` is false (same as the old if-chain's `return`).
// Rows are tried in table order. Other workstreams: export a `CanvasCommand[]` from your own file and
// ask WS-A to add it to extraRows() below, or register rows at runtime (`registerCanvasCommands`) when
// `run` needs your component's state. Overlapping keys in one scope are refused (P3-11 test).
import type { CanvasCtx } from '../canvas-ctx'
import type { SelectionActions } from '../selection/use-selection-actions'
import type { SpaceStickyNote } from '../../core/space'
import type { NudgeDirection } from '../../penpot-mpl/nudge-burst'
import type { NudgeControl } from './use-nudge'
import { WHITEBOARD_LAYER_COMMANDS } from '../overlays/layers-commands'
