/** Rows that other workstreams export from their own files (WS-A adds the import here); their runtime
 *  registrations then no-op (same ids). WS-C: group / ungroup / hide / layers panel. WS-E: ⇧F10 / menu
 *  key. A function, read at lookup time: ContextMenus.tsx imports this module too (import cycle). */
const extraRows = (): readonly CanvasCommand[] => [
  ...WHITEBOARD_LAYER_COMMANDS,
  ...CONTEXT_MENU_COMMANDS
]

/** Shown in the help only: keys handled outside the table (Space hold in the key effect, A in the toolbar). */
export const HOLD_HINTS: readonly { label: string; display: string; group: CommandGroup }[] = [
  { label: 'Hold to pan (hand)', display: 'Space', group: 'View' },
  { label: 'Agents tray (toolbar)', display: 'A', group: 'Tools' }
]

// ── Matching ─────────────────────────────────────────────────────────────────────────────────────

const modOk = (req: ModReq, held: boolean): boolean => req === 'any' || req === held

export function chordMatches(c: KeyChord, event: KeyboardEvent): boolean {
  if (c.code !== undefined && event.code !== c.code) {
    return false
  }
  if (c.key !== undefined && (event.key ?? '').toLowerCase() !== c.key) {
    return false
  }
  return (
    modOk(c.mod, event.metaKey || event.ctrlKey) &&
    modOk(c.shift, event.shiftKey) &&
    modOk(c.alt, event.altKey)
  )
}

/** Runtime row sets and the canvas they belong to (`owner`, e.g. its rootRef; undefined = every canvas). */
const runtimeRows = new Map<readonly CanvasCommand[], unknown>()

/** Every row: the table, the workstream rows, then the runtime rows of `owner` (and ownerless ones).
 *  With no owner given: the runtime rows of every canvas (deduped by id, for listings). */
export function allCanvasCommands(owner?: unknown): CanvasCommand[] {
  const runtime: CanvasCommand[] = []
  const seen = new Set<string>()
  for (const [rows, rowOwner] of runtimeRows) {
    if (owner !== undefined && rowOwner !== undefined && rowOwner !== owner) {
      continue
    }
    for (const r of rows) {
      if (!seen.has(r.id)) {
        seen.add(r.id)
        runtime.push(r)
      }
    }
  }
  return [...CORE_COMMANDS, ...extraRows(), ...runtime]
}

/** First row of `scope` whose chord matches, or null. */
export function findCommand(
  event: KeyboardEvent,
  scope: CommandScope,
  rows: readonly CanvasCommand[] = allCanvasCommands()
): CanvasCommand | null {
  // Someone earlier (an Orca global binding, a menu) already used this key: never run a second action.
  if (event.defaultPrevented) {
    return null
  }
  for (const row of rows) {
    if (row.scope === scope && row.keys.some((c) => chordMatches(c, event))) {
      return row
    }
  }
  return null
}

// ── Conflicts (P3-11) ────────────────────────────────────────────────────────────────────────────

/** US-layout keys a physical code types (unshifted, shifted); enough to compare key vs code chords. */
const US_KEYS: Record<string, readonly [string, string]> = {
  Digit0: ['0', ')'],
  Digit1: ['1', '!'],
  Digit2: ['2', '@'],
  Digit3: ['3', '#'],
  Digit4: ['4', '$'],
  Digit5: ['5', '%'],
  Digit6: ['6', '^'],
  Digit7: ['7', '&'],
  Digit8: ['8', '*'],
  Digit9: ['9', '('],
  Minus: ['-', '_'],
  Equal: ['=', '+'],
  Slash: ['/', '?'],
  NumpadAdd: ['+', '+'],
  NumpadSubtract: ['-', '-']
}

const modsOverlap = (a: ModReq, b: ModReq): boolean => a === 'any' || b === 'any' || a === b

/** Can one keypress match both chords? */
export function chordsOverlap(a: KeyChord, b: KeyChord): boolean {
  if (!modsOverlap(a.mod, b.mod) || !modsOverlap(a.alt, b.alt) || !modsOverlap(a.shift, b.shift)) {
    return false
  }
  if (a.code !== undefined && b.code !== undefined) {
    return a.code === b.code
  }
  if (a.key !== undefined && b.key !== undefined) {
    return a.key === b.key
  }
  const [withCode, withKey] = a.code !== undefined ? [a, b] : [b, a]
  const typed = US_KEYS[withCode.code ?? '']
  if (!typed || withKey.key === undefined) {
    return false
  }
  // Shift states both chords accept; the code types the unshifted or the shifted key.
  return [false, true]
    .filter((s) => modOk(withCode.shift, s) && modOk(withKey.shift, s))
    .some((s) => typed[s ? 1 : 0] === withKey.key)
}

export type KeyConflict = { scope: CommandScope; a: string; b: string }

/** Pairs of different rows in one scope that one keypress could trigger both of. */
export function findKeyConflicts(rows: readonly CanvasCommand[]): KeyConflict[] {
  const out: KeyConflict[] = []
  for (let i = 0; i < rows.length; i++) {
    for (let j = i + 1; j < rows.length; j++) {
      const a = rows[i]!
      const b = rows[j]!
      if (a.scope !== b.scope || a.id === b.id) {
        continue
      }
      if (a.keys.some((ka) => b.keys.some((kb) => chordsOverlap(ka, kb)))) {
        out.push({ scope: a.scope, a: a.id, b: b.id })
      }
    }
  }
  return out
}

/**
 * Runtime rows (WS-D: ⌘F jump, next / prev ask) whose `run` needs component state. `owner` = the canvas
 * they act on (pass its rootRef): two live canvases may register the same ids, and the key effect only
 * looks at the rows of the canvas that handles the key. Rows already in the table (same objects) are a
 * silent no-op; a key taken in that scope or an id repeated for the same canvas is refused and logged.
 */
export function registerCanvasCommands(
  rows: readonly CanvasCommand[],
  owner?: unknown
): {
  unregister: () => void
  conflicts: KeyConflict[]
} {
  const table = new Set<CanvasCommand>([...CORE_COMMANDS, ...extraRows()])
  if (rows.every((r) => table.has(r))) {
    return {
      unregister: () => {},
      conflicts: rows.map((r) => ({ scope: r.scope, a: r.id, b: r.id }))
    }
  }
  const existing = owner === undefined ? allCanvasCommands() : allCanvasCommands(owner)
  const ids = new Set(existing.map((r) => r.id))
  const conflicts = findKeyConflicts([...existing, ...rows]).filter((c) =>
    rows.some((r) => r.id === c.a || r.id === c.b)
  )
  const dupIds = rows.filter((r) => ids.has(r.id))
  if (conflicts.length > 0 || dupIds.length > 0) {
    for (const r of dupIds) {
      conflicts.push({ scope: r.scope, a: r.id, b: r.id })
    }
    console.warn(
      `[orca-plus canvas keys] refused rows ${rows.map((r) => r.id).join(', ')}:`,
      conflicts.map((c) => `${c.a} vs ${c.b}`).join('; ')
    )
    return { unregister: () => {}, conflicts }
  }
  runtimeRows.set(rows, owner)
  return {
    unregister: () => {
      runtimeRows.delete(rows)
    },
    conflicts: []
  }
}

// WS-A (TASK_16 wave 2): open / closed state of the `?` shortcut help. A tiny external store, so the key
// effect (keyboard/) and the overlay (overlays/HistoryZoomControls -> ShortcutHelp) share it without a new
// CanvasCtx field or a SpaceCanvas prop. Idea from Penpot's shortcuts panel; no Penpot code.
import { useSyncExternalStore } from 'react'

let open = false
const listeners = new Set<() => void>()

export function isShortcutHelpOpen(): boolean {
  return open
}

export function setShortcutHelpOpen(next: boolean): void {
  if (open === next) {
    return
  }
  open = next
  for (const fn of listeners) {
    fn()
  }
}

function subscribe(fn: () => void): () => void {
  listeners.add(fn)
  return () => {
    listeners.delete(fn)
  }
}

export function useShortcutHelpOpen(): boolean {
  return useSyncExternalStore(subscribe, isShortcutHelpOpen, isShortcutHelpOpen)
}

// WS-A (TASK_16 wave 2): the ONE "is the person typing here?" test for canvas keys and the clipboard.
// Inputs, textareas, selects and any editable element: isContentEditable covers contenteditable="",
// "true" and "plaintext-only", inherited from a parent too (the attribute check is a fallback for DOMs
// that do not compute isContentEditable).
const FIELD_SELECTOR = 'input, textarea, select'
const EDITABLE_SELECTOR = '[contenteditable]:not([contenteditable="false"])'

export function isTypingTarget(target: EventTarget | null): boolean {
  const el = target as HTMLElement | null
  if (!el || typeof el.closest !== 'function') {
    return false
  }
  if (el.isContentEditable) {
    return true
  }
  return Boolean(el.closest(FIELD_SELECTOR) || el.closest(EDITABLE_SELECTOR))
}

// WS-0 (TASK_16 wave 2): the canvas key effect, moved from space-canvas.tsx. Owner: WS-A.
// WS-A: the if-chain is now ONE table (./commands.ts); this effect only guards, looks the key up and runs
// the row. Old keys behave exactly as before (P3-00 golden "keys ·" snapshots unchanged); new rows:
// Shift+0, + / −, arrows (nudge), `?` (help). Keys never fire while typing (inputs, textareas, selects,
// contenteditable, IME) and arrows leave focused menus / lists alone.
import type { CanvasCtx } from '../canvas-ctx'
import type { SelectionActions } from '../selection/use-selection-actions'
import { isImeOwnedKeyboardEvent } from '../../core/ime-guard'
import { useEffect, useLayoutEffect, useRef } from 'react'
import { allCanvasCommands, findCommand, type CommandEnv } from './commands'
import { isShortcutHelpOpen, setShortcutHelpOpen } from './help-store'
import { useNudge } from './use-nudge'
import { isTypingTarget } from './typing-target'
import { addLiveCanvas, isKeyCanvas } from './active-canvas'

/** Widgets that own arrow keys themselves (Orca Plus menus, lists, sliders, tabs). */
const ARROW_OWNER_SELECTOR =
  '[role="menu"], [role="menubar"], [role="listbox"], [role="slider"], [role="tablist"], [role="grid"], [role="tree"]'

/** Modifier key-downs (Shift pressed mid-burst for 10 px steps) never end a nudge burst. */
const MODIFIER_KEYS = new Set(['Shift', 'Meta', 'Control', 'Alt', 'AltGraph', 'CapsLock'])

export function useCanvasKeys(ctx: CanvasCtx, sel: SelectionActions): void {
  const { rootRef, setSpaceHeld, spaceHeldRef } = ctx
  const nudge = useNudge(ctx)
  // Latest env without re-subscribing the window listeners on every render.
  const envRef = useRef<CommandEnv | null>(null)
  useLayoutEffect(() => {
    envRef.current = {
      ctx,
      sel,
      nudge,
      help: { open: () => setShortcutHelpOpen(true), close: () => setShortcutHelpOpen(false) }
    }
  })

  useEffect(() => {
    const root = rootRef.current
    const dropLive = root ? addLiveCanvas(root) : () => {}
    const onKeyDown = (event: KeyboardEvent): void => {
      if (!isKeyCanvas(rootRef.current)) {
        return
      }
      const isArrow = event.key?.startsWith('Arrow')
      if (!isArrow && !MODIFIER_KEYS.has(event.key)) {
        // Any other key (typing in a field, Space, a command) closes an open nudge burst first, so
        // nothing else ever folds into the nudge's undo entry.
        envRef.current?.nudge.end()
      }
      if (isImeOwnedKeyboardEvent(event)) {
        return
      }
      if (isTypingTarget(event.target)) {
        return
      }
      if (event.code === 'Space' && !event.metaKey && !event.ctrlKey && !event.altKey) {
        if (!spaceHeldRef.current) {
          spaceHeldRef.current = true
          setSpaceHeld(true)
        }
        event.preventDefault()
        return
      }
      const env = envRef.current
      if (!env) {
        return
      }
      // Table rows + this canvas's runtime rows (WS-D asks); skipped when the key was already used.
      const rows = allCanvasCommands(rootRef)
      const row =
        (isShortcutHelpOpen() ? findCommand(event, 'help', rows) : null) ??
        findCommand(event, 'canvas', rows)
      if (!row) {
        return
      }
      if (
        row.id.startsWith('arrange.nudge') &&
        (event.target as HTMLElement | null)?.closest?.(ARROW_OWNER_SELECTOR)
      ) {
        return
      }
      if (row.when && !row.when(env, event)) {
        return
      }
      if (row.run(env, event) === true) {
        event.preventDefault()
      }
    }

    const onKeyUp = (event: KeyboardEvent): void => {
      envRef.current?.nudge.keyUp()
      if (event.code === 'Space' && spaceHeldRef.current) {
        spaceHeldRef.current = false
        setSpaceHeld(false)
      }
    }

    const onBlurWindow = (): void => {
      envRef.current?.nudge.end()
      if (spaceHeldRef.current) {
        spaceHeldRef.current = false
        setSpaceHeld(false)
      }
    }

    // Any pointer press (a drag, the toolbar Undo, a menu, the layers panel, the inspector) closes an
    // open nudge burst before its own write, so that write is a separate undo entry.
    const onPointerDownAnywhere = (): void => {
      envRef.current?.nudge.end()
    }

    window.addEventListener('keydown', onKeyDown)
    window.addEventListener('keyup', onKeyUp)
    window.addEventListener('blur', onBlurWindow)
    window.addEventListener('pointerdown', onPointerDownAnywhere, true)
    return () => {
      dropLive()
      window.removeEventListener('pointerdown', onPointerDownAnywhere, true)
      window.removeEventListener('keydown', onKeyDown)
      window.removeEventListener('keyup', onKeyUp)
      window.removeEventListener('blur', onBlurWindow)
    }
  }, [rootRef, setSpaceHeld, spaceHeldRef])
}

// WS-A (TASK_16 wave 2): arrow-key nudge of the selected notes / shapes / text, else the selected Space
// tile. 1 px, Shift = 10 px. A burst (keys pressed close together) = ONE undo entry through the
// onWhiteboardTransaction seam; writes are batched to one per animation frame (absolute positions from
// the burst's start, so a dropped frame never loses a step). Burst rules: penpot-mpl/nudge-burst.ts.
// Agent data: only sticky x/y and the tile `layout` are written (goal tiles may move, never anything else).
import { useEffect, useLayoutEffect, useMemo, useRef } from 'react'
import type { SpaceCanvasNode } from '../../core/canvas-nodes'
import type { CanvasCtx } from '../canvas-ctx'
import type { SpaceLayout, SpaceStickyNote } from '../../core/space'
import {
  createNudgeBurst,
  nudgeVector,
  type NudgeBurst,
  type NudgeDirection
} from '../../penpot-mpl/nudge-burst'
import { movedTileLayout } from '../gestures/use-tile-gestures'

/** Our burst end: 500 ms after the last key-up (Penpot 250 ms), or 1 s with no press (held key). */
export const NUDGE_KEY_UP_GRACE_MS = 500

/** Open bursts by canvas (rootRef): the toolbar Undo / Redo close the burst before stepping history. */
const burstsByCanvas = new WeakMap<object, NudgeControl>()

/** Flush and close the canvas's open nudge burst (no-op when none). */
export function endNudgeBurst(rootRef: object): void {
  burstsByCanvas.get(rootRef)?.end()
}

export type NudgeControl = {
  /** One arrow press. False = nothing to nudge (the key is left to the page). */
  press: (direction: NudgeDirection, shift: boolean) => boolean
  keyUp: () => void
  /** Flush and close the open burst (any other command, blur, unmount). */
  end: () => void
}

type Burst = {
  signature: string
  stickies: Map<string, { x: number; y: number }>
  nodes: Map<string, { x: number; y: number }>
  tile: { key: string; layout: SpaceLayout } | null
  total: { x: number; y: number }
  raf: number | null
  /** A press since the last write (the end-of-burst flush skips a write that changes nothing). */
  dirty: boolean
  endTxn: (() => void) | null
}

type Targets = {
  signature: string
  stickies: SpaceStickyNote[]
  nodes: SpaceCanvasNode[]
  tile: { key: string; layout: SpaceLayout } | null
}

function targetsOf(ctx: CanvasCtx): Targets | null {
  if (ctx.editingStickyId) {
    return null
  }
  const stickies = ctx.effectiveSelectedIds
    .map((id) => ctx.stickiesById.get(id))
    .filter((s): s is SpaceStickyNote => Boolean(s) && !s?.locked)
  const nodes = ctx.effectiveSelectedNodeIds
    .map((id) => ctx.nodesById.get(id))
    .filter((n): n is SpaceCanvasNode => Boolean(n) && !n?.locked)
  if (ctx.effectiveSelectedIds.length > 0 || ctx.effectiveSelectedNodeIds.length > 0) {
    return stickies.length > 0 || nodes.length > 0
      ? {
          signature: `s:${stickies.map((s) => s.id).join(',')}|n:${nodes.map((n) => n.id).join(',')}`,
          stickies,
          nodes,
          tile: null
        }
      : null
  }
  const tile = ctx.selectedGoalId ? ctx.tiles.find((t) => t.key === ctx.selectedGoalId) : undefined
  if (!tile) {
    return null
  }
  return {
    signature: `t:${tile.key}`,
    stickies: [],
    nodes: [],
    tile: { key: tile.key, layout: { x: tile.x, y: tile.y, w: tile.w, h: tile.h } }
  }
}

const finiteOr = (v: number, fallback: number): number => (Number.isFinite(v) ? v : fallback)

export function useNudge(ctx: CanvasCtx): NudgeControl {
  const ctxRef = useRef(ctx)
  useLayoutEffect(() => {
    ctxRef.current = ctx
  })
  const burstRef = useRef<Burst | null>(null)
  const pendingRef = useRef<Targets | null>(null)

  const control = useMemo(() => {
    const flush = (): void => {
      const b = burstRef.current
      if (!b) {
        return
      }
      b.raf = null
      if (!b.dirty) {
        return
      }
      b.dirty = false
      const { onBatchUpdateStickyNotes, onUpdateStickyNote, onUpdateNode, onMoveTile } =
        ctxRef.current
      const { x: dx, y: dy } = b.total
      if (b.stickies.size > 0) {
        const patches: Record<string, Partial<SpaceStickyNote>> = {}
        for (const [id, base] of b.stickies) {
          patches[id] = {
            x: Math.round(finiteOr(base.x + dx, base.x)),
            y: Math.round(finiteOr(base.y + dy, base.y))
          }
        }
        const ids = Object.keys(patches)
        if (onBatchUpdateStickyNotes) {
          onBatchUpdateStickyNotes(patches)
        } else {
          for (const id of ids) {
            const p = patches[id]
            if (p) {
              onUpdateStickyNote?.(id, p)
            }
          }
        }
      }
      if (b.nodes.size > 0) {
        for (const [id, base] of b.nodes) {
          onUpdateNode?.(id, {
            x: Math.round(finiteOr(base.x + dx, base.x)),
            y: Math.round(finiteOr(base.y + dy, base.y))
          })
        }
      }
      if (b.tile) {
        onMoveTile(b.tile.key, movedTileLayout(b.tile.layout, dx, dy))
      }
    }

    const burst: NudgeBurst = createNudgeBurst({
      keyUpMs: NUDGE_KEY_UP_GRACE_MS,
      onStart: () => {
        const t = pendingRef.current
        if (!t) {
          return
        }
        burstRef.current = {
          signature: t.signature,
          stickies: new Map(t.stickies.map((s) => [s.id, { x: s.x, y: s.y }])),
          nodes: new Map(t.nodes.map((n) => [n.id, { x: n.x, y: n.y }])),
          tile: t.tile,
          total: { x: 0, y: 0 },
          raf: null,
          dirty: false,
          endTxn: ctxRef.current.onWhiteboardTransaction?.() ?? null
        }
      },
      onEnd: () => {
        const b = burstRef.current
        if (!b) {
          return
        }
        if (b.raf !== null && typeof window !== 'undefined') {
          window.cancelAnimationFrame(b.raf)
        }
        flush()
        burstRef.current = null
        b.endTxn?.()
      }
    })

    const press = (direction: NudgeDirection, shift: boolean): boolean => {
      const targets = targetsOf(ctxRef.current)
      if (!targets) {
        burst.end()
        return false
      }
      if (burstRef.current && burstRef.current.signature !== targets.signature) {
        burst.end()
      }
      pendingRef.current = targets
      burst.press()
      const b = burstRef.current as Burst | null
      if (!b) {
        return false
      }
      const v = nudgeVector(direction, shift)
      b.total = { x: b.total.x + v.x, y: b.total.y + v.y }
      b.dirty = true
      if (b.raf === null) {
        b.raf = window.requestAnimationFrame(flush)
      }
      return true
    }
    return { press, keyUp: () => burst.keyUp(), end: () => burst.end() }
  }, [])

  const { rootRef } = ctx
  useEffect(() => {
    burstsByCanvas.set(rootRef, control)
    return () => {
      control.end()
      burstsByCanvas.delete(rootRef)
    }
  }, [control, rootRef])
  return control
}

// WS-0 (TASK_16 wave 2): arrow label / toolbar chips: the second arrows.map block, moved verbatim
// from space-canvas.tsx. Owner: WS-C (skips hidden arrows).
import type { CanvasCtx } from '../canvas-ctx'
import {
  STICKY_COLORS,
  STICKY_COLOR_STYLE,
  WHITEBOARD_ARROW_ROUTINGS,
  resolveArrowPathAndHandles
} from '../../core/space'
import { hiddenIds, isArrowHidden } from '../../core/whiteboard-groups'
import { useMemo } from 'react'
import { isImeOwnedKeyboardEvent } from '../../core/ime-guard'

export function ArrowLabelLayer({ ctx }: { ctx: CanvasCtx }): React.JSX.Element {
  const {
    arrowLabelDraft,
    arrows,
    bendingArrow,
    boxMap,
    editingArrowId,
    hoveredArrowId,
    onDeleteArrow,
    onUpdateArrow,
    selectedArrowId,
    setArrowLabelDraft,
    setEditingArrowId,
    setHoveredArrowId,
    setSelectedArrowId
  } = ctx
  // WS-C: hidden arrows, and arrows that end on a hidden sticky, are not drawn.
  const hiddenStickyIds = useMemo(() => hiddenIds(ctx.stickies), [ctx.stickies])
  return (
    <>
      {arrows.map((arrow) => {
        if (isArrowHidden(arrow, hiddenStickyIds)) {
          return null
        }
        const withBend =
          bendingArrow && bendingArrow.arrowId === arrow.id
            ? { ...arrow, bend: bendingArrow.bend }
            : arrow
        const geom = resolveArrowPathAndHandles(withBend, boxMap)
        if (!geom) {
          return null
        }
        const isSelected = selectedArrowId === arrow.id
        const isHovered = hoveredArrowId === arrow.id
        const isEditing = editingArrowId === arrow.id
        if (!arrow.label && !isSelected && !isHovered && !isEditing) {
          return null
        }
        const showControls = isSelected || isHovered || isEditing
        const curRouting = arrow.routing ?? 'curve'
        return (
          <div
            key={`label-${arrow.id}`}
            data-space-arrow={arrow.id}
            onMouseEnter={() => setHoveredArrowId(arrow.id)}
            onMouseLeave={() => setHoveredArrowId((cur) => (cur === arrow.id ? null : cur))}
            style={{
              left: geom.mid.x,
              top: showControls ? geom.mid.y - 28 : geom.mid.y,
              transform: 'translate(-50%, -50%)'
            }}
            onPointerDown={(event) => event.stopPropagation()}
            onClick={(event) => {
              event.stopPropagation()
              setSelectedArrowId(arrow.id)
            }}
            className="pointer-events-auto absolute z-20 flex items-center gap-1.5 rounded-xl border border-sky-500/45 bg-zinc-900/95 px-2.5 py-1 text-xs text-zinc-100 shadow-xl whitespace-nowrap"
          >
            {isEditing ? (
              <input
                autoFocus
                value={arrowLabelDraft}
                onChange={(event) => setArrowLabelDraft(event.target.value)}
                onBlur={() => {
                  onUpdateArrow?.(arrow.id, { label: arrowLabelDraft.trim() || undefined })
                  setEditingArrowId(null)
                }}
                onKeyDown={(event) => {
                  if (isImeOwnedKeyboardEvent(event)) {
                    return
                  }
                  if (event.key === 'Enter') {
                    onUpdateArrow?.(arrow.id, { label: arrowLabelDraft.trim() || undefined })
                    setEditingArrowId(null)
                  } else if (event.key === 'Escape') {
                    setEditingArrowId(null)
                  }
                }}
                placeholder="Arrow label…"
                className="w-36 bg-transparent text-xs text-white outline-none"
              />
            ) : (
              <>
                {arrow.label ? <span className="font-medium px-1">{arrow.label}</span> : null}
                {isSelected || isHovered ? (
                  <>
                    <div className="flex items-center gap-1">
                      {STICKY_COLORS.map((c) => (
                        <button
                          key={c}
                          type="button"
                          title={`Arrow color: ${STICKY_COLOR_STYLE[c].label}`}
                          onClick={() => onUpdateArrow?.(arrow.id, { color: c })}
                          className={`size-3.5 rounded-full transition-transform hover:scale-110 ${STICKY_COLOR_STYLE[c].dot} ${
                            arrow.color === c ? 'ring-2 ring-white' : 'opacity-75 hover:opacity-100'
                          }`}
                        />
                      ))}
                    </div>
                    <span className="mx-0.5 h-3.5 w-px bg-white/15" />
                    <div className="flex items-center gap-0.5 rounded-lg bg-zinc-950/80 p-0.5">
                      {WHITEBOARD_ARROW_ROUTINGS.map((rt) => {
                        const label = rt === 'curve' ? 'Curve' : rt === 'elbow' ? 'Elbow' : 'Line'
                        const active = curRouting === rt
                        return (
                          <button
                            key={rt}
                            type="button"
                            title={`Routing: ${label}`}
                            onClick={() =>
                              onUpdateArrow?.(arrow.id, { routing: rt, bend: undefined })
                            }
                            className={`rounded px-1.5 py-0.5 text-[10px] font-semibold transition ${
                              active
                                ? 'bg-sky-500/25 text-sky-200'
                                : 'text-zinc-400 hover:text-white'
                            }`}
                          >
                            {label}
                          </button>
                        )
                      })}
                    </div>
                    <button
                      type="button"
                      title={
                        arrow.dash === 'dashed' ? 'Switch to solid line' : 'Switch to dashed line'
                      }
                      onClick={() =>
                        onUpdateArrow?.(arrow.id, {
                          dash: arrow.dash === 'dashed' ? 'solid' : 'dashed'
                        })
                      }
                      className={`rounded-md px-1.5 py-0.5 font-mono text-[11px] font-semibold ${
                        arrow.dash === 'dashed'
                          ? 'bg-sky-500/25 text-sky-200'
                          : 'text-zinc-300 hover:bg-white/10 hover:text-white'
                      }`}
                    >
                      ╌
                    </button>
                    <button
                      type="button"
                      title="Edit arrow label"
                      onClick={() => {
                        setSelectedArrowId(arrow.id)
                        setEditingArrowId(arrow.id)
                        setArrowLabelDraft(arrow.label ?? '')
                      }}
                      className="rounded-md px-1.5 py-0.5 text-[11px] font-medium text-zinc-300 hover:bg-white/10 hover:text-white"
                    >
                      ✎ Label
                    </button>
                    <button
                      type="button"
                      title="Flip arrow direction"
                      onClick={() =>
                        onUpdateArrow?.(arrow.id, {
                          fromId: arrow.toId,
                          toId: arrow.fromId,
                          fromPoint: arrow.toPoint,
                          toPoint: arrow.fromPoint
                        })
                      }
                      className="rounded-md px-1.5 py-0.5 text-[11px] font-medium text-sky-300 hover:bg-sky-500/20"
                    >
                      ⇄
                    </button>
                    <button
                      type="button"
                      title="Delete arrow"
                      onClick={() => {
                        onDeleteArrow?.(arrow.id)
                        setSelectedArrowId(null)
                      }}
                      className="rounded-md px-1.5 py-0.5 text-xs font-semibold text-rose-400 hover:bg-rose-500/20 hover:text-rose-200"
                    >
                      ✕
                    </button>
                  </>
                ) : null}
              </>
            )}
          </div>
        )
      })}
    </>
  )
}

