    reconnectingArrow,
    selectedArrowId,
    setArrowLabelDraft,
    setEditingArrowId,
    setHoveredArrowId,
    setSelectedArrowId,
    setSelectedStickyIds,
    toolMode
  } = ctx
  // WS-C: hidden arrows, and arrows that end on a hidden sticky, are not drawn.
  const hiddenStickyIds = useMemo(() => hiddenIds(ctx.stickies), [ctx.stickies])
  const { startArrowBendDrag, startArrowEndpointDrag, startEraserSwipe } = g
  const previewGeometry = drawingArrow
    ? resolveArrowPathAndHandles(
        {
          fromId: drawingArrow.fromId,
          toId: drawingArrow.toId,
          fromPoint: drawingArrow.fromPoint,
          toPoint: drawingArrow.currentPoint,
          routing: activeArrowRouting
        },
        boxMap,
        activeArrowRouting
      )
    : null
  return (
    <svg
      className="pointer-events-none absolute left-0 top-0 overflow-visible"
      width="1"
      height="1"
    >
      <defs>
        <marker
          id="orca-space-arrowhead-default"
          markerWidth="10"
          markerHeight="8"
          refX="9.2"
          refY="4"
          orient="auto"
        >
          <path d="M0,0.5 L10,4 L0,7.5 Z" fill={DEFAULT_ARROW_STROKE} />
        </marker>
        {STICKY_COLORS.map((c) => (
          <marker
            key={c}
            id={`orca-space-arrowhead-${c}`}
            markerWidth="10"
            markerHeight="8"
            refX="9.2"
            refY="4"
            orient="auto"
          >
            <path d="M0,0.5 L10,4 L0,7.5 Z" fill={STICKY_COLOR_STYLE[c].stroke} />
          </marker>
        ))}
      </defs>
      {arrows.map((arrow) => {
        if (isArrowHidden(arrow, hiddenStickyIds)) {
          return null
        }
        const withBend =
          bendingArrow && bendingArrow.arrowId === arrow.id
            ? { ...arrow, bend: bendingArrow.bend }
            : arrow
        const effectiveArrow =
          reconnectingArrow && reconnectingArrow.arrowId === arrow.id
            ? reconnectingArrow.end === 'from'
              ? {
                  ...withBend,
                  fromId: reconnectingArrow.snapId,
                  fromPoint: reconnectingArrow.point
                }
              : {
                  ...withBend,
                  toId: reconnectingArrow.snapId,
                  toPoint: reconnectingArrow.point
                }
            : withBend
        const geom = resolveArrowPathAndHandles(effectiveArrow, boxMap)
        if (!geom) {
          return null
        }
        const colorKey = arrow.color && STICKY_COLOR_STYLE[arrow.color] ? arrow.color : null
        const stroke = colorKey ? STICKY_COLOR_STYLE[colorKey].stroke : DEFAULT_ARROW_STROKE
        const markerId = colorKey
          ? `orca-space-arrowhead-${colorKey}`
          : 'orca-space-arrowhead-default'
        const isSelected = selectedArrowId === arrow.id
        const isHovered = hoveredArrowId === arrow.id
        const dashPattern = arrow.dash === 'dashed' ? '8 6' : isSelected ? '7 4' : undefined
        return (
          <g
            key={arrow.id}
            data-space-arrow={arrow.id}
            onMouseEnter={() => setHoveredArrowId(arrow.id)}
            onMouseLeave={() => setHoveredArrowId((cur) => (cur === arrow.id ? null : cur))}
          >
            <path
              d={geom.path}
              fill="none"
              stroke="transparent"
              strokeWidth={28}
              className="pointer-events-auto cursor-pointer"
              onPointerDown={(event) => {
                if (toolMode === 'eraser') {
                  startEraserSwipe(event)
                  return
                }
                event.stopPropagation()
                setSelectedArrowId(arrow.id)
                setSelectedStickyIds([])
              }}
              onClick={(event) => {
                event.stopPropagation()
                setSelectedArrowId(arrow.id)
              }}
              onDoubleClick={(event) => {
                event.stopPropagation()
                setSelectedArrowId(arrow.id)
                setEditingArrowId(arrow.id)
                setArrowLabelDraft(arrow.label ?? '')
              }}
            />
            <path
              d={geom.path}
              fill="none"
              stroke={stroke}
              strokeWidth={isSelected ? 4 : isHovered ? 3.5 : 2.75}
              strokeDasharray={dashPattern}
              markerEnd={`url(#${markerId})`}
            />
            {/* Quickdraw midpoint bend diamond handle: drag perpendicular to bend arc, double-click to straighten */}
            {isSelected || isHovered || (bendingArrow && bendingArrow.arrowId === arrow.id) ? (
              <g
                className="pointer-events-auto cursor-grab active:cursor-grabbing"
                onPointerDown={startArrowBendDrag(arrow, geom.start, geom.end)}
                onDoubleClick={(event) => {
                  event.stopPropagation()
                  onUpdateArrow?.(arrow.id, { bend: undefined })
                }}
              >
                <title>Drag to bend arrow curve · Double-click to reset</title>
                <circle cx={geom.bendHandle.x} cy={geom.bendHandle.y} r={14} fill="transparent" />
                <rect
                  x={geom.bendHandle.x - 5.5}
                  y={geom.bendHandle.y - 5.5}
                  width={11}
                  height={11}
                  rx={2.5}
                  transform={`rotate(45 ${geom.bendHandle.x} ${geom.bendHandle.y})`}
                  fill="#09090b"
                  stroke={stroke}
                  strokeWidth={2.5}
                />
              </g>
            ) : null}
            {/* Draggable Endpoint Hit-Targets (always active) + Visible Handles on hover/select/arrow-tool */}
            <g
              className="pointer-events-auto cursor-grab active:cursor-grabbing"
              onPointerDown={startArrowEndpointDrag(arrow, 'from')}
            >
              <title>Drag to move arrow start to another Space, Shape, Note, Text, or point</title>
              <circle cx={geom.start.x} cy={geom.start.y} r={18} fill="transparent" />
              {isSelected || isHovered || toolMode === 'arrow' ? (
                <circle
                  cx={geom.start.x}
                  cy={geom.start.y}
                  r={isSelected || isHovered ? 8.5 : 5}
                  fill="#09090b"
                  stroke={stroke}
                  strokeWidth={isSelected || isHovered ? 2.75 : 2}
                />
              ) : null}
            </g>
            <g
              className="pointer-events-auto cursor-grab active:cursor-grabbing"
              onPointerDown={startArrowEndpointDrag(arrow, 'to')}
            >
              <title>Drag to move arrow tip to another Space, Shape, Note, Text, or point</title>
              <circle cx={geom.end.x} cy={geom.end.y} r={18} fill="transparent" />
              {isSelected || isHovered || toolMode === 'arrow' ? (
                <circle
                  cx={geom.end.x}
                  cy={geom.end.y}
                  r={isSelected || isHovered ? 8.5 : 5}
                  fill={stroke}
                  stroke="#09090b"
                  strokeWidth={isSelected || isHovered ? 2.5 : 1.5}
                />
              ) : null}
            </g>
          </g>
        )
      })}
      {previewGeometry ? (
        <path
          d={previewGeometry.path}
          fill="none"
          stroke={DEFAULT_ARROW_STROKE}
          strokeWidth={3}
          strokeDasharray={activeArrowDash === 'dashed' ? '8 6' : '6 4'}
          markerEnd="url(#orca-space-arrowhead-default)"
        />
      ) : null}
    </svg>
  )
}

// WS-0 (TASK_16 wave 2): live draw previews (shape, frame), multi-select bounds and the marquee box,
// moved verbatim from space-canvas.tsx. Owner: none.
import type { CanvasCtx } from '../canvas-ctx'
import { LEVEL_STYLE, normalizeMarqueeRect, resolveWhiteboardSurfaceStyle } from '../../core/space'

export function DrawPreview({ ctx }: { ctx: CanvasCtx }): React.JSX.Element {
  const { boxMap, drawingFrameRect, drawingShapeRect, effectiveSelectedIds, marqueeRect } = ctx
  return (
    <>
      {/* Live canvas draw-preview boxes (Shape, Frame, and Box-Marquee) */}
      {drawingShapeRect
        ? (() => {
            const r = normalizeMarqueeRect(drawingShapeRect.start, drawingShapeRect.current)
            const w = Math.max(24, Math.round(r.w))
            const h = Math.max(20, Math.round(r.h))
            const surf = resolveWhiteboardSurfaceStyle({
              kind: 'shape',
              color: drawingShapeRect.color,
              fillStyle: drawingShapeRect.fillStyle,
              borderStyle: 'dashed'
            })
            const st = drawingShapeRect.shapeType
            const isSvg = st === 'ellipse' || st === 'diamond'
            return (
              <div
                style={{
                  left: r.x,
                  top: r.y,
                  width: w,
                  height: h,
                  ...(!isSvg
                    ? {
                        backgroundColor: surf.backgroundColor,
                        borderColor: surf.borderColor,
                        borderWidth: 2,
                        borderStyle: 'dashed'
                      }
                    : {})
                }}
                className={`pointer-events-none absolute z-40 flex items-center justify-center ${
                  st === 'pill' ? 'rounded-full' : st === 'rect' ? 'rounded-md' : 'rounded-2xl'
                }`}
              >
                {isSvg ? (
                  <svg
                    viewBox={`0 0 ${w} ${h}`}
                    className="pointer-events-none absolute inset-0 size-full overflow-visible"
                  >
                    {st === 'ellipse' ? (
                      <ellipse
                        cx={w / 2}
                        cy={h / 2}
                        rx={Math.max(1, w / 2 - 2)}
                        ry={Math.max(1, h / 2 - 2)}
                        fill={surf.backgroundColor}
                        stroke={surf.borderColor}
                        strokeWidth={2}
                        strokeDasharray="6 4"
                      />
                    ) : (
                      <polygon
                        points={`${w / 2},2 ${w - 2},${h / 2} ${w / 2},${h - 2} 2,${h / 2}`}
                        fill={surf.backgroundColor}
                        stroke={surf.borderColor}
                        strokeWidth={2}
                        strokeDasharray="6 4"
                      />
                    )}
                  </svg>
                ) : null}
                {w >= 64 && h >= 36 ? (
                  <span className="relative z-10 rounded-md bg-zinc-950/85 px-1.5 py-0.5 font-mono text-[10px] font-semibold text-sky-300 shadow">
                    {Math.max(80, w)} × {Math.max(52, h)}
                  </span>
                ) : null}
              </div>
            )
          })()
        : null}

      {drawingFrameRect
        ? (() => {
            const r = normalizeMarqueeRect(drawingFrameRect.start, drawingFrameRect.current)
            const w = Math.max(40, Math.round(r.w))
            const h = Math.max(32, Math.round(r.h))
            const st = LEVEL_STYLE[drawingFrameRect.level]
            return (
              <div
                style={{ left: r.x, top: r.y, width: w, height: h }}
                className="pointer-events-none absolute z-40 flex flex-col overflow-hidden rounded-3xl border-2 border-dashed border-sky-400/85 bg-zinc-950/45 backdrop-blur-xs"
              >
                <div className={`h-2 w-full ${st.band}`} />
                <div className="flex flex-1 items-center justify-center">
                  <span className="rounded-lg bg-zinc-950/90 px-2 py-1 font-mono text-[11px] font-semibold text-sky-200 shadow">
                    {st.shortLabel} Space · {Math.max(320, w)} × {Math.max(200, h)}
                  </span>
                </div>
              </div>
            )
          })()
        : null}

      {effectiveSelectedIds.length >= 2
        ? (() => {
            let minX = Number.POSITIVE_INFINITY
            let minY = Number.POSITIVE_INFINITY
            let maxX = Number.NEGATIVE_INFINITY
            let maxY = Number.NEGATIVE_INFINITY
            for (const id of effectiveSelectedIds) {
              const b = boxMap.get(id)
              if (b) {
                minX = Math.min(minX, b.x)
                minY = Math.min(minY, b.y)
                maxX = Math.max(maxX, b.x + b.w)
                maxY = Math.max(maxY, b.y + b.h)
              }
            }
            if (!Number.isFinite(minX)) {
              return null
            }
            return (
              <div
                data-multiselect-bounds="true"
                style={{
                  left: minX - 10,
                  top: minY - 10,
                  width: maxX - minX + 20,
                  height: maxY - minY + 20
                }}
                className="pointer-events-none absolute z-20 rounded-2xl border border-dashed border-sky-400/65 bg-sky-400/[0.035]"
              >
                <span className="absolute -top-1.5 -left-1.5 size-2.5 rounded-xs border border-sky-300 bg-zinc-950 shadow" />
                <span className="absolute -top-1.5 -right-1.5 size-2.5 rounded-xs border border-sky-300 bg-zinc-950 shadow" />
                <span className="absolute -bottom-1.5 -left-1.5 size-2.5 rounded-xs border border-sky-300 bg-zinc-950 shadow" />
                <span className="absolute -right-1.5 -bottom-1.5 size-2.5 rounded-xs border border-sky-300 bg-zinc-950 shadow" />
              </div>
            )
          })()
        : null}

      {marqueeRect
        ? (() => {
            const r = normalizeMarqueeRect(marqueeRect.start, marqueeRect.current)
            return (
              <div
                style={{ left: r.x, top: r.y, width: r.w, height: r.h }}
                className="pointer-events-none absolute z-40 rounded-sm border border-sky-400 bg-sky-400/12 ring-1 ring-sky-400/25"
              />
            )
          })()
        : null}
    </>
  )
}

// WS-0 (TASK_16 wave 2): notes, shapes and text cards (sortedStickies.map), moved verbatim from
// space-canvas.tsx. Owner: WS-C (hidden / groupId / name / opacity land here).
// WS-C: hidden stickies are skipped, `opacity` is applied, a double-click enters a group (gestures).
import type { CanvasCtx, CanvasHandlers } from '../canvas-ctx'
import { QuickConnectPorts } from '../canvas-parts'
import {
  STICKY_COLOR_STYLE,
  type SpaceStickyNote,
  type StickyColor,
  resolveWhiteboardSurfaceStyle
} from '../../core/space'
import { isImeOwnedKeyboardEvent } from '../../core/ime-guard'
import { Lock } from 'lucide-react'

/** WS-C: `data-whiteboard-group` only on grouped stickies (old boards render the same DOM). */
function layerAttrs(sticky: SpaceStickyNote): Record<string, string> {
  return sticky.groupId ? { 'data-whiteboard-group': sticky.groupId } : {}
}

/** WS-C: the layer opacity (0–1); absent = no style key at all. */
function opacityStyle(sticky: SpaceStickyNote): React.CSSProperties {
  return sticky.opacity !== undefined ? { opacity: sticky.opacity } : {}
}

export function StickyLayer({ ctx, g }: { ctx: CanvasCtx; g: CanvasHandlers }): React.JSX.Element {
  const {
    arrowSnapTargetId,
    boxMap,
    editingStickyId,
    onUpdateStickyNote,
    selectedStickyIdSet,
    sortedStickies,
    stickyOffset,
    stickySizeOverride
  } = ctx
  const {
    startArrowDrag,
    commitStickyEdit,
    handleStickyTextareaBlur,
    onStickyDoubleClick,
    startStickyDrag,
    startStickyResize
  } = g
  return (
    <>
      {sortedStickies.map((sticky) => {
        // WS-C: a hidden sticky is not drawn (no DOM = no hit-test); it stays in the layers panel.
        if (sticky.hidden) {
          return null
        }
        const offset = stickyOffset[sticky.id]
        const sizeOvr = stickySizeOverride[sticky.id]
        const kind = sticky.kind ?? 'note'
        const isSelected = selectedStickyIdSet.has(sticky.id)
        const isEditing = editingStickyId === sticky.id && !sticky.locked
        const isArrowTarget = arrowSnapTargetId === sticky.id
        const colorKey: StickyColor =
          sticky.color && STICKY_COLOR_STYLE[sticky.color] ? sticky.color : 'amber'
        const box = boxMap.get(sticky.id)
        const effectiveW = box?.w ?? (sticky.w || 220)
        const effectiveH = box?.h ?? (sticky.h || 140)
        const fontClass =
          sticky.fontFamily === 'serif'
            ? 'font-serif'
            : sticky.fontFamily === 'mono'
              ? 'font-mono'
              : 'font-sans'
        const defaultAlign = kind === 'shape' ? 'center' : 'left'
        const effectiveAlign = sticky.textAlign ?? defaultAlign
        const alignClass =
          effectiveAlign === 'center'
            ? 'text-center'
            : effectiveAlign === 'right'
              ? 'text-right'
              : 'text-left'

        if (kind === 'shape') {
          const shapeType = sticky.shapeType ?? 'rounded'
          const effectiveFontSize = sizeOvr?.fontSize ?? sticky.fontSize ?? 16
          const effectiveWeight = sticky.fontWeight ?? 'semibold'
          const weightClass =
            effectiveWeight === 'bold'
              ? 'font-bold'
              : effectiveWeight === 'semibold'
                ? 'font-semibold'
                : 'font-normal'
          const surface = resolveWhiteboardSurfaceStyle({
            kind: 'shape',
            color: colorKey,
            fillStyle: sticky.fillStyle ?? 'soft',
            borderStyle: sticky.borderStyle ?? 'solid'
          })
          const isSvgShape = shapeType === 'ellipse' || shapeType === 'diamond'
          const shapeRadiusClass =
            shapeType === 'pill'
              ? 'rounded-full'
              : shapeType === 'rect'
                ? 'rounded-md'
                : 'rounded-2xl'
          const padClass =
            shapeType === 'diamond'
              ? 'px-7 py-5'
              : shapeType === 'ellipse'
                ? 'px-5 py-4'
                : shapeType === 'pill'
                  ? 'px-5 py-2.5'
                  : 'px-3.5 py-2.5'

          return (
            <div
              key={sticky.id}
              data-space-sticky={sticky.id}
              data-whiteboard-shape={shapeType}
              {...layerAttrs(sticky)}
              onPointerDown={startStickyDrag(sticky)}
              onDoubleClick={onStickyDoubleClick(sticky)}
              style={{
                ...opacityStyle(sticky),
                left: sticky.x + (offset?.x ?? 0),
                top: sticky.y + (offset?.y ?? 0),
                width: effectiveW,
                minHeight: effectiveH,
                color: surface.textColor,
                ...(!isSvgShape
                  ? {
                      backgroundColor: surface.backgroundColor,
                      borderColor: surface.borderColor,
                      borderWidth: surface.borderStyle === 'none' ? 0 : 2,
                      borderStyle: surface.borderStyle === 'dashed' ? 'dashed' : 'solid'
                    }
                  : {})
              }}
              className={`pointer-events-auto group/shape absolute z-10 flex flex-col justify-center overflow-visible transition-shadow ${
                isSvgShape ? 'rounded-xl' : `${shapeRadiusClass} shadow-lg`
              } ${!isSvgShape && surface.backdropBlur ? 'backdrop-blur-md' : ''} ${
                sticky.locked
                  ? 'cursor-default'
                  : isEditing
                    ? 'cursor-text'
                    : 'cursor-grab active:cursor-grabbing'
              } ${
                isArrowTarget
                  ? 'ring-2 ring-sky-400 shadow-[0_0_24px_rgba(56,189,248,0.45)]'
                  : isEditing
                    ? 'ring-2 ring-sky-400 shadow-[0_0_24px_rgba(56,189,248,0.28)]'
                    : isSelected
                      ? 'ring-2 ring-sky-400/90'
                      : ''
              }`}
            >
              {isSvgShape ? (
                <svg
                  viewBox={`0 0 ${effectiveW} ${effectiveH}`}
                  className="pointer-events-none absolute inset-0 size-full overflow-visible drop-shadow-lg"
                  aria-hidden="true"
                >
                  {shapeType === 'ellipse' ? (
                    <ellipse
                      cx={effectiveW / 2}
                      cy={effectiveH / 2}
                      rx={Math.max(2, effectiveW / 2 - 2)}
                      ry={Math.max(2, effectiveH / 2 - 2)}
                      fill={surface.backgroundColor}
                      stroke={surface.borderStyle === 'none' ? 'transparent' : surface.borderColor}
                      strokeWidth={surface.borderStyle === 'none' ? 0 : 2}
                      strokeDasharray={surface.borderStyle === 'dashed' ? '7 5' : undefined}
                    />
                  ) : (
                    <polygon
                      points={`${effectiveW / 2},2 ${effectiveW - 2},${effectiveH / 2} ${effectiveW / 2},${effectiveH - 2} 2,${effectiveH / 2}`}
                      strokeLinejoin="round"
                      fill={surface.backgroundColor}
                      stroke={surface.borderStyle === 'none' ? 'transparent' : surface.borderColor}
                      strokeWidth={surface.borderStyle === 'none' ? 0 : 2}
                      strokeDasharray={surface.borderStyle === 'dashed' ? '7 5' : undefined}
                    />
                  )}
                </svg>
              ) : null}

              {sticky.locked ? (
                <span
                  title="Locked"
                  className="pointer-events-none absolute top-1.5 right-1.5 z-20 flex size-5 items-center justify-center rounded-full bg-zinc-950/80 text-amber-300 shadow"
                >
                  <Lock className="size-3" />
                </span>
              ) : null}

              <QuickConnectPorts
                visible={isSelected && !isEditing}
                hoverClass="group-hover/shape:opacity-85"
                onStartArrow={(event) => startArrowDrag(event, sticky.id)}
              />

              <div
                className={`relative z-10 flex w-full flex-1 items-center justify-center ${padClass}`}
              >
                {isEditing ? (
                  <textarea
                    autoFocus
                    value={sticky.text}
                    rows={Math.max(1, sticky.text.split('\n').length)}
                    onPointerDown={(event) => event.stopPropagation()}
                    onClick={(event) => event.stopPropagation()}
                    onBlur={(event) => handleStickyTextareaBlur(sticky, event)}
                    onKeyDown={(event) => {
                      if (isImeOwnedKeyboardEvent(event)) {
                        return
                      }
                      if (
                        event.key === 'Escape' ||
                        (event.key === 'Enter' && (event.metaKey || event.ctrlKey))
                      ) {
                        event.preventDefault()
                        commitStickyEdit(sticky)
                      }
                    }}
                    onChange={(event) =>
                      onUpdateStickyNote?.(sticky.id, { text: event.target.value })
                    }
                    placeholder="Type label…"
                    style={{
                      fontSize: `${effectiveFontSize}px`,
                      lineHeight: 1.28,
                      color: surface.textColor
                    }}
                    className={`w-full resize-none rounded-lg bg-transparent caret-sky-400 outline-none selection:bg-sky-400/35 ${fontClass} ${weightClass} ${alignClass}`}
                  />
                ) : (
                  <div
                    style={{
                      fontSize: `${effectiveFontSize}px`,
                      lineHeight: 1.28,
                      color: surface.textColor
                    }}
                    className={`pointer-events-none w-full whitespace-pre-wrap break-words ${fontClass} ${weightClass} ${alignClass}`}
                  >
                    {sticky.text ||
                      (isSelected ? (
                        <span
                          style={{ color: surface.placeholderColor }}
                          className="text-xs font-normal"
                        >
                          Double-click or press Enter to label…
                        </span>
                      ) : null)}
                  </div>
                )}
              </div>

              {!sticky.locked ? (
                <>
                  <div
                    data-sticky-resize="true"
                    title="Drag right edge to widen shape"
                    onPointerDown={startStickyResize(sticky, 'e')}
                    className="absolute top-3 bottom-5 -right-1 z-20 w-2.5 cursor-ew-resize"
                  />
                  <div
                    data-sticky-resize="true"
                    title="Drag bottom edge to resize shape height"
                    onPointerDown={startStickyResize(sticky, 's')}
                    className="absolute right-5 -bottom-1 left-3 z-20 h-2.5 cursor-ns-resize"
                  />
                  <div
                    data-sticky-resize="true"
                    title="Drag corner to resize shape (hold Shift for aspect lock)"
                    onPointerDown={startStickyResize(sticky, 'se')}
                    className={`absolute -right-2 -bottom-2 z-20 flex size-6 cursor-nwse-resize items-center justify-center rounded-lg border text-[11px] font-bold shadow-md transition ${
                      isSelected || isEditing
                        ? 'border-sky-300 bg-sky-500 text-zinc-950 opacity-100 hover:scale-110'
                        : 'border-white/20 bg-zinc-900/90 text-zinc-200 opacity-0 group-hover/shape:opacity-100 hover:border-sky-400'
                    }`}
                  >
                    ↘
                  </div>
                </>
              ) : null}
            </div>
          )
        }

        if (kind === 'text') {
          const hasBg = Boolean(sticky.fillStyle && sticky.fillStyle !== 'none')
          const effectiveFontSize = sizeOvr?.fontSize ?? sticky.fontSize ?? (hasBg ? 18 : 36)
          const effectiveWeight = sticky.fontWeight ?? (hasBg ? 'semibold' : 'bold')
          const weightClass =
            effectiveWeight === 'bold'
              ? 'font-bold'
              : effectiveWeight === 'semibold'
                ? 'font-semibold'
                : 'font-normal'
          const surface = resolveWhiteboardSurfaceStyle({
            kind: 'text',
            color: colorKey,
            fillStyle: sticky.fillStyle ?? 'none',
            borderStyle: sticky.borderStyle ?? (hasBg ? 'solid' : 'none')
          })

          return (
            <div
              key={sticky.id}
              data-space-sticky={sticky.id}
              {...layerAttrs(sticky)}
              onPointerDown={startStickyDrag(sticky)}
              onDoubleClick={onStickyDoubleClick(sticky)}
              style={{
                ...opacityStyle(sticky),
                left: sticky.x + (offset?.x ?? 0),
                top: sticky.y + (offset?.y ?? 0),
                width: effectiveW,
                minHeight: effectiveH,
                color: surface.textColor,
                ...(hasBg
                  ? {
                      backgroundColor: surface.backgroundColor,
                      borderColor: surface.borderColor,
                      borderWidth: surface.borderStyle === 'none' ? 0 : 2,
                      borderStyle: surface.borderStyle === 'dashed' ? 'dashed' : 'solid'
                    }
                  : {})
              }}
              className={`pointer-events-auto group/text absolute z-10 flex flex-col justify-center transition ${
                hasBg ? 'rounded-xl shadow-lg' : 'rounded-2xl'
              } ${hasBg && surface.backdropBlur ? 'backdrop-blur-md' : ''} ${
                sticky.locked
                  ? 'cursor-default'
                  : isEditing
                    ? 'cursor-text'
                    : 'cursor-grab active:cursor-grabbing'
              } ${
                isArrowTarget
                  ? 'ring-2 ring-sky-400 shadow-[0_0_24px_rgba(56,189,248,0.45)]'
                  : hasBg
                    ? isSelected || isEditing
                      ? 'ring-2 ring-sky-400/90'
                      : ''
                    : isSelected || isEditing
                      ? 'border-2 border-dashed border-sky-400/80 bg-zinc-900/45 shadow-lg'
                      : 'border-2 border-transparent hover:border-dashed hover:border-white/30'
              }`}
            >
              {sticky.locked ? (
                <span
                  title="Locked"
                  className="pointer-events-none absolute top-1 right-1 z-20 flex size-5 items-center justify-center rounded-full bg-zinc-950/80 text-amber-300 shadow"
                >
                  <Lock className="size-3" />
                </span>
              ) : null}

              <QuickConnectPorts
                visible={isSelected && !isEditing}
                hoverClass="group-hover/text:opacity-85"
                onStartArrow={(event) => startArrowDrag(event, sticky.id)}
              />

              {isEditing ? (
                <textarea
                  autoFocus
                  value={sticky.text}
                  onPointerDown={(event) => event.stopPropagation()}
                  onClick={(event) => event.stopPropagation()}
                  onBlur={(event) => handleStickyTextareaBlur(sticky, event)}
                  onKeyDown={(event) => {
                    if (isImeOwnedKeyboardEvent(event)) {
                      return
                    }
                    if (
                      event.key === 'Escape' ||
                      (event.key === 'Enter' && (event.metaKey || event.ctrlKey))
                    ) {
                      event.preventDefault()
                      commitStickyEdit(sticky)
                    }
                  }}
                  onChange={(event) =>
                    onUpdateStickyNote?.(sticky.id, { text: event.target.value })
                  }
                  placeholder="Write something…"
                  style={{
                    fontSize: `${effectiveFontSize}px`,
                    lineHeight: 1.2,
                    color: surface.textColor
                  }}
                  className={`w-full flex-1 resize-none bg-transparent outline-none ${
                    hasBg ? 'px-4 py-2.5' : 'p-2.5'
                  } ${fontClass} ${weightClass} ${alignClass}`}
                />
              ) : (
                <div
                  style={{
                    fontSize: `${effectiveFontSize}px`,
                    lineHeight: 1.2,
                    color: surface.textColor
                  }}
                  className={`pointer-events-none w-full flex-1 whitespace-pre-wrap break-words ${
                    hasBg ? 'px-4 py-2.5' : 'p-2.5'
                  } ${fontClass} ${weightClass} ${alignClass}`}
                >
                  {sticky.text || (
                    <span style={{ color: surface.placeholderColor }}>Write something…</span>
                  )}
                </div>
              )}

              {!sticky.locked ? (
                <>
                  <div
                    data-sticky-resize="true"
                    title="Drag right edge to adjust text width"
                    onPointerDown={startStickyResize(sticky, 'width')}
                    className={`absolute top-2.5 bottom-6 -right-1.5 flex w-3 cursor-ew-resize items-center justify-center rounded-full transition ${
                      isSelected || isEditing
                        ? 'bg-sky-400/55 opacity-100 hover:bg-sky-400'
                        : 'bg-white/25 opacity-0 group-hover/text:opacity-75 hover:bg-sky-400'
                    }`}
                  />
                  <div
                    data-sticky-resize="true"
                    title="Drag corner to scale text size"
                    onPointerDown={startStickyResize(sticky, 'scale')}
                    className={`absolute -right-2 -bottom-2 flex size-6 cursor-nwse-resize items-center justify-center rounded-lg border text-[11px] font-bold shadow-md transition ${
                      isSelected || isEditing
                        ? 'border-sky-300 bg-sky-500 text-zinc-950 opacity-100 hover:scale-110'
                        : 'border-white/20 bg-zinc-900/90 text-zinc-200 opacity-0 group-hover/text:opacity-100 hover:border-sky-400'
                    }`}
                  >
                    ↘
                  </div>
                </>
              ) : null}
            </div>
          )
        }

        // Sleek AFFiNE Sticky Note card (`kind === 'note'`) — zero inline button clutter; floating inspector handles controls
        const effectiveFontSize = sizeOvr?.fontSize ?? sticky.fontSize ?? 14
        const effectiveWeight = sticky.fontWeight ?? 'normal'
        const weightClass =
          effectiveWeight === 'bold'
            ? 'font-bold'
            : effectiveWeight === 'semibold'
              ? 'font-semibold'
              : 'font-normal'
        const surface = resolveWhiteboardSurfaceStyle({
          kind: 'note',
          color: colorKey,
          fillStyle: sticky.fillStyle ?? 'soft',
          borderStyle: sticky.borderStyle ?? 'solid'
        })

        return (
          <div
            key={sticky.id}
            data-space-sticky={sticky.id}
            {...layerAttrs(sticky)}
            onPointerDown={startStickyDrag(sticky)}
            onDoubleClick={onStickyDoubleClick(sticky)}
            style={{
              ...opacityStyle(sticky),
              left: sticky.x + (offset?.x ?? 0),
              top: sticky.y + (offset?.y ?? 0),
              width: effectiveW,
              minHeight: effectiveH,
              backgroundColor: surface.backgroundColor,
              borderColor: surface.borderColor,
              borderWidth: surface.borderStyle === 'none' ? 0 : 1.5,
              borderStyle: surface.borderStyle === 'dashed' ? 'dashed' : 'solid',
              color: surface.textColor
            }}
            className={`pointer-events-auto group/sticky absolute z-10 flex flex-col overflow-visible rounded-2xl shadow-xl transition-shadow ${
              surface.backdropBlur ? 'backdrop-blur-md' : ''
            } ${
              sticky.locked
                ? 'cursor-default'
                : isEditing
                  ? 'cursor-text'
                  : 'cursor-grab active:cursor-grabbing'
            } ${
              isArrowTarget
                ? 'ring-2 ring-sky-400 shadow-[0_0_24px_rgba(56,189,248,0.45)]'
                : isSelected
                  ? 'ring-2 ring-sky-400/90'
                  : ''
            }`}
          >
            {/* Minimal top accent strip */}
            <div className="flex h-3 w-full items-center justify-between rounded-t-2xl px-2.5 pt-1">
              <span
                style={{ backgroundColor: surface.accentHex }}
                className="h-1 w-8 rounded-full opacity-55"
              />
              {sticky.locked ? <Lock className="size-3 text-amber-400" /> : null}
            </div>

            <QuickConnectPorts
              visible={isSelected && !isEditing}
              hoverClass="group-hover/sticky:opacity-85"
              onStartArrow={(event) => startArrowDrag(event, sticky.id)}
            />

            {isEditing ? (
              <textarea
                autoFocus
                value={sticky.text}
                onPointerDown={(event) => event.stopPropagation()}
                onClick={(event) => event.stopPropagation()}
                onBlur={(event) => handleStickyTextareaBlur(sticky, event)}
                onKeyDown={(event) => {
                  if (isImeOwnedKeyboardEvent(event)) {
                    return
                  }
                  if (
                    event.key === 'Escape' ||
                    (event.key === 'Enter' && (event.metaKey || event.ctrlKey))
                  ) {
                    event.preventDefault()
                    commitStickyEdit(sticky)
                  }
                }}
                onChange={(event) => onUpdateStickyNote?.(sticky.id, { text: event.target.value })}
                placeholder="Write a note…"
                style={{
                  fontSize: `${effectiveFontSize}px`,
                  height: effectiveH - 22,
                  color: surface.textColor
                }}
                className={`min-h-[84px] w-full flex-1 resize-none bg-transparent px-3.5 py-2.5 leading-relaxed outline-none ${fontClass} ${weightClass} ${alignClass}`}
              />
            ) : (
              <div
                style={{
                  fontSize: `${effectiveFontSize}px`,
                  minHeight: effectiveH - 22,
                  color: surface.textColor
                }}
                className={`pointer-events-none w-full flex-1 whitespace-pre-wrap break-words px-3.5 py-2.5 leading-relaxed ${fontClass} ${weightClass} ${alignClass}`}
              >
                {sticky.text || (
                  <span style={{ color: surface.placeholderColor }}>Double-click to write…</span>
                )}
              </div>
            )}

            {/* Subtle AFFiNE folded paper corner */}
            <span
              aria-hidden="true"
              className="pointer-events-none absolute right-0 bottom-0 size-3.5 rounded-tl-md rounded-br-2xl bg-black/14"
            />

            {!sticky.locked ? (
              <>
                <div
                  data-sticky-resize="true"
                  title="Drag right edge to widen sticky note"
                  onPointerDown={startStickyResize(sticky, 'e')}
                  className="absolute top-4 bottom-6 -right-1 w-2.5 cursor-ew-resize"
                />
                <div
                  data-sticky-resize="true"
                  title="Drag bottom edge to lengthen sticky note"
                  onPointerDown={startStickyResize(sticky, 's')}
                  className="absolute right-6 -bottom-1 left-3 h-2.5 cursor-ns-resize"
                />
                <div
                  data-sticky-resize="true"
                  title="Drag corner to resize sticky note"
                  onPointerDown={startStickyResize(sticky, 'se')}
                  className={`absolute right-1 bottom-1 flex size-6 cursor-nwse-resize items-center justify-center rounded-lg text-[11px] transition ${
                    isSelected || isEditing
                      ? 'bg-sky-500 text-zinc-950 opacity-100'
                      : 'bg-black/20 text-current opacity-0 group-hover/sticky:opacity-80 hover:opacity-100'
                  }`}
                >
                  ↘
                </div>
              </>
            ) : null}
          </div>
        )
      })}
    </>
  )
}

// WS-0 (TASK_16 wave 2): one Space tile's derived values and its two-deck header (emoji / level
// pickers, title, badges), moved verbatim from the tiles.map body in space-canvas.tsx. Owner: none.
import type { CanvasCtx } from '../canvas-ctx'
import type { SpaceTile } from '../../core/space'
import {
  BENCH_KEY,
  CARD_WIDTH,
  GAP,
  LEVEL_STYLE,
  SPACE_EMOJI_CATEGORIES,
  SPACE_LEVELS,
  TEAM_PADDING,
  defaultSpaceEmoji,
  isImageEmoji,
  resolveSpaceBgStyle
} from '../../core/space'
import { SpaceEmojiGraphic, readCustomEmojiFile } from '../../space-emoji'
import { TitleText } from '../canvas-parts'
import { isImeOwnedKeyboardEvent } from '../../core/ime-guard'
import { isOverTile } from '../../space-drag'

/** Per-tile values the tile body and the header both read (was the top of the tiles.map callback). */
export function tileLocals(ctx: CanvasCtx, tile: SpaceTile) {
  const {
    agentsBySpace,
    arrowSnapTargetId,
    drag,
    emojiCategoryTab,
    goalsById,
    inspectedAgentId,
    selectedGoalId,
    tileOffset,
    tileSizeOverride
  } = ctx
  const goal = goalsById.get(tile.key)
  const members = agentsBySpace.get(tile.key) ?? []
  const waitingCount = members.filter((a) => a.attention).length
  const sizeOvr = tileSizeOverride[tile.key]
  const effectiveW = sizeOvr?.w ?? tile.w
  const effectiveH = sizeOvr?.h ?? tile.h
  const columns = Math.max(
    1,
    Math.min(8, Math.floor((effectiveW - TEAM_PADDING * 2 + GAP) / (CARD_WIDTH + GAP)))
  )
  const over = isOverTile(drag, tile.key)
  const isArrowTarget = arrowSnapTargetId === tile.key
  const offset = tileOffset[tile.key]
  const isBench = tile.key === BENCH_KEY
  const style = goal ? LEVEL_STYLE[goal.level] : null
  const isSide = goal?.level === 'side'
  const openTasks = goal ? goal.tasks.filter((task) => !task.done) : []
  const openAsks = goal ? goal.asks.filter((ask) => ask.status === 'open') : []
  const doneOutcomes = goal ? goal.outcomes.filter((item) => item.done).length : 0
  const nextOutcome =
    goal && goal.outcomes.length > 0
      ? (goal.outcomes.find((o) => !o.done) ?? goal.outcomes.at(-1))
      : undefined
  const isSelected = Boolean(goal && selectedGoalId === goal.id)
  const hasInspectedMember = Boolean(
    inspectedAgentId && members.some((m) => m.id === inspectedAgentId)
  )
  const displayEmoji = goal
    ? goal.emoji || defaultSpaceEmoji(goal.title, goal.level, goal.emoji)
    : '🧰'
  const bgStyle = resolveSpaceBgStyle(goal?.bgColor)
  const isLightBg = bgStyle.isLight
  const titleFontSize = goal?.titleSize ?? 16
  const activeEmojiCat =
    SPACE_EMOJI_CATEGORIES.find((c) => c.id === emojiCategoryTab) ?? SPACE_EMOJI_CATEGORIES[0]!
  return {
    goal,
    members,
    waitingCount,
    sizeOvr,
    effectiveW,
    effectiveH,
    columns,
    over,
    isArrowTarget,
    offset,
    isBench,
    style,
    isSide,
    openTasks,
    openAsks,
    doneOutcomes,
    nextOutcome,
    isSelected,
    hasInspectedMember,
    displayEmoji,
    bgStyle,
    isLightBg,
    titleFontSize,
    activeEmojiCat
  }
}

/** U-37: Space titles stay >= 11 px on screen (like the Bench header), but never wider than the tile.
 *  Why: at Fit 55 % a 16 px title was ~9 px, and ~6 px with a smaller titleSize. */
export const TILE_TITLE_MIN_SCREEN_PX = 11
export function tileTitleFont(base: number, scale: number, tileW: number, chars: number): number {
  const wanted = Math.max(base, TILE_TITLE_MIN_SCREEN_PX / Math.max(scale, 0.05))
  // The title shares its row with the icon (~44 px) and padding (~32 px).
  const room = Math.max(0, tileW - 76)
  const cap = room / (Math.max(chars, 6) * 0.55)
  return Math.round(Math.max(base, Math.min(wanted, cap)))
}

/** U-37: the Bench is a place: solid amber header, readable label + big count at any zoom.
 *  Why: a 5 px dashed label read as dead space. The font is counter-scaled (~13 px on screen), but never
 *  wider than the tile: when zoomed far out the long form ("N unassigned") gives way to "Bench N". */
export const BENCH_LABEL_PX = 13
const BENCH_SHORT_BELOW_SCALE = 0.5
const BENCH_CHAR_W = 0.62 // average glyph width / font size, semi-bold
export function benchHeaderFont(
  count: number,
  scale: number,
  tileW: number
): { px: number; short: boolean; chars: number } {
  const short = scale < BENCH_SHORT_BELOW_SCALE
  const tail = short ? '' : count === 1 ? ' new' : ' unassigned'
  // "Bench" + count (1.4x) + tail, plus the chip's own padding and gaps (~3 em).
  const chars = 5 + String(count).length * 1.4 + tail.length + 3
  const wanted = Math.max(BENCH_LABEL_PX, BENCH_LABEL_PX / Math.max(scale, 0.05))
  const fits = Math.max(8, (tileW - 24) / (chars * BENCH_CHAR_W))
  return { px: Math.round(Math.min(wanted, fits)), short, chars }
}
export function BenchHeader({
  count,
  scale,
  tileW
}: {
  count: number
  scale: number
  tileW: number
}): React.JSX.Element {
  const { px, short } = benchHeaderFont(count, scale, tileW)
  return (
    <span
      style={{ fontSize: px, lineHeight: 1.1, maxWidth: Math.max(80, tileW - 24) }}
      className="op-bench-header inline-flex items-center gap-2 overflow-hidden whitespace-nowrap rounded-lg bg-amber-500 px-2.5 py-1 font-semibold text-zinc-950"
    >
      <span>Bench</span>
      <span
        style={{ fontSize: Math.round(px * 1.4) }}
        className="op-bench-count font-bold tabular-nums"
      >
        {count}
      </span>
      {short ? null : (
        <span className="font-medium opacity-80">{count === 1 ? 'new' : 'unassigned'}</span>
      )}
    </span>
  )
}

export type TileLocals = ReturnType<typeof tileLocals>

