                    <div className="flex flex-wrap items-center gap-1 border-b border-white/[0.1] pb-1.5">
                      <span className="text-[10px] text-zinc-500 mr-1">Yours:</span>
                      {space.customEmojis.map((custom, idx) => (
                        <button
                          key={`c-${idx}`}
                          type="button"
                          onClick={() => {
                            onChangeGoalEmoji?.(goal.id, custom)
