                type="button"
                aria-haspopup="menu"
                aria-expanded={levelPickerGoalId === goal.id}
                aria-label={`Priority: ${style.label}. Click to change`}
                title="Change priority"
                onPointerDown={(event) => event.stopPropagation()}
                onClick={(event) => {
                  event.stopPropagation()
                  setLevelPickerGoalId((cur) => (cur === goal.id ? null : goal.id))
                  setEmojiPickerGoalId(null)
                }}
                className={`flex shrink-0 items-center gap-1.5 rounded-full px-2 py-0.5 text-[10px] font-semibold transition-colors duration-150 ${
                  isLightBg
                    ? 'bg-black/[0.06] text-slate-800 hover:bg-black/10'
                    : 'bg-white/[0.06] text-zinc-300 hover:bg-white/[0.1] hover:text-zinc-100'
                }`}
              >
                <span aria-hidden="true" className={`size-1.5 rounded-full ${style.dot}`} />
                {style.shortLabel}
                <span aria-hidden="true" className="text-[8px] opacity-50">
                  ▾
                </span>
              </button>
              {levelPickerGoalId === goal.id ? (
                <div
                  data-space-panel="level-picker"
                  role="menu"
                  aria-label="Space priority"
                  ref={(node) => {
                    // Focus the current level so arrows / Escape work right away.
                    if (node && !node.contains(document.activeElement)) {
                      const current =
                        node.querySelector<HTMLButtonElement>('[aria-checked="true"]') ??
                        node.querySelector<HTMLButtonElement>('button')
                      current?.focus()
                    }
                  }}
                  onPointerDown={(event) => event.stopPropagation()}
                  onClick={(event) => event.stopPropagation()}
                  onKeyDown={(event) => {
                    if (event.key === 'Escape') {
                      event.stopPropagation()
                      setLevelPickerGoalId(null)
                      ;(
                        event.currentTarget.parentElement?.querySelector(
                          'button'
                        ) as HTMLButtonElement | null
                      )?.focus()
                      return
                    }
                    if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
                      event.preventDefault()
                      const items = Array.from(
                        event.currentTarget.querySelectorAll<HTMLButtonElement>(
                          '[role="menuitemradio"]'
                        )
                      )
                      const at = items.indexOf(document.activeElement as HTMLButtonElement)
                      const step = event.key === 'ArrowDown' ? 1 : -1
                      items[(at + step + items.length) % items.length]?.focus()
                    }
                  }}
                  className="absolute left-0 top-7 z-40 flex w-48 flex-col gap-0.5 rounded-2xl bg-[#0b0c0f]/95 p-1.5 text-xs text-zinc-200 shadow-[0_18px_45px_rgba(0,0,0,0.55)] ring-1 ring-white/[0.08] backdrop-blur-md"
                >
                  {SPACE_LEVELS.map((level) => (
                    <button
                      key={level}
                      type="button"
                      role="menuitemradio"
                      aria-checked={goal.level === level}
                      data-level-option={level}
                      onClick={() => {
                        setLevelPickerGoalId(null)
                        if (level !== goal.level) {
                          onUpdateGoal?.(goal.id, { level })
                        }
                      }}
                      className={`flex items-center gap-2 rounded-xl px-2.5 py-1.5 text-left transition-colors duration-150 hover:bg-white/[0.08] ${
                        goal.level === level ? 'bg-white/[0.06] text-zinc-50' : ''
                      }`}
                    >
                      <span
                        aria-hidden="true"
                        className={`size-2 rounded-full ${LEVEL_STYLE[level].dot}`}
                      />
                      <span className="flex-1">{LEVEL_STYLE[level].label}</span>
                      {goal.level === level ? (
                        <span aria-hidden="true" className="text-zinc-400">
                          ✓
                        </span>
                      ) : null}
                    </button>
                  ))}
                </div>
              ) : null}
            </div>
          ) : style ? (
            <span
              className={`shrink-0 rounded-full px-2 py-0.5 text-[10px] font-semibold ${
                isLightBg ? 'bg-black/[0.06] text-slate-800' : 'bg-white/[0.06] text-zinc-300'
              }`}
            >
              {style.shortLabel}
            </span>
          ) : null}
          <span
            className={`rounded-full px-2 py-0.5 text-[11px] font-medium ${
              isLightBg ? 'bg-black/10 text-slate-800' : 'bg-white/[0.06] text-zinc-400'
            }`}
          >
            {members.length} {members.length === 1 ? 'agent' : 'agents'}
          </span>
          {waitingCount > 0 ? (
            <span className="rounded-full bg-red-500/20 border border-red-500/50 px-2 py-0.5 text-[10px] font-semibold text-red-500 animate-pulse">
              🔴 {waitingCount} waiting
            </span>
          ) : null}
        </div>

        <div className="flex shrink-0 items-center gap-1">
          {goal && ctx.host?.onFocusTask ? (
            <button
              type="button"
              title="Set this Space as your active focus task"
              onPointerDown={(event) => event.stopPropagation()}
              onClick={(event) => {
                event.stopPropagation()
                const firstTask = openTasks[0]
                ctx.host?.onFocusTask?.(
                  firstTask?.w93Slug || goal.w93Slug || goal.id,
                  firstTask?.text || goal.title
                )
              }}
              className={`opacity-0 transition-opacity duration-150 group-hover/tile:opacity-100 focus-within:opacity-100 focus-visible:opacity-100 motion-reduce:transition-none rounded-lg border px-1.5 py-0.5 text-[11px] ${
                isLightBg
                  ? 'border-slate-300 bg-white/80 text-slate-700 hover:bg-white'
                  : 'border-transparent bg-white/[0.05] text-zinc-400 hover:bg-white/[0.1] hover:text-zinc-100'
              }`}
            >
              🎯
            </button>
          ) : null}
          {goal ? (
            <>
              {/* The goal row below already opens the Space; only side quests (no goal row) need this. */}
              {isSide ? (
                <button
                  type="button"
                  onClick={(event) => {
                    event.stopPropagation()
                    onOpenGoal(goal)
                  }}
                  className={`rounded-lg border px-2 py-0.5 text-[11px] font-medium transition ${
                    isLightBg
                      ? 'border-slate-300 bg-white/80 text-slate-800 hover:bg-white'
                      : 'border-transparent bg-white/[0.05] text-zinc-400 hover:bg-white/[0.1] hover:text-zinc-100'
                  }`}
                >
                  Open ›
                </button>
              ) : null}
              <button
                type="button"
                aria-label="Space options"
                onClick={(event) => {
                  event.stopPropagation()
                  // Keyboard (Enter/Space) clicks have detail 0 and no pointer position.
                  const rect = event.currentTarget.getBoundingClientRect()
                  onGoalMenu(
                    goal,
                    event.detail === 0
                      ? { x: rect.left, y: rect.bottom + 4 }
                      : { x: event.clientX, y: event.clientY }
                  )
                }}
                className={`rounded-lg px-1.5 py-0.5 text-xs transition ${
                  isLightBg
                    ? 'text-slate-700 hover:bg-black/10'
                    : 'text-zinc-400 hover:bg-white/[0.1] hover:text-zinc-100'
                }`}
              >
                •••
              </button>
            </>
          ) : null}
        </div>
      </div>
    </header>
  )
}

// WS-0 (TASK_16 wave 2): Space tiles (tiles.map), moved verbatim from space-canvas.tsx.
// Owner: none. The two-deck header lives in TileHeader.tsx.
import type { CanvasCtx, CanvasHandlers } from '../canvas-ctx'
import { TileHeader, tileLocals } from './TileHeader'
import { CARD_WIDTH, GAP, TEAM_PADDING, tileSize } from '../../core/space'
import { QuickConnectPorts, firstImageFile, hasImageFile } from '../canvas-parts'
import { readCustomEmojiFile } from '../../space-emoji'
import { SpacewareSprite } from '../../sprites/space-sprite'

export function TileLayer({ ctx, g }: { ctx: CanvasCtx; g: CanvasHandlers }): React.JSX.Element {
  const {
    drag,
    imageDropGoalId,
    inspectedAgentId,
    onChangeAgentState,
    onChangeGoalEmoji,
    onMoveTile,
    onNotify,
    onOpenGoal,
    onRegisterCustomEmoji,
    onRemoveAgent,
    onSelectAgent,
    onStartDrag,
    setImageDropGoalId,
    tiles
  } = ctx
  const { startArrowDrag, startTileDrag, startTileResize } = g
  const draggingBotId = drag?.item.kind === 'bot' ? drag.item.botId : null
  return (
    <>
      {tiles.map((tile) => {
        const t = tileLocals(ctx, tile)
        const {
          goal,
          members,
          waitingCount,
          effectiveW,
          effectiveH,
          columns,
          over,
          isArrowTarget,
          offset,
          isBench,
          isSide,
          openTasks,
          openAsks,
          doneOutcomes,
          nextOutcome,
          isSelected,
          hasInspectedMember,
          bgStyle,
          isLightBg
        } = t

        return (
          <section
            key={tile.key}
            data-space-tile={tile.key}
            data-level={goal?.level}
            onPointerDown={startTileDrag(tile)}
            onDragOver={(event) => {
              // Drop an image file on a Space to make it the Space icon (OpenMausBot parity).
              if (!goal || !hasImageFile(event.dataTransfer)) {
                return
              }
              event.preventDefault()
              event.dataTransfer.dropEffect = 'copy'
              if (imageDropGoalId !== goal.id) {
                setImageDropGoalId(goal.id)
              }
            }}
            onDragLeave={(event) => {
              if (
                imageDropGoalId === tile.key &&
                !event.currentTarget.contains(event.relatedTarget as Node | null)
              ) {
                setImageDropGoalId(null)
              }
            }}
            onDrop={(event) => {
              setImageDropGoalId(null)
              const file = goal ? firstImageFile(event.dataTransfer) : null
              if (!goal || !file) {
                return
              }
              event.preventDefault()
              event.stopPropagation()
              void readCustomEmojiFile(file)
                .then((dataUrl) => {
                  onRegisterCustomEmoji?.(dataUrl)
                  onChangeGoalEmoji?.(goal.id, dataUrl)
                })
                .catch((error: unknown) => {
                  onNotify?.(
                    `Space icon not set: ${error instanceof Error ? error.message : 'unreadable image'}`
                  )
                })
            }}
            style={{
              left: tile.x + (offset?.x ?? 0),
              top: tile.y + (offset?.y ?? 0),
              width: effectiveW,
              minHeight: effectiveH,
              ...(bgStyle.backgroundColor ? { backgroundColor: bgStyle.backgroundColor } : {})
            }}
            className={`pointer-events-auto group/tile absolute flex flex-col overflow-visible rounded-3xl border transition-[border-color,box-shadow,background-color] duration-200 motion-reduce:transition-none ${
              isBench
                ? waitingCount > 0
                  ? 'border-red-500/50 bg-[#0b0c0f]/80'
                  : members.length > 0
                    ? 'border-amber-500/60 bg-amber-500/[0.06]'
                    : 'border-amber-500/25 bg-[#0b0c0f]/70'
                : `${bgStyle.backgroundColor ? '' : 'bg-[#0b0c0f]/88 backdrop-blur-md'} shadow-[0_18px_45px_rgba(0,0,0,0.38)] ${
                    waitingCount > 0
                      ? 'border-red-500/55'
                      : isLightBg
                        ? 'border-slate-300/90'
                        : isSide
                          ? 'border-dashed border-white/[0.1]'
                          : 'border-white/[0.08]'
                  }`
            } ${
              isArrowTarget
                ? 'ring-2 ring-sky-400 shadow-[0_0_28px_rgba(56,189,248,0.45)]'
                : over || imageDropGoalId === tile.key
                  ? 'ring-2 ring-primary bg-primary/10'
                  : isSelected
                    ? 'ring-2 ring-foreground/40'
                    : hasInspectedMember
                      ? 'ring-2 ring-primary/45'
                      : ''
            }`}
          >
            {/* Two-deck Header:
                  Row 1: Space Icon + Full Title (always in view even when width is small) + quick Title Size A-/A+
                  Row 2: Category badge ("General" / P1..P3) + Waiting/Count pills + Bg Color + Arrow + Open + Menu */}
            <TileHeader ctx={ctx} t={t} />

            {goal && !isSide ? (
              <button
                type="button"
                onClick={() => onOpenGoal(goal)}
                className={`flex w-full flex-col gap-1 border-y px-4 py-1.5 text-left text-xs transition ${
                  isLightBg
                    ? 'border-slate-300/80 bg-black/[0.04] hover:bg-black/[0.08]'
                    : 'border-white/[0.08] bg-white/[0.035] hover:bg-white/[0.06]'
                }`}
              >
                <div className="flex w-full items-center justify-between gap-2">
                  <span className={`truncate ${isLightBg ? 'text-slate-600' : 'text-zinc-400'}`}>
                    {goal.goal || 'Click to set the goal, outcomes, and tasks…'}
                  </span>
                  <span
                    className={`flex shrink-0 items-center gap-1.5 text-[11px] ${
                      isLightBg ? 'text-slate-700' : 'text-zinc-400'
                    }`}
                  >
                    {goal.outcomes.length > 0 ? (
                      <span
                        className={`rounded px-1.5 py-0.2 font-medium ${
                          isLightBg ? 'bg-white/90 text-slate-900' : 'bg-white/[0.08] text-zinc-200'
                        }`}
                      >
                        Outcomes {doneOutcomes}/{goal.outcomes.length}
                      </span>
                    ) : null}
                    {openTasks.length > 0 ? (
                      <span
                        className={`rounded px-1.5 py-0.2 ${
                          isLightBg ? 'bg-white/90 text-slate-800' : 'bg-white/[0.08] text-zinc-300'
                        }`}
                      >
                        {openTasks.length} {openTasks.length === 1 ? 'task' : 'tasks'}
                      </span>
                    ) : null}
                    {openAsks.length > 0 ? (
                      <span className="rounded bg-red-500/20 px-1.5 py-0.2 font-semibold text-red-500">
                        {openAsks.length} {openAsks.length === 1 ? 'ask' : 'asks'}
                      </span>
                    ) : null}
                  </span>
                </div>
                {nextOutcome ? (
                  <div
                    className={`flex w-full items-center gap-1.5 text-[11px] ${
                      isLightBg ? 'text-slate-700' : 'text-zinc-400'
                    }`}
                  >
                    <span className="shrink-0 font-mono text-[10px] text-emerald-500">
                      {nextOutcome.done ? '✓' : '🎯'}
                    </span>
                    <span
                      className={`truncate ${
                        nextOutcome.done
                          ? 'line-through opacity-70'
                          : isLightBg
                            ? 'text-slate-900 font-medium'
                            : 'text-zinc-100'
                      }`}
                    >
                      {nextOutcome.text}
                    </span>
                  </div>
                ) : null}
              </button>
            ) : null}

            {isBench && members.length === 0 ? (
              <div className="px-4 pt-0.5 pb-3">
                <div className="flex h-8 items-center justify-center rounded-xl border border-dashed border-white/[0.12] px-3 text-[11px] text-zinc-500">
                  All open tabs are assigned to Spaces
                </div>
              </div>
            ) : (
              <div
                style={{
                  padding: TEAM_PADDING,
                  gap: GAP,
                  gridTemplateColumns: `repeat(${columns}, ${CARD_WIDTH}px)`
                }}
                className="grid flex-1 content-start justify-center"
              >
                {members.map((agent) => (
                  <SpacewareSprite
                    key={agent.id}
                    agent={agent}
                    tileKey={tile.key}
                    taskText={openTasks.find((task) => task.botId === agent.id)?.text}
                    hasOpenAsk={openAsks.some(
                      (ask) => ask.botId === agent.id || ask.forBotId === agent.id
                    )}
                    isDragging={draggingBotId === agent.id}
                    isSelected={inspectedAgentId === agent.id}
                    onSelect={() => onSelectAgent(agent.id)}
                    onStartDrag={onStartDrag({ kind: 'bot', botId: agent.id })}
                    onRemove={onRemoveAgent ? () => onRemoveAgent(agent.id) : undefined}
                    onChangeState={
                      onChangeAgentState ? (mode) => onChangeAgentState(agent.id, mode) : undefined
                    }
                  />
                ))}
                {members.length === 0 ? (
                  <button
                    type="button"
                    onClick={() => {
                      if (goal) {
                        onOpenGoal(goal)
                      }
                    }}
                    style={{ gridColumn: `span ${columns}` }}
                    className={`flex h-20 items-center justify-center rounded-2xl border border-dashed px-3 text-xs transition ${
                      isLightBg
                        ? 'border-slate-400/70 text-slate-600 hover:border-slate-700 hover:text-slate-900'
                        : 'border-white/[0.14] text-zinc-500 hover:border-primary/40 hover:text-zinc-200'
                    }`}
                  >
                    Drag an A01 agent or Spaceware tab here
                  </button>
                ) : null}
              </div>
            )}

            {/* 4-side magnetic quick-connect arrow ports on Space tiles */}
            <QuickConnectPorts
              visible={isSelected}
              hoverClass="group-hover/tile:opacity-80"
              onStartArrow={(event) => startArrowDrag(event, tile.key)}
            />

            {/* Invisible grips on the other 3 corners (nw / ne / sw), OpenMausBot parity */}
            {(['nw', 'ne', 'sw'] as const).map((corner) => (
              <div
                key={corner}
                data-tile-resize="true"
                data-resize-corner={corner}
                title="Drag corner to resize Space"
                onPointerDown={startTileResize(tile, corner)}
                className={`absolute z-20 size-4 ${
                  corner === 'nw'
                    ? '-top-1 -left-1 cursor-nwse-resize'
                    : corner === 'ne'
                      ? '-top-1 -right-1 cursor-nesw-resize'
                      : '-bottom-1 -left-1 cursor-nesw-resize'
                }`}
              />
            ))}
            {/* Right edge, bottom edge, and large bottom-right corner resize handles for Space workspace */}
            <div
              data-tile-resize="true"
              title="Drag right edge to widen Space workspace"
              onPointerDown={startTileResize(tile, 'e')}
              className="absolute top-8 bottom-8 -right-1 w-2.5 cursor-ew-resize"
            />
            <div
              data-tile-resize="true"
              title="Drag bottom edge to make Space workspace taller"
              onPointerDown={startTileResize(tile, 's')}
              className="absolute right-8 -bottom-1 left-6 h-2.5 cursor-ns-resize"
            />
            <div
              data-tile-resize="true"
              title="Drag corner to resize Space workspace · Double-click to auto-fit"
              onPointerDown={startTileResize(tile, 'se')}
              onDoubleClick={(event) => {
                event.stopPropagation()
                const auto = tileSize(members.length, Boolean(isSide || isBench))
                onMoveTile(tile.key, { x: tile.x, y: tile.y, w: auto.w, h: auto.h })
              }}
              data-resize-corner="se"
              className={`absolute right-1 bottom-1 z-20 flex size-6 cursor-nwse-resize items-end justify-end p-1.5 opacity-0 transition-opacity duration-150 group-hover/tile:opacity-100 motion-reduce:transition-none ${
                isLightBg
                  ? 'text-slate-500 hover:text-slate-900'
                  : 'text-zinc-500 hover:text-zinc-100'
              }`}
            >
              <svg width="10" height="10" viewBox="0 0 10 10" aria-hidden="true">
                <path
                  d="M9 1L1 9M9 5L5 9"
                  stroke="currentColor"
                  strokeWidth="1.5"
                  strokeLinecap="round"
                />
              </svg>
            </div>
          </section>
        )
      })}
    </>
  )
}

// WS-D (TASK_16 wave 2): small arrows on the canvas border that point at asks outside the view, with
// a count when several sit the same way. Click = go to the oldest of them (glide + select its agent).
// Read only on agent data. Owner: WS-D.
import type { AskEdge } from '../../core/ask-pins'
import { ASK_NEEDS_YOU } from './AskPins'

export function AskEdgeIndicators({
  edges,
  textOf,
  onPick
}: {
  edges: readonly AskEdge[]
  textOf: (askId: string) => string
  onPick: (askId: string) => void
}): React.JSX.Element | null {
  if (edges.length === 0) {
    return null
  }
  return (
    <div
      data-ask-edges="true"
      className="pointer-events-none absolute inset-0 z-30 overflow-hidden"
    >
      {edges.map((edge) => {
        const first = edge.askIds[0]!
        const label =
          edge.count > 1 ? `${edge.count} asks off screen` : `Ask off screen: ${textOf(first)}`
        return (
          <button
            key={edge.askIds.join('|')}
            type="button"
            data-ask-edge={edge.count}
            data-ask-edge-angle={Math.round(edge.angle)}
            aria-label={`${label}. Go to the oldest`}
            title={`${label}\nClick: go there`}
            onPointerDown={(event) => event.stopPropagation()}
            onClick={(event) => {
              event.stopPropagation()
              onPick(first)
            }}
            style={{ transform: `translate3d(${edge.x - 14}px, ${edge.y - 14}px, 0)` }}
            className="pointer-events-auto absolute left-0 top-0 flex size-7 cursor-pointer items-center justify-center rounded-full focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white/70"
          >
            <svg
              width="28"
              height="28"
              viewBox="0 0 28 28"
              aria-hidden="true"
              style={{ transform: `rotate(${edge.angle}deg)` }}
              className="absolute inset-0 drop-shadow-[0_2px_6px_rgba(0,0,0,0.5)]"
            >
              <path d="M28 14 L20 8 V20 Z" fill={ASK_NEEDS_YOU} />
              <circle cx="14" cy="14" r="8.5" fill={ASK_NEEDS_YOU} stroke="#fff" strokeWidth="2" />
            </svg>
            <span className="relative text-[10px] font-bold leading-none text-white">
              {edge.count}
            </span>
          </button>
        )
      })}
    </div>
  )
}

// WS-D (TASK_16 wave 2): "N asks" chip, top right of the canvas. Click = next open ask, Shift+click =
// previous (keys N / Shift+N). It shows the white Spaceware sprite of the agent it goes to next, with
// its role accessory. One control, read only on agent data. Owner: WS-D.
import { stepAsk } from '../../core/ask-pins'
import { MiniSpacewareSprite } from '../../sprites/space-sprite'
import { spriteRoleOf } from '../../sprites/space-sprite-accessory'
import type { CanvasCtx } from '../canvas-ctx'
import type { AskPinsApi } from './use-ask-pins'

export function AskNavigator({
  ctx,
  api
}: {
  ctx: CanvasCtx
  api: AskPinsApi
}): React.JSX.Element | null {
  const { asks, activeAskId, nextAsk, prevAsk } = api
  if (asks.length === 0) {
    return null
  }
  const upcoming = stepAsk(asks, activeAskId, 1)!
  const at = activeAskId ? asks.findIndex((ref) => ref.ask.id === activeAskId) : -1
  const agent = ctx.agents.find(
    (a) => a.id === upcoming.ask.botId || a.unifiedTabId === upcoming.ask.botId
  )
  const who = upcoming.ask.botName || upcoming.ask.agentName || agent?.name || 'Agent'
  const count = `${asks.length} ${asks.length === 1 ? 'ask' : 'asks'}`
  return (
    <div className="pointer-events-none absolute right-3 top-3 z-30">
      <button
        type="button"
        data-ask-navigator={asks.length}
        aria-label={`${count} waiting on you. Go to the next: ${who}`}
        title={`${count} waiting on you\nClick or N: next (${who}) · Shift+click or Shift+N: previous · ⌘F: jump by name`}
        onPointerDown={(event) => event.stopPropagation()}
        onClick={(event) => {
          event.stopPropagation()
          if (event.shiftKey) {
            prevAsk()
          } else {
            nextAsk()
          }
        }}
        className="pointer-events-auto flex cursor-pointer items-center gap-1.5 rounded-full border border-red-500/55 bg-zinc-950/90 py-1 pl-1.5 pr-2.5 text-xs font-semibold text-zinc-100 shadow-lg backdrop-blur-md hover:bg-zinc-900 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white/40"
      >
        <MiniSpacewareSprite attention awake role={spriteRoleOf(agent ?? { name: who })} />
        <span>{count}</span>
        {at >= 0 ? (
          <span className="font-mono text-[10px] text-zinc-400">
            {at + 1}/{asks.length}
          </span>
        ) : null}
        <span aria-hidden="true" className="text-zinc-400">
          ›
        </span>
      </button>
    </div>
  )
}

// WS-D (TASK_16 wave 2): numbered pins for every open agent ask, beside the tile they belong to.
// Screen space (outside the zoomed layer) so a pin keeps its size at any zoom, like Penpot's comment
// bubbles. Read only: a click glides to the tile and selects the asking agent (onSelectAgent); the
// answer happens in that agent's panel. AskLayer is the one mount for pins + edge arrows + navigator
// + ⌘F jump. Owner: WS-D.
import { ZOOM_TWEEN_MS } from '../../core/space'
import { ASK_PIN_SIZE, type AskPin } from '../../core/ask-pins'
import { SPACEWARE_ISLAND_PALETTE } from '../../sprites/space-sprite'
import type { CanvasCtx } from '../canvas-ctx'
import { AskEdgeIndicators } from './AskEdgeIndicators'
import { AskNavigator } from './AskNavigator'
import { JumpTo } from './JumpTo'
import { useAskPins } from './use-ask-pins'

/** The needs-you colour (same red as a sprite that waits on you). */
export const ASK_NEEDS_YOU = SPACEWARE_ISLAND_PALETTE.attentionHalo

export function AskPins({
  pins,
  textOf,
  activeAskId,
  tweening,
  reducedMotion,
  onPick
}: {
  pins: readonly AskPin[]
  textOf: (askId: string) => string
  activeAskId: string | null
  tweening: boolean
  reducedMotion: boolean
  onPick: (askId: string) => void
}): React.JSX.Element | null {
  const shown = pins.filter((pin) => pin.visible)
  if (shown.length === 0) {
    return null
  }
  const half = ASK_PIN_SIZE / 2
  return (
    <div data-ask-pins="true" className="pointer-events-none absolute inset-0 z-20 overflow-hidden">
      {shown.map((pin) => {
        const label = textOf(pin.askId)
        const active = pin.askId === activeAskId
        return (
          <button
            key={pin.askId}
            type="button"
            data-ask-pin={pin.askId}
            data-ask-tile={pin.tileKey}
            aria-label={`Ask ${pin.n}: ${label}. Go to the agent`}
            title={`${label}${pin.more > 0 ? ` (+${pin.more} more on this Space)` : ''}\nClick: go to the agent (answer in its panel)`}
            onPointerDown={(event) => event.stopPropagation()}
            onClick={(event) => {
              event.stopPropagation()
              onPick(pin.askId)
            }}
            style={{
              width: ASK_PIN_SIZE,
              height: ASK_PIN_SIZE,
              transform: `translate3d(${pin.x - half}px, ${pin.y - half}px, 0)`,
              backgroundColor: ASK_NEEDS_YOU,
              transition:
                tweening && !reducedMotion
                  ? `transform ${ZOOM_TWEEN_MS}ms cubic-bezier(0.22, 1, 0.36, 1)`
                  : undefined
            }}
            className={`pointer-events-auto absolute left-0 top-0 flex cursor-pointer items-center justify-center rounded-full rounded-bl-none border-2 border-white text-[10px] font-bold leading-none text-white shadow-[0_4px_12px_rgba(0,0,0,0.45)] hover:scale-110 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white/70 motion-reduce:hover:scale-100 ${
              active ? 'ring-2 ring-white/80' : ''
            }`}
          >
            {pin.n}
            {pin.more > 0 ? (
              <span
                data-ask-pin-more={pin.more}
                className="absolute -right-2 -top-2 rounded-full bg-zinc-950 px-1 text-[9px] text-white ring-1 ring-white/40"
              >
                +{pin.more}
              </span>
            ) : null}
          </button>
        )
      })}
    </div>
  )
}

/** One mount for everything WS-D draws on the canvas. */
export function AskLayer({ ctx }: { ctx: CanvasCtx }): React.JSX.Element | null {
  const api = useAskPins(ctx)
  const { asks, measured, layout, activeAskId, goToAsk, jumpOpen, setJumpOpen } = api
  const textById = new Map(
    asks.map((ref) => [
      ref.ask.id,
      `${ref.ask.botName || ref.ask.agentName || 'Agent'}: ${ref.ask.text}`
    ])
  )
  const textOf = (askId: string): string => textById.get(askId) ?? ''
  if (!measured || (asks.length === 0 && !jumpOpen)) {
    return null
  }
  return (
    <>
      <AskPins
        pins={layout.pins}
        textOf={textOf}
        activeAskId={activeAskId}
        tweening={ctx.zoomTweening}
        reducedMotion={ctx.reducedMotion}
        onPick={goToAsk}
      />
      <AskEdgeIndicators edges={layout.edges} textOf={textOf} onPick={goToAsk} />
      <AskNavigator ctx={ctx} api={api} />
      {jumpOpen ? <JumpTo ctx={ctx} api={api} onClose={() => setJumpOpen(false)} /> : null}
    </>
  )
}

// WS-0 (TASK_16 wave 2): canvas double-click / right-click → create menu (openCanvasCreate), moved
// verbatim from space-canvas.tsx (the root div's inline handlers). Owner: WS-E (selection menu lands here).
// WS-E: right-click on a note / shape / text, an arrow or a Space tile opens a small menu (Penpot's
// ui/workspace/context_menu.cljs idea, re-implemented, our actions). Empty canvas still opens the board's
// create menu, unchanged. Shortcut labels come from the ONE key table (keyboard/commands.ts). Space tiles
// get only safe rows (zoom, open): a whiteboard menu never edits agent data. Keyboard: the menu key or
// Shift+F10 opens it on the selection; the first row takes focus, arrows move, Esc closes and gives focus
// back. The menu renders only while open. It also mounts the clipboard listeners (use-clipboard.ts).
import { useEffect, useRef, useSyncExternalStore } from 'react'
import type { CanvasCtx, CanvasHandlers } from '../canvas-ctx'
import { toCanvas } from '../../core/space'
import { expandToGroups } from '../../core/whiteboard-groups'
import { fitSelection } from '../../core/viewport-fit'
import { registerCanvasCommands, type CanvasCommand } from '../keyboard/commands'
import {
  canvasContextMenuState,
  closeCanvasContextMenu,
  contextMenuItems,
  openCanvasContextMenu,
  subscribeCanvasContextMenu,
  type ContextMenuItemId,
  type ContextMenuTarget
} from './context-menu-items'
import { focusMenuOnOpen, handleMenuKey } from '../../menu-keys'
import {
  copyWhiteboardSelection,
  requestWhiteboardPaste,
  useWhiteboardClipboard
} from '../selection/use-clipboard'
import {
  groupSelection,
  toggleHidden,
  toggleLock,
  ungroupSelection,
  whiteboardActionState
} from './layers-actions'

// ── Opening ────────────────────────────────────────────────────────────────────────────────────────

const EXCLUDED =
  '[data-space-tile], [data-space-card], [data-space-sticky], [data-space-arrow], [data-space-dock], [data-whiteboard-inspector], [data-whiteboard-multiselect], [data-whiteboard-history]'

/** Shift+F10 / the menu key: open the menu on the current selection (or the selected Space). */
export const CONTEXT_MENU_COMMANDS: readonly CanvasCommand[] = [
  {
    id: 'edit.contextMenu',
    label: 'Open the context menu',
    group: 'Edit',
    scope: 'canvas',
    keys: [
      { key: 'contextmenu', mod: false, shift: 'any', alt: false },
      { key: 'f10', mod: false, shift: true, alt: false }
    ],
    display: '⇧F10',
    when: ({ ctx }) =>
      !ctx.editingStickyId &&
      (ctx.effectiveSelectedIds.length > 0 || Boolean(ctx.selectedArrowId || ctx.selectedGoalId)),
    run: ({ ctx }) => openMenuOnSelection(ctx)
  }
]

function openMenuOnSelection(ctx: CanvasCtx): boolean {
  const rect = ctx.rootRef.current?.getBoundingClientRect()
  if (!rect) {
    return false
  }
  const target: ContextMenuTarget =
    ctx.effectiveSelectedIds.length > 0
      ? { kind: 'selection' }
      : ctx.selectedArrowId
        ? { kind: 'arrow', id: ctx.selectedArrowId }
        : { kind: 'goal', id: ctx.selectedGoalId ?? '' }
  const anchorId =
    target.kind === 'selection'
      ? ctx.effectiveSelectedIds[0]
      : target.kind === 'goal'
        ? target.id
        : ''
  const box = anchorId ? ctx.boxMap.get(anchorId) : undefined
  const at = box
    ? { x: box.x + box.w / 2, y: box.y + box.h / 2 }
    : toCanvas({ x: 120, y: 120 }, ctx.view)
  openCanvasContextMenu({
    client: {
      x: rect.left + at.x * ctx.view.scale + ctx.view.x,
      y: rect.top + at.y * ctx.view.scale + ctx.view.y
    },
    at,
    target,
    returnFocus: document.activeElement as HTMLElement | null
  })
  return true
}

export function useCanvasContextMenus(ctx: CanvasCtx) {
  const { onContextCreate, rootRef, view } = ctx
  useWhiteboardClipboard(ctx)
  useEffect(() => registerCanvasCommands(CONTEXT_MENU_COMMANDS).unregister, [])
  useEffect(() => closeCanvasContextMenu, [])
  const openCanvasCreate = (clientX: number, clientY: number): void => {
    const rect = rootRef.current?.getBoundingClientRect()
    if (!rect) {
      return
    }
    onContextCreate(
      { x: clientX, y: clientY },
      toCanvas({ x: clientX - rect.left, y: clientY - rect.top }, view)
    )
  }

  const onCanvasDoubleClick = (event: React.MouseEvent<HTMLDivElement>): void => {
    if (
      !(event.target as HTMLElement).closest(
        '[data-space-tile], [data-space-card], [data-space-sticky], [data-space-arrow], [data-space-dock], [data-whiteboard-inspector], [data-whiteboard-multiselect], [data-whiteboard-history], button, input, textarea'
      )
    ) {
      openCanvasCreate(event.clientX, event.clientY)
    }
  }

  /** WS-E: right-click on an item. True = a menu opened (the event is consumed). */
  const openItemMenu = (event: React.MouseEvent<HTMLDivElement>): boolean => {
    const el = event.target as HTMLElement
    if (el.closest('input, textarea, [contenteditable="true"]')) {
      return false
    }
    const rect = rootRef.current?.getBoundingClientRect()
    if (!rect) {
      return false
    }
    const stickyId = el.closest('[data-space-sticky]')?.getAttribute('data-space-sticky')
    const arrowId = el.closest('[data-space-arrow]')?.getAttribute('data-space-arrow')
    const goalId = el.closest('[data-space-tile]')?.getAttribute('data-space-tile')
    let target: ContextMenuTarget | null = null
    if (stickyId && ctx.stickiesById.has(stickyId)) {
      if (!ctx.effectiveSelectedIds.includes(stickyId)) {
        ctx.setSelectedStickyIds(expandToGroups(ctx.stickies, [stickyId]))
        ctx.setSelectedArrowId(null)
      }
      target = { kind: 'selection' }
    } else if (arrowId) {
      ctx.setSelectedArrowId(arrowId)
      ctx.setSelectedStickyIds([])
      target = { kind: 'arrow', id: arrowId }
    } else if (goalId && ctx.space.goals.some((g) => g.id === goalId)) {
      target = { kind: 'goal', id: goalId }
    }
    if (!target) {
      return false
    }
    event.preventDefault()
    openCanvasContextMenu({
      client: { x: event.clientX, y: event.clientY },
      at: toCanvas({ x: event.clientX - rect.left, y: event.clientY - rect.top }, view),
      target,
      returnFocus: document.activeElement as HTMLElement | null
    })
    return true
  }

  const onCanvasContextMenu = (event: React.MouseEvent<HTMLDivElement>): void => {
    if (!(event.target as HTMLElement).closest(EXCLUDED)) {
      event.preventDefault()
      openCanvasCreate(event.clientX, event.clientY)
      return
    }
    openItemMenu(event)
  }

  return { openCanvasCreate, onCanvasDoubleClick, onCanvasContextMenu }
}

// ── The menu ───────────────────────────────────────────────────────────────────────────────────────

const MENU_W = 220

/** Rendered by the canvas overlays (ItemInspector.tsx); nothing while closed. */
export function CanvasContextMenu({
  ctx,
  g
}: {
  ctx: CanvasCtx
  g: CanvasHandlers
}): React.JSX.Element | null {
  const state = useSyncExternalStore(
    subscribeCanvasContextMenu,
    canvasContextMenuState,
    canvasContextMenuState
  )
  const menuRef = useRef<HTMLDivElement | null>(null)

  useEffect(() => {
    if (!state) {
      return
    }
    const onDown = (event: PointerEvent): void => {
      if (!menuRef.current?.contains(event.target as Node)) {
        closeCanvasContextMenu()
      }
    }
    const onClose = (): void => closeCanvasContextMenu()
    document.addEventListener('pointerdown', onDown, true)
    window.addEventListener('wheel', onClose, { passive: true })
    window.addEventListener('blur', onClose)
    return () => {
      document.removeEventListener('pointerdown', onDown, true)
      window.removeEventListener('wheel', onClose)
      window.removeEventListener('blur', onClose)
    }
  }, [state])

  if (!state) {
    return null
  }
  const ids = ctx.effectiveSelectedIds
  const actionState = whiteboardActionState(ctx, ids)
  const items = contextMenuItems(state.target, {
    ...actionState,
    allLocked: ids.length > 0 && ids.every((id) => ctx.stickiesById.get(id)?.locked),
    canPaste: Boolean(ctx.onBatchAddWhiteboard)
  })
  const close = (): void => {
    closeCanvasContextMenu()
    state.returnFocus?.focus?.()
  }
  const zoomTo = (id: string): void => {
    const el = ctx.rootRef.current
    const box = ctx.boxMap.get(id)
    const next = el && box ? fitSelection([box], el.clientWidth, el.clientHeight) : null
    if (next) {
      ctx.markZoomTween()
      ctx.setView(next)
    }
  }
  const run = (id: ContextMenuItemId): void => {
    const target = state.target
    close()
    switch (id) {
      case 'copy':
        copyWhiteboardSelection(ctx)
        return
      case 'paste':
        requestWhiteboardPaste(ctx, state.at)
        return
      case 'duplicate':
        g.duplicateSelected()
        return
      case 'delete':
        g.deleteSelected()
        return
      case 'front':
        g.bringIdsToFront(ids)
        return
      case 'back':
        g.sendIdsToBack(ids)
        return
      case 'group':
        groupSelection(ctx)
        return
      case 'ungroup':
        ungroupSelection(ctx)
        return
      case 'hide':
        toggleHidden(ctx)
        return
      case 'lock':
        toggleLock(ctx)
        return
      case 'zoom':
        if (target.kind === 'goal') {
          zoomTo(target.id)
        } else {
          g.fitToSelection()
        }
        return
      case 'open': {
        const goal = target.kind === 'goal' ? ctx.space.goals.find((x) => x.id === target.id) : null
        if (goal) {
          ctx.onOpenGoal(goal)
        }
      }
    }
  }
  const rect = ctx.rootRef.current?.getBoundingClientRect()
  const rootW = ctx.rootRef.current?.clientWidth || 1184
  const rootH = ctx.rootRef.current?.clientHeight || 860
  const estH = items.length * 30 + 12
  const left = Math.max(8, Math.min(rootW - MENU_W - 8, state.client.x - (rect?.left ?? 0)))
  const top = Math.max(8, Math.min(rootH - estH - 8, state.client.y - (rect?.top ?? 0)))
  return (
    <div
      ref={(el) => {
        menuRef.current = el
        focusMenuOnOpen(el)
      }}
      role="menu"
      aria-label="Item actions"
      data-whiteboard-context-menu={state.target.kind}
      onKeyDown={(event) => {
        if (menuRef.current) {
          handleMenuKey(event, menuRef.current, closeCanvasContextMenu, state.returnFocus)
        }
      }}
      onContextMenu={(event) => {
        event.preventDefault()
        event.stopPropagation()
      }}
      onPointerDown={(event) => event.stopPropagation()}
      onDoubleClick={(event) => event.stopPropagation()}
      style={{ left, top, width: MENU_W }}
      className="pointer-events-auto absolute z-50 rounded-lg border border-white/10 bg-zinc-900/95 p-1 text-[12px] text-zinc-100 shadow-xl backdrop-blur"
    >
      {items.map((it) => (
        <div key={it.id}>
          {it.divider ? <div role="separator" className="my-1 h-px bg-white/10" /> : null}
          <button
            type="button"
            role="menuitem"
            disabled={it.disabled}
            onClick={() => run(it.id)}
            className="flex w-full items-center justify-between rounded px-2 py-1 text-left hover:bg-white/10 focus:bg-white/10 focus:outline-none disabled:opacity-40"
          >
            <span>{it.label}</span>
            {it.shortcut ? (
              <kbd className="font-sans text-[11px] text-zinc-400">{it.shortcut}</kbd>
            ) : null}
          </button>
        </div>
      ))}
    </div>
  )
}

// WS-0 (TASK_16 wave 2): the bottom dock (WhiteboardEdgelessDock wiring), moved verbatim from
// space-canvas.tsx. Owner: none. The drag ghost is DockGhost.tsx.
import type { CanvasCtx, CanvasHandlers } from '../canvas-ctx'
import { WhiteboardEdgelessDock } from '../../whiteboard-toolbar'
import { cornerStacked, dockMaxWidthFor } from '../corner-layout'
import { useCanvasWidth } from '../use-canvas-width'

export function Dock({ ctx, g }: { ctx: CanvasCtx; g: CanvasHandlers }): React.JSX.Element {
  const {
    activeArrowDash,
    activeArrowRouting,
    activeFillStyle,
    activeShapeColor,
    activeShapeType,
    activeTextPreset,
    askModelOnDrop,
    dockNoteColor,
    dockSpaceLevel,
    drag,
    onChangeToolMode,
    onSelectModelId,
    onStartDrag,
    onToggleAskModelOnDrop,
    selectedModelId,
    setActiveArrowDash,
    setActiveArrowRouting,
    setActiveFillStyle,
    setActiveShapeColor,
    setActiveShapeType,
    setActiveTextPreset,
    setDockNoteColor,
    setDockSpaceLevel,
    toolMode
  } = ctx
  const { handleStartDockItemDrag } = g
  const canvasWidth = useCanvasWidth(ctx.rootRef)
  return (
    <>
      {/* AFFiNE Edgeless Matte-Dark Floating Dock */}
      <div
        style={{ maxWidth: dockMaxWidthFor(canvasWidth) }}
        className="op-dock-wrap pointer-events-none absolute bottom-3 left-1/2 z-30 flex -translate-x-1/2 flex-col items-center"
      >
        <WhiteboardEdgelessDock
          narrow={cornerStacked(canvasWidth) || (canvasWidth > 0 && canvasWidth < 420)}
          toolMode={toolMode}
          onChangeToolMode={onChangeToolMode}
          activeShapeType={activeShapeType}
          onChangeShapeType={setActiveShapeType}
          activeShapeColor={activeShapeColor}
          onChangeShapeColor={setActiveShapeColor}
          activeFillStyle={activeFillStyle}
          onChangeFillStyle={setActiveFillStyle}
          activeArrowRouting={activeArrowRouting}
          onChangeArrowRouting={setActiveArrowRouting}
          activeArrowDash={activeArrowDash}
          onChangeArrowDash={setActiveArrowDash}
          dockSpaceLevel={dockSpaceLevel}
          onChangeDockSpaceLevel={setDockSpaceLevel}
          dockNoteColor={dockNoteColor}
          onChangeDockNoteColor={setDockNoteColor}
          selectedModelId={selectedModelId}
          onSelectModelId={onSelectModelId}
          askModelOnDrop={askModelOnDrop}
          onToggleAskModelOnDrop={onToggleAskModelOnDrop}
          onStartDockItemDrag={handleStartDockItemDrag}
          onStartAgentSpawnDrag={(spawnerId, ev) => onStartDrag({ kind: 'spawn', spawnerId })(ev)}
          isDraggingBot={drag?.item.kind === 'bot'}
          isOverTrash={drag?.over?.kind === 'palette-remove'}
          activeTextPreset={activeTextPreset}
          onSelectTextPreset={(preset) => {
            setActiveTextPreset(preset.id)
            setActiveFillStyle(preset.fillStyle)
            if (preset.id !== 'backed-label') {
              setActiveShapeColor(preset.color)
            }
            onChangeToolMode?.('text')
          }}
        />
      </div>
    </>
  )
}

// WS-0 (TASK_16 wave 2): zoom-scaled ghost preview while dragging an item out of the dock (portal),
// moved verbatim from space-canvas.tsx. Owner: none.
import type { CanvasCtx } from '../canvas-ctx'
import { LEVEL_STYLE, resolveWhiteboardSurfaceStyle } from '../../core/space'
import { TOOLBAR_TEXT_PRESETS } from '../../whiteboard-toolbar'
import { createPortal } from 'react-dom'

export function DockGhost({ ctx }: { ctx: CanvasCtx }): React.JSX.Element {
  const {
    activeFillStyle,
    activeShapeColor,
    activeShapeType,
    activeTextPreset,
    dockDrag,
    dockNoteColor,
    dockSpaceLevel,
    view
  } = ctx
  return (
    <>
      {/* Live AFFiNE zoom-scaled floating ghost preview while dragging Space, Note, Shape, or Text Card out of dock */}
      {dockDrag && typeof document !== 'undefined'
        ? createPortal(
            <div
              style={{
                left: 0,
                top: 0,
                transform: `translate3d(${Math.round(dockDrag.clientX - (dockDrag.kind === 'space' ? 112 : 84))}px, ${Math.round(dockDrag.clientY - (dockDrag.kind === 'space' ? 58 : 44))}px, 0) scale(${Math.max(0.76, Math.min(1.16, view.scale)).toFixed(3)})`,
                transformOrigin: 'center center'
              }}
              className="pointer-events-none fixed z-50 will-change-transform"
            >
              {dockDrag.kind === 'space'
                ? (() => {
                    const lvl = dockDrag.options.spaceLevel ?? dockSpaceLevel
                    const st = LEVEL_STYLE[lvl]
                    return (
                      <div className="flex w-56 flex-col overflow-hidden rounded-2xl border-2 border-sky-400/85 bg-zinc-950/95 text-xs text-white shadow-[0_24px_60px_rgba(0,0,0,0.65)] backdrop-blur-md">
                        <div className={`h-2.5 w-full ${st.band}`} />
                        <div className="flex flex-col gap-1.5 p-3">
                          <div className="flex items-center justify-between gap-2">
                            <span className="font-semibold">New {st.shortLabel} Space</span>
                            <span
                              className={`rounded border px-1.5 py-0.2 text-[10px] font-bold ${st.chip}`}
                            >
                              {st.shortLabel}
                            </span>
                          </div>
                          <div className="space-y-1 pt-0.5">
                            <div className="h-1 w-28 rounded-full bg-white/25" />
                            <div className="h-1 w-16 rounded-full bg-white/12" />
                          </div>
                          <span className="text-[10px] text-sky-300/90">
                            Release to drop on canvas
                          </span>
                        </div>
                      </div>
                    )
                  })()
                : dockDrag.kind === 'shape'
                  ? (() => {
                      const shapeType = dockDrag.options.shapeType ?? activeShapeType
                      const color = dockDrag.options.color ?? activeShapeColor
                      const fillStyle = dockDrag.options.fillStyle ?? activeFillStyle
                      const surf = resolveWhiteboardSurfaceStyle({
                        kind: 'shape',
                        color,
                        fillStyle,
                        borderStyle: 'solid'
                      })
                      const isSym = shapeType === 'ellipse' || shapeType === 'diamond'
                      const w = isSym ? 132 : 168
                      const h = isSym ? 112 : 84
                      const isSvg = shapeType === 'ellipse' || shapeType === 'diamond'
                      return (
                        <div
                          style={{
                            width: w,
                            height: h,
                            color: surf.textColor,
                            ...(!isSvg
                              ? {
                                  backgroundColor: surf.backgroundColor,
                                  borderColor: surf.borderColor,
                                  borderWidth: 2,
                                  borderStyle: 'solid'
                                }
                              : {})
                          }}
                          className={`relative flex items-center justify-center text-xs font-semibold shadow-[0_24px_60px_rgba(0,0,0,0.58)] ${
                            shapeType === 'pill'
                              ? 'rounded-full'
                              : shapeType === 'rect'
                                ? 'rounded-md'
                                : 'rounded-2xl'
                          } ${!isSvg && surf.backdropBlur ? 'backdrop-blur-md' : ''}`}
                        >
                          {isSvg ? (
                            <svg
                              viewBox={`0 0 ${w} ${h}`}
                              className="pointer-events-none absolute inset-0 size-full overflow-visible drop-shadow-xl"
                            >
                              {shapeType === 'ellipse' ? (
                                <ellipse
                                  cx={w / 2}
                                  cy={h / 2}
                                  rx={w / 2 - 2}
                                  ry={h / 2 - 2}
                                  fill={surf.backgroundColor}
                                  stroke={surf.borderColor}
                                  strokeWidth={2}
                                />
                              ) : (
                                <polygon
                                  points={`${w / 2},2 ${w - 2},${h / 2} ${w / 2},${h - 2} 2,${h / 2}`}
                                  fill={surf.backgroundColor}
                                  stroke={surf.borderColor}
                                  strokeWidth={2}
                                />
                              )}
                            </svg>
                          ) : null}
                          <span className="relative z-10 text-[11px] opacity-90">
                            Release to drop & label
                          </span>
                        </div>
                      )
                    })()
                  : dockDrag.kind === 'text-card'
                    ? (() => {
                        const preset =
                          TOOLBAR_TEXT_PRESETS.find(
                            (p) => p.id === (dockDrag.options.textCardPreset ?? activeTextPreset)
                          ) ?? TOOLBAR_TEXT_PRESETS[0]!
                        const fillStyle = dockDrag.options.fillStyle ?? preset.fillStyle
                        const color = dockDrag.options.color ?? preset.color
                        const surf = resolveWhiteboardSurfaceStyle({
                          kind: 'text',
                          color,
                          fillStyle,
                          borderStyle: dockDrag.options.borderStyle ?? preset.borderStyle
                        })
                        return (
                          <div
                            style={{
                              backgroundColor:
                                fillStyle === 'none' ? 'rgba(24,24,27,0.9)' : surf.backgroundColor,
                              borderColor:
                                fillStyle === 'none' ? 'rgba(56,189,248,0.65)' : surf.borderColor,
                              color: surf.textColor
                            }}
                            className="flex min-w-40 flex-col gap-0.5 rounded-xl border-2 px-4 py-2.5 shadow-[0_24px_60px_rgba(0,0,0,0.58)] backdrop-blur-md"
                          >
                            <span className="text-sm font-bold">
                              {dockDrag.options.defaultText || preset.sample}
                            </span>
                            <span className="text-[10px] opacity-75">Release to drop & type</span>
                          </div>
                        )
                      })()
                    : (() => {
                        const noteColor = dockDrag.options.color ?? dockNoteColor
                        const surf = resolveWhiteboardSurfaceStyle({
                          kind: 'note',
                          color: noteColor,
                          fillStyle: dockDrag.options.fillStyle ?? 'soft',
                          borderStyle: 'solid'
                        })
                        return (
                          <div
                            style={{
                              backgroundColor: surf.backgroundColor,
                              borderColor: surf.borderColor,
                              color: surf.textColor
                            }}
                            className="relative flex w-44 rotate-1 flex-col gap-1.5 rounded-xl border-2 p-3 text-xs shadow-[0_24px_60px_rgba(0,0,0,0.55)] backdrop-blur-md"
                          >
                            <div className="flex items-center justify-between font-semibold">
                              <span>Sticky Note</span>
                              <span className="text-[10px] uppercase opacity-70">{noteColor}</span>
                            </div>
                            <div className="space-y-1 py-0.5">
                              <div className="h-1 w-24 rounded-full bg-current/30" />
                              <div className="h-1 w-16 rounded-full bg-current/20" />
                            </div>
                            <span className="text-[10px] opacity-85">Release to drop & type</span>
                            <span className="pointer-events-none absolute right-0 bottom-0 size-3 rounded-tl-sm bg-black/20" />
                          </div>
                        )
                      })()}
            </div>,
            document.body
          )
        : null}
    </>
  )
}

// WS-0 (TASK_16 wave 2): bottom-right undo / redo + zoom out / fit / zoom in, moved verbatim from
// space-canvas.tsx. Owner: WS-A. WS-A: − / + share zoomStep() with the keys; the `?` shortcut help
// (ShortcutHelp) renders here only while open, so it adds no always-visible control.
import type { CanvasCtx, CanvasHandlers } from '../canvas-ctx'
import { WhiteboardHistoryControls } from '../../whiteboard-toolbar'
import { useEffect, useRef } from 'react'
import { setKeepOut } from '../../core/keep-out'
import { CORNER_GAP, CORNER_W, cornerBottomFor } from '../corner-layout'
import { useCanvasWidth } from '../use-canvas-width'
import { ShortcutHelp } from './ShortcutHelp'
import { endNudgeBurst } from '../keyboard/use-nudge'

export function HistoryZoomControls({
  ctx,
  g
}: {
  ctx: CanvasCtx
  g: CanvasHandlers
}): React.JSX.Element {
  const { canRedo, canUndo, onRedo, onUndo, rootRef, view } = ctx
  const { hasSelection, fitToSelection, fitAllSpaces, zoomStep } = g
  const cornerRef = useRef<HTMLDivElement | null>(null)
  const canvasWidth = useCanvasWidth(rootRef)
  const bottom = cornerBottomFor(canvasWidth)
  // U-37: tell the pinned squares where this column is (keep-out zone, shared/orca-plus/keep-out.ts).
  useEffect(() => {
    const el = cornerRef.current
    const publish = (): void => {
      const r = el?.getBoundingClientRect()
      setKeepOut(
        'canvas-corner',
        r && r.width > 0 ? { left: r.left, top: r.top, right: r.right, bottom: r.bottom } : null
      )
    }
    publish()
    window.addEventListener('resize', publish)
    return () => {
      window.removeEventListener('resize', publish)
      setKeepOut('canvas-corner', null)
    }
  }, [bottom, canvasWidth])
  return (
    <>
      {/* Bottom-Right History (Undo/Redo) + Zoom Controls */}
      {/* U-37: one column in the corner, clear of the whiteboard toolbar (see corner-layout.ts). */}
      <div
        ref={cornerRef}
        style={{ width: CORNER_W, right: CORNER_GAP, bottom }}
        className="op-canvas-corner pointer-events-none absolute z-30 flex flex-col items-end gap-1.5"
      >
        <WhiteboardHistoryControls
          canUndo={canUndo}
          canRedo={canRedo}
          onUndo={
            onUndo &&
            (() => {
              // A nudge burst still open would write over the undone state: close it first.
              endNudgeBurst(rootRef)
              onUndo()
            })
          }
          onRedo={
            onRedo &&
            (() => {
              endNudgeBurst(rootRef)
              onRedo()
            })
          }
        />
        <div className="pointer-events-auto flex items-center gap-0.5 whitespace-nowrap rounded-2xl border border-border/60 bg-card/95 p-1 text-xs shadow-lg backdrop-blur-md">
          <button
            type="button"
            title="Zoom out (1.5x step)"
            onClick={() => zoomStep('out')}
            className="rounded-xl px-2 py-1 text-sm font-bold text-muted-foreground hover:bg-accent hover:text-foreground"
          >
            −
          </button>
          <button
            type="button"
            data-zoom-fit={hasSelection ? 'selection' : 'all'}
            title={
              hasSelection ? 'Zoom to selection (Shift+2)' : 'Fit all Spaces in view (Shift+1)'
            }
            onClick={() => {
              if (!hasSelection || !fitToSelection()) {
                fitAllSpaces()
              }
            }}
            className="rounded-xl px-1.5 py-1 font-mono text-[11px] whitespace-nowrap text-muted-foreground hover:bg-accent hover:text-foreground"
          >
            {Math.round(view.scale * 100)}% · Fit
          </button>
          <button
            type="button"
            title="Zoom in (1.5x step)"
            onClick={() => zoomStep('in')}
            className="rounded-xl px-2 py-1 text-sm font-bold text-muted-foreground hover:bg-accent hover:text-foreground"
          >
            +
          </button>
        </div>
      </div>
      <ShortcutHelp owner={rootRef} />
    </>
  )
}

// WS-0 (TASK_16 wave 2): floating inspector for one selected note / shape / text card,
// moved verbatim from space-canvas.tsx. Owner: WS-E (color picker lands here).
// WS-E: a second row under the inspector: fill colour + opacity (controls/ColorField.tsx; no x/y/w/h).
// The selection context menu (overlays/ContextMenus.tsx) renders here too; nothing while closed.
import type { CanvasCtx, CanvasHandlers } from '../canvas-ctx'
import { ClampedFloatingToolbar } from '../canvas-parts'
import type { SpaceStickyNote } from '../../core/space'
import { WhiteboardItemInspector } from '../../whiteboard-toolbar'
import { ColorField } from '../controls/ColorField'
import { CanvasContextMenu } from './ContextMenus'

export function ItemInspector({
  ctx,
  g
}: {
  ctx: CanvasCtx
  g: CanvasHandlers
}): React.JSX.Element {
  const {
    boxMap,
    drawingArrow,
    editingStickyId,
    marqueeRect,
    onChangeToolMode,
    onUpdateStickyNote,
    panning,
    rootRef,
    setActiveFillStyle,
    setActiveShapeColor,
    setActiveShapeType,
    setEditingStickyId,
    singleSelectedSticky,
    view
  } = ctx
  const { bringIdsToFront, sendIdsToBack, duplicateSelected, deleteSelected, startArrowDrag } = g
  return (
    <>
      {/* Crisp 1:1 Screen-Space Floating Item Inspector above (or below near top edge) single selected item */}
      {singleSelectedSticky && !panning && !marqueeRect && !drawingArrow
        ? (() => {
            const selBox = boxMap.get(singleSelectedSticky.id)
            if (!selBox) {
              return null
            }
            const kind = singleSelectedSticky.kind ?? 'note'
            const hasBg = Boolean(
              singleSelectedSticky.fillStyle && singleSelectedSticky.fillStyle !== 'none'
            )
            const defaultBold = kind === 'text' && !hasBg
            const defaultFontSize = kind === 'text' ? (hasBg ? 18 : 36) : kind === 'shape' ? 16 : 14
            const curBold =
              (singleSelectedSticky.fontWeight ??
                (defaultBold ? 'bold' : kind === 'shape' ? 'semibold' : 'normal')) === 'bold'

            return (
              <ClampedFloatingToolbar anchorRect={selBox} view={view} containerRef={rootRef}>
                <div className="flex max-w-full flex-col items-center gap-1">
                  <WhiteboardItemInspector
                    kind={kind}
                    shapeType={singleSelectedSticky.shapeType ?? 'rounded'}
                    fillStyle={
                      singleSelectedSticky.fillStyle ?? (kind === 'text' ? 'none' : 'soft')
                    }
                    borderStyle={
                      singleSelectedSticky.borderStyle ??
                      (kind === 'text' && !hasBg ? 'none' : 'solid')
                    }
                    color={singleSelectedSticky.color ?? 'amber'}
                    fontSize={singleSelectedSticky.fontSize ?? defaultFontSize}
                    fontFamily={singleSelectedSticky.fontFamily ?? 'sans'}
                    bold={curBold}
                    textAlign={
                      singleSelectedSticky.textAlign ?? (kind === 'shape' ? 'center' : 'left')
                    }
                    locked={Boolean(singleSelectedSticky.locked)}
                    isEditing={editingStickyId === singleSelectedSticky.id}
                    onChangeShapeType={(st) => {
                      setActiveShapeType(st)
                      onUpdateStickyNote?.(singleSelectedSticky.id, { shapeType: st })
                    }}
                    onConvertToShape={(st = 'rounded') => {
                      const curFill = singleSelectedSticky.fillStyle
                      const nextFill = !curFill || curFill === 'none' ? 'soft' : curFill
                      onUpdateStickyNote?.(singleSelectedSticky.id, {
                        kind: 'shape',
                        shapeType: st,
                        fillStyle: nextFill,
                        borderStyle: 'solid',
                        textAlign: 'center',
                        w: Math.max(180, selBox.w),
                        h: Math.max(88, selBox.h),
                        fontSize: Math.min(36, singleSelectedSticky.fontSize ?? 20)
                      })
                    }}
                    onChangeFillStyle={(fs) => {
                      setActiveFillStyle(fs)
                      const patch: Partial<SpaceStickyNote> = { fillStyle: fs }
                      if (fs === 'paper' || fs === 'paper-light') {
                        patch.color = 'paper'
                      }
                      if (
                        kind === 'text' &&
                        fs !== 'none' &&
                        (!singleSelectedSticky.borderStyle ||
                          singleSelectedSticky.borderStyle === 'none')
                      ) {
                        patch.borderStyle = 'solid'
                      }
                      onUpdateStickyNote?.(singleSelectedSticky.id, patch)
                    }}
                    onChangeBorderStyle={(bs) =>
                      onUpdateStickyNote?.(singleSelectedSticky.id, { borderStyle: bs })
                    }
                    onChangeColor={(c) => {
                      setActiveShapeColor(c)
                      onUpdateStickyNote?.(singleSelectedSticky.id, { color: c })
                    }}
                    onChangeFontSize={(sz) =>
                      onUpdateStickyNote?.(singleSelectedSticky.id, { fontSize: sz })
                    }
                    onChangeFontFamily={(ff) =>
                      onUpdateStickyNote?.(singleSelectedSticky.id, { fontFamily: ff })
                    }
                    onToggleBold={(b) =>
                      onUpdateStickyNote?.(singleSelectedSticky.id, {
                        fontWeight: b ? 'bold' : 'normal'
                      })
                    }
                    onChangeTextAlign={(al) =>
                      onUpdateStickyNote?.(singleSelectedSticky.id, { textAlign: al })
                    }
                    onBringToFront={() => bringIdsToFront([singleSelectedSticky.id])}
                    onSendToBack={() => sendIdsToBack([singleSelectedSticky.id])}
                    onToggleLock={(lk) => {
                      if (lk) {
                        setEditingStickyId(null)
                      }
                      onUpdateStickyNote?.(singleSelectedSticky.id, { locked: lk })
                    }}
                    onEditText={() =>
                      setEditingStickyId((cur) =>
                        cur === singleSelectedSticky.id ? null : singleSelectedSticky.id
                      )
                    }
                    onDuplicate={duplicateSelected}
                    onStartConnectDrag={(ev) => startArrowDrag(ev, singleSelectedSticky.id)}
                    onConnect={() => onChangeToolMode?.('arrow')}
                    onDelete={() => {
                      deleteSelected()
                    }}
                  />
                  {singleSelectedSticky.locked ? null : (
                    <ColorField
                      color={singleSelectedSticky.color ?? 'amber'}
                      opacity={singleSelectedSticky.opacity}
                      onChangeColor={(c) => {
                        setActiveShapeColor(c)
                        onUpdateStickyNote?.(singleSelectedSticky.id, { color: c })
                      }}
                      onChangeOpacity={(op) =>
                        onUpdateStickyNote?.(singleSelectedSticky.id, { opacity: op })
                      }
                    />
                  )}
                </div>
              </ClampedFloatingToolbar>
            )
          })()
        : null}
      <CanvasContextMenu ctx={ctx} g={g} />
    </>
  )
}

// WS-D (TASK_16 wave 2): ⌘F jump to an agent or a Space by name. Same match as the Sessions sidebar
// filter in space-palette.tsx (name, Space title, subagent roles, split pane titles; see
// matchesSessionQuery), plus the agent's role and Space titles / goals. Enter or click = glide to the
// tile (+ select the agent). Never changes a goal or an ask. Owner: WS-D.
import { useEffect, useMemo, useRef, useState } from 'react'
import type { SpaceAgent, SpaceGoal } from '../../core/space'
import {
  readAgentSplitInfo,
  readAgentSubagents,
  type AgentPresenceFields
} from '../../sprites/space-agent-presence'
import { MiniSpacewareSprite } from '../../sprites/space-sprite'
import { spriteRoleOf } from '../../sprites/space-sprite-accessory'
import { isImeOwnedKeyboardEvent } from '../../core/ime-guard'
import type { CanvasCtx } from '../canvas-ctx'
import type { AskPinsApi } from './use-ask-pins'

/**
 * The Sessions sidebar match (space-palette.tsx filteredSessions), as one pure function so the
 * sidebar and ⌘F agree. `query` is already trimmed and lower case.
 */
export function matchesSessionQuery(
  agent: SpaceAgent,
  query: string,
  spaceTitle: string | undefined,
  activityText?: string
): boolean {
  const presence = agent as SpaceAgent & AgentPresenceFields
  return (
    agent.name.toLowerCase().includes(query) ||
    (spaceTitle?.toLowerCase().includes(query) ?? false) ||
    (activityText?.toLowerCase().includes(query) ?? false) ||
    readAgentSubagents(presence).some((s) => s.role.toLowerCase().includes(query)) ||
    (readAgentSplitInfo(presence)?.panes.some((p) => p.title?.toLowerCase().includes(query)) ??
      false)
  )
}

export type JumpTarget =
  | { kind: 'agent'; id: string; label: string; sub: string; agent: SpaceAgent }
  | { kind: 'goal'; id: string; label: string; sub: string }

/** Agents first (name starts with the query ranks higher), then Spaces. Max `limit` rows. */
export function searchJumpTargets(
  agents: readonly SpaceAgent[],
  goals: readonly SpaceGoal[],
  tileOfAgent: ReadonlyMap<string, string>,
  rawQuery: string,
  limit = 8
): JumpTarget[] {
  const query = rawQuery.trim().toLowerCase()
  const titleOf = new Map(goals.map((goal) => [goal.id, goal.title]))
  const agentRows: (JumpTarget & { rank: number })[] = []
  for (const agent of agents) {
    const tile = tileOfAgent.get(agent.id)
    const spaceTitle = tile ? titleOf.get(tile) : undefined
    const role = spriteRoleOf(agent)
    const hit =
      !query ||
      matchesSessionQuery(agent, query, spaceTitle) ||
      role.toLowerCase().includes(query) ||
      (agent.role?.toLowerCase().includes(query) ?? false)
    if (!hit) {
      continue
    }
    const name = agent.name.toLowerCase()
    agentRows.push({
      kind: 'agent',
      id: agent.id,
      label: agent.name,
      sub: spaceTitle ?? 'Bench',
      agent,
      rank: !query ? 2 : name.startsWith(query) ? 0 : name.includes(query) ? 1 : 2
    })
  }
  agentRows.sort((a, b) => a.rank - b.rank)
  const goalRows: JumpTarget[] = []
  for (const goal of goals) {
    if (goal.status === 'done') {
      continue
    }
    if (
      !query ||
      goal.title.toLowerCase().includes(query) ||
      goal.goal.toLowerCase().includes(query)
    ) {
      goalRows.push({ kind: 'goal', id: goal.id, label: goal.title, sub: 'Space' })
    }
  }
  return [...agentRows.map(({ rank: _rank, ...row }) => row as JumpTarget), ...goalRows].slice(
    0,
    limit
  )
}

export function JumpTo({
  ctx,
  api,
  onClose
}: {
  ctx: CanvasCtx
  api: AskPinsApi
  onClose: () => void
}): React.JSX.Element {
  const [query, setQuery] = useState('')
  const [cursor, setCursor] = useState(0)
  const inputRef = useRef<HTMLInputElement | null>(null)
  const results = useMemo(
    () => searchJumpTargets(ctx.agents, ctx.space.goals, api.tileOfAgent, query),
    [api.tileOfAgent, ctx.agents, ctx.space.goals, query]
  )
  useEffect(() => {
    inputRef.current?.focus()
  }, [])
  const pick = (target: JumpTarget | undefined): void => {
    if (!target) {
      return
    }
    if (target.kind === 'agent') {
      api.goToAgent(target.id)
    } else {
      api.goToTile(target.id)
    }
    onClose()
  }
  const active = Math.min(cursor, Math.max(0, results.length - 1))
  return (
    <div
      data-jump-to="true"
      role="dialog"
      aria-label="Jump to agent or Space"
      onPointerDown={(event) => event.stopPropagation()}
      className="pointer-events-auto absolute left-1/2 top-3 z-40 w-[320px] max-w-[calc(100%-32px)] -translate-x-1/2 rounded-2xl border border-white/10 bg-zinc-950/95 p-1.5 shadow-2xl backdrop-blur-md"
    >
      <input
        ref={inputRef}
        type="search"
        value={query}
        placeholder="Jump to agent or Space…"
        aria-label="Jump to agent or Space by name"
        onChange={(event) => {
          setQuery(event.target.value)
          setCursor(0)
        }}
        onBlur={(event) => {
          if (!event.currentTarget.parentElement?.contains(event.relatedTarget as Node | null)) {
            onClose()
          }
        }}
        onKeyDown={(event) => {
          if (isImeOwnedKeyboardEvent(event)) {
            return
          }
          if (event.key === 'Escape') {
            event.preventDefault()
            onClose()
          } else if (event.key === 'ArrowDown') {
            event.preventDefault()
            setCursor((c) => Math.min(c + 1, results.length - 1))
          } else if (event.key === 'ArrowUp') {
            event.preventDefault()
            setCursor((c) => Math.max(c - 1, 0))
          } else if (event.key === 'Enter') {
            event.preventDefault()
            pick(results[active])
          }
        }}
        className="w-full rounded-xl border border-white/10 bg-white/[0.04] px-2.5 py-1.5 text-sm text-zinc-100 outline-none placeholder:text-zinc-500 focus:border-white/25"
      />
      <ul
        role="listbox"
        aria-label="Matches"
        className="scrollbar-sleek mt-1 max-h-[280px] overflow-y-auto"
      >
        {results.length === 0 ? (
          <li className="px-2.5 py-2 text-xs text-zinc-500">No agent or Space with that name.</li>
        ) : (
          results.map((target, i) => (
            <li
              key={`${target.kind}:${target.id}`}
              role="option"
              aria-selected={i === active}
              data-jump-target={`${target.kind}:${target.id}`}
              onMouseEnter={() => setCursor(i)}
              onMouseDown={(event) => event.preventDefault()}
              onClick={() => pick(target)}
              className={`flex cursor-pointer items-center gap-2 rounded-lg px-2 py-1.5 text-sm ${
                i === active ? 'bg-white/10 text-white' : 'text-zinc-300'
              }`}
            >
              {target.kind === 'agent' ? (
                <MiniSpacewareSprite
                  busy={target.agent.busy}
                  attention={target.agent.attention}
                  awake
                  role={spriteRoleOf(target.agent)}
                />
              ) : (
                <span aria-hidden="true" className="w-6 text-center text-xs text-zinc-500">
                  ▢
                </span>
              )}
              <span className="min-w-0 flex-1 truncate">{target.label}</span>
              <span className="shrink-0 text-[10px] text-zinc-500">{target.sub}</span>
            </li>
          ))
        )}
      </ul>
    </div>
  )
}

// WS-C (TASK_16 wave 2): the whiteboard layers panel. A left drawer that lists Spaces (read only), notes /
// shapes / text (top of the paint order first, groups folded under a header) and arrows, with eye, lock,
// rename (double-click) and drag reorder (= zIndex). Idea from Penpot's layers sidebar
// (ui/workspace/sidebar/layers.cljs, layer_item.cljs) and our G_app-Data TreeTable `layers` mode;
// re-implemented, no Penpot or G_app-Data code.
// Opens and closes only from ⌥L (listed in the `?` help; Esc inside it closes too). No close button and
// nothing rendered while closed: no always-visible chrome. Per row: eye + lock buttons only.
// Agent data rule: Space rows have no control (no eye, no lock, no group, no drag); every write goes
// through layers-actions.ts / onUpdateArrow and patches stickies or arrows only.
import { useEffect, useMemo, useRef, useState } from 'react'
import { Eye, EyeOff, Group, Lock, Unlock } from 'lucide-react'
import type { CanvasCtx } from '../canvas-ctx'
import { isImeOwnedKeyboardEvent } from '../../core/ime-guard'
import { registerCanvasCommands } from '../keyboard/commands'
import { paintOrder, reorderPatches } from '../../core/whiteboard-groups'
import { toggleHidden, toggleLock } from './layers-actions'
import { LAYER_ROW_PX, LAYER_VIRTUAL_AFTER, buildLayerRows, type LayerRow } from './layers-rows'
import { WHITEBOARD_LAYER_COMMANDS } from './layers-commands'
import { setLayersPanelOpen, useLayersPanelOpen } from './layers-store'

// The rows are registered once per window, however many canvases are mounted.
let registered = 0
let unregisterRows: (() => void) | null = null

function useLayerCommands(): void {
  useEffect(() => {
    registered += 1
    if (registered === 1) {
      unregisterRows = registerCanvasCommands(WHITEBOARD_LAYER_COMMANDS).unregister
    }
    return () => {
      registered -= 1
      if (registered === 0) {
        unregisterRows?.()
        unregisterRows = null
      }
    }
  }, [])
}

export function LayersPanel({ ctx }: { ctx: CanvasCtx }): React.JSX.Element | null {
  useLayerCommands()
  const open = useLayersPanelOpen()
  return open ? <LayersPanelBody ctx={ctx} /> : null
}

type DropHint = { key: string; place: 'above' | 'below' } | null

function LayersPanelBody({ ctx }: { ctx: CanvasCtx }): React.JSX.Element {
  const {
    arrows,
    onBatchUpdateStickyNotes,
    onUpdateArrow,
    onUpdateStickyNote,
    onWhiteboardTransaction,
    selectedArrowId,
    selectedStickyIdSet,
    setSelectedArrowId,
    setSelectedStickyIds,
    stickies,
    visibleGoals
  } = ctx
  const rows = useMemo(
    () => buildLayerRows(visibleGoals, stickies, arrows),
    [visibleGoals, stickies, arrows]
  )
  const [renaming, setRenaming] = useState<string | null>(null)
  const [draft, setDraft] = useState('')
  const [dropHint, setDropHint] = useState<DropHint>(null)
  const [scrollTop, setScrollTop] = useState(0)
  const [viewH, setViewH] = useState(480)
  const dragIdsRef = useRef<string[] | null>(null)
  const listRef = useRef<HTMLDivElement | null>(null)

  useEffect(() => {
    const el = listRef.current
    if (el && el.clientHeight > 0) {
      setViewH(el.clientHeight)
    }
  }, [])

  const virtual = rows.length > LAYER_VIRTUAL_AFTER
  const first = virtual ? Math.max(0, Math.floor(scrollTop / LAYER_ROW_PX) - 10) : 0
  const last = virtual
    ? Math.min(rows.length, Math.ceil((scrollTop + viewH) / LAYER_ROW_PX) + 10)
    : rows.length
  const shown = rows.slice(first, last)

  const stickyIdsOf = (row: LayerRow): string[] =>
    row.kind === 'group' ? row.memberIds : row.kind === 'sticky' ? [row.id] : []

  const select = (row: LayerRow, additive: boolean): void => {
    if (row.kind === 'arrow') {
      if (!row.hidden) {
        setSelectedStickyIds([])
        setSelectedArrowId(row.id)
      }
      return
    }
    if (row.kind !== 'group' && row.kind !== 'sticky') {
      return
    }
    // A hidden layer is listed but never selected (P3-37: never moved, copied or deleted by accident).
    const hidden = new Set(stickies.filter((s) => s.hidden).map((s) => s.id))
    const ids = stickyIdsOf(row).filter((id) => !hidden.has(id))
    if (ids.length === 0) {
      return
    }
    setSelectedArrowId(null)
    setSelectedStickyIds((cur) =>
      additive ? [...cur.filter((id) => !ids.includes(id)), ...ids] : ids
    )
  }

  const startRename = (row: LayerRow): void => {
    if (row.kind !== 'sticky' && row.kind !== 'arrow') {
      return
    }
    setRenaming(row.key)
    setDraft(row.label)
  }

  const commitRename = (row: LayerRow): void => {
    setRenaming(null)
    const name = draft.trim() || undefined
    if (row.kind === 'sticky') {
      if ((stickies.find((s) => s.id === row.id)?.name ?? undefined) !== name) {
        onUpdateStickyNote?.(row.id, { name })
      }
    } else if (row.kind === 'arrow') {
      if ((arrows.find((a) => a.id === row.id)?.name ?? undefined) !== name) {
        onUpdateArrow?.(row.id, { name })
      }
    }
  }

  const toggleEye = (row: LayerRow): void => {
    if (row.kind === 'arrow') {
      onUpdateArrow?.(row.id, { hidden: row.hidden ? undefined : true })
      if (!row.hidden && selectedArrowId === row.id) {
        setSelectedArrowId(null)
      }
      return
    }
    toggleHidden(ctx, stickyIdsOf(row))
  }

  const drop = (row: LayerRow, place: 'above' | 'below'): void => {
    const moving = dragIdsRef.current
    dragIdsRef.current = null
    setDropHint(null)
    const target = stickyIdsOf(row)
    if (!moving || target.length === 0) {
      return
    }
    // A group target: above its top member, or below its bottom member.
    const order = paintOrder(stickies).map((s) => s.id)
    const sorted = [...target].sort((a, b) => order.indexOf(a) - order.indexOf(b))
    const targetId = (place === 'above' ? (sorted.at(-1) ?? sorted[0]) : sorted[0])!
    const result = reorderPatches(stickies, moving, targetId, place)
    if (result.ok && Object.keys(result.patches).length > 0) {
      const write = (): void => onBatchUpdateStickyNotes?.(result.patches)
      if (onWhiteboardTransaction) {
        onWhiteboardTransaction(write)
      } else {
        write()
      }
    }
  }

  const renderRow = (row: LayerRow): React.JSX.Element => {
    if (row.kind === 'section') {
      return (
        <div
          key={row.key}
          className="flex items-end px-2 pb-0.5 text-[10px] font-semibold uppercase tracking-wide text-muted-foreground"
          style={{ height: LAYER_ROW_PX }}
        >
          {row.label}
        </div>
      )
    }
    if (row.kind === 'goal') {
      return (
        <div
          key={row.key}
          role="treeitem"
          aria-readonly="true"
          data-whiteboard-layer-goal={row.id}
          title="Space (agent data: read only here)"
          className="flex items-center gap-1.5 truncate rounded-lg px-2 text-muted-foreground"
          style={{ height: LAYER_ROW_PX }}
        >
          <span className="truncate">{row.label}</span>
        </div>
      )
    }
    const isSelected =
      row.kind === 'arrow'
        ? selectedArrowId === row.id
        : stickyIdsOf(row).length > 0 && stickyIdsOf(row).every((id) => selectedStickyIdSet.has(id))
    const draggable = row.kind === 'sticky' || row.kind === 'group'
    const hint = dropHint?.key === row.key ? dropHint.place : null
    const locked = row.kind === 'arrow' ? false : row.locked
    return (
      <div
        key={row.key}
        role="treeitem"
        aria-selected={isSelected}
        data-whiteboard-layer={row.kind === 'group' ? `group:${row.groupId}` : row.id}
        draggable={draggable && renaming !== row.key}
        onDragStart={(event) => {
          dragIdsRef.current = stickyIdsOf(row)
          event.dataTransfer?.setData('text/plain', row.key)
        }}
        onDragOver={(event) => {
          if (!draggable || !dragIdsRef.current) {
            return
          }
          event.preventDefault()
          const rect = event.currentTarget.getBoundingClientRect()
          const place = event.clientY - rect.top < rect.height / 2 ? 'above' : 'below'
          setDropHint((cur) =>
            cur?.key === row.key && cur.place === place ? cur : { key: row.key, place }
          )
        }}
        onDragLeave={() => setDropHint((cur) => (cur?.key === row.key ? null : cur))}
        onDrop={(event) => {
          event.preventDefault()
          drop(row, hint ?? 'above')
        }}
        onDragEnd={() => {
          dragIdsRef.current = null
          setDropHint(null)
        }}
        onClick={(event) => select(row, event.shiftKey)}
        onDoubleClick={() => startRename(row)}
        className={`group/layer flex items-center gap-1 rounded-lg pr-1 ${
          row.kind === 'sticky' && row.depth === 1 ? 'pl-6' : 'pl-2'
        } ${isSelected ? 'bg-sky-500/20 text-foreground' : 'text-foreground hover:bg-muted/60'} ${
          row.hidden ? 'opacity-50' : ''
        } ${hint === 'above' ? 'shadow-[inset_0_2px_0_#38bdf8]' : ''} ${
          hint === 'below' ? 'shadow-[inset_0_-2px_0_#38bdf8]' : ''
        }`}
        style={{ height: LAYER_ROW_PX }}
      >
        {row.kind === 'group' ? <Group className="size-3 shrink-0 text-muted-foreground" /> : null}
        {renaming === row.key ? (
          <input
            autoFocus
            value={draft}
            aria-label="Layer name"
            maxLength={120}
            onChange={(event) => setDraft(event.target.value)}
            onBlur={() => commitRename(row)}
            onKeyDown={(event) => {
              if (isImeOwnedKeyboardEvent(event)) {
                return
              }
              if (event.key === 'Enter') {
                event.preventDefault()
                commitRename(row)
              } else if (event.key === 'Escape') {
                event.preventDefault()
                event.stopPropagation()
                setRenaming(null)
              }
            }}
            className="min-w-0 flex-1 rounded-md border border-border/60 bg-background px-1 text-xs outline-none focus:border-ring"
          />
        ) : (
          <span className="min-w-0 flex-1 truncate">{row.label}</span>
        )}
        <button
          type="button"
          aria-label={row.hidden ? 'Show layer' : 'Hide layer'}
          title={row.hidden ? 'Show' : 'Hide'}
          onClick={(event) => {
            event.stopPropagation()
            toggleEye(row)
          }}
          className={`flex size-5 shrink-0 items-center justify-center rounded-md text-muted-foreground hover:text-foreground ${
            row.hidden ? '' : 'opacity-0 group-hover/layer:opacity-100 focus-visible:opacity-100'
          }`}
        >
          {row.hidden ? <EyeOff className="size-3" /> : <Eye className="size-3" />}
        </button>
        {row.kind === 'arrow' ? (
          <span className="size-5 shrink-0" />
        ) : (
          <button
            type="button"
            aria-label={locked ? 'Unlock layer' : 'Lock layer'}
            title={locked ? 'Unlock' : 'Lock'}
            onClick={(event) => {
              event.stopPropagation()
              toggleLock(ctx, stickyIdsOf(row))
            }}
            className={`flex size-5 shrink-0 items-center justify-center rounded-md text-muted-foreground hover:text-foreground ${
              locked
                ? 'text-amber-300'
                : 'opacity-0 group-hover/layer:opacity-100 focus-visible:opacity-100'
            }`}
          >
            {locked ? <Lock className="size-3" /> : <Unlock className="size-3" />}
          </button>
        )}
      </div>
    )
  }

  return (
    <div
      role="dialog"
      aria-label="Layers"
      data-whiteboard-layers="true"
      data-orca-plus-scroll-lock="true"
      onPointerDown={(event) => event.stopPropagation()}
      onKeyDown={(event) => {
        if (event.key === 'Escape' && !renaming) {
          event.preventDefault()
          setLayersPanelOpen(false)
        }
      }}
      className="absolute top-3 bottom-16 left-3 z-40 flex w-64 flex-col rounded-2xl border border-border/60 bg-card/95 p-1.5 text-xs shadow-lg backdrop-blur-md"
    >
      <div className="flex items-center justify-between px-2 pb-1">
        <span className="font-semibold text-foreground">Layers</span>
        <kbd className="font-mono text-[10px] text-muted-foreground" title="⌥L or Esc closes">
          ⌥L
        </kbd>
      </div>
      <div
        ref={listRef}
        role="tree"
        data-space-scroll="true"
        onScroll={(event) => setScrollTop(event.currentTarget.scrollTop)}
        className="scrollbar-sleek min-h-0 flex-1 overflow-y-auto"
      >
        {rows.length === 0 ? (
          <p className="px-2 py-2 text-muted-foreground">Nothing on this board yet.</p>
        ) : virtual ? (
          <div style={{ height: rows.length * LAYER_ROW_PX, position: 'relative' }}>
            <div style={{ position: 'absolute', top: first * LAYER_ROW_PX, left: 0, right: 0 }}>
              {shown.map(renderRow)}
            </div>
          </div>
        ) : (
          shown.map(renderRow)
        )}
      </div>
    </div>
  )
}

// WS-0 (TASK_16 wave 2): floating multi-selection bar (align, distribute, batch fill / color, lock,
// layer, duplicate, delete), moved verbatim from space-canvas.tsx. Owner: WS-B.
import type { CanvasCtx, CanvasHandlers } from '../canvas-ctx'
import type { BoxRect } from '../canvas-ctx'
import { ClampedFloatingToolbar } from '../canvas-parts'
import type { SpaceStickyNote } from '../../core/space'
import { WhiteboardMultiSelectBar } from '../../whiteboard-toolbar'

export function MultiSelectBar({
  ctx,
  g
}: {
  ctx: CanvasCtx
  g: CanvasHandlers
}): React.JSX.Element {
  const {
    activeFillStyle,
    activeShapeColor,
    boxMap,
    drawingArrow,
    effectiveSelectedIds,
    marqueeRect,
    onBatchUpdateStickyNotes,
    panning,
    rootRef,
    setActiveFillStyle,
    setActiveShapeColor,
    setEditingStickyId,
    setSelectedStickyIds,
    stickiesById,
    view
  } = ctx
  const {
    bringIdsToFront,
    sendIdsToBack,
    duplicateSelected,
    deleteSelected,
    handleMultiAlign,
    handleMultiDistribute
  } = g
  return (
    <>
      {/* Screen-Space Floating Multi-Selection Alignment, Distribution, Batch Fill/Color, Lock & Layer Bar */}
      {effectiveSelectedIds.length >= 2 && !panning && !marqueeRect && !drawingArrow
        ? (() => {
            let minX = Number.POSITIVE_INFINITY
            let minY = Number.POSITIVE_INFINITY
            let maxX = Number.NEGATIVE_INFINITY
            let maxY = Number.NEGATIVE_INFINITY
            let allLocked = true
            for (const id of effectiveSelectedIds) {
              const b = boxMap.get(id)
              if (b) {
                minX = Math.min(minX, b.x)
                minY = Math.min(minY, b.y)
                maxX = Math.max(maxX, b.x + b.w)
                maxY = Math.max(maxY, b.y + b.h)
              }
              if (!stickiesById.get(id)?.locked) {
                allLocked = false
              }
            }
            const groupAnchor: BoxRect = Number.isFinite(minX)
              ? {
                  x: minX - 10,
                  y: minY - 10,
                  w: maxX - minX + 20,
                  h: maxY - minY + 20
                }
              : { x: 240, y: 180, w: 320, h: 120 }

            return (
              <ClampedFloatingToolbar anchorRect={groupAnchor} view={view} containerRef={rootRef}>
                <WhiteboardMultiSelectBar
                  selectedCount={effectiveSelectedIds.length}
                  activeColor={activeShapeColor}
                  activeFillStyle={activeFillStyle}
                  allLocked={allLocked}
                  onAlign={handleMultiAlign}
                  onDistribute={handleMultiDistribute}
                  onBatchColor={(c) => {
                    setActiveShapeColor(c)
                    const patches: Record<string, Partial<SpaceStickyNote>> = {}
                    for (const id of effectiveSelectedIds) {
                      if (!stickiesById.get(id)?.locked) {
                        patches[id] = { color: c }
                      }
                    }
                    onBatchUpdateStickyNotes?.(patches)
                  }}
                  onBatchFillStyle={(fs) => {
                    setActiveFillStyle(fs)
                    const patches: Record<string, Partial<SpaceStickyNote>> = {}
                    for (const id of effectiveSelectedIds) {
                      const it = stickiesById.get(id)
                      if (it && !it.locked) {
                        patches[id] = {
                          fillStyle: fs,
                          ...(fs === 'paper' || fs === 'paper-light' ? { color: 'paper' } : {}),
                          ...(it.kind === 'text' &&
                          fs !== 'none' &&
                          (!it.borderStyle || it.borderStyle === 'none')
                            ? { borderStyle: 'solid' }
                            : {})
                        }
                      }
                    }
                    onBatchUpdateStickyNotes?.(patches)
                  }}
                  onBringToFront={() => bringIdsToFront(effectiveSelectedIds)}
                  onSendToBack={() => sendIdsToBack(effectiveSelectedIds)}
                  onDuplicate={duplicateSelected}
                  onToggleLock={(nextLocked) => {
                    if (nextLocked) {
                      setEditingStickyId(null)
                    }
                    const patches: Record<string, Partial<SpaceStickyNote>> = {}
                    for (const id of effectiveSelectedIds) {
                      patches[id] = { locked: nextLocked }
                    }
                    onBatchUpdateStickyNotes?.(patches)
                  }}
                  onDelete={() => {
                    deleteSelected()
                  }}
                  onClearSelection={() => setSelectedStickyIds([])}
                />
              </ClampedFloatingToolbar>
            )
          })()
        : null}
    </>
  )
}

// U-37: after a Fit that showed only the Spaces with members, a small chip on each side says how many
// Spaces are off screen ("← 4 Spaces"); a click pans to the nearest one. Renders nothing otherwise.
import type { CanvasCtx } from '../canvas-ctx'
import { offscreenGroups, type OffscreenSide } from '../../core/viewport-fit'

const ARROW: Record<OffscreenSide, string> = { left: '←', right: '→', top: '↑', bottom: '↓' }
const POS: Record<OffscreenSide, string> = {
  left: 'left-2 top-1/2 -translate-y-1/2',
  right: 'right-2 top-1/2 -translate-y-1/2',
  top: 'top-14 left-1/2 -translate-x-1/2',
  bottom: 'bottom-28 left-1/2 -translate-x-1/2'
}

export function OffscreenCue({ ctx }: { ctx: CanvasCtx }): React.JSX.Element | null {
  const { boxMap, fitPartial, markZoomTween, rootRef, setView, view } = ctx
  const el = rootRef.current
  if (!fitPartial || !el) {
    return null
  }
  const boxes = ctx.tiles.flatMap((t) => {
    const b = boxMap.get(t.key)
    return b ? [b] : []
  })
  const groups = offscreenGroups(boxes, view, el.clientWidth, el.clientHeight)
  if (groups.length === 0) {
    return null
  }
  return (
    <>
      {groups.map((group) => (
        <button
          key={group.side}
          type="button"
          data-offscreen-cue={group.side}
          title="Pan to the nearest Space"
          onPointerDown={(event) => event.stopPropagation()}
          onClick={() => {
            markZoomTween()
            setView((v) => ({
              scale: v.scale,
              x: el.clientWidth / 2 - group.target.x * v.scale,
              y: el.clientHeight / 2 - group.target.y * v.scale
            }))
          }}
          className={`pointer-events-auto absolute z-30 whitespace-nowrap rounded-full border border-border/60 bg-card/95 px-2.5 py-1 text-[11px] font-medium text-foreground shadow-lg backdrop-blur-md hover:bg-accent ${POS[group.side]}`}
        >
          {ARROW[group.side]} {group.count} {group.count === 1 ? 'Space' : 'Spaces'}
        </button>
      ))}
    </>
  )
}

// WS-A (TASK_16 wave 2): the `?` keyboard-shortcut help, generated from the one command table
// (keyboard/commands.ts). Idea from Penpot's shortcuts panel (ui/workspace/sidebar/shortcuts.cljs:
// grouped list + search); re-implemented, no Penpot code. Opens only from `?`; Esc or a click outside
// closes it. No button and no click handler: it adds nothing to the always-visible UI.
import { useEffect, useMemo, useRef, useState } from 'react'
import { HOLD_HINTS, allCanvasCommands, type CommandGroup } from '../keyboard/commands'
import { setShortcutHelpOpen, useShortcutHelpOpen } from '../keyboard/help-store'

const GROUP_ORDER: readonly CommandGroup[] = ['Tools', 'Edit', 'Arrange', 'View', 'Help']

export type HelpRow = { id: string; label: string; display: string; group: CommandGroup }

/** The rows the help lists: canvas-scope commands + hold hints, filtered by a free-text query. */
export function shortcutHelpRows(query: string, owner?: unknown): HelpRow[] {
  const rows: HelpRow[] = [
    ...allCanvasCommands(owner)
      .filter((c) => c.scope === 'canvas')
      .map((c) => ({ id: c.id, label: c.label, display: c.display, group: c.group })),
    ...HOLD_HINTS.map((h) => ({ id: `hold.${h.display}`, ...h }))
  ]
  const words = query.toLowerCase().split(/\s+/).filter(Boolean)
  return rows.filter((r) => {
    const hay = `${r.label} ${r.display} ${r.id} ${r.group}`.toLowerCase()
    return words.every((w) => hay.includes(w))
  })
}

export function ShortcutHelp({ owner }: { owner?: unknown }): React.JSX.Element | null {
  const open = useShortcutHelpOpen()
  return open ? <ShortcutHelpPanel owner={owner} /> : null
}

function ShortcutHelpPanel({ owner }: { owner?: unknown }): React.JSX.Element {
  const [query, setQuery] = useState('')
  const panelRef = useRef<HTMLDivElement | null>(null)
  const inputRef = useRef<HTMLInputElement | null>(null)
  const rows = useMemo(() => shortcutHelpRows(query, owner), [owner, query])

  useEffect(() => {
    inputRef.current?.focus()
    const onPointerDown = (event: PointerEvent): void => {
      if (!panelRef.current?.contains(event.target as Node)) {
        setShortcutHelpOpen(false)
      }
    }
    document.addEventListener('pointerdown', onPointerDown, true)
    return () => document.removeEventListener('pointerdown', onPointerDown, true)
  }, [])

  return (
    <div
      ref={panelRef}
      role="dialog"
      aria-label="Keyboard shortcuts"
      data-space-shortcut-help="true"
      data-orca-plus-scroll-lock="true"
      onPointerDown={(e) => e.stopPropagation()}
      className="absolute right-3 bottom-16 z-40 flex max-h-[70%] w-80 flex-col rounded-2xl border border-border/60 bg-card/95 p-2 text-xs shadow-lg backdrop-blur-md"
    >
      <input
        ref={inputRef}
        type="search"
        value={query}
        placeholder="Search shortcuts"
        aria-label="Search shortcuts"
        onChange={(e) => setQuery(e.target.value)}
        onKeyDown={(e) => {
          if (e.key === 'Escape') {
            e.preventDefault()
            e.stopPropagation()
            setShortcutHelpOpen(false)
          }
        }}
        className="mb-2 rounded-xl border border-border/60 bg-background px-2.5 py-1.5 text-xs text-foreground outline-none placeholder:text-muted-foreground focus:border-ring"
      />
      <div className="scrollbar-sleek min-h-0 overflow-y-auto" data-space-scroll="true">
        {rows.length === 0 ? (
          <p className="px-1 py-2 text-muted-foreground">No shortcut matches.</p>
        ) : (
          GROUP_ORDER.map((group) => {
            const inGroup = rows.filter((r) => r.group === group)
            if (inGroup.length === 0) {
              return null
            }
            return (
              <section key={group} className="mb-1.5">
                <h3 className="px-1 pb-0.5 text-[10px] font-semibold uppercase tracking-wide text-muted-foreground">
                  {group}
                </h3>
                <ul>
                  {inGroup.map((r) => (
                    <li
                      key={r.id}
                      data-shortcut-id={r.id}
                      className="flex items-center justify-between gap-2 rounded-lg px-1 py-0.5 text-foreground"
                    >
                      <span>{r.label}</span>
                      <kbd className="rounded-md border border-border/60 bg-background px-1.5 font-mono text-[11px] text-muted-foreground">
                        {r.display}
                      </kbd>
                    </li>
                  ))}
                </ul>
              </section>
            )
          })
        )}
      </div>
    </div>
  )
}

// WS-E (TASK_16 wave 2): the canvas context menu's state (a tiny external store, like layers-store.ts)
// and its rows (pure: which rows each target shows, with labels from the ONE key table).
// The menu itself and the right-click wiring live in ContextMenus.tsx.
import type { Point } from '../../core/space'
import { allCanvasCommands, type CanvasCommand } from '../keyboard/commands'

// ── Open / closed state (tiny external store, like layers-store.ts) ────────────────────────────────

export type ContextMenuTarget =
  { kind: 'selection' } | { kind: 'arrow'; id: string } | { kind: 'goal'; id: string }
export type ContextMenuState = {
  /** Client px of the click (the menu's top-left). */
  client: Point
  /** Canvas point of the click (Paste lands there). */
  at: Point
  target: ContextMenuTarget
  /** Where focus goes back on Esc / close. */
  returnFocus: HTMLElement | null
}

let menu: ContextMenuState | null = null
const listeners = new Set<() => void>()
function emit(): void {
  for (const fn of listeners) {
    fn()
  }
}
export function openCanvasContextMenu(next: ContextMenuState): void {
  menu = next
  emit()
}
export function closeCanvasContextMenu(): void {
  if (menu) {
    menu = null
    emit()
  }
}
export function canvasContextMenuState(): ContextMenuState | null {
  return menu
}
export function subscribeCanvasContextMenu(fn: () => void): () => void {
  listeners.add(fn)
  return () => {
    listeners.delete(fn)
  }
}

// ── Rows ───────────────────────────────────────────────────────────────────────────────────────────

export type ContextMenuItemId =
  | 'copy'
  | 'paste'
  | 'duplicate'
  | 'delete'
  | 'front'
  | 'back'
  | 'group'
  | 'ungroup'
  | 'hide'
  | 'lock'
  | 'zoom'
  | 'open'
export type ContextMenuItem = {
  id: ContextMenuItemId
  label: string
  /** Display of the key-table row ('' when the action has no key). */
  shortcut: string
  disabled?: boolean
  /** Draw a divider above this row. */
  divider?: boolean
}

/** Key-table row behind each menu row (labels stay in step with the `?` help). */
const COMMAND_OF: Partial<Record<ContextMenuItemId, string>> = {
  copy: 'edit.copy',
  paste: 'edit.paste',
  duplicate: 'edit.duplicate',
  delete: 'edit.delete',
  front: 'arrange.front',
  back: 'arrange.back',
  group: 'arrange.group',
  ungroup: 'arrange.ungroup',
  hide: 'edit.hide',
  lock: 'edit.lock',
  zoom: 'view.fitSelection'
}

export function shortcutFor(
  id: ContextMenuItemId,
  rows: readonly CanvasCommand[] = allCanvasCommands()
): string {
  const cmd = COMMAND_OF[id]
  return (cmd && rows.find((r) => r.id === cmd)?.display) || ''
}

/** The rows a target shows. Pure: the menu test checks each selection type here. */
export function contextMenuItems(
  target: ContextMenuTarget,
  state: {
    canGroup: boolean
    canUngroup: boolean
    hideLabel: 'Hide' | 'Show'
    lockLabel: 'Lock' | 'Unlock'
    allLocked: boolean
    canPaste: boolean
  },
  rows: readonly CanvasCommand[] = allCanvasCommands()
): ContextMenuItem[] {
  const item = (
    id: ContextMenuItemId,
    label: string,
    extra: Partial<ContextMenuItem> = {}
  ): ContextMenuItem => ({ id, label, shortcut: shortcutFor(id, rows), ...extra })
  if (target.kind === 'goal') {
    // Agent data rule: a Space tile gets only rows that read it (nothing copies, hides or deletes it).
    return [item('zoom', 'Zoom to Space'), item('open', 'Open Space')]
  }
  if (target.kind === 'arrow') {
    return [item('paste', 'Paste here', { disabled: !state.canPaste }), item('delete', 'Delete')]
  }
  return [
    item('copy', 'Copy'),
    item('paste', 'Paste here', { disabled: !state.canPaste }),
    item('duplicate', 'Duplicate', { disabled: state.allLocked }),
    item('delete', 'Delete', { disabled: state.allLocked }),
    item('front', 'Bring to front', { divider: true, disabled: state.allLocked }),
    item('back', 'Send to back', { disabled: state.allLocked }),
    item('group', 'Group', { divider: true, disabled: !state.canGroup }),
    item('ungroup', 'Ungroup', { disabled: !state.canUngroup }),
    item('hide', state.hideLabel),
    item('lock', state.lockLabel),
    item('zoom', 'Zoom to selection', { divider: true })
  ]
}

// WS-C (TASK_16 wave 2): group / ungroup / hide / lock on the Spaces whiteboard, bound to the canvas.
// The pure rules live in shared/orca-plus/whiteboard-groups.ts; this file applies their patches in ONE
// onBatchUpdateStickyNotes write inside onWhiteboardTransaction (= one undo entry) and keeps the canvas
// selection honest (a hidden sticky leaves the selection).
//
// Public API for WS-E's context menu and WS-B's box. Every action takes the CanvasCtx (or the subset
// below) and an optional id list (default: the current sticky selection) and returns a result:
//   groupSelection(ctx, ids?)    ⌘G   2+ stickies -> one new group
//   ungroupSelection(ctx, ids?)  ⇧⌘G  every group touched is dissolved
//   toggleHidden(ctx, ids?)      ⇧⌘H  any visible -> hide all, else show all
//   toggleLock(ctx, ids?)        ⌘L   any unlocked -> lock all, else unlock all
//   whiteboardActionState(ctx, ids?) -> { canGroup, canUngroup, hideLabel, lockLabel } for menu rows
// Agent data rule: goal ids (and any non-sticky id) are refused; asks, tasks, notes, placements and
// removedAskIds are never touched (only stickies are patched).
import type { CanvasCtx } from '../canvas-ctx'
import {
  groupIndex,
  groupStickies,
  toggleHiddenPatches,
  toggleLockPatches,
  ungroupStickies,
  type PatchResult,
  type WhiteboardRefusal
} from '../../core/whiteboard-groups'

export type WhiteboardActionCtx = Pick<
  CanvasCtx,
  | 'space'
  | 'stickies'
  | 'effectiveSelectedIds'
  | 'onBatchUpdateStickyNotes'
  | 'onWhiteboardTransaction'
  | 'setSelectedStickyIds'
  | 'setEditingStickyId'
>

export type WhiteboardActionResult =
  | { ok: true; changed: number; groupId?: string }
  | { ok: false; reason: WhiteboardRefusal; ids: string[] }

function goalCheck(ctx: WhiteboardActionCtx): (id: string) => boolean {
  const goalIds = new Set(ctx.space.goals.map((goal) => goal.id))
  return (id) => goalIds.has(id)
}

/** One write, one undo entry (the transaction also covers a board that records per write). */
function applyPatches(ctx: WhiteboardActionCtx, result: PatchResult): WhiteboardActionResult {
  if (!result.ok) {
    return result
  }
  const changed = Object.keys(result.patches).length
  if (changed > 0 && ctx.onBatchUpdateStickyNotes) {
    const write = (): void => ctx.onBatchUpdateStickyNotes?.(result.patches)
    if (ctx.onWhiteboardTransaction) {
      ctx.onWhiteboardTransaction(write)
    } else {
      write()
    }
  }
  return { ok: true, changed, ...(result.groupId ? { groupId: result.groupId } : {}) }
}

export function groupSelection(
  ctx: WhiteboardActionCtx,
  ids: readonly string[] = ctx.effectiveSelectedIds
): WhiteboardActionResult {
  return applyPatches(ctx, groupStickies(ctx.stickies, ids, goalCheck(ctx)))
}

export function ungroupSelection(
  ctx: WhiteboardActionCtx,
  ids: readonly string[] = ctx.effectiveSelectedIds
): WhiteboardActionResult {
  return applyPatches(ctx, ungroupStickies(ctx.stickies, ids, goalCheck(ctx)))
}

export function toggleHidden(
  ctx: WhiteboardActionCtx,
  ids: readonly string[] = ctx.effectiveSelectedIds
): WhiteboardActionResult {
  const result = toggleHiddenPatches(ctx.stickies, ids, goalCheck(ctx))
  const out = applyPatches(ctx, result)
  if (result.ok) {
    const nowHidden = new Set(
      Object.entries(result.patches)
        .filter(([, patch]) => patch.hidden === true)
        .map(([id]) => id)
    )
    if (nowHidden.size > 0) {
      ctx.setSelectedStickyIds((cur) => cur.filter((id) => !nowHidden.has(id)))
      ctx.setEditingStickyId((cur) => (cur && nowHidden.has(cur) ? null : cur))
    }
  }
  return out
}

export function toggleLock(
  ctx: WhiteboardActionCtx,
  ids: readonly string[] = ctx.effectiveSelectedIds
): WhiteboardActionResult {
  return applyPatches(ctx, toggleLockPatches(ctx.stickies, ids, goalCheck(ctx)))
}

/** What a menu shows for `ids` (enabled rows and the toggle labels). */
export function whiteboardActionState(
  ctx: Pick<WhiteboardActionCtx, 'stickies' | 'effectiveSelectedIds'>,
  ids: readonly string[] = ctx.effectiveSelectedIds
): {
  canGroup: boolean
  canUngroup: boolean
  hideLabel: 'Hide' | 'Show'
  lockLabel: 'Lock' | 'Unlock'
} {
  const byId = new Map(ctx.stickies.map((s) => [s.id, s]))
  const picked = ids.flatMap((id) => {
    const s = byId.get(id)
    return s ? [s] : []
  })
  const live = groupIndex(ctx.stickies)
  return {
    canGroup: picked.length >= 2 && picked.length === ids.length,
    canUngroup: picked.some((s) => s.groupId !== undefined && live.has(s.groupId)),
    hideLabel: picked.length > 0 && picked.every((s) => s.hidden) ? 'Show' : 'Hide',
    lockLabel: picked.length > 0 && picked.every((s) => s.locked) ? 'Unlock' : 'Lock'
  }
}

