// WS-C (TASK_16 wave 2): the rows of the whiteboard layers panel (LayersPanel.tsx), built from the board.
// Pure, so the tests and the render budget call it without React. Idea from Penpot's layers sidebar
// (ui/workspace/sidebar/layers.cljs) and our G_app-Data TreeTable `layers` mode; re-implemented.
import type { SpaceArrow, SpaceGoal, SpaceStickyNote } from '../../core/space'
import { groupIndex, paintOrder, stickyLayerLabel } from '../../core/whiteboard-groups'

export const LAYER_ROW_PX = 26
/** Above this many rows only the rows in view are rendered (plan: virtualise rows > 200). */
export const LAYER_VIRTUAL_AFTER = 200

export type LayerRow =
  | { kind: 'section'; key: string; label: string }
  | { kind: 'goal'; key: string; id: string; label: string }
  | {
      kind: 'group'
      key: string
      groupId: string
      memberIds: string[]
      label: string
      hidden: boolean
      locked: boolean
    }
  | {
      kind: 'sticky'
      key: string
      id: string
      label: string
      depth: 0 | 1
      hidden: boolean
      locked: boolean
      stickyKind: 'note' | 'text' | 'shape'
    }
  | { kind: 'arrow'; key: string; id: string; label: string; hidden: boolean }

function arrowLabel(arrow: SpaceArrow, names: ReadonlyMap<string, string>): string {
  if (arrow.name) {
    return arrow.name
  }
  if (arrow.label) {
    return arrow.label
  }
  const end = (id?: string): string => (id ? (names.get(id) ?? 'item') : 'point')
  return `${end(arrow.fromId)} → ${end(arrow.toId)}`
}

/** The panel rows, top to bottom. Pure (tests + the render-time budget). */
export function buildLayerRows(
  goals: readonly SpaceGoal[],
  stickies: readonly SpaceStickyNote[],
  arrows: readonly SpaceArrow[]
): LayerRow[] {
  const rows: LayerRow[] = []
  if (goals.length > 0) {
    rows.push({ kind: 'section', key: 's:goals', label: 'Spaces' })
    for (const goal of goals) {
      rows.push({ kind: 'goal', key: `g:${goal.id}`, id: goal.id, label: goal.title || 'Space' })
    }
  }
  const names = new Map<string, string>()
  for (const goal of goals) {
    names.set(goal.id, goal.title || 'Space')
  }
  if (stickies.length > 0) {
    rows.push({ kind: 'section', key: 's:notes', label: 'Notes' })
    const live = groupIndex(stickies)
    const byId = new Map(stickies.map((s) => [s.id, s]))
    const done = new Set<string>()
    const topFirst = paintOrder(stickies).toReversed()
    const stickyRow = (s: SpaceStickyNote, depth: 0 | 1): LayerRow => ({
      kind: 'sticky',
      key: `n:${s.id}`,
      id: s.id,
      label: stickyLayerLabel(s),
      depth,
      hidden: s.hidden === true,
      locked: s.locked === true,
      stickyKind: s.kind ?? 'note'
    })
    for (const s of topFirst) {
      names.set(s.id, stickyLayerLabel(s))
      if (done.has(s.id)) {
        continue
      }
      const members = s.groupId ? live.get(s.groupId) : undefined
      if (!members || !s.groupId) {
        rows.push(stickyRow(s, 0))
        continue
      }
      const memberNotes = topFirst.filter((m) => m.groupId === s.groupId)
      rows.push({
        kind: 'group',
        key: `grp:${s.groupId}`,
        groupId: s.groupId,
        memberIds: members,
        label: `Group · ${members.length}`,
        hidden: members.every((id) => byId.get(id)?.hidden),
        locked: members.every((id) => byId.get(id)?.locked)
      })
      for (const m of memberNotes) {
        done.add(m.id)
        rows.push(stickyRow(m, 1))
      }
    }
  }
  if (arrows.length > 0) {
    rows.push({ kind: 'section', key: 's:arrows', label: 'Arrows' })
    for (const a of arrows) {
      rows.push({
        kind: 'arrow',
        key: `a:${a.id}`,
        id: a.id,
        label: arrowLabel(a, names),
        hidden: a.hidden === true
      })
    }
  }
  return rows
}

// WS-C (TASK_16 wave 2): open / closed state of the whiteboard layers panel. A tiny external store (same
// shape as keyboard/help-store.ts), so the ⌥L key row and the panel share it without a new CanvasCtx
// field or a SpaceCanvas prop.
import { useSyncExternalStore } from 'react'

let open = false
const listeners = new Set<() => void>()

export function isLayersPanelOpen(): boolean {
  return open
}

export function setLayersPanelOpen(next: boolean): void {
  if (open === next) {
    return
  }
  open = next
  for (const fn of listeners) {
    fn()
  }
}

function subscribe(fn: () => void): () => void {
  listeners.add(fn)
  return () => {
    listeners.delete(fn)
  }
}

export function useLayersPanelOpen(): boolean {
  return useSyncExternalStore(subscribe, isLayersPanelOpen, isLayersPanelOpen)
}

// WS-D (TASK_16 wave 2): open agent asks on the canvas: pin layout, next / prev, glide, ⌘F jump.
// Read only on agent data: it reads goal.asks and never writes them. The answer happens in the agent's
// own panel (onSelectAgent). Owner: WS-D.
import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import {
  collectOpenAsks,
  layoutAskPins,
  stepAsk,
  viewToShowBox,
  type AskBox,
  type AskPinLayout,
  type OpenAskRef
} from '../../core/ask-pins'
import type { CanvasCtx } from '../canvas-ctx'
import { registerCanvasCommands, type CanvasCommand, type KeyChord } from '../keyboard/commands'

/** The three keys this module runs. `mod` = ⌘ on macOS, Ctrl elsewhere. */
export const ASK_KEYS = {
  jump: { key: 'f', mod: true, shift: false, alt: false },
  next: { key: 'n', mod: false, shift: false, alt: false },
  prev: { key: 'n', mod: false, shift: true, alt: false }
} as const satisfies Record<string, KeyChord>

type AskKeyActions = {
  jump: () => void
  next: () => void
  prev: () => void
  hasAsks: () => boolean
}

/**
 * Rows for WS-A's one shortcut table (registered at runtime: `run` needs this hook's state), so the
 * `?` help lists them and the P3-11 conflict check sees them.
 */
export function askCommandRows(
  actions: AskKeyActions,
  claim: (event: KeyboardEvent) => boolean
): CanvasCommand[] {
  return [
    {
      id: 'ask.jump-to',
      label: 'Jump to agent or Space by name',
      group: 'View',
      scope: 'canvas',
      keys: [ASK_KEYS.jump],
      display: '⌘F',
      run: (_env, event) => {
        const mine = claim(event)
        if (mine) {
          actions.jump()
        }
        return mine
      }
    },
    {
      id: 'ask.next',
      label: 'Next open ask',
      group: 'View',
      scope: 'canvas',
      keys: [ASK_KEYS.next],
      display: 'N',
      when: () => actions.hasAsks(),
      run: (_env, event) => {
        const mine = claim(event)
        if (mine) {
          actions.next()
        }
        return mine
      }
    },
    {
      id: 'ask.prev',
      label: 'Previous open ask',
      group: 'View',
      scope: 'canvas',
      keys: [ASK_KEYS.prev],
      display: '⇧N',
      when: () => actions.hasAsks(),
      run: (_env, event) => {
        const mine = claim(event)
        if (mine) {
          actions.prev()
        }
        return mine
      }
    }
  ]
}

export type AskPinsApi = {
  asks: OpenAskRef[]
  /** False until the canvas has a size (first layout); nothing is drawn before that. */
  measured: boolean
  layout: AskPinLayout
  activeAskId: string | null
  goToAsk: (askId: string) => void
  nextAsk: () => void
  prevAsk: () => void
  /** Glide to the tile an agent sits on and select it (⌘F result). */
  goToAgent: (agentId: string) => void
  /** Glide to a Space tile (⌘F result). Nothing else changes. */
  goToTile: (tileKey: string) => void
  jumpOpen: boolean
  setJumpOpen: (open: boolean) => void
  tileOfAgent: ReadonlyMap<string, string>
}

const EMPTY_SIZE = { width: 0, height: 0 }

function useViewportSize(rootRef: React.RefObject<HTMLDivElement | null>): {
  width: number
  height: number
} {
  const [size, setSize] = useState(EMPTY_SIZE)
  useEffect(() => {
    const el = rootRef.current
    if (!el) {
      return
    }
    const read = (): void => {
      const width = el.clientWidth
      const height = el.clientHeight
      setSize((prev) =>
        prev.width === width && prev.height === height
          ? prev
          : width > 0
            ? { width, height }
            : EMPTY_SIZE
      )
    }
    read()
    if (typeof ResizeObserver === 'undefined') {
      window.addEventListener('resize', read)
      return () => window.removeEventListener('resize', read)
    }
    const observer = new ResizeObserver(read)
    observer.observe(el)
    return () => observer.disconnect()
  }, [rootRef])
  return size
}

/** True when `id` (agent id or its unified tab id) is the agent whose panel is already open. */
export function isInspectedAgent(
  agents: CanvasCtx['agents'],
  inspectedAgentId: string | null,
  id: string
): boolean {
  if (!inspectedAgentId) {
    return false
  }
  if (inspectedAgentId === id) {
    return true
  }
  const open = agents.find((a) => a.id === inspectedAgentId || a.unifiedTabId === inspectedAgentId)
  return Boolean(open && (open.id === id || open.unifiedTabId === id))
}

export function useAskPins(ctx: CanvasCtx): AskPinsApi {
  const { space, boxMap, agentsBySpace, view, setView, markZoomTween, rootRef, onSelectAgent } = ctx
  const { agents, inspectedAgentId } = ctx
  const viewport = useViewportSize(rootRef)
  const [activeAskId, setActiveAskId] = useState<string | null>(null)
  const [jumpOpen, setJumpOpen] = useState(false)

  const tileOfAgent = useMemo(() => {
    const map = new Map<string, string>()
    for (const [key, members] of agentsBySpace) {
      for (const agent of members) {
        map.set(agent.id, key)
        if (agent.unifiedTabId) {
          map.set(agent.unifiedTabId, key)
        }
      }
    }
    return map
  }, [agentsBySpace])

  const asks = useMemo(
    () =>
      collectOpenAsks(
        space.goals,
        (key) => boxMap.has(key),
        (botId) => tileOfAgent.get(botId)
      ),
    [boxMap, space.goals, tileOfAgent]
  )

  const boxOf = useCallback((key: string): AskBox | undefined => boxMap.get(key), [boxMap])
  const layout = useMemo(
    () =>
      viewport.width > 0 ? layoutAskPins(asks, boxOf, view, viewport) : { pins: [], edges: [] },
    [asks, boxOf, view, viewport]
  )

  const goToTile = useCallback(
    (tileKey: string): void => {
      const box = boxMap.get(tileKey)
      const el = rootRef.current
      if (!box || !el) {
        return
      }
      const size = { width: el.clientWidth, height: el.clientHeight }
      markZoomTween()
      setView((v) => viewToShowBox(box, v, size))
    },
    [boxMap, markZoomTween, rootRef, setView]
  )

  const goToAsk = useCallback(
    (askId: string): void => {
      const ref = asks.find((r) => r.ask.id === askId)
      if (!ref) {
        return
      }
      setActiveAskId(askId)
      goToTile(ref.tileKey)
      // onSelectAgent toggles in space-board: re-selecting the open agent would close its panel.
      if (!isInspectedAgent(agents, inspectedAgentId, ref.ask.botId)) {
        onSelectAgent(ref.ask.botId)
      }
    },
    [agents, asks, goToTile, inspectedAgentId, onSelectAgent]
  )

  const nextAsk = useCallback((): void => {
    const ref = stepAsk(asks, activeAskId, 1)
    if (ref) {
      goToAsk(ref.ask.id)
    }
  }, [activeAskId, asks, goToAsk])
  const prevAsk = useCallback((): void => {
    const ref = stepAsk(asks, activeAskId, -1)
    if (ref) {
      goToAsk(ref.ask.id)
    }
  }, [activeAskId, asks, goToAsk])

  const goToAgent = useCallback(
    (agentId: string): void => {
      const key = tileOfAgent.get(agentId)
      if (key) {
        goToTile(key)
      }
      if (!isInspectedAgent(agents, inspectedAgentId, agentId)) {
        onSelectAgent(agentId)
      }
    },
    [agents, goToTile, inspectedAgentId, onSelectAgent, tileOfAgent]
  )

  // Keys: rows in WS-A's table, run by its one key effect (canvas/keyboard/use-canvas-keys.ts: typing
  // guard, IME, burst end). claim() keeps one keypress to one visible canvas.
  const actionsRef = useRef<AskKeyActions>({
    jump: () => setJumpOpen(true),
    next: nextAsk,
    prev: prevAsk,
    hasAsks: () => asks.length > 0
  })
  actionsRef.current = {
    jump: () => setJumpOpen(true),
    next: nextAsk,
    prev: prevAsk,
    hasAsks: () => asks.length > 0
  }
  useEffect(() => {
    const claimed = new WeakSet<KeyboardEvent>()
    const onScreen = (): boolean => {
      const root = rootRef.current
      return Boolean(root && root.isConnected && root.clientWidth > 0)
    }
    const claim = (event: KeyboardEvent): boolean => {
      if (claimed.has(event) || !onScreen()) {
        return false
      }
      claimed.add(event)
      return true
    }
    const proxy: AskKeyActions = {
      jump: () => actionsRef.current.jump(),
      next: () => actionsRef.current.next(),
      prev: () => actionsRef.current.prev(),
      hasAsks: () => actionsRef.current.hasAsks()
    }
    // Owner = this canvas: two live boards each keep their own ⌘F / N / ⇧N (WS-A routes the key).
    const { unregister } = registerCanvasCommands(askCommandRows(proxy, claim), rootRef)
    return () => {
      unregister()
    }
  }, [rootRef])

  return {
    asks,
    measured: viewport.width > 0,
    layout,
    activeAskId,
    goToAsk,
    nextAsk,
    prevAsk,
    goToAgent,
    goToTile,
    jumpOpen,
    setJumpOpen,
    tileOfAgent
  }
}

// WS-E (TASK_16 wave 2): the ⌘C / ⌘V rows for WS-A's key table (keyboard/commands.ts). Same ids, keys
