// WS-A (TASK_16 wave 2): ⌘D of grouped notes. The board's copies keep the source groupId; this gives
// the copies NEW groupIds (one per source group, via WS-C's remapCopiedGroups), so a duplicated group is
// a new group, never a member of the original. A group with only one copied member gets no group.
import type { SpaceStickyNote } from '../../core/space'
import { remapCopiedGroups } from '../../core/whiteboard-groups'

/** Patches for `created[i]` (the copy of `sources[i]`); empty when nothing was grouped. */
export function regroupCopyPatches(
  sources: readonly Pick<SpaceStickyNote, 'groupId'>[],
  created: readonly string[],
  makeId?: () => string
): Record<string, Partial<SpaceStickyNote>> {
  if (sources.length !== created.length) {
    return {}
  }
  const remapped = remapCopiedGroups(
    sources.map((st) => ({ groupId: st.groupId })),
    makeId
  )
  const counts = new Map<string, number>()
  for (const r of remapped) {
    if (r.groupId) {
      counts.set(r.groupId, (counts.get(r.groupId) ?? 0) + 1)
    }
  }
  const patches: Record<string, Partial<SpaceStickyNote>> = {}
  remapped.forEach((r, i) => {
    const createdId = created[i]
    if (sources[i]?.groupId && createdId) {
      patches[createdId] = {
        groupId: r.groupId && (counts.get(r.groupId) ?? 0) >= 2 ? r.groupId : undefined
      }
    }
  })
  return patches
}

import { useEffect, useRef } from 'react'
import { MAX_STICKIES, type Point, type SpaceStickyNote } from '../../core/space'
import {
  buildClipboardPayload,
  clipRefusalMessage,
  parseClipboardPayload,
  planPaste,
  textToPayload,
  WHITEBOARD_CLIP_MIME,
  WHITEBOARD_CLIP_WEB_MIME,
  type ClipParse
} from '../../core/whiteboard-clipboard'
import type { CanvasCtx } from '../canvas-ctx'
import { isTypingTarget } from '../keyboard/typing-target'

export function useClipboardBuffer(): {
  copiedStickiesRef: React.MutableRefObject<SpaceStickyNote[]>
  pasteCountRef: React.MutableRefObject<number>
} {
  const copiedStickiesRef = useRef<SpaceStickyNote[]>([])
  const pasteCountRef = useRef(0)
  return { copiedStickiesRef, pasteCountRef }
}

export type ClipboardCtx = Pick<
  CanvasCtx,
  | 'space'
  | 'stickies'
  | 'arrows'
  | 'effectiveSelectedIds'
  | 'editingStickyId'
  | 'onNotify'
  | 'onBatchAddWhiteboard'
  | 'setSelectedStickyIds'
  | 'setSelectedArrowId'
>

let memory: { text: string; json: string } | null = null
let pasteCount = 0
let pointer: { x: number; y: number } | null = null
let pending: { ctx: ClipboardCtx; at: Point | null; timer: ReturnType<typeof setTimeout> } | null =
  null

export function resetWhiteboardClipboard(): void {
  memory = null
  pasteCount = 0
  pointer = null
  if (pending) {
    clearTimeout(pending.timer)
  }
  pending = null
}

export function whiteboardClipboardMemory(): { text: string; json: string } | null {
  return memory
}

function writeViaCopyEvent(text: string, json: string): boolean {
  if (typeof document === 'undefined' || typeof document.execCommand !== 'function') {
    return false
  }
  let wrote = false
  const onCopy = (event: ClipboardEvent): void => {
    if (!event.clipboardData) {
      return
    }
    event.clipboardData.setData('text/plain', text)
    event.clipboardData.setData(WHITEBOARD_CLIP_MIME, json)
    event.preventDefault()
    event.stopImmediatePropagation()
    wrote = true
  }
  document.addEventListener('copy', onCopy, true)
  try {
    document.execCommand('copy')
  } catch {
    // ok: older DOM implementations throw on execCommand('copy')
    wrote = false
  } finally {
    document.removeEventListener('copy', onCopy, true)
  }
  return wrote
}

async function writeViaClipboardApi(text: string, json: string): Promise<void> {
  const clip = typeof navigator !== 'undefined' ? navigator.clipboard : undefined
  const Item = (globalThis as { ClipboardItem?: typeof ClipboardItem }).ClipboardItem
  if (clip?.write && Item) {
    try {
      await clip.write([
        new Item({
          'text/plain': new Blob([text], { type: 'text/plain' }),
          [WHITEBOARD_CLIP_WEB_MIME]: new Blob([json], { type: WHITEBOARD_CLIP_MIME })
        })
      ])
      return
    } catch {
      // ok: custom web MIME rejected or permission denied; fall back to writeText
      // Fallback below
    }
  }
  try {
    await clip?.writeText?.(text)
  } catch {
    // ok: clipboard write blocked in headless/jsdom; in-memory buffer still works
    // In-memory buffer handles same-window paste
  }
}

export function copyWhiteboardSelection(
  ctx: ClipboardCtx,
  ids: readonly string[] = ctx.effectiveSelectedIds
): boolean {
  const goalIds = new Set(ctx.space.goals.map((g) => g.id))
  const built = buildClipboardPayload(ctx.stickies, ctx.arrows, ids, goalIds)
  if (!built.ok) {
    if (built.reason !== 'empty') {
      ctx.onNotify?.(clipRefusalMessage(built.reason))
    }
    return built.reason !== 'empty'
  }
  memory = { text: built.text, json: built.json }
  pasteCount = 0
  if (!writeViaCopyEvent(built.text, built.json)) {
    void writeViaClipboardApi(built.text, built.json)
  }
  return true
}

export function pasteWhiteboardPayload(
  ctx: ClipboardCtx,
  parsed: ClipParse,
  at: Point | null = null
): boolean {
  if (!parsed.ok) {
    if (parsed.reason !== 'not-ours') {
      ctx.onNotify?.(clipRefusalMessage(parsed.reason))
    }
    return false
  }
  if (!ctx.onBatchAddWhiteboard) {
    ctx.onNotify?.('Paste is not available on this board.')
    return false
  }
  const room = MAX_STICKIES - (ctx.space.stickies?.length ?? 0)
  if (!at) {
    pasteCount += 1
  }
  const step = 28 * pasteCount
  const plan = planPaste(parsed.payload, { at, offset: { x: step, y: step }, room })
  if (plan.stickies.length === 0) {
    ctx.onNotify?.(`Not pasted: the board already holds ${MAX_STICKIES} notes.`)
    return false
  }
  const result = ctx.onBatchAddWhiteboard({ stickies: plan.stickies, arrows: plan.arrows })
  const dropped = plan.dropped + result.droppedStickies
  if (dropped > 0) {
    ctx.onNotify?.(
      `${dropped} note${dropped === 1 ? '' : 's'} not pasted: a board holds ${MAX_STICKIES}.`
    )
  }
  if (result.stickyIds.length > 0) {
    ctx.setSelectedStickyIds(result.stickyIds)
    ctx.setSelectedArrowId(null)
  }
  return result.stickyIds.length > 0
}

export function pasteFromClipboardData(
  ctx: ClipboardCtx,
  data: { json?: string | null; text?: string | null },
  at: Point | null = null
): boolean {
  if (data.json) {
    return pasteWhiteboardPayload(ctx, parseClipboardPayload(data.json), at)
  }
  const text = data.text ?? ''
  if (memory && text && text === memory.text) {
    return pasteWhiteboardPayload(ctx, parseClipboardPayload(memory.json), at)
  }
  return pasteWhiteboardPayload(ctx, textToPayload(text), at)
}

async function readClipboardFallback(): Promise<{ json: string | null; text: string | null }> {
  const clip = typeof navigator !== 'undefined' ? navigator.clipboard : undefined
  let json: string | null = null
  let text: string | null = null
  try {
    for (const item of (await clip?.read?.()) ?? []) {
      if (item.types.includes(WHITEBOARD_CLIP_WEB_MIME)) {
        json = await (await item.getType(WHITEBOARD_CLIP_WEB_MIME)).text()
      }
    }
  } catch {
    // ok: clipboard.read unsupported or permission denied; try readText below
    json = null
  }
  if (typeof clip?.readText === 'function') {
    try {
      text = await clip.readText()
    } catch {
      // ok: clipboard.readText denied; fall back to in-memory buffer if present
      text = memory?.text ?? null
    }
  } else {
    text = memory?.text ?? null
  }
  return { json, text }
}

function finishPending(data: { json?: string | null; text?: string | null } | null): void {
  const job = pending
  if (!job) {
    return
  }
  clearTimeout(job.timer)
  pending = null
  if (data) {
    pasteFromClipboardData(job.ctx, data, job.at)
    return
  }
  void readClipboardFallback().then((read) => pasteFromClipboardData(job.ctx, read, job.at))
}

export function requestWhiteboardPaste(ctx: ClipboardCtx, at: Point | null = null): void {
  if (pending) {
    clearTimeout(pending.timer)
  }
  pending = { ctx, at, timer: setTimeout(() => finishPending(null), 50) }
  finishPending(null)
}

export function pointerCanvasPoint(ctx: Pick<CanvasCtx, 'clientToCanvasPoint'>): Point | null {
  return pointer ? ctx.clientToCanvasPoint(pointer.x, pointer.y) : null
}

export function useWhiteboardClipboard(ctx: CanvasCtx): void {
  const ctxRef = useRef(ctx)
  ctxRef.current = ctx
  const { rootRef } = ctx
  useEffect(() => {
    const root = rootRef.current
    const onMove = (event: PointerEvent): void => {
      pointer = { x: event.clientX, y: event.clientY }
    }
    const onLeave = (): void => {
      pointer = null
    }
    const onPaste = (event: ClipboardEvent): void => {
      const target = event.target as HTMLElement | null
      const onCanvas =
        target === document.body ||
        target === document.documentElement ||
        Boolean(root && target && root.contains(target))
      if (!onCanvas || isTypingTarget(target) || ctxRef.current.editingStickyId) {
        return
      }
      const data = event.clipboardData
      const json = data?.getData(WHITEBOARD_CLIP_MIME) || null
      const text = data?.getData('text/plain') || null
      if (!pending && !json && !text) {
        return
      }
      event.preventDefault()
      if (pending) {
        finishPending({ json, text })
      } else {
        pasteFromClipboardData(ctxRef.current, { json, text }, pointerCanvasPoint(ctxRef.current))
      }
    }
    root?.addEventListener('pointermove', onMove)
    root?.addEventListener('pointerleave', onLeave)
    document.addEventListener('paste', onPaste)
    return () => {
      root?.removeEventListener('pointermove', onMove)
      root?.removeEventListener('pointerleave', onLeave)
      document.removeEventListener('paste', onPaste)
    }
  }, [rootRef])
}

// WS-A (TASK_16 wave 2): smart ⌘D (penpot-mpl/duplicate-delta.ts: move the copy, ⌘D again repeats that
// offset for 10 s). A duplicated group becomes a NEW group (copy + regroup = one undo entry).
// Agent data: copies only notes / shapes / text (+ arrows between them); never a goal tile.
import { useCallback, useRef } from 'react'
import type { CanvasCtx } from '../canvas-ctx'
import type { SpaceStickyNote } from '../../core/space'
import {
  calcDuplicateDelta,
  memorizeDuplicated,
  type DuplicateMemo
} from '../../penpot-mpl/duplicate-delta'
import { regroupCopyPatches } from './duplicate-groups'

/** First-copy offsets (unchanged from before WS-A): one item +24, several +28. */
export const DUPLICATE_OFFSET_ONE = { x: 24, y: 24 }
export const DUPLICATE_OFFSET_MANY = { x: 28, y: 28 }

export function useDuplicateSelected(ctx: CanvasCtx): () => void {
  const {
    effectiveSelectedIds,
    onBatchDuplicateStickyNotes,
    onBatchUpdateStickyNotes,
    onDuplicateStickyNote,
    onWhiteboardTransaction,
    setSelectedStickyIds,
    stickies,
    stickiesById
  } = ctx
  const duplicateMemoRef = useRef<DuplicateMemo | null>(null)
  return useCallback((): void => {
    const unlocked = effectiveSelectedIds.filter((id) => !stickiesById.get(id)?.locked)
    if (unlocked.length === 0) {
      return
    }
    const now = Date.now()
    const delta = calcDuplicateDelta(
      duplicateMemoRef.current,
      unlocked,
      (id) => stickiesById.get(id),
      now,
      unlocked.length >= 2 ? DUPLICATE_OFFSET_MANY : DUPLICATE_OFFSET_ONE
    )
    // The board copies keep the source groupId; a duplicated group must be a NEW group (WS-C rule).
    const grouped = unlocked.some((id) => stickiesById.get(id)?.groupId)
    const run = (): void => {
      if (unlocked.length >= 2 && onBatchDuplicateStickyNotes) {
        const created = onBatchDuplicateStickyNotes(unlocked, delta)
        if (Array.isArray(created) && created.length > 0) {
          setSelectedStickyIds(created)
          duplicateMemoRef.current = memorizeDuplicated(unlocked, created, now)
          if (grouped) {
            // The board returns copies in board order (space.stickies), the same order as here.
            const set = new Set(unlocked)
            regroupCopies(
              stickies.filter((st) => set.has(st.id)),
              created
            )
          }
        }
        return
      }
      const firstId = unlocked[0]!
      const clonedId = onDuplicateStickyNote?.(firstId, delta)
      if (typeof clonedId === 'string') {
        setSelectedStickyIds([clonedId])
        duplicateMemoRef.current = memorizeDuplicated([firstId], [clonedId], now)
        if (grouped) {
          const src = stickiesById.get(firstId)
          regroupCopies(src ? [src] : [], [clonedId])
        }
      }
    }
    function regroupCopies(sources: readonly SpaceStickyNote[], created: readonly string[]): void {
      const patches = regroupCopyPatches(sources, created)
      if (Object.keys(patches).length > 0) {
        onBatchUpdateStickyNotes?.(patches)
      }
    }
    if (grouped && onWhiteboardTransaction) {
      // Copy + regroup = ONE undo entry.
      onWhiteboardTransaction(run)
    } else {
      run()
    }
  }, [
    effectiveSelectedIds,
    onBatchDuplicateStickyNotes,
    onBatchUpdateStickyNotes,
    onDuplicateStickyNote,
    onWhiteboardTransaction,
    setSelectedStickyIds,
    stickies,
    stickiesById
  ])
}

// WS-0 (TASK_16 wave 2): selection actions (front / back / duplicate / delete / align / distribute,
// zoom to selection, fit all), moved verbatim from space-canvas.tsx. Owner: WS-A.
// WS-A: smart duplicate lives in use-duplicate.ts (move the copy, ⌘D again repeats that offset for
// 10 s) and the zoom steps shared by the keys (+ / - / Shift+0) and the bottom-right buttons.
// Agent data: duplicate copies only notes / shapes / text (+ arrows between them); never a goal tile.
import type { CanvasCtx } from '../canvas-ctx'
import type { BoxRect } from '../canvas-ctx'
import {
  type SpaceStickyNote,
  alignWhiteboardItems,
  fitSpaces,
  distributeWhiteboardItems,
  ZOOM_STEP_IN_FACTOR,
  ZOOM_STEP_OUT_FACTOR,
  zoomAt
} from '../../core/space'
import type { ToolbarMultiAlign, ToolbarMultiDistribute } from '../../whiteboard-toolbar'
import { fitFreeArea, fitSelection } from '../../core/viewport-fit'
import { FIT_BOTTOM_INSET, FIT_SIDE_INSET, FIT_TOP_INSET } from '../corner-layout'
import { useDuplicateSelected } from './use-duplicate'
import { useCallback } from 'react'

export { DUPLICATE_OFFSET_MANY, DUPLICATE_OFFSET_ONE } from './use-duplicate'

export function useSelectionActions(ctx: CanvasCtx) {
  const {
    agentsBySpace,
    boxMapRef,
    effectiveSelectedIds,
    effectiveSelectedNodeIds,
    markZoomTween,
    nodesById,
    onBatchDeleteStickyNotes,
    onBatchUpdateStickyNotes,
    onDeleteArrow,
    onDeleteNode,
    onDeleteStickyNote,
    onUpdateStickyNote,
    rootRef,
    selectedArrowId,
    selectedGoalId,
    setEditingStickyId,
    setSelectedArrowId,
    setSelectedNodeIds,
    setSelectedStickyIds,
    setFitPartial,
    setView,
    stickies,
    stickiesById,
    tiles
  } = ctx
  const bringIdsToFront = useCallback(
    (ids: readonly string[]): void => {
      const unlocked = ids.filter((id) => !stickiesById.get(id)?.locked)
      if (unlocked.length === 0) {
        return
      }
      let maxZ = 0
      for (const s of stickies) {
        if ((s.zIndex ?? 0) > maxZ) {
          maxZ = s.zIndex ?? 0
        }
      }
      if (unlocked.length === 1) {
        onUpdateStickyNote?.(unlocked[0]!, { zIndex: Math.min(500, maxZ + 1) })
        return
      }
      const patches: Record<string, Partial<SpaceStickyNote>> = {}
      unlocked.forEach((id, idx) => {
        patches[id] = { zIndex: Math.min(500, maxZ + 1 + idx) }
      })
      onBatchUpdateStickyNotes?.(patches)
    },
    [onBatchUpdateStickyNotes, onUpdateStickyNote, stickies, stickiesById]
  )

  const sendIdsToBack = useCallback(
    (ids: readonly string[]): void => {
      const unlocked = ids.filter((id) => !stickiesById.get(id)?.locked)
      if (unlocked.length === 0) {
        return
      }
      let minZ = 0
      for (const s of stickies) {
        if ((s.zIndex ?? 0) < minZ) {
          minZ = s.zIndex ?? 0
        }
      }
      if (unlocked.length === 1) {
        onUpdateStickyNote?.(unlocked[0]!, { zIndex: Math.max(-50, minZ - 1) })
        return
      }
      const patches: Record<string, Partial<SpaceStickyNote>> = {}
      unlocked.forEach((id, idx) => {
        patches[id] = { zIndex: Math.max(-50, minZ - unlocked.length + idx) }
      })
      onBatchUpdateStickyNotes?.(patches)
    },
    [onBatchUpdateStickyNotes, onUpdateStickyNote, stickies, stickiesById]
  )

  const duplicateSelected = useDuplicateSelected(ctx)

  const deleteSelected = useCallback((): boolean => {
    if (selectedArrowId) {
      onDeleteArrow?.(selectedArrowId)
      setSelectedArrowId(null)
      return true
    }
    const unlockedNodes = effectiveSelectedNodeIds.filter((id) => !nodesById.get(id)?.locked)
    const unlocked = effectiveSelectedIds.filter((id) => !stickiesById.get(id)?.locked)
    if (unlocked.length === 0 && unlockedNodes.length === 0) {
      return false
    }
    for (const nodeId of unlockedNodes) {
      onDeleteNode?.(nodeId)
    }
    if (unlockedNodes.length > 0) {
      setSelectedNodeIds((cur) => cur.filter((id) => !unlockedNodes.includes(id)))
    }
    if (unlocked.length >= 2 && onBatchDeleteStickyNotes) {
      onBatchDeleteStickyNotes(unlocked)
    } else {
      for (const id of unlocked) {
        onDeleteStickyNote?.(id)
      }
    }
    if (unlocked.length > 0) {
      setSelectedStickyIds((cur) => cur.filter((id) => !unlocked.includes(id)))
      setEditingStickyId(null)
    }
    return true
  }, [
    effectiveSelectedIds,
    effectiveSelectedNodeIds,
    nodesById,
    onBatchDeleteStickyNotes,
    onDeleteArrow,
    onDeleteNode,
    onDeleteStickyNote,
    selectedArrowId,
    setEditingStickyId,
    setSelectedArrowId,
    setSelectedNodeIds,
    setSelectedStickyIds,
    stickiesById
  ])

  const handleMultiAlign = useCallback(
    (alignment: ToolbarMultiAlign): void => {
      const items = effectiveSelectedIds
        .filter((id) => !stickiesById.get(id)?.locked)
        .map((id) => {
          const b = boxMapRef.current.get(id)
          return b ? { id, x: b.x, y: b.y, w: b.w, h: b.h } : null
        })
        .filter((it): it is { id: string; x: number; y: number; w: number; h: number } =>
          Boolean(it)
        )
      if (items.length < 2) {
        return
      }
      const nextCoords = alignWhiteboardItems(items, alignment)
      onBatchUpdateStickyNotes?.(nextCoords)
    },
    [boxMapRef, effectiveSelectedIds, onBatchUpdateStickyNotes, stickiesById]
  )

  const handleMultiDistribute = useCallback(
    (axis: ToolbarMultiDistribute): void => {
      const items = effectiveSelectedIds
        .filter((id) => !stickiesById.get(id)?.locked)
        .map((id) => {
          const b = boxMapRef.current.get(id)
          return b ? { id, x: b.x, y: b.y, w: b.w, h: b.h } : null
        })
        .filter((it): it is { id: string; x: number; y: number; w: number; h: number } =>
          Boolean(it)
        )
      if (items.length < 3) {
        return
      }
      const nextCoords = distributeWhiteboardItems(items, axis)
      onBatchUpdateStickyNotes?.(nextCoords)
    },
    [boxMapRef, effectiveSelectedIds, onBatchUpdateStickyNotes, stickiesById]
  )

  const hasSelection =
    effectiveSelectedIds.length > 0 ||
    effectiveSelectedNodeIds.length > 0 ||
    Boolean(selectedGoalId)
  /** Boxes of what is selected: whiteboard items + canvas nodes, else the selected Space tile. */
  const selectionBoxes = useCallback((): BoxRect[] => {
    const selectedBoardIds = [...effectiveSelectedIds, ...effectiveSelectedNodeIds]
    const ids =
      selectedBoardIds.length > 0 ? selectedBoardIds : selectedGoalId ? [selectedGoalId] : []
    return ids.flatMap((id) => {
      const box = boxMapRef.current.get(id)
      return box ? [box] : []
    })
  }, [boxMapRef, effectiveSelectedIds, effectiveSelectedNodeIds, selectedGoalId])
  /** Zoom to selection (Shift+2): fit it with 40 px padding, zoom clamped. False = nothing selected. */
  const fitToSelection = useCallback((): boolean => {
    const el = rootRef.current
    const next = el ? fitSelection(selectionBoxes(), el.clientWidth, el.clientHeight) : null
    if (!next) {
      return false
    }
    markZoomTween()
    setView(next)
    return true
  }, [markZoomTween, rootRef, selectionBoxes, setView])
  /** Fit all Spaces in the free area, centred, never below a readable scale (U-37). */
  const fitAllSpaces = useCallback((): void => {
    const el = rootRef.current
    if (!el) {
      return
    }
    const next = fitFreeArea(
      tiles.map((t) => {
        const box = boxMapRef.current.get(t.key) ?? t
        return {
          x: box.x,
          y: box.y,
          w: box.w,
          h: box.h,
          hasMembers: (agentsBySpace.get(t.key)?.length ?? 0) > 0
        }
      }),
      el.clientWidth,
      el.clientHeight,
      {
        top: FIT_TOP_INSET,
        bottom: FIT_BOTTOM_INSET,
        left: FIT_SIDE_INSET,
        right: FIT_SIDE_INSET
      }
    )
    markZoomTween()
    if (next) {
      setFitPartial(next.partial)
      setView({ x: next.x, y: next.y, scale: next.scale })
    } else {
      // Nothing to fit (empty board, canvas not laid out): reset the view as before.
      setFitPartial(false)
      setView(fitSpaces(tiles, el.clientWidth, el.clientHeight))
    }
  }, [agentsBySpace, boxMapRef, markZoomTween, rootRef, setFitPartial, setView, tiles])
  /** One zoom step around the viewport center (the − / + buttons and keys), with the zoom tween. */
  const zoomStep = useCallback(
    (direction: 'in' | 'out'): void => {
      const el = rootRef.current
      const center = el ? { x: el.clientWidth / 2, y: el.clientHeight / 2 } : { x: 400, y: 260 }
      markZoomTween()
      setView((v) =>
        zoomAt(
          v,
          direction === 'in' ? v.scale * ZOOM_STEP_IN_FACTOR : v.scale / ZOOM_STEP_OUT_FACTOR,
          center
        )
      )
    },
    [markZoomTween, rootRef, setView]
  )
  /** Shift+0: 100 % around the viewport center, with the zoom tween. */
  const zoomTo100 = useCallback((): void => {
    const el = rootRef.current
    const center = el ? { x: el.clientWidth / 2, y: el.clientHeight / 2 } : { x: 400, y: 260 }
    markZoomTween()
    setView((v) => zoomAt(v, 1, center))
  }, [markZoomTween, rootRef, setView])
  return {
    zoomStep,
    zoomTo100,
    bringIdsToFront,
    sendIdsToBack,
    duplicateSelected,
    deleteSelected,
    handleMultiAlign,
    handleMultiDistribute,
    hasSelection,
    selectionBoxes,
    fitToSelection,
    fitAllSpaces
  }
}

export type SelectionActions = ReturnType<typeof useSelectionActions>

// WS-0 (TASK_16 wave 2): SpaceCanvas derived data (stickies, goals, agents per Space, tiles, box map),
// moved verbatim from space-canvas.tsx. Owner: WS-A (with canvas-ctx.ts).

import { useEffect, useMemo, useRef } from 'react'
import type { SpaceCanvasNode } from '../core/canvas-nodes'
import {
  BENCH_KEY,
  computeAutoTextDimensions,
  computeCardMinHeight,
  computeShapeDimensions,
  extraPresenceHeightForMembers,
  layoutSpaces,
  resolveAgentGoalId,
  type SpaceAgent,
  type SpaceGoal,
  type SpaceState,
  type SpaceStickyNote
} from '../core/space'
import type { BoxRect } from './canvas-ctx'
import type { CanvasState } from './use-canvas-state'

export type CanvasModelInput = {
  agents: readonly SpaceAgent[]
  space: SpaceState
  pendingEditStickyId: string | null
  onConsumePendingEditSticky?: () => void
}

export function useCanvasModel(
  { agents, space, pendingEditStickyId, onConsumePendingEditSticky }: CanvasModelInput,
  {
    selectedStickyIds,
    setSelectedStickyIds,
    selectedNodeIds,
    setEditingStickyId,
    setSelectedArrowId,
    tileOffset,
    tileSizeOverride,
    stickyOffset,
    stickySizeOverride,
    nodeOffset,
    multiNodeDragDelta,
    nodeSizeOverride
  }: CanvasState
) {
  useEffect(() => {
    if (pendingEditStickyId) {
      setSelectedStickyIds([pendingEditStickyId])
      setEditingStickyId(pendingEditStickyId)
      setSelectedArrowId(null)
      onConsumePendingEditSticky?.()
    }
  }, [
    onConsumePendingEditSticky,
    pendingEditStickyId,
    setEditingStickyId,
    setSelectedArrowId,
    setSelectedStickyIds
  ])

  const stickies = useMemo(() => space.stickies ?? [], [space.stickies])
  const stickiesById = useMemo(
    () => new Map<string, SpaceStickyNote>(stickies.map((s) => [s.id, s])),
    [stickies]
  )
  const sortedStickies = useMemo(
    () =>
      [...stickies].sort((a, b) => (a.zIndex ?? 0) - (b.zIndex ?? 0) || a.createdAt - b.createdAt),
    [stickies]
  )
  // WS-C: a hidden sticky is never selected (so never moved, copied, deleted or nudged from the canvas).
  const effectiveSelectedIds = useMemo(
    () => selectedStickyIds.filter((id) => stickiesById.has(id) && !stickiesById.get(id)?.hidden),
    [selectedStickyIds, stickiesById]
  )
  const selectedStickyIdSet = useMemo(() => new Set(effectiveSelectedIds), [effectiveSelectedIds])
  const singleSelectedStickyId =
    effectiveSelectedIds.length === 1 ? (effectiveSelectedIds[0] ?? null) : null
  const singleSelectedSticky = singleSelectedStickyId
    ? (stickiesById.get(singleSelectedStickyId) ?? null)
    : null
  const arrows = useMemo(() => space.arrows ?? [], [space.arrows])

  const nodes = useMemo(() => space.nodes ?? [], [space.nodes])
  const nodesById = useMemo(
    () => new Map<string, SpaceCanvasNode>(nodes.map((n) => [n.id, n])),
    [nodes]
  )
  const sortedNodes = useMemo(
    () => [...nodes].sort((a, b) => (a.zIndex ?? 0) - (b.zIndex ?? 0) || a.createdAt - b.createdAt),
    [nodes]
  )
  const effectiveSelectedNodeIds = useMemo(
    () => selectedNodeIds.filter((id) => nodesById.has(id) && !nodesById.get(id)?.hidden),
    [nodesById, selectedNodeIds]
  )
  const selectedNodeIdSet = useMemo(
    () => new Set(effectiveSelectedNodeIds),
    [effectiveSelectedNodeIds]
  )

  const visibleGoals = useMemo(
    () => space.goals.filter((goal) => goal.status !== 'done'),
    [space.goals]
  )
  const goalsById = useMemo(
    () => new Map<string, SpaceGoal>(visibleGoals.map((goal) => [goal.id, goal])),
    [visibleGoals]
  )
  const validGoalIds = useMemo(() => new Set<string>(goalsById.keys()), [goalsById])
  const liveAgentIds = useMemo(() => {
    const ids = new Set<string>()
    for (const agent of agents) {
      ids.add(agent.id)
      if (agent.unifiedTabId) {
        ids.add(agent.unifiedTabId)
      }
    }
    return ids
  }, [agents])

  const agentsBySpace = useMemo(() => {
    const map = new Map<string, SpaceAgent[]>()
    for (const goal of visibleGoals) {
      map.set(goal.id, [])
    }
    map.set(BENCH_KEY, [])
    for (const agent of agents) {
      const key = resolveAgentGoalId(space, agent, validGoalIds, liveAgentIds) ?? BENCH_KEY
      map.get(key)?.push(agent)
    }
    return map
  }, [agents, liveAgentIds, space, validGoalIds, visibleGoals])

  const tiles = useMemo(
    () =>
      layoutSpaces(
        visibleGoals,
        (key) => agentsBySpace.get(key)?.length ?? 0,
        space.bench,
        (key, width) => extraPresenceHeightForMembers(agentsBySpace.get(key) ?? [], width)
      ),
    [agentsBySpace, space.bench, visibleGoals]
  )

  const boxMap = useMemo(() => {
    const map = new Map<string, BoxRect>()
    for (const tile of tiles) {
      const off = tileOffset[tile.key]
      const sz = tileSizeOverride[tile.key]
      map.set(tile.key, {
        x: tile.x + (off?.x ?? 0),
        y: tile.y + (off?.y ?? 0),
        w: sz?.w ?? tile.w,
        h: sz?.h ?? tile.h
      })
    }
    for (const sticky of stickies) {
      // WS-C: a hidden sticky has no box: not hit-tested, not snapped to, no arrow end, no marquee.
      if (sticky.hidden) {
        continue
      }
      const off = stickyOffset[sticky.id]
      const sz = stickySizeOverride[sticky.id]
      const kind = sticky.kind ?? 'note'
      if (kind === 'shape') {
        const shapeType = sticky.shapeType ?? 'rounded'
        const font = sz?.fontSize ?? sticky.fontSize ?? 16
        const defaultW = shapeType === 'ellipse' || shapeType === 'diamond' ? 150 : 196
        const defaultH = shapeType === 'ellipse' || shapeType === 'diamond' ? 150 : 96
        const dims = computeShapeDimensions(
          sticky.text,
          font,
          sz?.w ?? (sticky.w || defaultW),
          sz?.h ?? (sticky.h || defaultH),
          shapeType
        )
        map.set(sticky.id, {
          x: sticky.x + (off?.x ?? 0),
          y: sticky.y + (off?.y ?? 0),
          w: dims.w,
          h: dims.h
        })
      } else if (kind === 'text') {
        const hasBg = Boolean(sticky.fillStyle && sticky.fillStyle !== 'none')
        const font = sz?.fontSize ?? sticky.fontSize ?? (hasBg ? 18 : 36)
        const autoDims = computeAutoTextDimensions(
          sticky.text,
          font,
          sz?.w ?? sticky.w ?? 220,
          sticky.autosize !== false,
          920,
          hasBg
        )
        map.set(sticky.id, {
          x: sticky.x + (off?.x ?? 0),
          y: sticky.y + (off?.y ?? 0),
          w: sz?.w ?? autoDims.w,
          h: sz?.h ?? autoDims.h
        })
      } else {
        const font = sz?.fontSize ?? sticky.fontSize ?? 14
        const cardW = sz?.w ?? (sticky.w || 220)
        const baseH = sz?.h ?? (sticky.h || 140)
        map.set(sticky.id, {
          x: sticky.x + (off?.x ?? 0),
          y: sticky.y + (off?.y ?? 0),
          w: cardW,
          h: sz?.h ?? computeCardMinHeight(sticky.text, font, cardW, baseH)
        })
      }
    }
    for (const node of nodes) {
      if (node.hidden) {
        continue
      }
      const sizeOvr = nodeSizeOverride?.id === node.id ? nodeSizeOverride : null
      const singleOff = nodeOffset?.id === node.id ? nodeOffset : null
      const groupOff =
        selectedNodeIdSet.has(node.id) && multiNodeDragDelta ? multiNodeDragDelta : null
      map.set(node.id, {
        x: (sizeOvr ? sizeOvr.x : node.x) + (singleOff?.dx ?? 0) + (groupOff?.x ?? 0),
        y: (sizeOvr ? sizeOvr.y : node.y) + (singleOff?.dy ?? 0) + (groupOff?.y ?? 0),
        w: sizeOvr ? sizeOvr.w : node.w,
        h: sizeOvr ? sizeOvr.h : node.h
      })
    }
    return map
  }, [
    multiNodeDragDelta,
    nodeOffset,
    nodeSizeOverride,
    nodes,
    selectedNodeIdSet,
    stickies,
    stickyOffset,
    stickySizeOverride,
    tileOffset,
    tileSizeOverride,
    tiles
  ])

  const boxMapRef = useRef<ReadonlyMap<string, BoxRect>>(boxMap)
  boxMapRef.current = boxMap
  return useMemo(
    () => ({
      stickies,
      stickiesById,
      sortedStickies,
      effectiveSelectedIds,
      selectedStickyIdSet,
      singleSelectedStickyId,
      singleSelectedSticky,
      arrows,
      nodes,
      nodesById,
      sortedNodes,
      effectiveSelectedNodeIds,
      selectedNodeIdSet,
      visibleGoals,
      goalsById,
      validGoalIds,
      liveAgentIds,
      agentsBySpace,
      tiles,
      boxMap,
      boxMapRef
    }),
    [
      stickies,
      stickiesById,
      sortedStickies,
      effectiveSelectedIds,
      selectedStickyIdSet,
      singleSelectedStickyId,
      singleSelectedSticky,
      arrows,
      nodes,
      nodesById,
      sortedNodes,
      effectiveSelectedNodeIds,
      selectedNodeIdSet,
      visibleGoals,
      goalsById,
      validGoalIds,
      liveAgentIds,
      agentsBySpace,
      tiles,
      boxMap,
      boxMapRef
    ]
  )
}

export type CanvasModel = ReturnType<typeof useCanvasModel>

// U-37: the canvas root's width, kept live (ResizeObserver, window resize as the fallback).
import { useEffect, useState } from 'react'

export function useCanvasWidth(rootRef: React.RefObject<HTMLElement | null>): number {
  const [width, setWidth] = useState(0)
  useEffect(() => {
    const el = rootRef.current
    if (!el) {
      return
    }
    const read = (): void => setWidth(el.clientWidth)
    read()
    if (typeof ResizeObserver !== 'undefined') {
      const ro = new ResizeObserver(read)
      ro.observe(el)
      return () => ro.disconnect()
    }
    window.addEventListener('resize', read)
    return () => window.removeEventListener('resize', read)
  }, [rootRef])
  return width
}

