  computer: SpaceComputerTarget
  pinned?: boolean
}

export type BaseCanvasNode = {
  id: string
  x: number
  y: number
  w: number
  h: number
  zIndex?: number
  locked?: boolean
  hidden?: boolean
  groupId?: string
  createdAt: number
}

export type SessionCanvasNode = BaseCanvasNode & {
  kind: 'session'
  sessionId: string
  sessionKind: SpaceSessionKind
  title: string
  roleId?: AgentRoleId
  agentName?: string
  status: SpaceNodeLiveStatus
  workingLine?: string
  projectSlug?: string
  computer: SpaceComputerTarget
  pinned?: boolean
}

export type AgentCanvasNode = BaseCanvasNode & {
  kind: 'agent'
  roleId: AgentRoleId
  title: string
  spawnMode: A01SpawnMode
  projectSlug?: string
  computer: SpaceComputerTarget
  status: SpaceNodeLiveStatus
  workingLine?: string
  sessionId?: string
  modelId?: string
}

export type ProjectCanvasNode = BaseCanvasNode & {
  kind: 'project'
  projectSlug: string
  title: string
  readiness: C02ProjectReadiness
  readinessScore?: number
  productsCount: number
  channels: string[]
  liveRefs: C02ProjectLiveRef[]
}

export type SpaceCanvasNode = SessionCanvasNode | AgentCanvasNode | ProjectCanvasNode

export type SpaceNodeDropPayload =
  | { kind: 'session'; session: DraggableSessionSummary }
  | { kind: 'a01-role'; roleId: AgentRoleId }
  | { kind: 'project'; project: C02ProjectSummary }

export const SESSION_NODE_DEFAULT_SIZE = { w: 320, h: 176 } as const
export const AGENT_NODE_DEFAULT_SIZE = { w: 312, h: 184 } as const
export const PROJECT_NODE_DEFAULT_SIZE = { w: 324, h: 196 } as const

export const CANVAS_NODE_MIN_W = 240
export const CANVAS_NODE_MAX_W = 920
export const CANVAS_NODE_MIN_H = 140
export const CANVAS_NODE_MAX_H = 720

export function clampCanvasNodeBox(box: { x: number; y: number; w: number; h: number }): {
  x: number
  y: number
  w: number
  h: number
} {
  return {
    x: Math.round(clampNum(box.x, -100_000, 100_000)),
    y: Math.round(clampNum(box.y, -100_000, 100_000)),
    w: Math.round(clampNum(box.w, CANVAS_NODE_MIN_W, CANVAS_NODE_MAX_W)),
    h: Math.round(clampNum(box.h, CANVAS_NODE_MIN_H, CANVAS_NODE_MAX_H))
  }
}

export function serializeNodeDropPayload(payload: SpaceNodeDropPayload): string {
  return JSON.stringify(payload)
}

export function parseNodeDropPayload(raw: string | null | undefined): SpaceNodeDropPayload | null {
  if (!raw || !raw.trim()) {
    return null
  }
  try {
    const parsed = JSON.parse(raw) as Record<string, unknown> | null
    if (!parsed || typeof parsed !== 'object') {
      return null
    }
    if (
      parsed.kind === 'a01-role' &&
      typeof parsed.roleId === 'string' &&
      A01_ROLE_IDS.includes(parsed.roleId as AgentRoleId)
    ) {
      return { kind: 'a01-role', roleId: parsed.roleId as AgentRoleId }
    }
    if (parsed.kind === 'session' && parsed.session && typeof parsed.session === 'object') {
      const s = parsed.session as Record<string, unknown>
      if (typeof s.sessionId === 'string' && s.sessionId.trim()) {
        return {
          kind: 'session',
          session: {
            sessionId: s.sessionId.trim(),
            sessionKind:
              s.sessionKind === 'orca-terminal' || s.sessionKind === 'orca-agent'
                ? s.sessionKind
                : 'openmanus-thread',
            title: typeof s.title === 'string' && s.title.trim() ? s.title.trim() : s.sessionId,
            ...(typeof s.roleId === 'string' && A01_ROLE_IDS.includes(s.roleId as AgentRoleId)
              ? { roleId: s.roleId as AgentRoleId }
              : {}),
            ...(typeof s.agentName === 'string' && s.agentName.trim()
              ? { agentName: s.agentName.trim() }
              : {}),
            status:
              s.status === 'working' || s.status === 'waiting' || s.status === 'done'
                ? s.status
                : 'idle',
            ...(typeof s.workingLine === 'string' && s.workingLine.trim()
              ? { workingLine: s.workingLine.trim() }
              : {}),
            ...(typeof s.projectSlug === 'string' && s.projectSlug.trim()
              ? { projectSlug: s.projectSlug.trim() }
              : {}),
            computer: isSpaceComputerTarget(s.computer) ? s.computer : 'local-ax',
            ...(typeof s.pinned === 'boolean' ? { pinned: s.pinned } : {})
          }
        }
      }
    }
    if (parsed.kind === 'project' && parsed.project && typeof parsed.project === 'object') {
      const p = parsed.project as Record<string, unknown>
      if (typeof p.slug === 'string' && p.slug.trim()) {
        return {
          kind: 'project',
          project: {
            slug: p.slug.trim(),
            title: typeof p.title === 'string' && p.title.trim() ? p.title.trim() : p.slug.trim(),
            readiness:
              p.readiness === 'green' || p.readiness === 'orange' || p.readiness === 'red'
                ? p.readiness
                : 'green',
            ...(typeof p.readinessScore === 'number' && Number.isFinite(p.readinessScore)
              ? { readinessScore: clampNum(Math.round(p.readinessScore), 0, 100) }
              : {}),
            productsCount:
              typeof p.productsCount === 'number' && Number.isFinite(p.productsCount)
                ? Math.max(0, Math.trunc(p.productsCount))
                : 0,
            channels: Array.isArray(p.channels)
              ? p.channels.filter((c): c is string => typeof c === 'string' && Boolean(c.trim()))
              : [],
            liveRefs: Array.isArray(p.liveRefs)
              ? p.liveRefs
                  .filter((r): r is Record<string, unknown> =>
                    Boolean(
                      r &&
                      typeof r === 'object' &&
                      typeof (r as { label?: unknown }).label === 'string'
                    )
                  )
                  .map((r) => ({
                    label: String(r.label).trim(),
                    ...(typeof r.url === 'string' && r.url.trim() ? { url: r.url.trim() } : {}),
                    ...(typeof r.path === 'string' && r.path.trim() ? { path: r.path.trim() } : {})
                  }))
              : []
          }
        }
      }
    }
    return null
  } catch {
    // ok: invalid external drag payload is ignored safely
    return null
  }
}

export function normalizeCanvasNode(
  raw: unknown,
  makeId: (prefix?: string) => string
): SpaceCanvasNode | null {
  if (!raw || typeof raw !== 'object') {
    return null
  }
  const obj = raw as Record<string, unknown>
  const kind = obj.kind
  if (kind !== 'session' && kind !== 'agent' && kind !== 'project') {
    return null
  }
  const defaults =
    kind === 'session'
      ? SESSION_NODE_DEFAULT_SIZE
      : kind === 'agent'
        ? AGENT_NODE_DEFAULT_SIZE
        : PROJECT_NODE_DEFAULT_SIZE
  const box = clampCanvasNodeBox({
    x: typeof obj.x === 'number' && Number.isFinite(obj.x) ? obj.x : 120,
    y: typeof obj.y === 'number' && Number.isFinite(obj.y) ? obj.y : 120,
    w: typeof obj.w === 'number' && Number.isFinite(obj.w) ? obj.w : defaults.w,
    h: typeof obj.h === 'number' && Number.isFinite(obj.h) ? obj.h : defaults.h
  })
  const base: BaseCanvasNode = {
    id: typeof obj.id === 'string' && obj.id.trim() ? obj.id.trim() : makeId(`node-${kind}`),
    ...box,
    ...(typeof obj.zIndex === 'number' && Number.isFinite(obj.zIndex)
      ? { zIndex: Math.round(clampNum(obj.zIndex, -50, 500)) }
      : {}),
    ...(typeof obj.locked === 'boolean' ? { locked: obj.locked } : {}),
    ...(typeof obj.hidden === 'boolean' ? { hidden: obj.hidden } : {}),
    ...(typeof obj.groupId === 'string' && obj.groupId.trim()
      ? { groupId: obj.groupId.trim().slice(0, 64) }
      : {}),
    createdAt:
      typeof obj.createdAt === 'number' && Number.isFinite(obj.createdAt) ? obj.createdAt : 0
  }

  if (kind === 'session') {
    const sessionId =
      typeof obj.sessionId === 'string' && obj.sessionId.trim() ? obj.sessionId.trim() : base.id
    const roleId =
      typeof obj.roleId === 'string' && A01_ROLE_IDS.includes(obj.roleId as AgentRoleId)
        ? (obj.roleId as AgentRoleId)
        : undefined
    return {
      ...base,
      kind: 'session',
      sessionId,
      sessionKind:
        obj.sessionKind === 'orca-terminal' || obj.sessionKind === 'orca-agent'
          ? obj.sessionKind
          : 'openmanus-thread',
      title:
        typeof obj.title === 'string' && obj.title.trim()
          ? obj.title.trim().slice(0, 140)
          : sessionId,
      ...(roleId ? { roleId } : {}),
      ...(typeof obj.agentName === 'string' && obj.agentName.trim()
        ? { agentName: obj.agentName.trim().slice(0, 80) }
        : {}),
      status:
        obj.status === 'working' || obj.status === 'waiting' || obj.status === 'done'
          ? obj.status
          : 'idle',
      ...(typeof obj.workingLine === 'string' && obj.workingLine.trim()
        ? { workingLine: obj.workingLine.trim().slice(0, 180) }
        : {}),
      ...(typeof obj.projectSlug === 'string' && obj.projectSlug.trim()
        ? { projectSlug: obj.projectSlug.trim().slice(0, 80) }
        : {}),
      computer: isSpaceComputerTarget(obj.computer) ? obj.computer : 'local-ax',
      ...(typeof obj.pinned === 'boolean' ? { pinned: obj.pinned } : {})
    }
  }

  if (kind === 'agent') {
    const roleId: AgentRoleId =
      typeof obj.roleId === 'string' && A01_ROLE_IDS.includes(obj.roleId as AgentRoleId)
        ? (obj.roleId as AgentRoleId)
        : 'worker'
    const roleMeta = AGENT_ROLE_ACCESSORIES[roleId]
    const requestedMode: A01SpawnMode =
      obj.spawnMode === 'long-term-employee' && roleMeta.longTermEmployeeCapable
        ? 'long-term-employee'
        : 'temporary-worker'
    return {
      ...base,
      kind: 'agent',
      roleId,
      title:
        typeof obj.title === 'string' && obj.title.trim()
          ? obj.title.trim().slice(0, 140)
          : roleMeta.label,
      spawnMode: requestedMode,
      ...(typeof obj.projectSlug === 'string' && obj.projectSlug.trim()
        ? { projectSlug: obj.projectSlug.trim().slice(0, 80) }
        : {}),
      computer: isSpaceComputerTarget(obj.computer) ? obj.computer : 'local-ax',
      status:
        obj.status === 'working' || obj.status === 'waiting' || obj.status === 'done'
          ? obj.status
          : 'idle',
      ...(typeof obj.workingLine === 'string' && obj.workingLine.trim()
        ? { workingLine: obj.workingLine.trim().slice(0, 180) }
        : {}),
      ...(typeof obj.sessionId === 'string' && obj.sessionId.trim()
        ? { sessionId: obj.sessionId.trim() }
        : {}),
      ...(typeof obj.modelId === 'string' && obj.modelId.trim()
        ? { modelId: obj.modelId.trim() }
        : {})
    }
  }

  const projectSlug =
    typeof obj.projectSlug === 'string' && obj.projectSlug.trim()
      ? obj.projectSlug.trim().slice(0, 80)
      : 'x-labs'
  return {
    ...base,
    kind: 'project',
    projectSlug,
    title:
      typeof obj.title === 'string' && obj.title.trim()
        ? obj.title.trim().slice(0, 140)
        : projectSlug,
    readiness:
      obj.readiness === 'green' || obj.readiness === 'orange' || obj.readiness === 'red'
        ? obj.readiness
        : 'green',
    ...(typeof obj.readinessScore === 'number' && Number.isFinite(obj.readinessScore)
      ? { readinessScore: clampNum(Math.round(obj.readinessScore), 0, 100) }
      : {}),
    productsCount:
      typeof obj.productsCount === 'number' && Number.isFinite(obj.productsCount)
        ? Math.max(0, Math.trunc(obj.productsCount))
        : 0,
    channels: Array.isArray(obj.channels)
      ? obj.channels
          .filter((c): c is string => typeof c === 'string' && Boolean(c.trim()))
          .map((c) => c.trim().slice(0, 64))
          .slice(0, 12)
      : [],
    liveRefs: Array.isArray(obj.liveRefs)
      ? obj.liveRefs
          .filter((r): r is Record<string, unknown> =>
            Boolean(
              r && typeof r === 'object' && typeof (r as { label?: unknown }).label === 'string'
            )
          )
          .map((r) => ({
            label: String(r.label).trim().slice(0, 64),
            ...(typeof r.url === 'string' && r.url.trim() ? { url: r.url.trim() } : {}),
            ...(typeof r.path === 'string' && r.path.trim() ? { path: r.path.trim() } : {})
          }))
          .slice(0, 12)
      : []
  }
}

export type MagneticArrowSemanticEffect =
  | {
      kind: 'bind-project'
      projectNodeId: string
      targetNodeId: string
      projectSlug: string
      fromNode: ProjectCanvasNode
      toNode: SessionCanvasNode | AgentCanvasNode
    }
  | {
      kind: 'connect-nodes'
      fromId: string
      toId: string
      fromNode: SessionCanvasNode | AgentCanvasNode
      toNode: SessionCanvasNode | AgentCanvasNode
    }

/**
 * Pure semantic resolver when a magnetic arrow connects `fromId ──▶ toId`:
 * - `C02 Project Card ──▶ Agent / Session Node` => `bind-project` (`host.onBindProjectToNode`)
 * - `Agent/Session A ──▶ Agent/Session B` => `connect-nodes` (`host.onConnectNodes`)
 */
export function resolveArrowConnectionEffect(
  fromId: string | undefined,
  toId: string | undefined,
  nodesById: ReadonlyMap<string, SpaceCanvasNode>
): MagneticArrowSemanticEffect | null {
  if (!fromId || !toId || fromId === toId) {
    return null
  }
  const fromNode = nodesById.get(fromId)
  const toNode = nodesById.get(toId)
  if (!fromNode || !toNode) {
    return null
  }
  if (fromNode.kind === 'project' && (toNode.kind === 'session' || toNode.kind === 'agent')) {
    return {
      kind: 'bind-project',
      projectNodeId: fromNode.id,
      targetNodeId: toNode.id,
      projectSlug: fromNode.projectSlug,
      fromNode,
      toNode
    }
  }
  if (
    (fromNode.kind === 'session' || fromNode.kind === 'agent') &&
    (toNode.kind === 'session' || toNode.kind === 'agent')
  ) {
    return {
      kind: 'connect-nodes',
      fromId: fromNode.id,
      toId: toNode.id,
      fromNode,
      toNode
    }
  }
  return null
}

export function createSessionCanvasNode(
  session: DraggableSessionSummary,
  position: { x: number; y: number },
  makeId: (prefix?: string) => string,
  now = Date.now()
): SessionCanvasNode {
  const box = clampCanvasNodeBox({
    x: position.x,
    y: position.y,
    w: SESSION_NODE_DEFAULT_SIZE.w,
    h: SESSION_NODE_DEFAULT_SIZE.h
  })
  return {
    id: makeId('node-session'),
    kind: 'session',
    ...box,
    sessionId: session.sessionId,
    sessionKind: session.sessionKind,
    title: session.title,
    ...(session.roleId ? { roleId: session.roleId } : {}),
    ...(session.agentName ? { agentName: session.agentName } : {}),
    status: session.status,
    ...(session.workingLine ? { workingLine: session.workingLine } : {}),
    ...(session.projectSlug ? { projectSlug: session.projectSlug } : {}),
    computer: session.computer,
    ...(session.pinned !== undefined ? { pinned: session.pinned } : {}),
    createdAt: now
  }
}

export function createAgentCanvasNode(
  params: {
    id?: string
    roleId: AgentRoleId
    spawnMode: A01SpawnMode
    projectSlug?: string
    computer: SpaceComputerTarget
    position: { x: number; y: number }
    modelId?: string
    title?: string
  },
  makeId: (prefix?: string) => string,
  now = Date.now()
): AgentCanvasNode {
  const roleMeta = AGENT_ROLE_ACCESSORIES[params.roleId]
  const box = clampCanvasNodeBox({
    x: params.position.x,
    y: params.position.y,
    w: AGENT_NODE_DEFAULT_SIZE.w,
    h: AGENT_NODE_DEFAULT_SIZE.h
  })
  const spawnMode: A01SpawnMode =
    params.spawnMode === 'long-term-employee' && roleMeta.longTermEmployeeCapable
      ? 'long-term-employee'
      : 'temporary-worker'
  return {
    id: params.id ?? makeId('node-agent'),
    kind: 'agent',
    ...box,
    roleId: params.roleId,
    title: params.title?.trim() || roleMeta.label,
    spawnMode,
    ...(params.projectSlug?.trim() ? { projectSlug: params.projectSlug.trim() } : {}),
    computer: params.computer,
    status: 'working',
    workingLine:
      spawnMode === 'long-term-employee'
        ? `Booting A01 ${roleMeta.label} + Hindsight memory…`
        : `Spawning temporary ${roleMeta.label} worker…`,
    ...(params.modelId ? { modelId: params.modelId } : {}),
    createdAt: now
  }
}

export function createProjectCanvasNode(
  project: C02ProjectSummary,
  position: { x: number; y: number },
  makeId: (prefix?: string) => string,
  now = Date.now()
): ProjectCanvasNode {
  const box = clampCanvasNodeBox({
    x: position.x,
    y: position.y,
    w: PROJECT_NODE_DEFAULT_SIZE.w,
    h: PROJECT_NODE_DEFAULT_SIZE.h
  })
  return {
    id: makeId('node-project'),
    kind: 'project',
    ...box,
    projectSlug: project.slug,
    title: project.title,
    readiness: project.readiness,
    ...(project.readinessScore !== undefined ? { readinessScore: project.readinessScore } : {}),
    productsCount: project.productsCount,
    channels: [...project.channels],
    liveRefs: project.liveRefs.map((ref) => ({ ...ref })),
    createdAt: now
  }
}

export function upsertCanvasNode(
  nodes: readonly SpaceCanvasNode[] | undefined,
  node: SpaceCanvasNode
): SpaceCanvasNode[] {
  const list = nodes ? [...nodes] : []
  const idx = list.findIndex((item) => item.id === node.id)
  if (idx >= 0) {
    list[idx] = node
    return list
  }
  return [...list, node].slice(0, MAX_CANVAS_NODES)
}

export function patchCanvasNode(
  nodes: readonly SpaceCanvasNode[] | undefined,
  nodeId: string,
  patch: Partial<SpaceCanvasNode>
): SpaceCanvasNode[] {
  if (!nodes || nodes.length === 0) {
    return []
  }
  return nodes.map((item) => {
    if (item.id !== nodeId) {
      return item
    }
    const merged = { ...item, ...patch, kind: item.kind } as SpaceCanvasNode
    const clamped = clampCanvasNodeBox(merged)
    return { ...merged, ...clamped }
  })
}

export function removeCanvasNode(
  nodes: readonly SpaceCanvasNode[] | undefined,
  nodeId: string
): SpaceCanvasNode[] {
  if (!nodes || nodes.length === 0) {
    return []
  }
  return nodes.filter((item) => item.id !== nodeId)
}

import type React from 'react'

export type KeyboardEventLike = {
  isComposing?: boolean
  keyCode?: number
  key?: string
  metaKey?: boolean
  ctrlKey?: boolean
  nativeEvent?: {
    isComposing?: boolean
    keyCode?: number
  }
}

/**
 * Returns true when an active IME composition owns the keystroke (e.g. Japanese/Chinese/Korean
 * candidate confirmation via Enter/Escape, or keyCode 229). Host apps should never intercept
 * IME-owned keys as canvas shortcuts.
 */
export function isImeOwnedKeyboardEvent(
  event: KeyboardEventLike | React.KeyboardEvent | KeyboardEvent
): boolean {
  const like = event as KeyboardEventLike
  if (like.isComposing || like.nativeEvent?.isComposing) {
    return true
  }
  if (like.keyCode === 229 || like.nativeEvent?.keyCode === 229) {
    return true
  }
  return like.key === 'Process'
}

export function isMacLikePlatform(): boolean {
  if (typeof navigator === 'undefined') {
    return true
  }
  return /Mac|iPhone|iPad|iPod/i.test(navigator.platform || navigator.userAgent || '')
}

export type KeepOutRect = { left: number; top: number; right: number; bottom: number }

const zones = new Map<string, KeepOutRect>()
const listeners = new Set<() => void>()

export function setKeepOut(id: string, rect: KeepOutRect | null): void {
  const prev = zones.get(id)
  if (!rect) {
    if (zones.delete(id)) {
      listeners.forEach((cb) => cb())
    }
    return
  }
  if (
    prev &&
    prev.left === rect.left &&
    prev.top === rect.top &&
    prev.right === rect.right &&
    prev.bottom === rect.bottom
  ) {
    return
  }
  zones.set(id, { ...rect })
  listeners.forEach((cb) => cb())
}

export function getKeepOuts(): KeepOutRect[] {
  return [...zones.values()].map((r) => ({ ...r }))
}

export function subscribeKeepOut(cb: () => void): () => void {
  listeners.add(cb)
  return () => listeners.delete(cb)
}

export function overlapsKeepOut(rect: KeepOutRect, gap = 0): KeepOutRect | null {
  for (const z of zones.values()) {
    if (
      rect.left < z.right + gap &&
      rect.right > z.left - gap &&
      rect.top < z.bottom + gap &&
      rect.bottom > z.top - gap
    ) {
      return { ...z }
    }
  }
  return null
}

export function pushOutOfKeepOut(rect: KeepOutRect, gap = 8): KeepOutRect {
  let r = { ...rect }
  for (let i = 0; i < zones.size + 1; i++) {
    const z = overlapsKeepOut(r, 0)
    if (!z) {
      break
    }
    const w = r.right - r.left
    const h = r.bottom - r.top
    const moves = [
      { dx: z.left - gap - r.right, dy: 0 },
      { dx: 0, dy: z.top - gap - r.bottom },
      { dx: z.right + gap - r.left, dy: 0 },
      { dx: 0, dy: z.bottom + gap - r.top }
    ]
    const m = moves.reduce((a, b) =>
      Math.abs(a.dx) + Math.abs(a.dy) <= Math.abs(b.dx) + Math.abs(b.dy) ? a : b
    )
    r = {
      left: r.left + m.dx,
      top: r.top + m.dy,
      right: r.left + m.dx + w,
      bottom: r.top + m.dy + h
    }
  }
  return r
}

export type PinView = 'auto' | 'chat' | 'terminal'
export type PinKind = 'agent' | 'terminal' | 'browser' | 'editor'
export type Pt = { x: number; y: number }
export type Box = { x: number; y: number; w: number; h: number }
export type Viewport = { w: number; h: number }

export type PinnedSession = {
  tabId: string
  worktreeId: string
  kind: PinKind
  name: string
  square: Pt
  win: Box
  open: boolean
  view: PinView
  z: number
}

export type PinnedState = { pins: PinnedSession[] }

export const PINNED_STORAGE_KEY = 'xlabs-space-canvas:pinned-sessions-v1'
export const MAX_PINS = 6
export const SQUARE_W = 72
export const SQUARE_H = 84
export const TOP_SAFE = 40
export const BOTTOM_SAFE = 36
export const RIGHT_RESERVED = 88
export const WIN_DEFAULT = { w: 420, h: 520 }
export const WIN_MIN = { w: 300, h: 240 }
export const WIN_MAX_FRACTION = 0.9
export const SNAP_PX = 8
const EDGE_GAP = 12

export const EMPTY_PINNED: PinnedState = { pins: [] }

const clamp = (v: number, lo: number, hi: number): number =>
  Math.min(Math.max(v, lo), Math.max(lo, hi))

export function clampSquare(p: Pt, vp: Viewport): Pt {
  return {
    x: Math.round(clamp(p.x, 0, vp.w - SQUARE_W)),
    y: Math.round(clamp(p.y, TOP_SAFE, vp.h - BOTTOM_SAFE - SQUARE_H))
  }
}

export function clampWinSize(
  size: { w: number; h: number },
  vp: Viewport
): { w: number; h: number } {
  const maxW = Math.max(WIN_MIN.w, vp.w * WIN_MAX_FRACTION)
  const maxH = Math.max(WIN_MIN.h, (vp.h - TOP_SAFE - BOTTOM_SAFE) * WIN_MAX_FRACTION)
  return {
    w: Math.round(clamp(size.w, WIN_MIN.w, maxW)),
    h: Math.round(clamp(size.h, WIN_MIN.h, maxH))
  }
}

export function clampWindow(b: Box, vp: Viewport): Box {
  const size = clampWinSize(b, vp)
  return {
    ...size,
    x: Math.round(clamp(b.x, 0, vp.w - size.w)),
    y: Math.round(clamp(b.y, TOP_SAFE, vp.h - BOTTOM_SAFE - size.h))
  }
}

const hits = (a: Box, b: Box): boolean =>
  a.x < b.x + b.w && b.x < a.x + a.w && a.y < b.y + b.h && b.y < a.y + a.h

export function windowNearSquare(
  square: Pt,
  size: { w: number; h: number },
  vp: Viewport,
  avoid: readonly Box[] = []
): Box {
  const s = clampWinSize(size, vp)
  const spots: Pt[] = [
    { x: square.x - s.w - EDGE_GAP, y: square.y + SQUARE_H - s.h },
    { x: square.x + SQUARE_W - s.w, y: square.y - s.h - EDGE_GAP },
    { x: square.x - s.w - EDGE_GAP, y: square.y },
    { x: square.x + SQUARE_W + EDGE_GAP, y: square.y + SQUARE_H - s.h },
    { x: square.x + SQUARE_W + EDGE_GAP, y: square.y },
    { x: square.x, y: square.y + SQUARE_H + EDGE_GAP }
  ]
  const boxes = spots.map((p) => clampWindow({ ...p, ...s }, vp))
  const free = boxes.find((b) => !avoid.some((a) => hits(b, a)))
  return free ?? boxes[0]!
}

export function defaultSquarePos(index: number, vp: Viewport): Pt {
  const step = SQUARE_W + 12
  const perRow = Math.max(1, Math.floor((vp.w - RIGHT_RESERVED - 24) / step))
  const col = index % perRow
  const row = Math.floor(index / perRow)
  return clampSquare(
    {
      x: vp.w - RIGHT_RESERVED - SQUARE_W - col * step,
      y: vp.h - BOTTOM_SAFE - SQUARE_H - row * (SQUARE_H + 12)
    },
    vp
  )
}

export function freeSquarePos(
  existing: readonly Pt[],
  vp: Viewport,
  keepOut: readonly Box[] = []
): Pt {
  const taken: Box[] = [
    ...existing.map((p) => ({ x: p.x, y: p.y, w: SQUARE_W, h: SQUARE_H })),
    ...keepOut
  ]
  for (let k = 0; k < 120; k++) {
    const pos = defaultSquarePos(k, vp)
    const box = { x: pos.x, y: pos.y, w: SQUARE_W, h: SQUARE_H }
    if (!taken.some((t) => hits(box, t))) {
      return pos
    }
  }
  return defaultSquarePos(existing.length, vp)
}

export type PinInput = { tabId: string; worktreeId: string; kind: PinKind; name: string }

export type PinnedAction =
  | { type: 'pin'; input: PinInput; vp: Viewport; keepOut?: readonly Box[] }
  | { type: 'setView'; tabId: string; view: PinView }
  | { type: 'unpin'; tabId: string }
  | { type: 'rename'; tabId: string; name: string }
  | { type: 'moveSquare'; tabId: string; to: Pt; vp: Viewport }
  | { type: 'setWindow'; tabId: string; box: Box; vp: Viewport }
  | { type: 'open'; tabId: string; vp: Viewport; keepOut?: readonly Box[] }
  | { type: 'close'; tabId: string }
  | { type: 'raise'; tabId: string }
  | { type: 'resetPosition'; tabId: string; vp: Viewport; keepOut?: readonly Box[] }
  | { type: 'prune'; keep: ReadonlySet<string> }
  | { type: 'clampAll'; vp: Viewport }

export const isPinned = (s: PinnedState, tabId: string): boolean =>
  s.pins.some((p) => p.tabId === tabId)

export const isPinnable = (kind: PinKind): boolean => kind !== 'editor'

const topZ = (s: PinnedState): number => s.pins.reduce((m, p) => Math.max(m, p.z), 0)

export const canPin = (s: PinnedState): boolean => s.pins.length < MAX_PINS

function patch(
  s: PinnedState,
  tabId: string,
  fn: (p: PinnedSession) => PinnedSession
): PinnedState {
  let changed = false
  const pins = s.pins.map((p) => {
    if (p.tabId !== tabId) {
      return p
    }
    const next = fn(p)
    changed = changed || next !== p
    return next
  })
  return changed ? { pins } : s
}

export function pinnedReducer(s: PinnedState, a: PinnedAction): PinnedState {
  switch (a.type) {
    case 'pin': {
      if (isPinned(s, a.input.tabId) || !canPin(s) || !isPinnable(a.input.kind)) {
        return s
      }
      const square = freeSquarePos(
        s.pins.map((p) => p.square),
        a.vp,
        a.keepOut
      )
      const win = windowNearSquare(square, WIN_DEFAULT, a.vp)
      const name = a.input.name.trim() || 'Session'
      return {
        pins: [
          ...s.pins,
          { ...a.input, name, square, win, open: false, view: 'auto', z: topZ(s) + 1 }
        ]
      }
    }
    case 'unpin':
      return isPinned(s, a.tabId) ? { pins: s.pins.filter((p) => p.tabId !== a.tabId) } : s
    case 'rename': {
      const name = a.name.trim()
      return name ? patch(s, a.tabId, (p) => (p.name === name ? p : { ...p, name })) : s
    }
    case 'moveSquare':
      return patch(s, a.tabId, (p) => {
        const square = clampSquare(a.to, a.vp)
        return square.x === p.square.x && square.y === p.square.y ? p : { ...p, square }
      })
    case 'setWindow':
      return patch(s, a.tabId, (p) => ({ ...p, win: clampWindow(a.box, a.vp) }))
    case 'open': {
      const target = s.pins.find((p) => p.tabId === a.tabId)
      if (!target) {
        return s
      }
      const avoid = [
        ...s.pins
          .filter((p) => p !== target && !p.open)
          .map((p) => ({ x: p.square.x, y: p.square.y, w: SQUARE_W, h: SQUARE_H })),
        ...(a.keepOut ?? [])
      ]
      const win = windowNearSquare(target.square, target.win, a.vp, avoid)
      const z = topZ(s) + 1
      return { pins: s.pins.map((p) => (p === target ? { ...p, win, open: true, z } : p)) }
    }
    case 'setView':
      return patch(s, a.tabId, (p) => (p.view === a.view ? p : { ...p, view: a.view }))
    case 'close':
      return patch(s, a.tabId, (p) => (p.open ? { ...p, open: false } : p))
    case 'raise':
      return patch(s, a.tabId, (p) => (p.z === topZ(s) ? p : { ...p, z: topZ(s) + 1 }))
    case 'resetPosition': {
      const target = s.pins.find((p) => p.tabId === a.tabId)
      if (!target) {
        return s
      }
      const others = s.pins.filter((p) => p !== target)
      const square = freeSquarePos(
        others.map((p) => p.square),
        a.vp,
        a.keepOut
      )
      const avoid = [
        ...others
          .filter((p) => !p.open)
          .map((p) => ({ x: p.square.x, y: p.square.y, w: SQUARE_W, h: SQUARE_H })),
        ...(a.keepOut ?? [])
      ]
      const win = windowNearSquare(square, target.win, a.vp, avoid)
      return patch(s, a.tabId, (p) => ({ ...p, square, win }))
    }
    case 'prune': {
      const pins = s.pins.filter((p) => a.keep.has(p.tabId))
      return pins.length === s.pins.length ? s : { pins }
    }
    case 'clampAll': {
      let changed = false
      const pins = s.pins.map((p) => {
        const square = clampSquare(p.square, a.vp)
        const win = clampWindow(p.win, a.vp)
        if (
          square.x === p.square.x &&
          square.y === p.square.y &&
          win.x === p.win.x &&
          win.y === p.win.y &&
          win.w === p.win.w &&
          win.h === p.win.h
        ) {
          return p
        }
        changed = true
        return { ...p, square, win }
      })
      return changed ? { pins } : s
    }
  }
}

const KINDS: readonly PinKind[] = ['agent', 'terminal', 'browser', 'editor']
const num = (v: unknown): v is number => typeof v === 'number' && Number.isFinite(v)

export function parsePinned(raw: string | null): PinnedState {
  if (!raw) {
    return EMPTY_PINNED
  }
  try {
    const data: unknown = JSON.parse(raw)
    const list = (data as { pins?: unknown })?.pins
    if (!Array.isArray(list)) {
      return EMPTY_PINNED
    }
    const pins: PinnedSession[] = []
    const seen = new Set<string>()
    for (const item of list) {
      const p = item as Partial<PinnedSession> | null
      if (
        !p ||
        typeof p.tabId !== 'string' ||
        typeof p.worktreeId !== 'string' ||
        typeof p.name !== 'string' ||
        !p.square ||
        !num(p.square.x) ||
        !num(p.square.y) ||
        !p.win ||
        !num(p.win.x) ||
        !num(p.win.y) ||
        !num(p.win.w) ||
        !num(p.win.h) ||
        seen.has(p.tabId) ||
        pins.length >= MAX_PINS
      ) {
        continue
      }
      seen.add(p.tabId)
      pins.push({
        tabId: p.tabId,
        worktreeId: p.worktreeId,
        kind: KINDS.includes(p.kind as PinKind) ? (p.kind as PinKind) : 'agent',
        name: p.name,
        square: { x: p.square.x, y: p.square.y },
        win: { x: p.win.x, y: p.win.y, w: p.win.w, h: p.win.h },
        open: p.open === true,
        view: p.view === 'chat' || p.view === 'terminal' ? p.view : 'auto',
        z: num(p.z) ? p.z : pins.length + 1
      })
    }
    return { pins }
  } catch {
    // ok: corrupted saved pin state safely falls back to EMPTY_PINNED
    return EMPTY_PINNED
  }
}

export const serializePinned = (s: PinnedState): string => JSON.stringify({ pins: s.pins })

import {
  BENCH_KEY,
  EMPTY_SPACE,
  SPACE_LEVELS,
  SPACE_LOCAL_STORAGE_KEY,
  normalizeSpaceState,
  type Point,
  type SpaceAgent,
  type SpaceAsk,
  type SpaceFocusRequest,
  type SpaceGoal,
  type SpaceLayout,
  type SpaceState,
  type SpaceTile,
  type View
} from './space'

export const CARD_WIDTH = 148
export const CARD_HEIGHT = 112
export const GAP = 14
export const TEAM_PADDING = 20
export const TILE_HEADER = 76
export const TILE_SUMMARY = 40
const EMPTY_HEIGHT = 96
const SPACING = 48

export function tileSize(agentCount: number, side = false): { w: number; h: number } {
  const columns = agentCount > 4 ? 3 : 2
  const rows = Math.ceil(agentCount / columns)
  const cardsHeight = rows > 0 ? rows * (CARD_HEIGHT + GAP) - GAP : EMPTY_HEIGHT
  return {
    w: columns * CARD_WIDTH + (columns - 1) * GAP + TEAM_PADDING * 2,
    h: TILE_HEADER + (side ? 0 : TILE_SUMMARY) + cardsHeight + TEAM_PADDING
  }
}

export type TileResizeHandle = 'nw' | 'ne' | 'sw' | 'se' | 'e' | 's'
export const TILE_MIN_W = 260
export const TILE_MAX_W = 2600
export const TILE_MIN_H = 160
export const TILE_MAX_H = 2200

export function resizeTileLayout(
  origin: SpaceLayout,
  handle: TileResizeHandle,
  dx: number,
  dy: number
): SpaceLayout {
  const clamp = (value: number, min: number, max: number): number =>
    Math.max(min, Math.min(max, Math.round(value)))
  const west = handle === 'nw' || handle === 'sw'
  const east = handle === 'ne' || handle === 'se' || handle === 'e'
  const north = handle === 'nw' || handle === 'ne'
  const south = handle === 'sw' || handle === 'se' || handle === 's'
  const w = west
    ? clamp(origin.w - dx, TILE_MIN_W, TILE_MAX_W)
    : east
      ? clamp(origin.w + dx, TILE_MIN_W, TILE_MAX_W)
      : origin.w
  const h = north
    ? clamp(origin.h - dy, TILE_MIN_H, TILE_MAX_H)
    : south
      ? clamp(origin.h + dy, TILE_MIN_H, TILE_MAX_H)
      : origin.h
  return {
    x: west ? Math.round(origin.x + origin.w - w) : origin.x,
    y: north ? Math.round(origin.y + origin.h - h) : origin.y,
    w,
    h
  }
}

export function minTileHeightForWidth(agentCount: number, width: number, side = false): number {
  if (agentCount <= 0) {
    return side ? 92 : 160
  }
  const columns = Math.max(
    1,
    Math.min(8, Math.floor((width - TEAM_PADDING * 2 + GAP) / (CARD_WIDTH + GAP)))
  )
  const rows = Math.ceil(agentCount / columns)
  const cardsHeight = rows * (CARD_HEIGHT + GAP) - GAP
  return TILE_HEADER + (side ? 0 : TILE_SUMMARY) + cardsHeight + TEAM_PADDING
}

export function extraPresenceHeightForAgent(
  agent: Pick<SpaceAgent, 'splitInfo' | 'subagents'>
): number {
  const hasSplit = Boolean(agent.splitInfo && agent.splitInfo.paneCount >= 2)
  const subCount = agent.subagents?.length ?? 0
  if (!hasSplit && subCount === 0) {
    return 0
  }
  let extra = 8
  if (hasSplit) {
    extra += agent.splitInfo?.direction === 'vertical' ? 76 : 58
  }
  if (subCount > 0) {
    extra += 34 + Math.min(subCount, 3) * 24 + (subCount > 3 ? 18 : 0)
  }
  return extra
}

export function extraPresenceHeightForMembers(
  members: readonly Pick<SpaceAgent, 'splitInfo' | 'subagents'>[],
  width: number
): number {
  if (members.length === 0) {
    return 0
  }
  const columns = Math.max(
    1,
    Math.min(8, Math.floor((width - TEAM_PADDING * 2 + GAP) / (CARD_WIDTH + GAP)))
  )
  let totalExtra = 0
  for (let i = 0; i < members.length; i += columns) {
    let rowMax = 0
    const end = Math.min(members.length, i + columns)
    for (let j = i; j < end; j += 1) {
      const m = members[j]
      if (m) {
        rowMax = Math.max(rowMax, extraPresenceHeightForAgent(m))
      }
    }
    totalExtra += rowMax
  }
  return totalExtra
}

export function layoutSpaces(
  goals: readonly SpaceGoal[],
  agentCount: (key: string) => number,
  bench?: SpaceLayout,
  extraHeightForKey?: (key: string, width: number) => number
): SpaceTile[] {
  const tiles: SpaceTile[] = []
  let y = 40
  let right = 40
  for (const level of SPACE_LEVELS.filter((candidate) => candidate !== 'side')) {
    const row = goals.filter((goal) => goal.level === level)
    if (row.length === 0) {
      continue
    }
    let x = 40
    let tallest = 0
    for (const goal of row) {
      const count = agentCount(goal.id)
      const size = tileSize(count)
      const w = goal.layout?.w && goal.layout.w >= 260 ? Math.round(goal.layout.w) : size.w
      const baseH = goal.layout?.h && goal.layout.h >= 160 ? Math.round(goal.layout.h) : size.h
      const extraH = extraHeightForKey ? Math.max(0, extraHeightForKey(goal.id, w)) : 0
      const h = Math.max(baseH, minTileHeightForWidth(count, w, false) + extraH)
      tiles.push({
        key: goal.id,
        x: goal.layout?.x ?? x,
        y: goal.layout?.y ?? y,
        w,
        h
      })
      x += w + SPACING
      tallest = Math.max(tallest, h)
    }
    right = Math.max(right, x)
    y += tallest + SPACING
  }
  let sideY = 40
  for (const goal of goals.filter((candidate) => candidate.level === 'side')) {
    const count = agentCount(goal.id)
    const size = tileSize(count, true)
    const w = goal.layout?.w && goal.layout.w >= 260 ? Math.round(goal.layout.w) : size.w
    const baseH = goal.layout?.h && goal.layout.h >= 140 ? Math.round(goal.layout.h) : size.h
    const extraH = extraHeightForKey ? Math.max(0, extraHeightForKey(goal.id, w)) : 0
    const h = Math.max(baseH, minTileHeightForWidth(count, w, true) + extraH)
    tiles.push({
      key: goal.id,
      x: goal.layout?.x ?? right,
      y: goal.layout?.y ?? sideY,
      w,
      h
    })
    sideY += h + SPACING
  }
  const benchCount = agentCount(BENCH_KEY)
  const benchSize = tileSize(benchCount, true)
  const benchMinW = benchCount === 0 ? 220 : 260
  const benchMinH = benchCount === 0 ? 84 : 140
  const benchW = bench?.w && bench.w >= benchMinW ? Math.round(bench.w) : benchSize.w
  const rawBenchH =
    bench?.h && bench.h >= benchMinH ? Math.round(bench.h) : benchCount === 0 ? 96 : benchSize.h
  const benchExtraH = extraHeightForKey ? Math.max(0, extraHeightForKey(BENCH_KEY, benchW)) : 0
  const benchH = Math.max(rawBenchH, minTileHeightForWidth(benchCount, benchW, true) + benchExtraH)
  tiles.push({
    key: BENCH_KEY,
    x: bench?.x ?? 40,
    y: bench?.y ?? Math.max(y, 40),
    w: benchW,
    h: benchH
  })
  return tiles
}

export function toCanvas(point: Point, view: View): Point {
  return {
    x: (point.x - view.x) / view.scale,
    y: (point.y - view.y) / view.scale
  }
}

export const ZOOM_STEP_IN_FACTOR = 1.28 * 1.5
export const ZOOM_STEP_OUT_FACTOR = 1.4 * 1.5
export const ZOOM_WHEEL_SENSITIVITY_IN = 0.0028 * 1.5
export const ZOOM_WHEEL_SENSITIVITY_OUT = 0.0044 * 1.5
export const ZOOM_TWEEN_MS = Math.round(135 / 1.5)

export function zoomAt(view: View, nextScale: number, focal: Point): View {
  const clamped = Math.max(0.18, Math.min(2, nextScale))
  return {
    scale: clamped,
    x: focal.x - ((focal.x - view.x) / view.scale) * clamped,
    y: focal.y - ((focal.y - view.y) / view.scale) * clamped
  }
}

export function fitSpaces(tiles: readonly SpaceTile[], width: number, height: number): View {
  if (tiles.length === 0 || width <= 0 || height <= 0) {
    return { x: 40, y: 40, scale: 1 }
  }
  const minX = Math.min(...tiles.map((t) => t.x))
  const minY = Math.min(...tiles.map((t) => t.y))
  const maxX = Math.max(...tiles.map((t) => t.x + t.w))
  const maxY = Math.max(...tiles.map((t) => t.y + t.h))
  const boxW = Math.max(200, maxX - minX)
  const boxH = Math.max(160, maxY - minY)
  const pad = 64
  const scale = Math.max(
    0.35,
    Math.min(1.15, Math.min((width - pad * 2) / boxW, (height - pad * 2) / boxH))
  )
  return {
    scale,
    x: Math.round((width - boxW * scale) / 2 - minX * scale),
    y: Math.round((height - boxH * scale) / 2 - minY * scale)
  }
}

export type KanbanCardImport = {
  card: string
  title: string
  state?: string
  roadmap: string[]
  tasks: string[]
}

export function cardsFromKanbanTree(tree: unknown): KanbanCardImport[] {
  const nodes =
    tree && typeof tree === 'object' && Array.isArray((tree as { nodes?: unknown }).nodes)
      ? ((tree as { nodes: Record<string, unknown>[] }).nodes ?? [])
      : []
  const cards: KanbanCardImport[] = []
  for (const node of nodes) {
    if (!node || typeof node !== 'object') {
      continue
    }
    const title = typeof node.title === 'string' ? node.title.trim() : ''
    if (!title) {
      continue
    }
    if (node.depth === 0 && node.kind === 'goal' && typeof node.id === 'string') {
      const state = typeof node.state === 'string' && node.state.trim() ? node.state.trim() : ''
      cards.push({ card: node.id, title, ...(state ? { state } : {}), roadmap: [], tasks: [] })
      continue
    }
    const current = cards.at(-1)
    if (!current || node.depth === 0) {
      continue
    }
    if (node.kind === 'task') {
      current.tasks.push(title)
    } else {
      const state = typeof node.state === 'string' && node.state.trim() ? node.state.trim() : ''
      current.roadmap.push(state ? `${title} (${state})` : title)
    }
  }
  return cards
}

export function resolveAgentGoalId(
  space: SpaceState,
  agent: { id: string; unifiedTabId?: string; name?: string },
  validGoalIds?: ReadonlySet<string>,
  liveOtherIds?: ReadonlySet<string>
): string | null {
  const check = (gid: string | undefined): string | null => {
    if (!gid) {
      return null
    }
    if (validGoalIds && !validGoalIds.has(gid)) {
      return null
    }
    return gid
  }
  const direct =
    check(space.placements[agent.id]) ??
    (agent.unifiedTabId ? check(space.placements[agent.unifiedTabId]) : null)
  if (direct) {
    return direct
  }
  if (agent.name && space.placementNames) {
    for (const [savedId, savedName] of Object.entries(space.placementNames)) {
      if (savedId !== agent.id && savedId !== agent.unifiedTabId && liveOtherIds?.has(savedId)) {
        continue
      }
      if (savedName === agent.name) {
        const matched = check(space.placements[savedId])
        if (matched) {
          return matched
        }
      }
    }
  }
  return null
}

export function purgeAgentPlacements(
  space: SpaceState,
  agent: { id: string; unifiedTabId?: string; name?: string },
  liveOtherIds?: ReadonlySet<string>
): SpaceState {
  const keysToPurge = new Set<string>([agent.id])
  if (agent.unifiedTabId) {
    keysToPurge.add(agent.unifiedTabId)
  }
  if (agent.name && space.placementNames) {
    for (const [savedId, savedName] of Object.entries(space.placementNames)) {
      if (savedId !== agent.id && savedId !== agent.unifiedTabId && liveOtherIds?.has(savedId)) {
        continue
      }
      if (savedName === agent.name) {
        keysToPurge.add(savedId)
      }
    }
  }
  const nextPlacements = { ...space.placements }
  const nextNames = { ...space.placementNames }
  const nextThreadGoals = { ...space.threadGoals }
  for (const key of keysToPurge) {
    delete nextPlacements[key]
    delete nextNames[key]
    delete nextThreadGoals[key]
  }
  return {
    ...space,
    placements: nextPlacements,
    placementNames: nextNames,
    threadGoals: nextThreadGoals
  }
}

export function isAssistantMessageAskingQuestion(
  text?: string | null,
  isToolOutput?: boolean
): boolean {
  if (isToolOutput || !text) {
    return false
  }
  const trimmed = text.trim()
  if (!trimmed) {
    return false
  }
  const tail = trimmed.slice(-700)
  if (tail.includes('?')) {
    return true
  }
  return /\b(needs input|decision needed|ask:|what'?s the call|what is the call|what'?s the outcome|do you want|would you like|should i|which option|let me know|waiting on you|waiting for your)\b/i.test(
    tail
  )
}

function extractRolePrefix(label: string | undefined): string {
  if (!label) {
    return ''
  }
  return (label.split('·')[0] ?? '').trim().toLowerCase()
}

export function doesAskMatchAgent(
  ask: SpaceAsk,
  agent: { id: string; unifiedTabId?: string; name?: string },
  agentStayInSameGoal = false,
  goalAgentsCount = 0
): boolean {
  if (ask.status !== 'open') {
    return false
  }
  if (
    ask.botId === agent.id ||
    (agent.unifiedTabId && ask.botId === agent.unifiedTabId) ||
    ask.forBotId === agent.id
  ) {
    return true
  }
  const agentNameLower = (agent.name ?? '').trim().toLowerCase()
  if (agentNameLower) {
    const candidates = [ask.botName, ask.agentName, ask.botId]
      .filter((c): c is string => typeof c === 'string' && Boolean(c.trim()))
      .map((c) => c.trim().toLowerCase())
    if (candidates.includes(agentNameLower)) {
      return true
    }
    if (agentStayInSameGoal) {
      const agentRole = extractRolePrefix(agent.name)
      if (
        agentRole &&
        candidates.some((c) => extractRolePrefix(c) === agentRole || c === agentRole)
      ) {
        return true
      }
      if (goalAgentsCount === 1) {
        return true
      }
    }
  }
  return false
}

export function doesAgentHaveOpenAsk(
  space: SpaceState,
  agent: { id: string; unifiedTabId?: string; name?: string },
  agentGoalId: string | null,
  goalAgentsCount = 0
): boolean {
  for (const goal of space.goals) {
    const inThisGoal = Boolean(agentGoalId && goal.id === agentGoalId)
    for (const ask of goal.asks) {
      if (doesAskMatchAgent(ask, agent, inThisGoal, inThisGoal ? goalAgentsCount : 0)) {
        return true
      }
    }
  }
  return false
}

export function resolveFocusRequestTarget(
  space: SpaceState,
  agents: readonly { id: string; unifiedTabId?: string; name: string; attention?: boolean }[],
  req: SpaceFocusRequest
): { agentId: string | null; spaceId: string | null } {
  const validGoalIds = new Set(space.goals.map((g) => g.id))
  const resolvedSpaceId = req.spaceId && validGoalIds.has(req.spaceId) ? req.spaceId : null

  if (req.tabId) {
    const byId = agents.find((a) => a.id === req.tabId || a.unifiedTabId === req.tabId)
    if (byId) {
      return {
        agentId: byId.id,
        spaceId: resolvedSpaceId ?? resolveAgentGoalId(space, byId, validGoalIds)
      }
    }
  }

  if (req.agentName) {
    const targetLower = req.agentName.trim().toLowerCase()
    const byName = agents.find((a) => a.name.trim().toLowerCase() === targetLower)
    if (byName) {
      return {
        agentId: byName.id,
        spaceId: resolvedSpaceId ?? resolveAgentGoalId(space, byName, validGoalIds)
      }
    }
  }

  const targetRole = extractRolePrefix(req.role || req.agentName)
  if (resolvedSpaceId) {
    const inSpace = agents.filter(
      (a) => resolveAgentGoalId(space, a, validGoalIds) === resolvedSpaceId
    )
    if (targetRole) {
      const byRoleInSpace = inSpace.find((a) => extractRolePrefix(a.name) === targetRole)
      if (byRoleInSpace) {
        return { agentId: byRoleInSpace.id, spaceId: resolvedSpaceId }
      }
    }
    const waitingInSpace = inSpace.find((a) => a.attention) ?? inSpace[0]
    if (waitingInSpace) {
      return { agentId: waitingInSpace.id, spaceId: resolvedSpaceId }
    }
  }

  if (targetRole) {
    const byRoleAny = agents.find((a) => extractRolePrefix(a.name) === targetRole)
    if (byRoleAny) {
      return {
        agentId: byRoleAny.id,
        spaceId: resolvedSpaceId ?? resolveAgentGoalId(space, byRoleAny, validGoalIds)
      }
    }
  }

  return { agentId: null, spaceId: resolvedSpaceId }
}

export function readSpaceLocal(): SpaceState {
  try {
    if (typeof localStorage === 'undefined') {
      return EMPTY_SPACE
    }
    const raw = localStorage.getItem(SPACE_LOCAL_STORAGE_KEY)
    return raw ? normalizeSpaceState(JSON.parse(raw)) : EMPTY_SPACE
  } catch {
    // ok: localStorage unavailable or corrupted JSON safely falls back to EMPTY_SPACE
    return EMPTY_SPACE
  }
}

export function writeSpaceLocal(state: SpaceState): void {
  try {
    if (typeof localStorage === 'undefined') {
      return
    }
    localStorage.setItem(SPACE_LOCAL_STORAGE_KEY, JSON.stringify(state))
  } catch {
    // ok: ignore storage quota errors on local fallback
    return
  }
}

export const SPACE_PANEL_ATTR = 'data-space-panel'
export const SPACE_SCROLL_ATTR = 'data-space-scroll'

const PANEL_SELECTOR = [
  `[${SPACE_PANEL_ATTR}]`,
  '[data-space-scroll-lock]',
  '[data-orca-plus-scroll-lock]',
  '[data-space-dock]',
  '[data-space-drawer]',
  '[data-space-spawn-popover]',
  '[data-whiteboard-inspector]',
  '[data-whiteboard-multiselect]',
  '[data-whiteboard-history]',
  '[data-agent-ui-panel]',
  '[data-space-palette]'
].join(', ')

const TEXT_ENTRY_SELECTOR =
  'input, textarea, select, [contenteditable=""], [contenteditable="true"]'
const SCROLLABLE_OVERFLOW = /(auto|scroll|overlay)/
const LINE_PX = 16

export type WheelDecision = 'ignore' | 'block' | 'pan' | 'zoom'

export type WheelLike = {
  target: EventTarget | null
  deltaX: number
  deltaY: number
  deltaMode?: number
  ctrlKey?: boolean
  metaKey?: boolean
}

export type WheelContext = {
  root: Element
  overflowOf?: (el: Element) => { x: string; y: string }
}

type ScrollBox = Element & {
  scrollTop: number
  scrollLeft: number
  scrollHeight: number
  scrollWidth: number
  clientHeight: number
  clientWidth: number
}

function defaultOverflow(el: Element): { x: string; y: string } {
  const style = window.getComputedStyle(el)
  return { x: style.overflowX, y: style.overflowY }
}

function canScrollToward(
  el: ScrollBox,
  dx: number,
  dy: number,
  overflow: { x: string; y: string }
): boolean {
  if (dy !== 0 && SCROLLABLE_OVERFLOW.test(overflow.y) && el.scrollHeight > el.clientHeight) {
    const max = el.scrollHeight - el.clientHeight
    if ((dy > 0 && el.scrollTop < max - 0.5) || (dy < 0 && el.scrollTop > 0.5)) {
      return true
    }
  }
  if (dx !== 0 && SCROLLABLE_OVERFLOW.test(overflow.x) && el.scrollWidth > el.clientWidth) {
    const max = el.scrollWidth - el.clientWidth
    if ((dx > 0 && el.scrollLeft < max - 0.5) || (dx < 0 && el.scrollLeft > 0.5)) {
      return true
    }
  }
  return false
}

function isElement(value: unknown): value is Element {
  return (
    typeof value === 'object' &&
    value !== null &&
    typeof (value as Element).matches === 'function' &&
    'parentElement' in value
  )
}

export function decideWheel(event: WheelLike, ctx: WheelContext): WheelDecision {
  const zoom = Boolean(event.ctrlKey || event.metaKey)
  const target = event.target
  if (!isElement(target) || target === ctx.root || !ctx.root.contains(target)) {
    return zoom ? 'zoom' : 'pan'
  }
  const overflowOf = ctx.overflowOf ?? defaultOverflow
  const { dx, dy } = normalizeWheel(event)
  for (let el: Element | null = target; el && el !== ctx.root; el = el.parentElement) {
    if (el.matches(PANEL_SELECTOR)) {
      return zoom ? 'block' : 'ignore'
    }
    if (zoom) {
      continue
    }
    if (el.matches(TEXT_ENTRY_SELECTOR)) {
      return 'ignore'
    }
    const overflow = el.hasAttribute(SPACE_SCROLL_ATTR) ? { x: 'auto', y: 'auto' } : overflowOf(el)
    if (canScrollToward(el as ScrollBox, dx, dy, overflow)) {
      return 'ignore'
    }
  }
  return zoom ? 'zoom' : 'pan'
}

function finite(value: unknown): number {
  return typeof value === 'number' && Number.isFinite(value) ? value : 0
}

export function normalizeWheel(
  event: Pick<WheelLike, 'deltaX' | 'deltaY' | 'deltaMode'>,
  pageHeight = typeof window === 'undefined' ? 800 : window.innerHeight || 800
): { dx: number; dy: number } {
  const unit = event.deltaMode === 1 ? LINE_PX : event.deltaMode === 2 ? pageHeight : 1
  return { dx: finite(event.deltaX) * unit, dy: finite(event.deltaY) * unit }
}

export type WheelBatch = {
  dx: number
  dy: number
  factor: number
  focal: { x: number; y: number } | null
}

export type WheelBatcher = {
  pan: (dx: number, dy: number) => void
  zoom: (factor: number, focal: { x: number; y: number }) => void
  flush: () => void
  dispose: () => void
}

type FrameApi = {
  request: (cb: () => void) => number
  cancel: (id: number) => void
}

const defaultFrames: FrameApi = {
  request: (cb) => window.requestAnimationFrame(cb),
  cancel: (id) => window.cancelAnimationFrame(id)
}

export function createWheelBatcher(
  apply: (batch: WheelBatch) => void,
  frames: FrameApi = defaultFrames
): WheelBatcher {
  let pending: WheelBatch = { dx: 0, dy: 0, factor: 1, focal: null }
  let frame: number | null = null
  const flush = (): void => {
    frame = null
    const batch = pending
    pending = { dx: 0, dy: 0, factor: 1, focal: null }
    if (batch.dx === 0 && batch.dy === 0 && batch.factor === 1) {
      return
    }
    apply(batch)
  }
  const schedule = (): void => {
    if (frame === null) {
      frame = frames.request(flush)
    }
  }
  return {
    pan: (dx, dy) => {
      pending.dx += finite(dx)
      pending.dy += finite(dy)
      schedule()
    },
    zoom: (factor, focal) => {
      if (!Number.isFinite(factor) || factor <= 0) {
        return
      }
      pending.factor *= factor
      pending.focal = focal
      schedule()
    },
    flush: () => {
      if (frame !== null) {
        frames.cancel(frame)
      }
      flush()
    },
    dispose: () => {
      if (frame !== null) {
        frames.cancel(frame)
      }
      frame = null
      pending = { dx: 0, dy: 0, factor: 1, focal: null }
    }
  }
}

import type { View } from './space'

export const FIT_MIN_SCALE = 0.18
export const FIT_MAX_SCALE = 2
export const FIT_PADDING_PX = 40

export type FitBox = { x: number; y: number; w: number; h: number }

export function fitSelection(
  boxes: readonly FitBox[],
  width: number,
  height: number,
  opts: { padding?: number; minScale?: number; maxScale?: number } = {}
): View | null {
  if (boxes.length === 0 || !(width > 0) || !(height > 0)) {
    return null
  }
  const pad = opts.padding ?? FIT_PADDING_PX
  const min = opts.minScale ?? FIT_MIN_SCALE
  const max = opts.maxScale ?? FIT_MAX_SCALE
  let x1 = Infinity
  let y1 = Infinity
  let x2 = -Infinity
  let y2 = -Infinity
  for (const b of boxes) {
    x1 = Math.min(x1, b.x, b.x + b.w)
    y1 = Math.min(y1, b.y, b.y + b.h)
    x2 = Math.max(x2, b.x, b.x + b.w)
    y2 = Math.max(y2, b.y, b.y + b.h)
  }
  const w = x2 - x1
  const h = y2 - y1
  const availW = Math.max(1, width - pad * 2)
  const availH = Math.max(1, height - pad * 2)
  const fit = Math.min(w > 0 ? availW / w : Infinity, h > 0 ? availH / h : Infinity)
  const scale = Math.max(min, Math.min(max, fit))
  return {
    scale,
    x: width / 2 - (x1 + w / 2) * scale,
    y: height / 2 - (y1 + h / 2) * scale
  }
}

export const READABLE_FIT_MIN_SCALE = 0.55
export const FIT_ALL_MIN_SCALE = 0.4
export type FitInsets = { top: number; right: number; bottom: number; left: number }
export type FitTile = FitBox & { hasMembers: boolean }
export type FitResult = View & { partial: boolean }

function unionOf(boxes: readonly FitBox[]): FitBox {
  const x1 = Math.min(...boxes.map((b) => b.x))
  const y1 = Math.min(...boxes.map((b) => b.y))
  const x2 = Math.max(...boxes.map((b) => b.x + b.w))
  const y2 = Math.max(...boxes.map((b) => b.y + b.h))
  return { x: x1, y: y1, w: x2 - x1, h: y2 - y1 }
}

export function fitFreeArea(
  tiles: readonly FitTile[],
  width: number,
  height: number,
  insets: FitInsets,
  opts: { padding?: number } = {}
): FitResult | null {
  const freeW = width - insets.left - insets.right
  const freeH = height - insets.top - insets.bottom
  if (tiles.length === 0 || !(freeW > 0) || !(freeH > 0)) {
    return null
  }
  const pad = opts.padding ?? 24
  const scaleFor = (box: FitBox): number =>
    Math.min(
      box.w > 0 ? (freeW - pad * 2) / box.w : Infinity,
      box.h > 0 ? (freeH - pad * 2) / box.h : Infinity
    )
  let box = unionOf(tiles)
  let scale = scaleFor(box)
  let partial = false
  if (scale >= FIT_ALL_MIN_SCALE) {
    scale = Math.min(1.15, scale)
  } else {
    const withMembers = tiles.filter((t) => t.hasMembers)
    box = unionOf(withMembers.length > 0 ? withMembers : tiles)
    scale = Math.max(READABLE_FIT_MIN_SCALE, Math.min(1, scaleFor(box)))
    partial = withMembers.length < tiles.length
  }
  const place = (start: number, size: number, free: number, inset: number): number =>
    size * scale > free - pad * 2
      ? inset + pad - start * scale
      : inset + free / 2 - (start + size / 2) * scale
  return {
    scale,
    x: Math.round(place(box.x, box.w, freeW, insets.left)),
    y: Math.round(place(box.y, box.h, freeH, insets.top)),
    partial
  }
}

export type OffscreenSide = 'left' | 'right' | 'top' | 'bottom'
export type OffscreenGroup = {
  side: OffscreenSide
  count: number
  target: { x: number; y: number }
}

export function offscreenGroups(
  boxes: readonly FitBox[],
  view: View,
  width: number,
  height: number
): OffscreenGroup[] {
  const groups = new Map<OffscreenSide, { count: number; best: FitBox; dist: number }>()
  for (const b of boxes) {
    const x1 = b.x * view.scale + view.x
    const y1 = b.y * view.scale + view.y
    const x2 = x1 + b.w * view.scale
    const y2 = y1 + b.h * view.scale
    const out: [OffscreenSide, number][] = [
      ['left', -x2],
      ['right', x1 - width],
      ['top', -y2],
      ['bottom', y1 - height]
    ]
    const [side, dist] = out.reduce((m, o) => (o[1] > m[1] ? o : m))
    if (dist <= 0) {
      continue
    }
    const cur = groups.get(side)
    if (!cur) {
      groups.set(side, { count: 1, best: b, dist })
    } else {
      cur.count += 1
      if (dist < cur.dist) {
        cur.best = b
        cur.dist = dist
      }
    }
  }
  return [...groups].map(([side, g]) => ({
    side,
    count: g.count,
    target: { x: g.best.x + g.best.w / 2, y: g.best.y + g.best.h / 2 }
  }))
}

import {
  STICKY_COLORS,
  WHITEBOARD_ARROW_ROUTINGS,
  WHITEBOARD_BORDER_STYLES,
  WHITEBOARD_FILL_STYLES,
  WHITEBOARD_FONT_FAMILIES,
  WHITEBOARD_FONT_WEIGHTS,
  WHITEBOARD_SHAPES,
  WHITEBOARD_TEXT_ALIGNS,
  type Point,
  type SpaceArrow,
  type SpaceStickyNote
} from './space'
import { remapCopiedGroups } from './whiteboard-groups'

export const WHITEBOARD_CLIP_MIME = 'application/x-xlabs-space-whiteboard+json'
export const WHITEBOARD_CLIP_WEB_MIME = `web ${WHITEBOARD_CLIP_MIME}`
export const CLIP_MAX_NOTE_CHARS = 10_000
export const CLIP_MAX_BYTES = 1024 * 1024
const AGENT_KEYS = ['goals', 'asks', 'placements', 'removedAskIds', 'agents'] as const

export type ClipSticky = Omit<
  SpaceStickyNote,
  'id' | 'createdAt' | 'hidden' | 'locked' | 'groupId'
> & { key: string; group?: string }

export type ClipArrow = Omit<SpaceArrow, 'id' | 'createdAt' | 'fromId' | 'toId' | 'hidden'> & {
  from?: string
  to?: string
}

export type WhiteboardClipPayload = { v: 1; stickies: ClipSticky[]; arrows: ClipArrow[] }

export type ClipRefusal = 'empty' | 'note-too-long' | 'too-big' | 'agent-data' | 'not-ours'
export type ClipBuild =
  | { ok: true; payload: WhiteboardClipPayload; json: string; text: string }
  | { ok: false; reason: ClipRefusal }

const REFUSAL_TEXT: Record<ClipRefusal, string> = {
  'note-too-long': `Refused: a note is longer than ${CLIP_MAX_NOTE_CHARS.toLocaleString('en-US')} characters.`,
  'too-big': 'Refused: the whiteboard copy is over 1 MB.',
  'agent-data': 'Not pasted: the clipboard holds Space or agent data.',
  'not-ours': 'Nothing to paste.',
  empty: 'Nothing to copy: select notes, shapes or text.'
}
export const clipRefusalMessage = (reason: ClipRefusal): string => REFUSAL_TEXT[reason]

export function byteLength(text: string): number {
  return new TextEncoder().encode(text).length
}

const oneOf = <T extends string>(list: readonly T[], v: unknown): T | undefined =>
  list.includes(v as T) ? (v as T) : undefined
const num = (v: unknown): number | undefined =>
  typeof v === 'number' && Number.isFinite(v) ? v : undefined
const str = (v: unknown, max = 200): string | undefined =>
  typeof v === 'string' ? v.slice(0, max) : undefined
const point = (v: unknown): Point | undefined => {
  const o = v as { x?: unknown; y?: unknown } | null
  const x = num(o?.x)
  const y = num(o?.y)
  return x !== undefined && y !== undefined ? { x, y } : undefined
}
const defined = <T extends object>(o: T): T =>
  Object.fromEntries(Object.entries(o).filter(([, v]) => v !== undefined)) as T

function clipSticky(src: Record<string, unknown>, key: string): ClipSticky {
  const opacity = num(src.opacity)
  return defined({
    key,
    group: str(src.group ?? src.groupId, 80),
    text: typeof src.text === 'string' ? src.text : '',
    color: oneOf(STICKY_COLORS, src.color) ?? 'amber',
    kind: oneOf(['note', 'text', 'shape'] as const, src.kind),
    shapeType: oneOf(WHITEBOARD_SHAPES, src.shapeType),
    fillStyle: oneOf(WHITEBOARD_FILL_STYLES, src.fillStyle),
    borderStyle: oneOf(WHITEBOARD_BORDER_STYLES, src.borderStyle),
    textAlign: oneOf(WHITEBOARD_TEXT_ALIGNS, src.textAlign),
    fontFamily: oneOf(WHITEBOARD_FONT_FAMILIES, src.fontFamily),
    fontWeight: oneOf(WHITEBOARD_FONT_WEIGHTS, src.fontWeight),
    fontSize: num(src.fontSize),
    autosize: typeof src.autosize === 'boolean' ? src.autosize : undefined,
    zIndex: num(src.zIndex),
    name: str(src.name),
    opacity: opacity === undefined ? undefined : Math.max(0, Math.min(1, opacity)),
    x: num(src.x) ?? 0,
    y: num(src.y) ?? 0,
    w: Math.max(1, num(src.w) ?? 160),
    h: Math.max(1, num(src.h) ?? 100)
  })
}

function clipArrow(src: Record<string, unknown>, from?: string, to?: string): ClipArrow {
  return defined({
    from,
    to,
    fromPoint: from ? undefined : point(src.fromPoint),
    toPoint: to ? undefined : point(src.toPoint),
    label: str(src.label, 500),
    color: oneOf(STICKY_COLORS, src.color),
    bend: num(src.bend),
    dash: oneOf(['solid', 'dashed'] as const, src.dash),
    routing: oneOf(WHITEBOARD_ARROW_ROUTINGS, src.routing),
    name: str(src.name)
  })
}

export function clipPlainText(stickies: readonly Pick<SpaceStickyNote, 'text'>[]): string {
  return stickies
    .map((s) => s.text.replace(/\s*\n\s*/g, ' ').trim())
    .filter(Boolean)
    .join('\n')
}

export function buildClipboardPayload(
  stickies: readonly SpaceStickyNote[],
  arrows: readonly SpaceArrow[],
  ids: readonly string[],
  goalIds: ReadonlySet<string> = new Set()
): ClipBuild {
  const byId = new Map(stickies.map((s) => [s.id, s]))
  const picked: SpaceStickyNote[] = []
  const seen = new Set<string>()
  for (const id of ids) {
    const s = byId.get(id)
    if (!s || s.hidden || goalIds.has(id) || seen.has(id)) {
      continue
    }
    seen.add(id)
    picked.push(s)
  }
  if (picked.length === 0) {
    return { ok: false, reason: 'empty' }
  }
  if (picked.some((s) => s.text.length > CLIP_MAX_NOTE_CHARS)) {
    return { ok: false, reason: 'note-too-long' }
  }
  const keyOf = new Map(picked.map((s, i) => [s.id, `n${i}`]))
  const groupKey = new Map<string, string>()
  const clipStickies = picked.map((s) => {
    const group = s.groupId
      ? (groupKey.get(s.groupId) ?? groupKey.set(s.groupId, `g${groupKey.size}`).get(s.groupId))
      : undefined
    return clipSticky(
      { ...(s as unknown as Record<string, unknown>), groupId: undefined, group },
      keyOf.get(s.id) ?? ''
    )
  })
  const clipArrows: ClipArrow[] = []
  for (const a of arrows) {
    if (a.hidden || !(a.fromId || a.toId)) {
      continue
    }
    const ends = [a.fromId, a.toId].filter((e): e is string => Boolean(e))
    if (ends.some((e) => goalIds.has(e) || !keyOf.has(e))) {
      continue
    }
    clipArrows.push(
      clipArrow(
        a as unknown as Record<string, unknown>,
        a.fromId ? keyOf.get(a.fromId) : undefined,
        a.toId ? keyOf.get(a.toId) : undefined
      )
    )
  }
  const payload: WhiteboardClipPayload = { v: 1, stickies: clipStickies, arrows: clipArrows }
  const json = JSON.stringify(payload)
  if (byteLength(json) > CLIP_MAX_BYTES) {
    return { ok: false, reason: 'too-big' }
  }
  return { ok: true, payload, json, text: clipPlainText(picked) }
}

export type ClipParse =
  { ok: true; payload: WhiteboardClipPayload } | { ok: false; reason: ClipRefusal }

export function parseClipboardPayload(json: string | null | undefined): ClipParse {
  if (!json) {
    return { ok: false, reason: 'not-ours' }
  }
  if (byteLength(json) > CLIP_MAX_BYTES) {
    return { ok: false, reason: 'too-big' }
  }
  let raw: unknown
  try {
    raw = JSON.parse(json)
  } catch {
    // ok: non-JSON clipboard text is rejected cleanly as 'not-ours'
    return { ok: false, reason: 'not-ours' }
  }
  const obj = raw as Record<string, unknown> | null
  if (!obj || typeof obj !== 'object' || obj.v !== 1 || !Array.isArray(obj.stickies)) {
    return { ok: false, reason: 'not-ours' }
  }
  if (AGENT_KEYS.some((k) => k in obj)) {
    return { ok: false, reason: 'agent-data' }
  }
  const stickies: ClipSticky[] = []
  const keys = new Set<string>()
  for (const item of obj.stickies as unknown[]) {
    const s = item as Record<string, unknown> | null
    if (!s || typeof s !== 'object') {
      continue
    }
    if (AGENT_KEYS.some((k) => k in s) || 'botId' in s || 'goalId' in s) {
      return { ok: false, reason: 'agent-data' }
    }
    if (typeof s.text === 'string' && s.text.length > CLIP_MAX_NOTE_CHARS) {
      return { ok: false, reason: 'note-too-long' }
    }
    const key = typeof s.key === 'string' && !keys.has(s.key) ? s.key : `n${stickies.length}`
    keys.add(key)
    stickies.push(clipSticky(s, key))
  }
  if (stickies.length === 0) {
    return { ok: false, reason: 'empty' }
  }
  const arrows: ClipArrow[] = []
  for (const item of Array.isArray(obj.arrows) ? (obj.arrows as unknown[]) : []) {
    const a = item as Record<string, unknown> | null
    if (!a || typeof a !== 'object') {
      continue
    }
    const from = typeof a.from === 'string' ? a.from : undefined
    const to = typeof a.to === 'string' ? a.to : undefined
    if (
      (a.from !== undefined && !(from && keys.has(from))) ||
      (a.to !== undefined && !(to && keys.has(to)))
    ) {
      continue
    }
    if (!from && !to) {
      continue
    }
    arrows.push(clipArrow(a, from, to))
  }
  return { ok: true, payload: { v: 1, stickies, arrows } }
}

export function textToPayload(text: string): ClipParse {
  const t = text.replace(/\r\n?/g, '\n').trim()
  if (!t) {
    return { ok: false, reason: 'not-ours' }
  }
  if (t.length > CLIP_MAX_NOTE_CHARS) {
    return { ok: false, reason: 'note-too-long' }
  }
  const lines = t.split('\n')
  const w = Math.min(560, Math.max(160, Math.max(...lines.map((l) => l.length)) * 8 + 32))
  const h = Math.min(600, Math.max(80, lines.length * 22 + 36))
  return {
    ok: true,
    payload: {
      v: 1,
      stickies: [{ key: 'n0', text: t, color: 'amber', kind: 'note', x: 0, y: 0, w, h }],
      arrows: []
    }
  }
}

export type ClipBatch = {
  stickies: (Omit<SpaceStickyNote, 'id' | 'createdAt'> & { id: string })[]
  arrows: Omit<SpaceArrow, 'id' | 'createdAt'>[]
}

export function planPaste(
  payload: WhiteboardClipPayload,
  opts: { at?: Point | null; offset?: Point; room: number; makeKey?: () => string }
): ClipBatch & { dropped: number } {
  let seq = 0
  const makeKey = opts.makeKey ?? (() => `clip-${Date.now().toString(36)}-${seq++}`)
  const room = Math.max(0, opts.room)
  const kept = payload.stickies.slice(0, room)
  const dropped = payload.stickies.length - kept.length
  const minX = kept.length > 0 ? Math.min(...kept.map((s) => s.x)) : 0
  const minY = kept.length > 0 ? Math.min(...kept.map((s) => s.y)) : 0
  const dx = kept.length === 0 ? 0 : opts.at ? opts.at.x - minX : (opts.offset?.x ?? 0)
  const dy = kept.length === 0 ? 0 : opts.at ? opts.at.y - minY : (opts.offset?.y ?? 0)
  const groupCount = new Map<string, number>()
  for (const s of kept) {
    if (s.group) {
      groupCount.set(s.group, (groupCount.get(s.group) ?? 0) + 1)
    }
  }
  const regrouped = remapCopiedGroups(
    kept.map((s) => ({
      groupId: s.group && (groupCount.get(s.group) ?? 0) >= 2 ? s.group : undefined
    }))
  )
  const keyMap = new Map<string, string>()
  const stickies = kept.map((s, i) => {
    const { key, group: _group, ...look } = s
    const id = makeKey()
    keyMap.set(key, id)
    const groupId = regrouped[i]?.groupId
    return { ...look, id, x: s.x + dx, y: s.y + dy, ...(groupId ? { groupId } : {}) }
  })
  const arrows: ClipBatch['arrows'] = []
  for (const a of payload.arrows) {
    const fromId = a.from ? keyMap.get(a.from) : undefined
    const toId = a.to ? keyMap.get(a.to) : undefined
    if ((a.from && !fromId) || (a.to && !toId)) {
      continue
    }
    const { from: _f, to: _t, ...rest } = a
    arrows.push(
      defined({
        ...rest,
        fromId,
        toId,
        fromPoint: a.fromPoint ? { x: a.fromPoint.x + dx, y: a.fromPoint.y + dy } : undefined,
        toPoint: a.toPoint ? { x: a.toPoint.x + dx, y: a.toPoint.y + dy } : undefined
      })
    )
  }
  return { stickies, arrows, dropped }
}

import { newSpaceId, type SpaceArrow, type SpaceStickyNote } from './space'

export type StickyPatches = Record<string, Partial<SpaceStickyNote>>
export type WhiteboardRefusal = 'empty' | 'goal' | 'unknown' | 'too-few'
export type PatchResult =
  | { ok: true; patches: StickyPatches; groupId?: string }
  | { ok: false; reason: WhiteboardRefusal; ids: string[] }

type IsGoal = (id: string) => boolean
const noGoal: IsGoal = () => false

export function groupIndex(stickies: readonly SpaceStickyNote[]): Map<string, string[]> {
  const all = new Map<string, string[]>()
  for (const s of stickies) {
    if (s.groupId) {
      const list = all.get(s.groupId)
      if (list) {
        list.push(s.id)
      } else {
        all.set(s.groupId, [s.id])
      }
    }
  }
  for (const [gid, ids] of all) {
    if (ids.length < 2) {
      all.delete(gid)
    }
  }
  return all
}

export function groupSelectionFor(
  stickies: readonly SpaceStickyNote[],
  id: string,
  index: ReadonlyMap<string, readonly string[]> = groupIndex(stickies)
): string[] {
  const sticky = stickies.find((s) => s.id === id)
  const members = sticky?.groupId ? index.get(sticky.groupId) : undefined
  if (!members) {
    return [id]
  }
  const hidden = new Set(stickies.filter((s) => s.hidden).map((s) => s.id))
  const visible = members.filter((m) => !hidden.has(m))
  return visible.length > 0 ? visible : [id]
}

export function expandToGroups(
  stickies: readonly SpaceStickyNote[],
  ids: readonly string[]
): string[] {
  const index = groupIndex(stickies)
  const out: string[] = []
  const seen = new Set<string>()
  for (const id of ids) {
    for (const m of groupSelectionFor(stickies, id, index)) {
      if (!seen.has(m)) {
        seen.add(m)
        out.push(m)
      }
    }
  }
  return out
}

export function isWholeGroup(
  stickies: readonly SpaceStickyNote[],
  ids: readonly string[]
): boolean {
  if (ids.length < 2) {
    return false
  }
  const firstId = ids[0]
  const first = firstId ? stickies.find((s) => s.id === firstId) : undefined
  if (!first?.groupId) {
    return false
  }
  const members = groupSelectionFor(stickies, first.id)
  return members.length === ids.length && members.every((m) => ids.includes(m))
}

function checkIds(
  stickies: readonly SpaceStickyNote[],
  ids: readonly string[],
  isGoal: IsGoal
): { ok: true; ids: string[] } | { ok: false; reason: WhiteboardRefusal; ids: string[] } {
  const unique = [...new Set(ids)]
  if (unique.length === 0) {
    return { ok: false, reason: 'empty', ids: [] }
  }
  const known = new Set(stickies.map((s) => s.id))
  const goals = unique.filter((id) => isGoal(id))
  if (goals.length > 0) {
    return { ok: false, reason: 'goal', ids: goals }
  }
  const unknown = unique.filter((id) => !known.has(id))
  if (unknown.length > 0) {
    return { ok: false, reason: 'unknown', ids: unknown }
  }
  return { ok: true, ids: unique }
}

function orphanPatches(
  stickies: readonly SpaceStickyNote[],
  leaving: ReadonlySet<string>
): StickyPatches {
  const patches: StickyPatches = {}
  for (const members of groupIndex(stickies).values()) {
    const left = members.filter((m) => !leaving.has(m))
    const leftId = left[0]
    if (left.length === 1 && leftId && left.length < members.length) {
      patches[leftId] = { groupId: undefined }
    }
  }
  return patches
}

export function groupStickies(
  stickies: readonly SpaceStickyNote[],
  ids: readonly string[],
  isGoal: IsGoal = noGoal,
  makeId: () => string = () => newSpaceId('group')
): PatchResult {
  const check = checkIds(stickies, ids, isGoal)
  if (!check.ok) {
    return check
  }
  if (check.ids.length < 2) {
    return { ok: false, reason: 'too-few', ids: check.ids }
  }
  const groupId = makeId()
  const patches = orphanPatches(stickies, new Set(check.ids))
  for (const id of check.ids) {
    patches[id] = { groupId }
  }
  return { ok: true, patches, groupId }
}

export function ungroupStickies(
  stickies: readonly SpaceStickyNote[],
  ids: readonly string[],
  isGoal: IsGoal = noGoal
): PatchResult {
  const check = checkIds(stickies, ids, isGoal)
  if (!check.ok) {
    return check
  }
  const picked = new Set(check.ids)
  const groups = new Set(
    stickies.filter((s) => picked.has(s.id) && s.groupId).map((s) => s.groupId as string)
  )
  const patches: StickyPatches = {}
  for (const s of stickies) {
    if (s.groupId && groups.has(s.groupId)) {
      patches[s.id] = { groupId: undefined }
    }
  }
  return { ok: true, patches }
}

export function toggleHiddenPatches(
  stickies: readonly SpaceStickyNote[],
  ids: readonly string[],
  isGoal: IsGoal = noGoal
): PatchResult {
  const check = checkIds(stickies, ids, isGoal)
  if (!check.ok) {
    return check
  }
  const byId = new Map(stickies.map((s) => [s.id, s]))
  const hide = check.ids.some((id) => !byId.get(id)?.hidden)
  const patches: StickyPatches = {}
  for (const id of check.ids) {
    patches[id] = { hidden: hide ? true : undefined }
  }
  return { ok: true, patches }
}

export function toggleLockPatches(
  stickies: readonly SpaceStickyNote[],
  ids: readonly string[],
  isGoal: IsGoal = noGoal
): PatchResult {
  const check = checkIds(stickies, ids, isGoal)
  if (!check.ok) {
    return check
  }
  const byId = new Map(stickies.map((s) => [s.id, s]))
  const lock = check.ids.some((id) => !byId.get(id)?.locked)
  const patches: StickyPatches = {}
  for (const id of check.ids) {
    patches[id] = { locked: lock }
  }
  return { ok: true, patches }
}

export function paintOrder(stickies: readonly SpaceStickyNote[]): SpaceStickyNote[] {
  return [...stickies].sort(
    (a, b) => (a.zIndex ?? 0) - (b.zIndex ?? 0) || a.createdAt - b.createdAt
  )
}

export function reorderPatches(
  stickies: readonly SpaceStickyNote[],
  moving: readonly string[],
  targetId: string,
  place: 'above' | 'below',
  isGoal: IsGoal = noGoal
): PatchResult {
  const check = checkIds(stickies, [...moving, targetId], isGoal)
  if (!check.ok) {
    return check
  }
  const movingSet = new Set(moving)
  if (movingSet.has(targetId)) {
    return { ok: true, patches: {} }
  }
  const order = paintOrder(stickies)
  const rest = order.filter((s) => !movingSet.has(s.id))
  const block = order.filter((s) => movingSet.has(s.id))
  const at = rest.findIndex((s) => s.id === targetId)
  const insertAt = place === 'above' ? at + 1 : at
  const next = [...rest.slice(0, insertAt), ...block, ...rest.slice(insertAt)]
  const patches: StickyPatches = {}
  next.forEach((s, i) => {
    if (s.zIndex !== i) {
      patches[s.id] = { zIndex: i }
    }
  })
  return { ok: true, patches }
}

export function hiddenIds(
  stickies: readonly Pick<SpaceStickyNote, 'id' | 'hidden'>[],
  extraHidden: readonly { id: string; hidden?: boolean }[] = []
): Set<string> {
  const set = new Set<string>()
  for (const s of stickies) {
    if (s.hidden) {
      set.add(s.id)
    }
  }
  for (const item of extraHidden) {
    if (item.hidden) {
      set.add(item.id)
    }
  }
  return set
}

export function isArrowHidden(arrow: SpaceArrow, hidden: ReadonlySet<string>): boolean {
  return (
    arrow.hidden === true ||
    (arrow.fromId !== undefined && hidden.has(arrow.fromId)) ||
    (arrow.toId !== undefined && hidden.has(arrow.toId))
  )
}

export function stickyLayerLabel(sticky: SpaceStickyNote): string {
  if (sticky.name) {
    return sticky.name
  }
  const line = sticky.text.trim().split('\n')[0]?.trim()
  if (line) {
    return line.length > 48 ? `${line.slice(0, 47)}…` : line
  }
  return sticky.kind === 'shape' ? 'Shape' : sticky.kind === 'text' ? 'Text' : 'Note'
}

export function remapCopiedGroups<T extends Pick<SpaceStickyNote, 'groupId'>>(
  copies: readonly T[],
  makeId: () => string = () => newSpaceId('group')
): T[] {
  const map = new Map<string, string>()
  return copies.map((c) => {
    if (!c.groupId) {
      return c
    }
    let next = map.get(c.groupId)
    if (!next) {
      next = makeId()
      map.set(c.groupId, next)
    }
    return { ...c, groupId: next }
  })
}

