export type WhiteboardShapeType = (typeof WHITEBOARD_SHAPES)[number]

export const WHITEBOARD_FILL_STYLES = [
  'none',
  'soft',
  'solid',
  'glass',
  'paper',
  'paper-light'
] as const
export type WhiteboardFillStyle = (typeof WHITEBOARD_FILL_STYLES)[number]

