}

export function resolveWhiteboardSurfaceStyle(options: {
  kind?: 'note' | 'text' | 'shape'
  color?: StickyColor
  fillStyle?: WhiteboardFillStyle
  borderStyle?: WhiteboardBorderStyle
}): WhiteboardSurfaceStyle {
  const kind = options.kind === 'text' || options.kind === 'shape' ? options.kind : 'note'
  const color = options.color && STICKY_COLORS.includes(options.color) ? options.color : 'amber'
  const fillStyle: WhiteboardFillStyle =
    options.fillStyle && WHITEBOARD_FILL_STYLES.includes(options.fillStyle)
      ? options.fillStyle
      : kind === 'text'
        ? 'none'
        : 'soft'
  const borderStyle: WhiteboardBorderStyle =
    options.borderStyle && WHITEBOARD_BORDER_STYLES.includes(options.borderStyle)
      ? options.borderStyle
      : kind === 'text' && fillStyle === 'none'
        ? 'none'
        : 'solid'
  const [rgb, accentHex, softText, noneText, solidBg, solidBorder, solidText, solidLight] =
    SURFACE_PALETTE[color]
  const hasBorder = borderStyle !== 'none'
  switch (fillStyle) {
    case 'paper':
      return {
        fillStyle,
        borderStyle,
        backgroundColor: 'rgba(16, 17, 21, 0.94)',
        borderColor: hasBorder ? 'rgba(255, 255, 255, 0.16)' : 'transparent',
        textColor: '#f4f4f5',
        placeholderColor: 'rgba(244, 244, 245, 0.45)',
        accentHex,
        backdropBlur: true,
        isLight: false
      }
    case 'paper-light':
      return {
        fillStyle,
        borderStyle,
        backgroundColor: '#faf9f6',
        borderColor: hasBorder ? '#d6d3cb' : 'transparent',
        textColor: '#141413',
        placeholderColor: 'rgba(20, 20, 19, 0.45)',
        accentHex,
        backdropBlur: false,
        isLight: true
      }
    case 'solid':
      return {
        fillStyle,
        borderStyle,
        backgroundColor: solidBg,
        borderColor: hasBorder ? solidBorder : 'transparent',
        textColor: solidText,
        placeholderColor: solidLight ? 'rgba(24, 24, 27, 0.5)' : 'rgba(255, 255, 255, 0.55)',
        accentHex,
        backdropBlur: false,
        isLight: solidLight
      }
    case 'glass':
      return {
        fillStyle,
        borderStyle,
        backgroundColor: 'rgba(24, 24, 27, 0.86)',
        borderColor: hasBorder ? `rgba(${rgb}, 0.42)` : 'transparent',
        textColor: softText,
        placeholderColor: 'rgba(244, 244, 245, 0.45)',
        accentHex,
        backdropBlur: true,
        isLight: false
      }
    case 'none':
      return {
        fillStyle,
        borderStyle,
        backgroundColor: 'transparent',
        borderColor: hasBorder ? `rgba(${rgb}, 0.65)` : 'transparent',
        textColor: noneText,
        placeholderColor: 'rgba(244, 244, 245, 0.42)',
        accentHex,
        backdropBlur: false,
        isLight: false
      }
    case 'soft':
      return {
        fillStyle,
        borderStyle,
        backgroundColor: `rgba(${rgb}, 0.18)`,
        borderColor: hasBorder ? `rgba(${rgb}, 0.55)` : 'transparent',
        textColor: softText,
        placeholderColor: 'rgba(244, 244, 245, 0.45)',
        accentHex,
        backdropBlur: true,
        isLight: false
      }
  }
}

export const CARDINAL_PORTS: readonly {
  side: CardinalSide
  rx: number
  ry: number
  nx: number
  ny: number
}[] = [
  { side: 'top', rx: 0.5, ry: 0, nx: 0, ny: -1 },
  { side: 'right', rx: 1, ry: 0.5, nx: 1, ny: 0 },
  { side: 'bottom', rx: 0.5, ry: 1, nx: 0, ny: 1 },
  { side: 'left', rx: 0, ry: 0.5, nx: -1, ny: 0 }
]

export function clampNum(val: number, min: number, max: number): number {
  return val < min ? min : val > max ? max : val
}

export function snapAxisDelta(dx: number, dy: number): { dx: number; dy: number } {
  return Math.abs(dx) >= Math.abs(dy) ? { dx, dy: 0 } : { dx: 0, dy }
}

export function snapPointAngle15Deg(
  origin: WhiteboardPoint,
  target: WhiteboardPoint
): WhiteboardPoint {
  const dx = target.x - origin.x
  const dy = target.y - origin.y
  const step = Math.PI / 12
  const angle = Math.round(Math.atan2(dy, dx) / step) * step
  const len = Math.hypot(dx, dy)
  return {
    x: Math.round(origin.x + Math.cos(angle) * len),
    y: Math.round(origin.y + Math.sin(angle) * len)
  }
}

export function getCardinalPortPoints(
  box: WhiteboardRect
): { side: CardinalSide; x: number; y: number; nx: number; ny: number }[] {
  return CARDINAL_PORTS.map((p) => ({
    side: p.side,
    x: Math.round(box.x + box.w * p.rx),
    y: Math.round(box.y + box.h * p.ry),
    nx: p.nx,
    ny: p.ny
  }))
}

export function resolveSmartBoxAnchor(
  box: WhiteboardRect,
  toward: WhiteboardPoint
): { point: WhiteboardPoint; nx: number; ny: number; side: CardinalSide } {
  const cx = box.x + box.w / 2
  const cy = box.y + box.h / 2
  const dx = toward.x - cx
  const dy = toward.y - cy
  if (Math.abs(dx) < 1 && Math.abs(dy) < 1) {
    return { point: { x: Math.round(cx), y: Math.round(box.y) }, nx: 0, ny: -1, side: 'top' }
  }
  const hw = Math.max(1, box.w / 2)
  const hh = Math.max(1, box.h / 2)
  const scaleX = Math.abs(dx) > 0.001 ? hw / Math.abs(dx) : Number.POSITIVE_INFINITY
  const scaleY = Math.abs(dy) > 0.001 ? hh / Math.abs(dy) : Number.POSITIVE_INFINITY
  if (scaleX <= scaleY) {
    const right = dx >= 0
    return {
      point: {
        x: Math.round(cx + (right ? hw : -hw)),
        y: Math.round(clampNum(cy + dy * scaleX, box.y + 10, box.y + box.h - 10))
      },
      nx: right ? 1 : -1,
      ny: 0,
      side: right ? 'right' : 'left'
    }
  }
  const bottom = dy >= 0
  return {
    point: {
      x: Math.round(clampNum(cx + dx * scaleY, box.x + 10, box.x + box.w - 10)),
      y: Math.round(cy + (bottom ? hh : -hh))
    },
    nx: 0,
    ny: bottom ? 1 : -1,
    side: bottom ? 'bottom' : 'top'
  }
}

export function computeSignedBendFromPoint(
  start: WhiteboardPoint,
  end: WhiteboardPoint,
  pointer: WhiteboardPoint,
  snapZeroThreshold = 7
): number {
  const dx = end.x - start.x
  const dy = end.y - start.y
  const len = Math.hypot(dx, dy) || 1
  const nx = -dy / len
  const ny = dx / len
  const rawBend =
    (pointer.x - (start.x + end.x) / 2) * nx + (pointer.y - (start.y + end.y) / 2) * ny
  return Math.abs(rawBend) < snapZeroThreshold ? 0 : Math.round(clampNum(rawBend, -1200, 1200))
}

function buildElbowPath(
  start: WhiteboardPoint,
  end: WhiteboardPoint,
  n0: { nx: number; ny: number },
  n1: { nx: number; ny: number },
  bend: number
): { mid: WhiteboardPoint; path: string } {
  const esc = 24
  let raw: WhiteboardPoint[]
  if (n0.ny === 0 && n1.ny === 0) {
    if (n0.nx === n1.nx) {
      const ox = n0.nx > 0 ? Math.max(start.x, end.x) + esc : Math.min(start.x, end.x) - esc
      raw = [start, { x: ox, y: start.y }, { x: ox, y: end.y }, end]
    } else if ((end.x - start.x) * n0.nx >= 0) {
      const span = Math.abs(end.x - start.x)
      const mx =
        span > 32 && Math.abs(bend) >= 1
          ? clampNum(
              Math.round((start.x + end.x) / 2 + bend),
              Math.min(start.x, end.x) + 16,
              Math.max(start.x, end.x) - 16
            )
          : Math.round((start.x + end.x) / 2)
      raw =
        start.y === end.y ? [start, end] : [start, { x: mx, y: start.y }, { x: mx, y: end.y }, end]
    } else {
      const sx0 = start.x + n0.nx * esc
      const sx1 = end.x + n1.nx * esc
      const my = Math.round((start.y + end.y) / 2 + bend)
      raw = [
        start,
        { x: sx0, y: start.y },
        { x: sx0, y: my },
        { x: sx1, y: my },
        { x: sx1, y: end.y },
        end
      ]
    }
  } else if (n0.nx === 0 && n1.nx === 0) {
    if (n0.ny === n1.ny) {
      const oy = n0.ny > 0 ? Math.max(start.y, end.y) + esc : Math.min(start.y, end.y) - esc
      raw = [start, { x: start.x, y: oy }, { x: end.x, y: oy }, end]
    } else if ((end.y - start.y) * n0.ny >= 0) {
      const span = Math.abs(end.y - start.y)
      const my =
        span > 32 && Math.abs(bend) >= 1
          ? clampNum(
              Math.round((start.y + end.y) / 2 + bend),
              Math.min(start.y, end.y) + 16,
              Math.max(start.y, end.y) - 16
            )
          : Math.round((start.y + end.y) / 2)
      raw =
        start.x === end.x ? [start, end] : [start, { x: start.x, y: my }, { x: end.x, y: my }, end]
    } else {
      const sy0 = start.y + n0.ny * esc
      const sy1 = end.y + n1.ny * esc
      const mx = Math.round((start.x + end.x) / 2 + bend)
      raw = [
        start,
        { x: start.x, y: sy0 },
        { x: mx, y: sy0 },
        { x: mx, y: sy1 },
        { x: end.x, y: sy1 },
        end
      ]
    }
  } else if (n0.ny === 0) {
    if ((end.x - start.x) * n0.nx >= 0 && (start.y - end.y) * n1.ny >= 0) {
      raw = [start, { x: end.x, y: start.y }, end]
    } else {
      const sx =
        (end.x - start.x) * n0.nx >= esc ? Math.round((start.x + end.x) / 2) : start.x + n0.nx * esc
      const sy =
        (start.y - end.y) * n1.ny >= esc ? Math.round((start.y + end.y) / 2) : end.y + n1.ny * esc
      raw = [start, { x: sx, y: start.y }, { x: sx, y: sy }, { x: end.x, y: sy }, end]
    }
  } else if ((end.y - start.y) * n0.ny >= 0 && (start.x - end.x) * n1.nx >= 0) {
    raw = [start, { x: start.x, y: end.y }, end]
  } else {
    const sy =
      (end.y - start.y) * n0.ny >= esc ? Math.round((start.y + end.y) / 2) : start.y + n0.ny * esc
    const sx =
      (start.x - end.x) * n1.nx >= esc ? Math.round((start.x + end.x) / 2) : end.x + n1.nx * esc
    raw = [start, { x: start.x, y: sy }, { x: sx, y: sy }, { x: sx, y: end.y }, end]
  }

  const pts: WhiteboardPoint[] = []
  for (const pt of raw) {
    const prev = pts.at(-1)
    if (prev && prev.x === pt.x && prev.y === pt.y) {
      continue
    }
    const prev2 = pts.at(-2)
    if (
      prev &&
      prev2 &&
      ((prev2.x === prev.x && prev.x === pt.x && (pt.y - prev.y) * (prev.y - prev2.y) >= 0) ||
        (prev2.y === prev.y && prev.y === pt.y && (pt.x - prev.x) * (prev.x - prev2.x) >= 0))
    ) {
      pts[pts.length - 1] = pt
      continue
    }
    pts.push(pt)
  }
  if (pts.length < 2) {
    return { mid: start, path: `M ${start.x} ${start.y} L ${end.x} ${end.y}` }
  }
  const pFirst = pts[0]!
  const pSecond = pts[1]!
  const pThird = pts[2]
  const segIdx =
    pts.length === 3 && pThird
      ? Math.hypot(pSecond.x - pFirst.x, pSecond.y - pFirst.y) >=
        Math.hypot(pThird.x - pSecond.x, pThird.y - pSecond.y)
        ? 0
        : 1
      : Math.floor((pts.length - 1) / 2)
  const segA = pts[segIdx]!
  const segB = pts[segIdx + 1]!
  const mid = {
    x: Math.round((segA.x + segB.x) / 2),
    y: Math.round((segA.y + segB.y) / 2)
  }
  const parts = [`M ${pFirst.x} ${pFirst.y}`]
  for (let i = 1; i < pts.length - 1; i++) {
    const p0 = pts[i - 1]!
    const p1 = pts[i]!
    const p2 = pts[i + 1]!
    const l1 = Math.hypot(p1.x - p0.x, p1.y - p0.y)
    const l2 = Math.hypot(p2.x - p1.x, p2.y - p1.y)
    const r = Math.min(8, l1 / 2, l2 / 2)
    if (r < 1) {
      parts.push(`L ${p1.x} ${p1.y}`)
    } else {
      const ix = Math.round((p1.x - ((p1.x - p0.x) / l1) * r) * 10) / 10
      const iy = Math.round((p1.y - ((p1.y - p0.y) / l1) * r) * 10) / 10
      const ox = Math.round((p1.x + ((p2.x - p1.x) / l2) * r) * 10) / 10
      const oy = Math.round((p1.y + ((p2.y - p1.y) / l2) * r) * 10) / 10
      parts.push(`L ${ix} ${iy} Q ${p1.x} ${p1.y} ${ox} ${oy}`)
    }
  }
  const last = pts.at(-1)!
  parts.push(`L ${last.x} ${last.y}`)
  return { mid, path: parts.join(' ') }
}

export function resolveArrowPathAndHandles(
  arrow: {
    fromId?: string
    toId?: string
    fromPoint?: WhiteboardPoint
    toPoint?: WhiteboardPoint
    bend?: number
    routing?: WhiteboardArrowRouting
  },
  boxMap: ReadonlyMap<string, WhiteboardRect>,
  routingOverride?: WhiteboardArrowRouting
): {
  start: WhiteboardPoint
  end: WhiteboardPoint
  mid: WhiteboardPoint
  bendHandle: WhiteboardPoint
  path: string
} | null {
  const fromBox = arrow.fromId ? boxMap.get(arrow.fromId) : undefined
  const toBox = arrow.toId ? boxMap.get(arrow.toId) : undefined
  const fromCenter = fromBox
    ? { x: fromBox.x + fromBox.w / 2, y: fromBox.y + fromBox.h / 2 }
    : arrow.fromPoint
  const toCenter = toBox ? { x: toBox.x + toBox.w / 2, y: toBox.y + toBox.h / 2 } : arrow.toPoint
  if (!fromCenter || !toCenter) {
    return null
  }

  const startAnchor = fromBox ? resolveSmartBoxAnchor(fromBox, toCenter) : null
  const start = startAnchor ? startAnchor.point : fromCenter
  const endAnchor = toBox ? resolveSmartBoxAnchor(toBox, start) : null
  const end = endAnchor ? endAnchor.point : toCenter
  const refinedStartAnchor = fromBox ? resolveSmartBoxAnchor(fromBox, end) : null
  const finalStart = refinedStartAnchor ? refinedStartAnchor.point : start

  const dx = end.x - finalStart.x
  const dy = end.y - finalStart.y
  const dist = Math.hypot(dx, dy)
  const bend = typeof arrow.bend === 'number' && Number.isFinite(arrow.bend) ? arrow.bend : 0
  const routing: WhiteboardArrowRouting = routingOverride ?? arrow.routing ?? 'curve'
  const horizontal = Math.abs(dx) >= Math.abs(dy)

  if (routing === 'elbow') {
    const n0 = refinedStartAnchor ?? {
      nx: horizontal ? (dx >= 0 ? 1 : -1) : 0,
      ny: horizontal ? 0 : dy >= 0 ? 1 : -1
    }
    const n1 = endAnchor ?? {
      nx: horizontal ? (dx >= 0 ? -1 : 1) : 0,
      ny: horizontal ? 0 : dy >= 0 ? -1 : 1
    }
    const elbow = buildElbowPath(finalStart, end, n0, n1, bend)
    return { start: finalStart, end, mid: elbow.mid, bendHandle: elbow.mid, path: elbow.path }
  }

  if (Math.abs(bend) >= 1) {
    const len = dist || 1
    const cx = finalStart.x + dx / 2 + (-dy / len) * bend * 2
    const cy = finalStart.y + dy / 2 + (dx / len) * bend * 2
    const mid = {
      x: Math.round(0.25 * finalStart.x + 0.5 * cx + 0.25 * end.x),
      y: Math.round(0.25 * finalStart.y + 0.5 * cy + 0.25 * end.y)
    }
    return {
      start: finalStart,
      end,
      mid,
      bendHandle: mid,
      path: `M ${finalStart.x} ${finalStart.y} Q ${Math.round(cx)} ${Math.round(cy)} ${end.x} ${end.y}`
    }
  }

  if (routing === 'straight' || (!refinedStartAnchor && !endAnchor)) {
    const mid = {
      x: Math.round((finalStart.x + end.x) / 2),
      y: Math.round((finalStart.y + end.y) / 2)
    }
    return {
      start: finalStart,
      end,
      mid,
      bendHandle: mid,
      path: `M ${finalStart.x} ${finalStart.y} L ${end.x} ${end.y}`
    }
  }

  const pull = clampNum(dist * 0.42, 24, 180)
  const cx1 = refinedStartAnchor
    ? finalStart.x + refinedStartAnchor.nx * pull
    : horizontal
      ? finalStart.x + dx * 0.45
      : finalStart.x
  const cy1 = refinedStartAnchor
    ? finalStart.y + refinedStartAnchor.ny * pull
    : horizontal
      ? finalStart.y
      : finalStart.y + dy * 0.45
  const cx2 = endAnchor ? end.x + endAnchor.nx * pull : horizontal ? end.x - dx * 0.45 : end.x
  const cy2 = endAnchor ? end.y + endAnchor.ny * pull : horizontal ? end.y : end.y - dy * 0.45
  const mid = {
    x: Math.round((finalStart.x + 3 * cx1 + 3 * cx2 + end.x) / 8),
    y: Math.round((finalStart.y + 3 * cy1 + 3 * cy2 + end.y) / 8)
  }
  return {
    start: finalStart,
    end,
    mid,
    bendHandle: mid,
    path: `M ${finalStart.x} ${finalStart.y} C ${Math.round(cx1)} ${Math.round(cy1)}, ${Math.round(cx2)} ${Math.round(cy2)}, ${end.x} ${end.y}`
  }
}

function estimateTextLinePx(line: string, fontSize: number): number {
  let units = 0
  for (const ch of Array.from(line)) {
    const code = ch.codePointAt(0) ?? 0
    units += code > 0x1f000 ? 1.18 : ch === ' ' ? 0.34 : 0.6
  }
  return Math.ceil(units * fontSize)
}

export function computeShapeDimensions(
  text: string,
  fontSize: number,
  boxW: number,
  boxH: number,
  shapeType: WhiteboardShapeType = 'rounded'
): { w: number; h: number } {
  const w = clampNum(Math.round(boxW || 160), 64, 1600)
  const minH = clampNum(Math.round(boxH || 80), 44, 1600)
  if (!text) {
    return { w, h: minH }
  }
  const safeFont = clampNum(fontSize || 16, 12, 120)
  const lineHeight = safeFont * 1.32
  const usableW =
    shapeType === 'diamond'
      ? Math.max(32, Math.floor(w * 0.54) - 12)
      : shapeType === 'ellipse'
        ? Math.max(36, Math.floor(w * 0.72) - 16)
        : shapeType === 'pill'
          ? Math.max(36, w - 34)
          : Math.max(40, w - 24)
  let visualLines = 0
  for (const line of text.split('\n')) {
    visualLines += Math.max(1, Math.ceil(estimateTextLinePx(line, safeFont) / usableW))
  }
  const textH = visualLines * lineHeight
  const neededH =
    shapeType === 'diamond'
      ? Math.ceil(textH * 1.65 + 32)
      : shapeType === 'ellipse'
        ? Math.ceil(textH * 1.32 + 26)
        : shapeType === 'pill'
          ? Math.ceil(textH + 22)
          : Math.ceil(textH + 20)
  return { w, h: clampNum(Math.max(44, minH, neededH), 44, 2400) }
}

export function computeAutoTextDimensions(
  text: string,
  fontSize: number,
  currentW: number,
  autosize = true,
  maxAutoWOrHasBg: number | boolean = 920,
  hasBackgroundArg = false
): { w: number; h: number } {
  const maxAutoW = typeof maxAutoWOrHasBg === 'number' ? maxAutoWOrHasBg : 920
  const hasBackground = typeof maxAutoWOrHasBg === 'boolean' ? maxAutoWOrHasBg : hasBackgroundArg
  const safeFont = clampNum(fontSize, 12, 200)
  const lineHeight = safeFont * 1.24
  const padX = hasBackground ? 36 : 24
  const padY = hasBackground ? 28 : 22
  const rawLines = (text.length > 0 ? text : 'Write something…').split('\n')
  const w = autosize
    ? clampNum(
        Math.max(0, ...rawLines.map((l) => estimateTextLinePx(l, safeFont))) + padX + 12,
        Math.max(96, Math.round(safeFont * 2.2)),
        maxAutoW
      )
    : clampNum(currentW || 240, 90, 1600)
  const usableW = Math.max(40, w - padX)
  let visualLines = 0
  for (const line of rawLines) {
    visualLines += Math.max(1, Math.ceil(estimateTextLinePx(line, safeFont) / usableW))
  }
  return { w, h: Math.max(hasBackground ? 48 : 44, Math.ceil(visualLines * lineHeight + padY)) }
}

export function computeCardMinHeight(
  text: string,
  fontSize: number,
  cardW: number,
  baseH: number
): number {
  const safeFont = clampNum(fontSize, 12, 64)
  const charsPerLine = Math.max(6, Math.floor(Math.max(80, cardW - 28) / (safeFont * 0.56)))
  let visualLines = 0
  for (const line of (text || '').split('\n')) {
    visualLines += Math.max(1, Math.ceil(Array.from(line).length / charsPerLine))
  }
  return Math.max(96, baseH, Math.ceil(visualLines * safeFont * 1.55 + 68))
}

export function alignWhiteboardItems<
  T extends { id: string; x: number; y: number; w: number; h: number }
>(
  items: readonly T[],
  mode: 'left' | 'center' | 'right' | 'top' | 'middle' | 'bottom'
): Record<string, { x: number; y: number }> {
  if (items.length === 0) {
    return {}
  }
  const minX = Math.min(...items.map((i) => i.x))
  const maxX = Math.max(...items.map((i) => i.x + i.w))
  const minY = Math.min(...items.map((i) => i.y))
  const maxY = Math.max(...items.map((i) => i.y + i.h))
  const out: Record<string, { x: number; y: number }> = {}
  for (const item of items) {
    switch (mode) {
      case 'left':
        out[item.id] = { x: Math.round(minX), y: Math.round(item.y) }
        break
      case 'center':
        out[item.id] = { x: Math.round((minX + maxX) / 2 - item.w / 2), y: Math.round(item.y) }
        break
      case 'right':
        out[item.id] = { x: Math.round(maxX - item.w), y: Math.round(item.y) }
        break
      case 'top':
        out[item.id] = { x: Math.round(item.x), y: Math.round(minY) }
        break
      case 'middle':
        out[item.id] = { x: Math.round(item.x), y: Math.round((minY + maxY) / 2 - item.h / 2) }
        break
      case 'bottom':
        out[item.id] = { x: Math.round(item.x), y: Math.round(maxY - item.h) }
        break
    }
  }
  return out
}

export function distributeWhiteboardItems<
  T extends { id: string; x: number; y: number; w: number; h: number }
>(items: readonly T[], axis: 'horizontal' | 'vertical'): Record<string, { x: number; y: number }> {
  if (items.length === 0) {
    return {}
  }
  const out: Record<string, { x: number; y: number }> = {}
  if (items.length < 3) {
    for (const item of items) {
      out[item.id] = { x: Math.round(item.x), y: Math.round(item.y) }
    }
    return out
  }
  const sorted = [...items].sort((a, b) => (axis === 'horizontal' ? a.x - b.x : a.y - b.y))
  const first = sorted[0]!
  const last = sorted.at(-1)!
  if (axis === 'horizontal') {
    const totalSize = sorted.reduce((sum, i) => sum + i.w, 0)
    const gap = (last.x + last.w - first.x - totalSize) / (sorted.length - 1)
    let cursor = first.x
    for (const item of sorted) {
      out[item.id] = { x: Math.round(cursor), y: Math.round(item.y) }
      cursor += item.w + gap
    }
    return out
  }
  const totalSize = sorted.reduce((sum, i) => sum + i.h, 0)
  const gap = (last.y + last.h - first.y - totalSize) / (sorted.length - 1)
  let cursor = first.y
  for (const item of sorted) {
    out[item.id] = { x: Math.round(item.x), y: Math.round(cursor) }
    cursor += item.h + gap
  }
  return out
}

export function rectIntersectsBox(a: WhiteboardRect, b: WhiteboardRect): boolean {
  return a.x <= b.x + b.w && a.x + a.w >= b.x && a.y <= b.y + b.h && a.y + a.h >= b.y
}

export function normalizeMarqueeRect(
  start: WhiteboardPoint,
  current: WhiteboardPoint
): WhiteboardRect {
  return {
    x: Math.min(start.x, current.x),
    y: Math.min(start.y, current.y),
    w: Math.abs(current.x - start.x),
    h: Math.abs(current.y - start.y)
  }
}

import { snapAxisDelta } from './whiteboard-kit'
import {
  applySnapDelta,
  snapDisabledBy,
  snapRect,
  type Axis,
  type SnapGuide,
  type SnapIndex,
  type SnapKind,
  type SnapRect
} from './whiteboard-snap'

export type DragModifiers = { shiftKey?: boolean; metaKey?: boolean }
export type SnappedDelta = { dx: number; dy: number; guides: readonly SnapGuide[] }

export const NO_GUIDES: readonly SnapGuide[] = Object.freeze([]) as readonly SnapGuide[]

function off(index: SnapIndex | null, mods: DragModifiers): boolean {
  return index === null || snapDisabledBy(mods)
}

export function snapMoveDelta(
  start: SnapRect,
  rawDx: number,
  rawDy: number,
  index: SnapIndex | null,
  zoom: number,
  mods: DragModifiers
): SnappedDelta {
  const locked = mods.shiftKey ? snapAxisDelta(rawDx, rawDy) : null
  const dx = locked ? locked.dx : rawDx
  const dy = locked ? locked.dy : rawDy
  if (off(index, mods)) {
    return { dx, dy, guides: NO_GUIDES }
  }
  const moved = { x: start.x + dx, y: start.y + dy, w: start.w, h: start.h }
  const r = snapRect(moved, index as SnapIndex, zoom)
  if (!locked) {
    return { dx: dx + r.dx, dy: dy + r.dy, guides: r.guides.length ? r.guides : NO_GUIDES }
  }
  const lockedAxis: Axis = Math.abs(rawDx) >= Math.abs(rawDy) ? 'y' : 'x'
  const fx = lockedAxis === 'x' ? dx : dx + r.dx
  const fy = lockedAxis === 'y' ? dy : dy + r.dy
  const final = snapRect(
    { x: start.x + fx, y: start.y + fy, w: start.w, h: start.h },
    index as SnapIndex,
    zoom
  )
  const guides = final.guides.filter((g) => g.axis !== lockedAxis)
  return { dx: fx, dy: fy, guides: guides.length ? guides : NO_GUIDES }
}

function draggedEdge(rect: SnapRect, kind: Exclude<SnapKind, 'move'>, axis: Axis): number | null {
  if (axis === 'x') {
    return kind.includes('w') ? rect.x : kind.includes('e') ? rect.x + rect.w : null
  }
  return kind.includes('n') ? rect.y : kind.includes('s') ? rect.y + rect.h : null
}

const CLAMPED_PX = 1
const ON_TARGET = 1e-6

export function snapResizeDelta(
  rawDx: number,
  rawDy: number,
  kind: Exclude<SnapKind, 'move'>,
  resize: (dx: number, dy: number) => SnapRect,
  index: SnapIndex | null,
  zoom: number,
  mods: DragModifiers
): SnappedDelta {
  if (off(index, mods)) {
    return { dx: rawDx, dy: rawDy, guides: NO_GUIDES }
  }
  const before = resize(rawDx, rawDy)
  const r = snapRect(before, index as SnapIndex, zoom, { kind })
  if (r.dx === 0 && r.dy === 0 && r.guides.length === 0) {
    return { dx: rawDx, dy: rawDy, guides: NO_GUIDES }
  }
  const target = applySnapDelta(before, r.dx, r.dy, kind)
  const final = resize(rawDx + r.dx, rawDy + r.dy)
  let dx = rawDx + r.dx
  let dy = rawDy + r.dy
  const hidden = new Set<Axis>()
  for (const axis of ['x', 'y'] as const) {
    const want = draggedEdge(target, kind, axis)
    const got = draggedEdge(final, kind, axis)
    if (want === null || got === null) {
      continue
    }
    const miss = Math.abs(got - want)
    if (miss > ON_TARGET) {
      hidden.add(axis)
    }
    if (miss > CLAMPED_PX) {
      if (axis === 'x') {
        dx = rawDx
      } else {
        dy = rawDy
      }
    }
  }
  const guides = hidden.size ? r.guides.filter((g) => !hidden.has(g.axis)) : r.guides
  return { dx, dy, guides: guides.length ? guides : NO_GUIDES }
}

export function snapPointTo(
  pt: { x: number; y: number },
  index: SnapIndex | null,
  zoom: number,
  mods: DragModifiers
): { x: number; y: number; guides: readonly SnapGuide[] } {
  if (off(index, mods)) {
    return { x: pt.x, y: pt.y, guides: NO_GUIDES }
  }
  const r = snapRect({ x: pt.x, y: pt.y, w: 0, h: 0 }, index as SnapIndex, zoom, { kind: 'se' })
  return { x: pt.x + r.dx, y: pt.y + r.dy, guides: r.guides.length ? r.guides : NO_GUIDES }
}

export function unionRect(rects: readonly SnapRect[]): SnapRect | null {
  if (rects.length === 0) {
    return null
  }
  let x1 = Infinity
  let y1 = Infinity
  let x2 = -Infinity
  let y2 = -Infinity
  for (const r of rects) {
    x1 = Math.min(x1, r.x)
    y1 = Math.min(y1, r.y)
    x2 = Math.max(x2, r.x + r.w)
    y2 = Math.max(y2, r.y + r.h)
  }
  return { x: x1, y: y1, w: x2 - x1, h: y2 - y1 }
}

// Snapping + smart guides for the Spaces whiteboard. Idea and gap math from Penpot (MPL-2.0):
// frontend/src/app/main/snap.cljs and viewport/snap_distances.cljs. The close ports live in
// ../penpot-mpl/ (MPL-2.0, see PROVENANCE.md); this file is our own glue: the per-gesture index,
// the screen-px threshold, resize handles, combining point + gap snaps, and the guide shapes.

import {
  calculateSegments,
  calculateSnap,
  getAreas,
  overlap,
  srDistance,
  type Axis,
  type SelRect
} from '../penpot-mpl/snap-distance'
import { getMinDistanceSnap, rectToSnapPoints } from '../penpot-mpl/snap-points'

export type { Axis } from '../penpot-mpl/snap-distance'

export type SnapRect = { x: number; y: number; w: number; h: number }
export type SnapKind = 'move' | 'n' | 's' | 'e' | 'w' | 'ne' | 'nw' | 'se' | 'sw'

export type SnapGuide =
  | { kind: 'line'; axis: Axis; at: number; from: number; to: number }
  | { kind: 'gap'; axis: Axis; from: number; to: number; cross: number; gap: number }

export type SnapResult = { dx: number; dy: number; guides: SnapGuide[] }

export type SnapOptions = {
  threshold?: number
  kind?: SnapKind
  disabled?: boolean
}

type AxisEntry = { value: number; lo: number; hi: number }
type AxisIndex = { values: Float64Array; entries: AxisEntry[] }

export type SnapIndex = {
  readonly rects: readonly SelRect[]
  readonly x: AxisIndex
  readonly y: AxisIndex
  readonly bounds: SelRect
}

export const SNAP_THRESHOLD_PX = 6
export const MAX_GAP_NEIGHBOURS = 12
const GUIDE_EPSILON_PX = 0.5
const NO_SNAP: SnapResult = Object.freeze({ dx: 0, dy: 0, guides: [] }) as SnapResult
const UNBOUNDED: SelRect = { x1: -Infinity, y1: -Infinity, x2: Infinity, y2: Infinity }

export function toSelRect(r: SnapRect): SelRect {
  const x1 = Math.min(r.x, r.x + r.w)
  const y1 = Math.min(r.y, r.y + r.h)
  return { x1, y1, x2: x1 + Math.abs(r.w), y2: y1 + Math.abs(r.h) }
}

export function snapDisabledBy(event: { metaKey?: boolean }): boolean {
  return Boolean(event.metaKey)
}

function buildAxis(rects: readonly SelRect[], axis: Axis): AxisIndex {
  const entries: AxisEntry[] = []
  for (const r of rects) {
    const [a1, a2, lo, hi] = axis === 'x' ? [r.x1, r.x2, r.y1, r.y2] : [r.y1, r.y2, r.x1, r.x2]
    entries.push(
      { value: a1, lo, hi },
      { value: a2, lo, hi },
      { value: a1 + (a2 - a1) / 2, lo, hi }
    )
  }
  entries.sort((a, b) => a.value - b.value)
  return { values: Float64Array.from(entries, (e) => e.value), entries }
}

export function createSnapIndex(
  others: readonly SnapRect[],
  opts: { bounds?: SnapRect } = {}
): SnapIndex {
  const rects = others.map(toSelRect)
  return {
    rects,
    x: buildAxis(rects, 'x'),
    y: buildAxis(rects, 'y'),
    bounds: opts.bounds ? toSelRect(opts.bounds) : UNBOUNDED
  }
}

function asIndex(others: SnapIndex | readonly SnapRect[]): SnapIndex {
  return 'rects' in others ? others : createSnapIndex(others)
}

function lowerBound(values: Float64Array, lo: number): number {
  let a = 0
  let b = values.length
  while (a < b) {
    const mid = (a + b) >> 1
    if (values[mid]! < lo) {
      a = mid + 1
    } else {
      b = mid
    }
  }
  return a
}

function* queryValues(axis: AxisIndex, lo: number, hi: number): Generator<number> {
  for (let i = lowerBound(axis.values, lo); i < axis.values.length && axis.values[i]! <= hi; i++) {
    yield axis.values[i]!
  }
}

export function snapPoints(rect: SnapRect, kind: SnapKind = 'move'): { x: number[]; y: number[] } {
  const r = toSelRect(rect)
  if (kind === 'move') {
    const pts = rectToSnapPoints(r)
    const center = pts[4]!
    return { x: [r.x1, r.x2, center.x], y: [r.y1, r.y2, center.y] }
  }
  const x: number[] = []
  const y: number[] = []
  if (kind.includes('w')) {
    x.push(r.x1)
  }
  if (kind.includes('e')) {
    x.push(r.x2)
  }
  if (kind.includes('n')) {
    y.push(r.y1)
  }
  if (kind.includes('s')) {
    y.push(r.y2)
  }
  return { x, y }
}

export function applySnapDelta(
  rect: SnapRect,
  dx: number,
  dy: number,
  kind: SnapKind = 'move'
): SnapRect {
  if (kind === 'move') {
    return { x: rect.x + dx, y: rect.y + dy, w: rect.w, h: rect.h }
  }
  let { x, y, w, h } = rect
  if (kind.includes('w')) {
    x += dx
    w -= dx
  } else if (kind.includes('e')) {
    w += dx
  }
  if (kind.includes('n')) {
    y += dy
    h -= dy
  } else if (kind.includes('s')) {
    h += dy
  }
  return { x, y, w, h }
}

function pointDelta(coords: readonly number[], axis: AxisIndex, accuracy: number): number | null {
  const hit = getMinDistanceSnap(coords, accuracy, (lo, hi) => queryValues(axis, lo, hi))
  return hit ? hit[1] - hit[0] : null
}

function lineGuides(
  final: SelRect,
  coords: readonly number[],
  axisName: Axis,
  axis: AxisIndex,
  eps: number
): SnapGuide[] {
  const crossLo = axisName === 'x' ? final.y1 : final.x1
  const crossHi = axisName === 'x' ? final.y2 : final.x2
  const byValue = new Map<number, { from: number; to: number }>()
  for (const c of coords) {
    for (
      let i = lowerBound(axis.values, c - eps);
      i < axis.values.length && axis.values[i]! <= c + eps;
      i++
    ) {
      const e = axis.entries[i]!
      const cur = byValue.get(e.value) ?? { from: crossLo, to: crossHi }
      cur.from = Math.min(cur.from, e.lo)
      cur.to = Math.max(cur.to, e.hi)
      byValue.set(e.value, cur)
    }
  }
  return [...byValue].map(([at, span]) => ({
    kind: 'line',
    axis: axisName,
    at,
    from: span.from,
    to: span.to
  }))
}

function sideNeighbours(
  index: SnapIndex,
  sel: SelRect,
  axis: Axis
): { lt: SelRect[]; gt: SelRect[] } {
  const areas = getAreas(index.bounds, sel)
  const ltArea = axis === 'x' ? areas.left : areas.top
  const gtArea = axis === 'x' ? areas.right : areas.bottom
  const lt: SelRect[] = []
  const gt: SelRect[] = []
  for (const r of index.rects) {
    if (!overlap(axis, r, sel)) {
      continue
    }
    if (axis === 'x') {
      if (r.x2 <= sel.x1 && r.x1 >= ltArea.x1) {
        lt.push(r)
      } else if (r.x1 >= sel.x2 && r.x2 <= gtArea.x2) {
        gt.push(r)
      }
    } else if (r.y2 <= sel.y1 && r.y1 >= ltArea.y1) {
      lt.push(r)
    } else if (r.y1 >= sel.y2 && r.y2 <= gtArea.y2) {
      gt.push(r)
    }
  }
  return {
    lt: nearest(lt, (r) => srDistance(axis, r, sel)),
    gt: nearest(gt, (r) => srDistance(axis, sel, r))
  }
}

function nearest(rects: SelRect[], dist: (r: SelRect) => number): SelRect[] {
  if (rects.length <= MAX_GAP_NEIGHBOURS) {
    return rects
  }
  return rects
    .map((r) => ({ r, d: dist(r) }))
    .sort((a, b) => a.d - b.d)
    .slice(0, MAX_GAP_NEIGHBOURS)
    .map((e) => e.r)
}

function gapGuides(index: SnapIndex, sel: SelRect, axis: Axis): SnapGuide[] {
  const { lt, gt } = sideNeighbours(index, sel, axis)
  return calculateSegments(axis, sel, lt, gt).map(([a, b]) => {
    const from = axis === 'x' ? Math.min(a.x2, b.x2) : Math.min(a.y2, b.y2)
    const to = axis === 'x' ? Math.max(a.x1, b.x1) : Math.max(a.y1, b.y1)
    const c1 = axis === 'x' ? Math.max(a.y1, b.y1) : Math.max(a.x1, b.x1)
    const c2 = axis === 'x' ? Math.min(a.y2, b.y2) : Math.min(a.x2, b.x2)
    return { kind: 'gap', axis, from, to, cross: c1 + (c2 - c1) / 2, gap: to - from }
  })
}

function closer(a: number | null, b: number | null): number | null {
  if (a === null || b === null) {
    return a ?? b
  }
  return Math.abs(b) < Math.abs(a) ? b : a
}

type Use = { points: boolean; gaps: boolean }

function solve(
  moving: SnapRect,
  others: SnapIndex | readonly SnapRect[],
  zoom: number,
  opts: SnapOptions,
  use: Use
): SnapResult {
  const kind = opts.kind ?? 'move'
  const gaps = use.gaps && kind === 'move'
  if (opts.disabled || (!use.points && !gaps)) {
    return NO_SNAP
  }
  const index = asIndex(others)
  const accuracy = (opts.threshold ?? SNAP_THRESHOLD_PX) / zoom
  let dx: number | null = null
  let dy: number | null = null
  if (use.points) {
    const pts = snapPoints(moving, kind)
    dx = pointDelta(pts.x, index.x, accuracy)
    dy = pointDelta(pts.y, index.y, accuracy)
  }
  if (gaps) {
    const sel = toSelRect(moving)
    const nx = sideNeighbours(index, sel, 'x')
    const ny = sideNeighbours(index, sel, 'y')
    dx = closer(dx, calculateSnap('x', sel, nx.lt, nx.gt, accuracy))
    dy = closer(dy, calculateSnap('y', sel, ny.lt, ny.gt, accuracy))
  }
  const moved = applySnapDelta(moving, dx ?? 0, dy ?? 0, kind)
  const final = toSelRect(moved)
  const guides: SnapGuide[] = []
  if (use.points) {
    const pts = snapPoints(moved, kind)
    const eps = GUIDE_EPSILON_PX / zoom
    guides.push(...lineGuides(final, pts.x, 'x', index.x, eps))
    guides.push(...lineGuides(final, pts.y, 'y', index.y, eps))
  }
  if (gaps) {
    guides.push(...gapGuides(index, final, 'x'), ...gapGuides(index, final, 'y'))
  }
  return { dx: dx ?? 0, dy: dy ?? 0, guides }
}

export function snapMove(
  moving: SnapRect,
  others: SnapIndex | readonly SnapRect[],
  zoom: number,
  opts: SnapOptions = {}
): SnapResult {
  return solve(moving, others, zoom, opts, { points: true, gaps: false })
}

export function snapGaps(
  moving: SnapRect,
  others: SnapIndex | readonly SnapRect[],
  zoom: number,
  opts: SnapOptions = {}
): SnapResult {
  return solve(moving, others, zoom, opts, { points: false, gaps: true })
}

export function snapRect(
  moving: SnapRect,
  others: SnapIndex | readonly SnapRect[],
  zoom: number,
  opts: SnapOptions = {}
): SnapResult {
  return solve(moving, others, zoom, opts, { points: true, gaps: true })
}

import React, { createContext, useContext } from 'react'
import type { AgentRoleId } from './generated/a01-roles'
import type {
  A01SpawnMode,
  C02ProjectLiveRef,
  C02ProjectSummary,
  DraggableSessionSummary,
  SpaceComputerTarget,
  SpaceSessionKind
} from './core/canvas-nodes'
import type { PinnedSession } from './core/pinned-sessions'
import type { Point, SpaceAgent, SpaceAsk } from './core/space'

export type A01SpawnRequest = {
  nodeId: string
  roleId: AgentRoleId
  spawnMode: A01SpawnMode
  projectSlug: string
  computer: SpaceComputerTarget
  position: Point
  modelId?: string
  goalId?: string
}

export type PinnedSessionBodyRenderOpts = {
  dark: boolean
  chat: boolean
  onOpenFull: () => void
  onAnswerAsk?: (ask: SpaceAsk, answer: 'yes' | 'no') => void
}

/**
 * Host adapter contract injected into `<SpaceCanvas host={...} />` or `<SpaceCanvasHostProvider>`.
 * Keeps `@xlabs/space-canvas` 100% free of Electron, IPC globals, or host app stores.
 */
export type SpaceCanvasHostAdapter = {
  /** Live sessions/threads from OpenManus or Orca terminals/agents available to drag onto the canvas. */
  sessions?: readonly DraggableSessionSummary[]
  /** Available C02 projects (e.g. `precision-peptide`, `surge`, `x-labs`) for project cards & spawn selector. */
  projects?: readonly C02ProjectSummary[]
  /** Default / active C02 project slug of the current Space. */
  activeProjectSlug?: string
  /** Active host worktree or workspace identifier for pinned floating squares. */
  activeWorktreeId?: string
  /** Called when the user switches the Space's top-level C02 project badge. */
  onSelectSpaceProject?: (projectSlug: string) => void
  /** Open the chat thread (OpenManus) or terminal/agent tab (Orca) in full view. */
  onOpenSession?: (sessionId: string, sessionKind: SpaceSessionKind) => void
  /** Pin or unpin a session as a floating face square. */
  onPinSession?: (sessionId: string, pinned: boolean, summary?: DraggableSessionSummary) => void
  /** Switch the execution target computer (`local-ax`, `mac2-lume-isolated`, `mac2-shared`, `cua-cloud`) for a node. */
  onSwitchNodeComputer?: (nodeId: string, nextComputer: SpaceComputerTarget) => void
  /** Spawn a registered `A01` role dropped onto the canvas via the 2-second Spawn Card. */
  onSpawnA01Agent?: (req: A01SpawnRequest) => void | Promise<void>
  /** Semantic arrow hook: drawing a magnetic arrow from a C02 Project Card ──▶ Agent/Session Node binds the project. */
  onBindProjectToNode?: (nodeId: string, projectSlug: string) => void
  /** Semantic arrow hook: drawing a magnetic arrow from Agent/Session A ──▶ Agent/Session B wires a handoff link. */
  onConnectNodes?: (fromId: string, toId: string) => void
  /** Open a live link / file reference on a C02 Project context card. */
  onOpenProjectRef?: (projectSlug: string, ref: C02ProjectLiveRef) => void
  /** Answer an open agent ask (`yes` / `no`) from an Ask Pin or Pinned Window. */
  onAnswerAsk?: (goalId: string, askId: string, answer: 'yes' | 'no') => void
  /** Optional custom renderer for the body inside an expanded Pinned Floating Window. */
  renderPinnedSessionBody?: (
    pin: PinnedSession,
    agent: SpaceAgent | null,
    opts: PinnedSessionBodyRenderOpts
  ) => React.ReactNode
  /** Optional terminal tail fetcher for Pinned Window fallback preview. */
  getTerminalTail?: (tabId: string) => Promise<string>
  /** Optional host image picker returning a `data:image/...` or URL string for custom Space emojis. */
  onPickImageDataUrl?: () => Promise<string | null>
  /** Optional host toast/notification callback. */
  onNotify?: (message: string, tone?: 'info' | 'warn' | 'good') => void
  /** Optional host focus-task callback triggered from a Goal tile's focus button. */
  onFocusTask?: (slugOrId: string, title: string) => void
}

const DEFAULT_HOST_ADAPTER: SpaceCanvasHostAdapter = Object.freeze({})

const SpaceCanvasHostContext = createContext<SpaceCanvasHostAdapter>(DEFAULT_HOST_ADAPTER)

export function SpaceCanvasHostProvider({
  adapter,
  children
}: {
  adapter?: SpaceCanvasHostAdapter
  children: React.ReactNode
}): React.JSX.Element {
  return (
    <SpaceCanvasHostContext.Provider value={adapter ?? DEFAULT_HOST_ADAPTER}>
      {children}
    </SpaceCanvasHostContext.Provider>
  )
}

export function useSpaceCanvasHost(): SpaceCanvasHostAdapter {
  return useContext(SpaceCanvasHostContext)
}

const ITEM = '[role^="menuitem"]'

function items(menu: HTMLElement): HTMLElement[] {
  return Array.from(menu.querySelectorAll<HTMLElement>(ITEM)).filter(
    (el) => !(el as HTMLButtonElement).disabled
  )
}

export function focusMenuOnOpen(menu: HTMLElement | null): void {
  if (!menu || menu.contains(document.activeElement)) {
    return
  }
  const list = items(menu)
  const current = list.find((el) => el.getAttribute('aria-checked') === 'true')
  ;(current ?? list[0])?.focus()
}

export function handleMenuKey(
  event: { key: string; preventDefault: () => void; stopPropagation: () => void },
  menu: HTMLElement,
  close: () => void,
  trigger: HTMLElement | null
): boolean {
  if (event.key === 'Escape') {
    event.preventDefault()
    event.stopPropagation()
    close()
    trigger?.focus()
    return true
  }
  if (!['ArrowDown', 'ArrowUp', 'Home', 'End'].includes(event.key)) {
    return false
  }
  event.preventDefault()
  const list = items(menu)
  if (list.length === 0) {
    return true
  }
  const at = list.indexOf(document.activeElement as HTMLElement)
  const next =
    event.key === 'Home'
      ? 0
      : event.key === 'End'
        ? list.length - 1
        : (at + (event.key === 'ArrowDown' ? 1 : -1) + list.length) % list.length
  list[next]?.focus()
  return true
}

export type MenuPoint = { x: number; y: number }

export function clampMenuPoint(
  point: MenuPoint,
  menu: { w: number; h: number },
  viewport: { w: number; h: number },
  margin = 8
): MenuPoint {
  let x = point.x
  let y = point.y
  if (x + menu.w > viewport.w - margin) {
    x = point.x - menu.w >= margin ? point.x - menu.w : viewport.w - menu.w - margin
  }
  if (y + menu.h > viewport.h - margin) {
    y = point.y - menu.h >= margin ? point.y - menu.h : viewport.h - menu.h - margin
  }
  x = Math.min(x, viewport.w - menu.w - margin)
  y = Math.min(y, viewport.h - menu.h - margin)
  return { x: Math.max(margin, x), y: Math.max(margin, y) }
}

export function canvasCenterPoint(canvas: HTMLElement | null): MenuPoint {
  if (!canvas) {
    return { x: 160, y: 120 }
  }
  const rect = canvas.getBoundingClientRect()
  const vx = Number(canvas.dataset.viewX ?? 0)
  const vy = Number(canvas.dataset.viewY ?? 0)
  const scale = Number(canvas.dataset.viewScale ?? 1) || 1
  return {
    x: Math.round((rect.width / 2 - vx) / scale),
    y: Math.round((rect.height / 2 - vy) / scale)
  }
}

export type SlotBox = { x: number; y: number; w: number; h: number }

export function canvasTileBoxes(canvas: HTMLElement | null): SlotBox[] {
  if (!canvas) {
    return []
  }
  return Array.from(
    canvas.querySelectorAll<HTMLElement>('[data-space-tile], [data-canvas-node]')
  ).map((el) => ({
    x: Number.parseFloat(el.style.left) || 0,
    y: Number.parseFloat(el.style.top) || 0,
    w: Number.parseFloat(el.style.width) || el.offsetWidth || 340,
    h: Number.parseFloat(el.style.minHeight) || el.offsetHeight || 220
  }))
}

export function nearestFreeSlot(
  center: MenuPoint,
  size: { w: number; h: number },
  occupied: readonly SlotBox[],
  opts: { gap?: number; step?: number; maxRings?: number } = {}
): MenuPoint {
  const gap = opts.gap ?? 24
  const step = opts.step ?? 40
  const maxRings = opts.maxRings ?? 80
  const x0 = center.x - size.w / 2
  const y0 = center.y - size.h / 2
  const free = (x: number, y: number): boolean =>
    occupied.every(
      (o) =>
        x + size.w + gap <= o.x ||
        x >= o.x + o.w + gap ||
        y + size.h + gap <= o.y ||
        y >= o.y + o.h + gap
    )
  for (let ring = 0; ring <= maxRings; ring++) {
    let best: MenuPoint | null = null
    let bestDist = Infinity
    for (let i = -ring; i <= ring; i++) {
      for (let j = -ring; j <= ring; j++) {
        if (Math.max(Math.abs(i), Math.abs(j)) !== ring) {
          continue
        }
        const x = x0 + i * step
        const y = y0 + j * step
        const d = Math.hypot(i, j)
        if (d < bestDist && free(x, y)) {
          best = { x, y }
          bestDist = d
        }
      }
    }
    if (best) {
      return { x: Math.round(best.x), y: Math.round(best.y) }
    }
  }
  return { x: Math.round(x0), y: Math.round(y0) }
}

import React, { useMemo, useState } from 'react'
import { Plus, Search, Users, X } from 'lucide-react'
import { SPACE_NODE_DRAG_MIME, serializeNodeDropPayload } from '../core/canvas-nodes'
import {
  A01_GROUPS,
  A01_ROLE_IDS,
  AGENT_ROLE_ACCESSORIES,
  type A01GroupId,
  type AgentRoleId
} from '../generated/a01-roles'
import type { DragItem } from '../space-drag'
import { MiniSpacewareSprite } from '../sprites/space-sprite'

export function A01RosterDrawer({
  open,
  dark,
  onClose,
  onRequestSpawn,
  onStartPointerDrag
}: {
  open: boolean
  dark: boolean
  onClose: () => void
  onRequestSpawn: (roleId: AgentRoleId) => void
  onStartPointerDrag?: (item: DragItem) => (event: React.PointerEvent) => void
}): React.JSX.Element | null {
  const [query, setQuery] = useState('')
  const [groupFilter, setGroupFilter] = useState<'all' | A01GroupId>('all')

  const filteredRoles = useMemo(() => {
    const q = query.trim().toLowerCase()
    return A01_ROLE_IDS.filter((roleId) => {
      const meta = AGENT_ROLE_ACCESSORIES[roleId]
      if (groupFilter !== 'all' && meta.group !== groupFilter) {
        return false
      }
      if (!q) {
        return true
      }
      return (
        roleId.toLowerCase().includes(q) ||
        meta.label.toLowerCase().includes(q) ||
        meta.tagline.toLowerCase().includes(q) ||
        meta.archetype.toLowerCase().includes(q)
      )
    })
  }, [groupFilter, query])

  if (!open) {
    return null
  }

  return (
    <div
      data-space-drawer="a01-roster"
      data-testid="a01-roster-drawer"
      onPointerDown={(e) => e.stopPropagation()}
      onWheel={(e) => e.stopPropagation()}
      className={`pointer-events-auto absolute top-14 left-3 z-40 flex max-h-[calc(100%-5rem)] w-80 flex-col overflow-hidden rounded-2xl border shadow-2xl backdrop-blur-xl ${
        dark
          ? 'border-zinc-700/85 bg-zinc-900/95 text-zinc-100'
          : 'border-zinc-300 bg-white/96 text-zinc-900'
      }`}
    >
      <div
        className={`flex items-center justify-between border-b px-3.5 py-2.5 ${
          dark ? 'border-zinc-800' : 'border-zinc-200'
        }`}
      >
        <div className="flex items-center gap-2">
          <Users className="h-4 w-4 text-indigo-400" />
          <div>
            <div className="text-[12px] font-semibold">
              A01 Registered Team ({A01_ROLE_IDS.length})
            </div>
            <div className="text-[10px] text-zinc-400">Drag onto whiteboard or click Spawn</div>
          </div>
        </div>
        <button
          type="button"
          aria-label="Close A01 Roster"
          onClick={onClose}
          className={`rounded-lg p-1 transition-colors ${
            dark ? 'text-zinc-400 hover:bg-zinc-800' : 'text-zinc-500 hover:bg-zinc-100'
          }`}
        >
          <X className="h-3.5 w-3.5" />
        </button>
      </div>

      <div className="space-y-2 p-2.5">
        <div
          className={`flex items-center gap-1.5 rounded-lg border px-2.5 py-1.5 ${
            dark ? 'border-zinc-700/80 bg-zinc-950/70' : 'border-zinc-200 bg-zinc-50'
          }`}
        >
          <Search className="h-3.5 w-3.5 text-zinc-400" />
          <input
            type="text"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="Search 18 registered A01 roles…"
            className="w-full bg-transparent text-[11px] outline-none placeholder:text-zinc-500"
          />
        </div>

        <div className="flex flex-wrap gap-1">
          <button
            type="button"
            onClick={() => setGroupFilter('all')}
            className={`rounded-md px-2 py-0.5 text-[10px] font-medium transition-colors ${
              groupFilter === 'all'
                ? 'bg-indigo-500 text-white'
                : dark
                  ? 'bg-zinc-800 text-zinc-300 hover:bg-zinc-700'
                  : 'bg-zinc-100 text-zinc-700 hover:bg-zinc-200'
            }`}
          >
            All ({A01_ROLE_IDS.length})
          </button>
          {A01_GROUPS.map((grp) => (
            <button
              key={grp.id}
              type="button"
              onClick={() => setGroupFilter(grp.id)}
              className={`rounded-md px-2 py-0.5 text-[10px] font-medium transition-colors ${
                groupFilter === grp.id
                  ? 'bg-indigo-500 text-white'
                  : dark
                    ? 'bg-zinc-800 text-zinc-300 hover:bg-zinc-700'
                    : 'bg-zinc-100 text-zinc-700 hover:bg-zinc-200'
              }`}
            >
              {grp.label}
            </button>
          ))}
        </div>
      </div>

      <div className="flex-1 space-y-1.5 overflow-y-auto px-2.5 pb-3">
        {filteredRoles.map((roleId) => {
          const meta = AGENT_ROLE_ACCESSORIES[roleId]
          const serialized = serializeNodeDropPayload({ kind: 'a01-role', roleId })
          return (
            <div
              key={roleId}
              data-testid={`a01-roster-role-${roleId}`}
              draggable
              onDragStart={(event) => {
                event.dataTransfer.effectAllowed = 'copy'
                event.dataTransfer.setData(SPACE_NODE_DRAG_MIME, serialized)
                event.dataTransfer.setData('text/plain', serialized)
              }}
              onPointerDown={
                onStartPointerDrag ? onStartPointerDrag({ kind: 'a01-role', roleId }) : undefined
              }
              className={`flex cursor-grab items-center justify-between gap-2 rounded-xl border p-2 transition-colors active:cursor-grabbing ${
                dark
                  ? 'border-zinc-800 bg-zinc-950/55 hover:border-indigo-500/45 hover:bg-zinc-800/70'
                  : 'border-zinc-200 bg-zinc-50/75 hover:border-indigo-300 hover:bg-indigo-50/40'
              }`}
            >
              <div className="flex min-w-0 items-center gap-2.5">
                <div
                  className={`flex h-9 w-9 shrink-0 items-center justify-center rounded-lg border ${
                    dark ? 'border-zinc-700 bg-zinc-900' : 'border-zinc-200 bg-white'
                  }`}
                >
                  <MiniSpacewareSprite role={roleId} awake size={26} />
                </div>
                <div className="min-w-0">
                  <div className="flex items-center gap-1.5">
                    <span className="truncate text-[12px] font-semibold">{meta.label}</span>
                    <span
                      className={`rounded px-1 py-0.2 text-[9px] font-medium ${
                        meta.longTermEmployeeCapable
                          ? dark
                            ? 'bg-violet-500/20 text-violet-200'
                            : 'bg-violet-100 text-violet-700'
                          : dark
                            ? 'bg-amber-500/20 text-amber-200'
                            : 'bg-amber-100 text-amber-800'
                      }`}
                    >
                      {meta.longTermEmployeeCapable ? '🧠 A01' : '⚡ Worker'}
                    </span>
                  </div>
                  <div className="truncate text-[10px] text-zinc-400">{meta.tagline}</div>
                </div>
              </div>

              <button
                type="button"
                data-testid={`spawn-role-btn-${roleId}`}
                onPointerDown={(e) => e.stopPropagation()}
                onClick={(e) => {
                  e.stopPropagation()
                  onRequestSpawn(roleId)
                }}
                className={`inline-flex shrink-0 items-center gap-1 rounded-lg border px-2 py-1 text-[10px] font-semibold transition-colors ${
                  dark
                    ? 'border-indigo-400/40 bg-indigo-500/20 text-indigo-100 hover:bg-indigo-500/35'
                    : 'border-indigo-300 bg-indigo-600 text-white hover:bg-indigo-700'
                }`}
              >
                <Plus className="h-3 w-3" />
                <span>Spawn</span>
              </button>
            </div>
          )
        })}
      </div>
    </div>
  )
}

import React, { useEffect, useMemo, useState } from 'react'
import { FolderKanban, Laptop, Sparkles, X } from 'lucide-react'
import {
  A01_SPAWN_MODES,
  SPACE_COMPUTER_TARGETS,
  type A01SpawnMode,
  type C02ProjectSummary,
  type SpaceComputerTarget
} from '../core/canvas-nodes'
import type { Point } from '../core/space'
import { AGENT_ROLE_ACCESSORIES, type AgentRoleId } from '../generated/a01-roles'
import { MiniSpacewareSprite } from '../sprites/space-sprite'

const DEFAULT_PROJECT_SLUGS = ['precision-peptide', 'surge', 'x-labs'] as const

export type PendingA01Spawn = {
  roleId: AgentRoleId
  position: Point
}

export function A01SpawnPopover({
  pending,
  dark,
  projects,
  defaultProjectSlug,
  onConfirm,
  onCancel
}: {
  pending: PendingA01Spawn | null
  dark: boolean
  projects?: readonly C02ProjectSummary[]
  defaultProjectSlug?: string
  onConfirm: (params: {
    roleId: AgentRoleId
    spawnMode: A01SpawnMode
    projectSlug: string
    computer: SpaceComputerTarget
    position: Point
  }) => void
  onCancel: () => void
}): React.JSX.Element | null {
  const roleMeta = pending ? AGENT_ROLE_ACCESSORIES[pending.roleId] : null

  const projectOptions = useMemo(() => {
    const slugs = new Map<string, string>()
    if (projects) {
      for (const proj of projects) {
        slugs.set(proj.slug, `${proj.title} (${proj.slug})`)
      }
    }
    for (const fallback of DEFAULT_PROJECT_SLUGS) {
      if (!slugs.has(fallback)) {
        slugs.set(fallback, fallback)
      }
    }
    if (defaultProjectSlug && !slugs.has(defaultProjectSlug)) {
      slugs.set(defaultProjectSlug, defaultProjectSlug)
    }
    return [...slugs.entries()].map(([slug, label]) => ({ slug, label }))
  }, [defaultProjectSlug, projects])

  const initialMode: A01SpawnMode = roleMeta?.longTermEmployeeCapable
    ? 'long-term-employee'
    : 'temporary-worker'

  const [spawnMode, setSpawnMode] = useState<A01SpawnMode>(initialMode)
  const [projectSlug, setProjectSlug] = useState<string>(
    defaultProjectSlug || projectOptions[0]?.slug || 'x-labs'
  )
  const [computer, setComputer] = useState<SpaceComputerTarget>('local-ax')

  useEffect(() => {
    if (!pending) {
      return
    }
    const meta = AGENT_ROLE_ACCESSORIES[pending.roleId]
    setSpawnMode(meta.longTermEmployeeCapable ? 'long-term-employee' : 'temporary-worker')
    setProjectSlug(defaultProjectSlug || projectOptions[0]?.slug || 'x-labs')
    setComputer('local-ax')
  }, [defaultProjectSlug, pending, projectOptions])

  if (!pending || !roleMeta) {
    return null
  }

  return (
    <div
      data-space-drawer="a01-spawn-popover"
      data-testid="a01-spawn-popover"
      onPointerDown={(e) => e.stopPropagation()}
      onKeyDown={(e) => {
        if (e.key === 'Escape') {
          e.stopPropagation()
          onCancel()
        } else if (e.key === 'Enter') {
          e.preventDefault()
          e.stopPropagation()
          onConfirm({
            roleId: pending.roleId,
            spawnMode,
            projectSlug,
            computer,
            position: pending.position
          })
        }
      }}
      className="pointer-events-auto absolute inset-0 z-50 flex items-center justify-center bg-black/35 backdrop-blur-[2px]"
    >
      <div
        className={`w-[380px] rounded-2xl border p-4 shadow-2xl ${
          dark
            ? 'border-indigo-500/45 bg-zinc-900 text-zinc-100'
            : 'border-indigo-300 bg-white text-zinc-900'
        }`}
      >
        <div className="flex items-start justify-between gap-2">
          <div className="flex items-center gap-2.5">
            <div
              className={`flex h-11 w-11 items-center justify-center rounded-xl border ${
                dark ? 'border-indigo-400/40 bg-indigo-500/15' : 'border-indigo-200 bg-indigo-50'
              }`}
            >
              <MiniSpacewareSprite role={pending.roleId} awake size={32} />
            </div>
            <div>
              <div className="flex items-center gap-1.5">
                <span className="text-[14px] font-bold">{roleMeta.label}</span>
                <span className="rounded bg-indigo-500/20 px-1.5 py-0.5 text-[10px] font-semibold text-indigo-300">
                  {roleMeta.archetype}
                </span>
              </div>
              <div className="text-[11px] text-zinc-400">{roleMeta.tagline}</div>
            </div>
          </div>
          <button
            type="button"
            aria-label="Cancel spawn"
            onClick={onCancel}
            className="rounded-lg p-1 text-zinc-400 hover:bg-zinc-800/60"
          >
            <X className="h-4 w-4" />
          </button>
        </div>

        <div className="mt-3.5 space-y-3">
          <div>
            <div className="mb-1.5 text-[10px] font-semibold tracking-wider text-zinc-400 uppercase">
              1 · Registration Mode
            </div>
            <div className="grid grid-cols-2 gap-2">
              {A01_SPAWN_MODES.map((mode) => {
                const disabled =
                  mode.id === 'long-term-employee' && !roleMeta.longTermEmployeeCapable
                const active = spawnMode === mode.id
                return (
                  <button
                    key={mode.id}
                    type="button"
                    disabled={disabled}
                    data-testid={`spawn-mode-${mode.id}`}
                    onClick={() => setSpawnMode(mode.id)}
                    className={`rounded-xl border p-2.5 text-left transition-all ${
                      disabled
                        ? 'cursor-not-allowed opacity-40'
                        : active
                          ? dark
                            ? 'border-indigo-400 bg-indigo-500/20 text-white'
                            : 'border-indigo-500 bg-indigo-50 text-indigo-950'
                          : dark
                            ? 'border-zinc-800 bg-zinc-950/60 text-zinc-300 hover:border-zinc-700'
                            : 'border-zinc-200 bg-zinc-50 text-zinc-700 hover:border-zinc-300'
                    }`}
                  >
                    <div className="text-[11px] font-semibold">{mode.label}</div>
                    <div className="mt-0.5 text-[9px] leading-snug text-zinc-400">
                      {mode.subtitle}
                    </div>
                  </button>
                )
              })}
            </div>
          </div>

          <div>
            <label
              htmlFor="a01-spawn-project"
              className="mb-1 flex items-center gap-1 text-[10px] font-semibold tracking-wider text-zinc-400 uppercase"
            >
              <FolderKanban className="h-3 w-3 text-emerald-400" />
              <span>2 · Bound C02 Project</span>
            </label>
            <select
              id="a01-spawn-project"
              data-testid="spawn-project-select"
              value={projectSlug}
              onChange={(e) => setProjectSlug(e.target.value)}
              className={`w-full rounded-xl border px-2.5 py-1.5 text-[12px] font-medium outline-none ${
                dark
                  ? 'border-zinc-700 bg-zinc-950 text-zinc-100'
                  : 'border-zinc-300 bg-zinc-50 text-zinc-900'
              }`}
            >
              {projectOptions.map((opt) => (
                <option key={opt.slug} value={opt.slug}>
                  {opt.label}
                </option>
              ))}
            </select>
          </div>

          <div>
            <div className="mb-1 flex items-center gap-1 text-[10px] font-semibold tracking-wider text-zinc-400 uppercase">
              <Laptop className="h-3 w-3 text-sky-400" />
              <span>3 · Target Computer</span>
            </div>
            <div className="grid grid-cols-2 gap-1.5">
              {SPACE_COMPUTER_TARGETS.map((target) => {
                const active = computer === target.id
                return (
                  <button
                    key={target.id}
                    type="button"
                    data-testid={`spawn-computer-${target.id}`}
                    onClick={() => setComputer(target.id)}
                    className={`rounded-lg border px-2.5 py-1.5 text-left text-[11px] font-medium transition-colors ${
                      active
                        ? dark
                          ? 'border-sky-400 bg-sky-500/20 text-sky-100'
                          : 'border-sky-500 bg-sky-50 text-sky-950'
                        : dark
                          ? 'border-zinc-800 bg-zinc-950/60 text-zinc-300 hover:border-zinc-700'
                          : 'border-zinc-200 bg-zinc-50 text-zinc-700 hover:border-zinc-300'
                    }`}
                  >
                    {target.label}
                  </button>
                )
              })}
            </div>
          </div>
        </div>

        <div className="mt-4 flex items-center justify-end gap-2">
          <button
            type="button"
            onClick={onCancel}
            className={`rounded-xl px-3 py-1.5 text-[11px] font-medium ${
              dark ? 'text-zinc-300 hover:bg-zinc-800' : 'text-zinc-600 hover:bg-zinc-100'
            }`}
          >
            Cancel
          </button>
          <button
            type="button"
            data-testid="confirm-a01-spawn"
            onClick={() =>
              onConfirm({
                roleId: pending.roleId,
                spawnMode,
                projectSlug,
                computer,
                position: pending.position
              })
            }
            className="inline-flex items-center gap-1.5 rounded-xl bg-indigo-500 px-3.5 py-1.5 text-[12px] font-semibold text-white shadow-sm transition-colors hover:bg-indigo-600"
          >
            <Sparkles className="h-3.5 w-3.5" />
            <span>Spawn on Canvas</span>
          </button>
        </div>
      </div>
    </div>
  )
}

import React from 'react'
import { ExternalLink, FolderKanban, Laptop, Trash2 } from 'lucide-react'
import {
  computerTargetMeta,
  nextComputerTarget,
  type AgentCanvasNode,
  type SpaceComputerTarget,
  type SpaceSessionKind
} from '../core/canvas-nodes'
import { AGENT_ROLE_ACCESSORIES } from '../generated/a01-roles'
import { MiniSpacewareSprite } from '../sprites/space-sprite'
import { nodeStatusMeta } from './NodeResizeHandles'

export function AgentNodeCard({
  node,
  dark,
  onOpenSession,
  onSwitchComputer,
  onDelete
}: {
  node: AgentCanvasNode
  dark: boolean
  onOpenSession?: (sessionId: string, kind: SpaceSessionKind) => void
  onSwitchComputer?: (nodeId: string, nextComputer: SpaceComputerTarget) => void
  onDelete?: (nodeId: string) => void
}): React.JSX.Element {
  const roleMeta = AGENT_ROLE_ACCESSORIES[node.roleId]
  const status = nodeStatusMeta(node.status)
  const computer = computerTargetMeta(node.computer)
  const isEmployee = node.spawnMode === 'long-term-employee'

  return (
    <div
      data-testid={`agent-node-${node.id}`}
      className={`flex h-full w-full flex-col justify-between rounded-2xl border p-3.5 shadow-xl backdrop-blur-md transition-colors ${
        dark
          ? 'border-indigo-500/45 bg-zinc-900/94 text-zinc-100'
          : 'border-indigo-300 bg-white/95 text-zinc-900'
      }`}
    >
      <div className="flex items-start justify-between gap-2.5">
        <div className="flex min-w-0 items-center gap-2.5">
          <div
            className={`flex h-10 w-10 shrink-0 items-center justify-center rounded-xl border ${
              dark ? 'border-indigo-400/40 bg-indigo-500/15' : 'border-indigo-200 bg-indigo-50'
            }`}
          >
            <MiniSpacewareSprite
              role={node.roleId}
              busy={node.status === 'working'}
              attention={node.status === 'waiting'}
              awake={node.status === 'working' || node.status === 'waiting'}
              size={30}
            />
          </div>
          <div className="min-w-0">
            <div className="flex items-center gap-1.5">
              <span
                data-testid={`agent-mode-${node.id}`}
                className={`rounded px-1.5 py-0.5 text-[9px] font-semibold ${
                  isEmployee
                    ? dark
                      ? 'bg-violet-500/20 text-violet-200'
                      : 'bg-violet-100 text-violet-800'
                    : dark
                      ? 'bg-amber-500/20 text-amber-200'
                      : 'bg-amber-100 text-amber-800'
                }`}
              >
                {isEmployee ? '🧠 Long-Term Employee' : '⚡ Temporary Worker'}
              </span>
            </div>
            <div className="mt-0.5 truncate text-[13px] font-semibold leading-tight">
              {node.title}
            </div>
            <div className="truncate text-[10px] text-zinc-400">{roleMeta.tagline}</div>
          </div>
        </div>

        <span
          className={`inline-flex shrink-0 items-center gap-1 rounded-full border px-2 py-0.5 text-[10px] font-semibold ${
            dark ? status.pillClassDark : status.pillClassLight
          }`}
        >
          <span className={`h-1.5 w-1.5 rounded-full ${status.dotClass}`} />
          <span>
            {status.emoji} {status.label}
          </span>
        </span>
