        </div>

        <div className="flex items-center gap-1">
          {node.sessionId && onOpenSession && (
            <button
              type="button"
              onPointerDown={(e) => e.stopPropagation()}
              onClick={(e) => {
                e.stopPropagation()
                onOpenSession(node.sessionId!, 'orca-agent')
              }}
              className={`inline-flex items-center gap-1 rounded-md border px-2 py-0.5 text-[10px] font-semibold ${
                dark
                  ? 'border-zinc-600 bg-zinc-800 text-zinc-100 hover:bg-zinc-700'
                  : 'border-zinc-300 bg-zinc-900 text-white hover:bg-zinc-800'
              }`}
            >
              <span>Open</span>
              <ExternalLink className="h-2.5 w-2.5" />
            </button>
          )}
          {!node.locked && onDelete && (
            <button
              type="button"
              aria-label="Remove A01 agent card"
              onPointerDown={(e) => e.stopPropagation()}
              onClick={(e) => {
                e.stopPropagation()
                onDelete(node.id)
              }}
              className={`inline-flex h-6 w-6 items-center justify-center rounded-md transition-colors ${
                dark
                  ? 'text-zinc-500 hover:bg-rose-500/20 hover:text-rose-300'
                  : 'text-zinc-400 hover:bg-rose-50 hover:text-rose-600'
              }`}
            >
              <Trash2 className="h-3 w-3" />
            </button>
          )}
        </div>
      </div>
    </div>
  )
}

import React from 'react'
import type {
  C02ProjectLiveRef,
  SessionCanvasNode,
  SpaceCanvasNode,
  SpaceComputerTarget,
  SpaceSessionKind
} from '../core/canvas-nodes'
import type { Point } from '../core/space'
import type { CardinalSide } from '../core/whiteboard-kit'
import type { Handler } from '../penpot-mpl/resize-handles'
import type { ToolbarToolMode } from '../whiteboard-toolbar'
import { AgentNodeCard } from './AgentNodeCard'
import { NodePortHandles, NodeResizeHandles } from './NodeResizeHandles'
import { ProjectNodeCard } from './ProjectNodeCard'
import { SessionNodeCard } from './SessionNodeCard'

export type NodeBoxOverride = {
  id: string
  x: number
  y: number
  w: number
  h: number
}

export function CanvasNodeLayer({
  nodes,
  dark,
  toolMode,
  selectedNodeIds,
  arrowTargetNodeId,
  nodeOffset,
  multiDragDelta,
  nodeSizeOverride,
  onSelectNode,
  onStartDragNode,
  onStartResizeNode,
  onStartPortArrow,
  onEraseNode,
  onOpenSession,
  onTogglePinSession,
  onSwitchComputer,
  onOpenProjectRef,
  onDeleteNode,
  onContextMenuNode
}: {
  nodes: readonly SpaceCanvasNode[]
  dark: boolean
  toolMode: ToolbarToolMode
  selectedNodeIds: ReadonlySet<string>
  arrowTargetNodeId?: string
  nodeOffset: { id: string; dx: number; dy: number } | null
  multiDragDelta: Point | null
  nodeSizeOverride: NodeBoxOverride | null
  onSelectNode: (nodeId: string, additive: boolean) => void
  onStartDragNode: (nodeId: string, event: React.PointerEvent) => void
  onStartResizeNode: (nodeId: string, handle: Handler, event: React.PointerEvent) => void
  onStartPortArrow: (nodeId: string, side: CardinalSide, event: React.PointerEvent) => void
  onEraseNode: (nodeId: string) => void
  onOpenSession?: (sessionId: string, kind: SpaceSessionKind) => void
  onTogglePinSession?: (node: SessionCanvasNode, nextPinned: boolean) => void
  onSwitchComputer?: (nodeId: string, nextComputer: SpaceComputerTarget) => void
  onOpenProjectRef?: (projectSlug: string, ref: C02ProjectLiveRef) => void
  onDeleteNode?: (nodeId: string) => void
  onContextMenuNode?: (nodeId: string, event: React.MouseEvent) => void
}): React.JSX.Element | null {
  if (nodes.length === 0) {
    return null
  }

  return (
    <>
      {nodes.map((node, index) => {
        if (node.hidden) {
          return null
        }
        const selected = selectedNodeIds.has(node.id)
        const isArrowTarget = arrowTargetNodeId === node.id
        const sizeOvr = nodeSizeOverride?.id === node.id ? nodeSizeOverride : null
        const singleOff = nodeOffset?.id === node.id ? nodeOffset : null
        const groupOff = selected && multiDragDelta ? multiDragDelta : null
        const x = (sizeOvr ? sizeOvr.x : node.x) + (singleOff?.dx ?? 0) + (groupOff?.x ?? 0)
        const y = (sizeOvr ? sizeOvr.y : node.y) + (singleOff?.dy ?? 0) + (groupOff?.y ?? 0)
        const w = sizeOvr ? sizeOvr.w : node.w
        const h = sizeOvr ? sizeOvr.h : node.h
        const z = 20 + (node.zIndex ?? index)

        return (
          <div
            key={node.id}
            data-space-node={node.id}
            data-space-node-kind={node.kind}
            style={{
              transform: `translate3d(${x}px, ${y}px, 0)`,
              width: w,
              height: h,
              zIndex: selected ? z + 60 : z
            }}
            onContextMenu={(event) => {
              if (onContextMenuNode) {
                event.preventDefault()
                event.stopPropagation()
                onContextMenuNode(node.id, event)
              }
            }}
            onPointerDown={(event) => {
              if (event.button !== 0) {
                return
              }
              event.stopPropagation()
              if (toolMode === 'eraser') {
                if (!node.locked) {
                  onEraseNode(node.id)
                }
                return
              }
              if (toolMode === 'arrow') {
                onStartPortArrow(node.id, 'right', event)
                return
              }
              const additive = event.shiftKey || event.metaKey || event.ctrlKey
              onSelectNode(node.id, additive)
              if (!node.locked && toolMode === 'select') {
                onStartDragNode(node.id, event)
              }
            }}
            onDoubleClick={(event) => {
              event.stopPropagation()
              if (node.kind === 'session') {
                onOpenSession?.(node.sessionId, node.sessionKind)
              } else if (node.kind === 'agent' && node.sessionId) {
                onOpenSession?.(node.sessionId, 'orca-agent')
              }
            }}
            className={`group/canvas-node pointer-events-auto absolute top-0 left-0 select-none ${
              node.locked ? 'cursor-default' : 'cursor-grab active:cursor-grabbing'
            } ${
              isArrowTarget
                ? 'rounded-2xl ring-2 ring-sky-400 ring-offset-2 ring-offset-transparent'
                : selected
                  ? 'rounded-2xl ring-2 ring-indigo-400'
                  : ''
            }`}
          >
            {node.kind === 'session' ? (
              <SessionNodeCard
                node={node}
                dark={dark}
                onOpenSession={onOpenSession}
                onTogglePin={onTogglePinSession}
                onSwitchComputer={onSwitchComputer}
                onDelete={onDeleteNode}
              />
            ) : node.kind === 'agent' ? (
              <AgentNodeCard
                node={node}
                dark={dark}
                onOpenSession={onOpenSession}
                onSwitchComputer={onSwitchComputer}
                onDelete={onDeleteNode}
              />
            ) : (
              <ProjectNodeCard
                node={node}
                dark={dark}
                onOpenProjectRef={onOpenProjectRef}
                onDelete={onDeleteNode}
              />
            )}

            {!node.locked && selected && toolMode === 'select' && (
              <NodeResizeHandles
                dark={dark}
                onStartResize={(handle, event) => onStartResizeNode(node.id, handle, event)}
              />
            )}

            <NodePortHandles
              nodeId={node.id}
              visible={toolMode === 'arrow' || isArrowTarget || selected}
              onStartPortArrow={onStartPortArrow}
            />
          </div>
        )
      })}
    </>
  )
}

import React from 'react'
import { CARDINAL_PORTS, type CardinalSide } from '../core/whiteboard-kit'
import type { SpaceNodeLiveStatus } from '../core/canvas-nodes'
import { HANDLERS, type Handler } from '../penpot-mpl/resize-handles'

export type NodeResizeHandle = Handler

const HANDLE_POSITIONS: Record<Handler, string> = {
  'top-left': '-top-1.5 -left-1.5 cursor-nwse-resize',
  top: '-top-1.5 left-1/2 -translate-x-1/2 cursor-ns-resize',
  'top-right': '-top-1.5 -right-1.5 cursor-nesw-resize',
  right: 'top-1/2 -right-1.5 -translate-y-1/2 cursor-ew-resize',
  'bottom-right': '-bottom-1.5 -right-1.5 cursor-nwse-resize',
  bottom: '-bottom-1.5 left-1/2 -translate-x-1/2 cursor-ns-resize',
  'bottom-left': '-bottom-1.5 -left-1.5 cursor-nesw-resize',
  left: 'top-1/2 -left-1.5 -translate-y-1/2 cursor-ew-resize'
}

export function NodeResizeHandles({
  dark,
  onStartResize
}: {
  dark: boolean
  onStartResize: (handle: Handler, event: React.PointerEvent) => void
}): React.JSX.Element {
  return (
    <>
      {HANDLERS.map((handle) => (
        <div
          key={handle}
          data-node-resize-handle={handle}
          onPointerDown={(event) => {
            event.stopPropagation()
            onStartResize(handle, event)
          }}
          className={`pointer-events-auto absolute z-30 h-2.5 w-2.5 rounded-sm border shadow-xs transition-transform hover:scale-125 ${HANDLE_POSITIONS[handle]} ${
            dark ? 'border-sky-300 bg-zinc-950' : 'border-sky-600 bg-white'
          }`}
        />
      ))}
    </>
  )
}

const PORT_POSITIONS: Record<CardinalSide, string> = {
  top: '-top-2.5 left-1/2 -translate-x-1/2',
  right: 'top-1/2 -right-2.5 -translate-y-1/2',
  bottom: '-bottom-2.5 left-1/2 -translate-x-1/2',
  left: 'top-1/2 -left-2.5 -translate-y-1/2'
}

export function NodePortHandles({
  nodeId,
  visible,
  onStartPortArrow
}: {
  nodeId: string
  visible: boolean
  onStartPortArrow: (nodeId: string, side: CardinalSide, event: React.PointerEvent) => void
}): React.JSX.Element {
  return (
    <>
      {CARDINAL_PORTS.map((port) => (
        <button
          key={port.side}
          type="button"
          data-node-port={`${nodeId}:${port.side}`}
          title={`Connect magnetic arrow (${port.side})`}
          aria-label={`Connect magnetic arrow from ${port.side}`}
          onPointerDown={(event) => {
            event.stopPropagation()
            onStartPortArrow(nodeId, port.side, event)
          }}
          className={`pointer-events-auto absolute z-30 flex h-4 w-4 items-center justify-center rounded-full border border-sky-300 bg-sky-500 text-[9px] font-bold text-white shadow-sm transition-all hover:scale-125 ${PORT_POSITIONS[port.side]} ${
            visible ? 'opacity-95' : 'opacity-0 group-hover/canvas-node:opacity-90'
          }`}
        />
      ))}
    </>
  )
}

export function nodeStatusMeta(status: SpaceNodeLiveStatus): {
  emoji: string
  label: string
  dotClass: string
  pillClassDark: string
  pillClassLight: string
} {
  if (status === 'working') {
    return {
      emoji: '🟠',
      label: 'Working',
      dotClass: 'bg-amber-400 animate-pulse',
      pillClassDark: 'border-amber-400/35 bg-amber-500/15 text-amber-200',
      pillClassLight: 'border-amber-500/40 bg-amber-50 text-amber-800'
    }
  }
  if (status === 'waiting') {
    return {
      emoji: '🔴',
      label: 'Waiting ask',
      dotClass: 'bg-rose-500 animate-pulse',
      pillClassDark: 'border-rose-400/45 bg-rose-500/20 text-rose-200',
      pillClassLight: 'border-rose-500/45 bg-rose-50 text-rose-800'
    }
  }
  if (status === 'done') {
    return {
      emoji: '🟢',
      label: 'Done',
      dotClass: 'bg-emerald-400',
      pillClassDark: 'border-emerald-400/35 bg-emerald-500/15 text-emerald-200',
      pillClassLight: 'border-emerald-500/40 bg-emerald-50 text-emerald-800'
    }
  }
  return {
    emoji: '🟢',
    label: 'Idle',
    dotClass: 'bg-emerald-400',
    pillClassDark: 'border-emerald-400/30 bg-emerald-500/10 text-emerald-200',
    pillClassLight: 'border-emerald-500/35 bg-emerald-50 text-emerald-700'
  }
}

