                    <span className="font-mono text-[10px] text-zinc-400">{project.slug}</span>
                  </div>
                  <div className="mt-0.5 text-[10px] text-zinc-400">
                    Products: {project.productsCount} · {project.channels.slice(0, 2).join(', ')}
