import type { SelRect } from './snap-distance'

export type SnapPoint = { x: number; y: number }

/** rect->snap-points: the 4 corners and the center. */
export function rectToSnapPoints(r: SelRect): SnapPoint[] {
  return [
    { x: r.x1, y: r.y1 },
    { x: r.x2, y: r.y1 },
    { x: r.x2, y: r.y2 },
    { x: r.x1, y: r.y2 },
    { x: r.x1 + (r.x2 - r.x1) / 2, y: r.y1 + (r.y2 - r.y1) / 2 }
  ]
}

/**
 * snap-accuracy-ranges + get-min-distance-snap for one axis: for every moving coordinate, query the
 * candidates in [c - accuracy, c + accuracy] and keep the closest pair as [from, to].
 */
export function getMinDistanceSnap(
  coords: readonly number[],
  accuracy: number,
  query: (lo: number, hi: number) => Iterable<number>
): [from: number, to: number] | null {
  let best: [number, number] | null = null
  let bestDist = Infinity
  for (const c of coords) {
    for (const value of query(c - accuracy, c + accuracy)) {
      const dist = Math.abs(value - c)
      if (dist < bestDist) {
        bestDist = dist
        best = [c, value]
      }
    }
  }
  return best
}

/** snap->vector: [[from-x to-x] [from-y to-y]] → the move vector, or null when neither axis snapped. */
export function snapToVector(
  x: [number, number] | null,
  y: [number, number] | null
): { x: number; y: number } | null {
  if (!x && !y) {
    return null
  }
  return { x: x ? x[1] - x[0] : 0, y: y ? y[1] - y[0] : 0 }
}

import React from 'react'
import { Pin } from 'lucide-react'
import { isPinnable, isPinned, type PinKind } from '../core/pinned-sessions'
import { useSpaceCanvasHost } from '../host-adapter'
import { pinSession, unpinSession, usePinnedState } from './pinned-store'

export type PinButtonProps = {
  tabId: string
  worktreeId?: string
  name: string
  size?: number
  kind?: PinKind
  className?: string
}

export function PinButton({
  tabId,
  worktreeId,
  name,
  size = 14,
  kind = 'agent',
  className = ''
}: PinButtonProps): React.JSX.Element | null {
  const host = useSpaceCanvasHost()
  const pinned = isPinned(usePinnedState(), tabId)
  if (!isPinnable(kind)) {
    return null
  }
  return (
    <button
      type="button"
      data-pin-button={tabId}
      data-pinned={pinned ? 'true' : 'false'}
      aria-pressed={pinned}
      aria-label={pinned ? `Unpin ${name}` : `Pin ${name}`}
      title={pinned ? 'Unpin session' : 'Pin session as a floating square'}
      onPointerDown={(event) => event.stopPropagation()}
      onKeyDown={(event) => {
        if (event.key === 'Enter' || event.key === ' ') {
          event.stopPropagation()
        }
      }}
      onClick={(event) => {
        event.stopPropagation()
        if (pinned) {
          unpinSession(tabId)
          host.onPinSession?.(tabId, false)
        } else {
          const wt = worktreeId ?? host.activeWorktreeId ?? ''
          if (pinSession({ tabId, worktreeId: wt, name, kind })) {
            host.onPinSession?.(tabId, true)
          }
        }
      }}
      className={`inline-flex shrink-0 cursor-pointer items-center justify-center rounded p-0.5 text-current transition hover:bg-white/10 focus-visible:outline-2 focus-visible:outline-offset-1 ${className}`}
    >
      <Pin size={size} fill={pinned ? 'currentColor' : 'none'} aria-hidden="true" />
    </button>
  )
}

import { passedDragThreshold } from '../penpot-mpl/drag-threshold'
import type { Pt } from '../core/pinned-sessions'
import type { SpaceAgent } from '../core/space'

export const DOUBLE_CLICK_MS = 400
export const CLICK_SLOP_PX = 4
export const CLICK_MAX_MS = 800

export type Release = { t: number; pt: Pt; onTag: boolean }

export function isDoubleClick(prev: Release | null, now: Release): boolean {
  return (
    prev !== null &&
    now.t - prev.t <= DOUBLE_CLICK_MS &&
    !passedDragThreshold(prev.pt, now.pt, CLICK_SLOP_PX)
  )
}

export function pressedOnTag(target: EventTarget | null): boolean {
  return Boolean((target as HTMLElement | null)?.closest?.('[data-pin-name-tag], input'))
}

export type PinStatus = 'needs-you' | 'working' | 'idle'

export function pinStatus(agent: Pick<SpaceAgent, 'attention' | 'busy'> | null): PinStatus {
  if (agent?.attention) {
    return 'needs-you'
  }
  return agent?.busy ? 'working' : 'idle'
}

