const PIN_STYLE = `
.orca-pin-glide { transition: opacity 180ms ease, transform 180ms ease; }
.orca-pin-leaving { opacity: 0 !important; transform: scale(0.92) !important; pointer-events: none !important; }
`

export function ensurePinStyle(): void {
  if (typeof document === 'undefined') {
    return
  }
  let el = document.getElementById(PIN_STYLE_ID)
  if (!el) {
    el = document.createElement('style')
    el.id = PIN_STYLE_ID
    document.head.appendChild(el)
  }
  if (el.textContent !== PIN_STYLE) {
    el.textContent = PIN_STYLE
  }
}

import React, { useEffect, useRef, useState } from 'react'
import { createPortal } from 'react-dom'
import { getBullseyeTheme } from '../core/theme'
import { focusMenuOnOpen, handleMenuKey } from '../menu-keys'
import { clampMenuPoint } from '../menu-position'
import { currentViewport } from './pinned-store'

export type PinMenuItem =
  | '-'
  | {
      label: string
      onSelect: () => void
      tone?: 'danger'
      disabled?: boolean
      disabledReason?: string
    }

const MENU_W = 168
const ROW_H = 30

export function usePinMenu(): {
  at: { x: number; y: number } | null
  close: () => void
  handlers: {
    onContextMenu: (e: React.MouseEvent) => void
    onKeyDown: (e: React.KeyboardEvent) => void
  }
} {
  const [at, setAt] = useState<{ x: number; y: number } | null>(null)
  return {
    at,
    close: () => setAt(null),
    handlers: {
      onContextMenu: (e) => {
        e.preventDefault()
        e.stopPropagation()
        setAt({ x: Math.round(e.clientX), y: Math.round(e.clientY) })
      },
      onKeyDown: (e) => {
        if ((e.shiftKey && e.key === 'F10') || e.key === 'ContextMenu') {
          e.preventDefault()
          e.stopPropagation()
          const r = (e.currentTarget as HTMLElement).getBoundingClientRect()
          setAt({ x: Math.round(r.left + Math.min(24, r.width / 2)), y: Math.round(r.top + 24) })
        }
      }
    }
  }
}

export function PinMenu({
  at,
  items,
  label,
  dark,
  onClose,
  returnFocus
}: {
  at: { x: number; y: number } | null
  items: readonly PinMenuItem[]
  label: string
  dark: boolean
  onClose: () => void
  returnFocus?: () => HTMLElement | null
}): React.JSX.Element | null {
  const p = getBullseyeTheme(dark)
  const menuRef = useRef<HTMLDivElement | null>(null)
  useEffect(() => {
    if (!at) {
      return undefined
    }
    const outside = (e: PointerEvent): void => {
      if (!menuRef.current?.contains(e.target as Node)) {
        onClose()
      }
    }
    window.addEventListener('pointerdown', outside, true)
    window.addEventListener('resize', onClose)
    window.addEventListener('blur', onClose)
    return () => {
      window.removeEventListener('pointerdown', outside, true)
      window.removeEventListener('resize', onClose)
      window.removeEventListener('blur', onClose)
    }
  }, [at, onClose])
  if (!at || typeof document === 'undefined') {
    return null
  }
  const rows = items.filter((i) => i !== '-').length
  const pos = clampMenuPoint(
    at,
    { w: MENU_W, h: rows * ROW_H + (items.length - rows) * 9 + 12 },
    currentViewport()
  )
  return createPortal(
    <div
      ref={(node) => {
        menuRef.current = node
        focusMenuOnOpen(node)
      }}
      role="menu"
      aria-label={label}
      data-pin-menu
      onPointerDown={(e) => e.stopPropagation()}
      onClick={(e) => e.stopPropagation()}
      onContextMenu={(e) => e.preventDefault()}
      onKeyDown={(e) => {
        const menu = menuRef.current
        if (menu && handleMenuKey(e, menu, onClose, returnFocus?.() ?? null)) {
          return
        }
        e.stopPropagation()
      }}
      style={{
        left: pos.x,
        top: pos.y,
        width: MENU_W,
        background: p.card,
        borderColor: p.borderStrong,
        color: p.ink,
        boxShadow: p.elevation
      }}
      className="pointer-events-auto fixed z-[49] select-none rounded-xl border p-1 text-xs"
    >
      {items.map((item, i) =>
        item === '-' ? (
          <div
            key={`sep-${i}`}
            role="separator"
            style={{ background: p.border }}
            className="mx-1 my-1 h-px"
          />
        ) : (
          <button
            key={item.label}
            type="button"
            role="menuitem"
            tabIndex={-1}
            disabled={item.disabled}
            title={item.disabled ? item.disabledReason : undefined}
            data-pin-menu-item={item.label}
            onClick={() => {
              onClose()
              item.onSelect()
            }}
            style={{ color: item.tone === 'danger' ? p.badText : p.ink }}
            className="flex h-[28px] w-full cursor-pointer items-center rounded-lg px-2.5 text-left font-semibold outline-none hover:brightness-95 focus-visible:ring-2 disabled:cursor-not-allowed disabled:opacity-50"
          >
            {item.label}
          </button>
        )
      )}
    </div>,
    document.body
  )
}

export function pinMenuItems(a: {
  onOpenFull: () => void
  onRename: () => void
  onReset: () => void
  onUnpin: () => void
}): PinMenuItem[] {
  return [
    { label: 'Open full', onSelect: a.onOpenFull },
    { label: 'Rename', onSelect: a.onRename },
    { label: 'Reset position', onSelect: a.onReset },
    '-',
    { label: 'Unpin', onSelect: a.onUnpin, tone: 'danger' }
  ]
}

import React, { useState } from 'react'
import { isImeOwnedKeyboardEvent } from '../core/ime-guard'
import type { BullseyeTheme } from '../core/theme'

export function PinNameTag({
  name,
  p,
  onCommit,
  editing,
  setEditing,
  variant = 'pill'
}: {
  name: string
  p: BullseyeTheme
  onCommit: (name: string) => void
  editing: boolean
  setEditing: (editing: boolean) => void
  variant?: 'pill' | 'header'
}): React.JSX.Element {
  const [draft, setDraft] = useState(name)
  if (editing) {
    const done = (save: boolean): void => {
      setEditing(false)
      if (save && draft.trim() && draft.trim() !== name) {
        onCommit(draft.trim())
      }
    }
    return (
      <input
        autoFocus
        aria-label="Name tag"
        value={draft}
        onChange={(e) => setDraft(e.target.value)}
        onFocus={(e) => e.currentTarget.select()}
        onPointerDown={(e) => e.stopPropagation()}
        onBlur={() => done(true)}
        onKeyDown={(e) => {
          e.stopPropagation()
          if (isImeOwnedKeyboardEvent(e)) {
            return
          }
          if (e.key === 'Enter') {
            e.preventDefault()
            done(true)
          } else if (e.key === 'Escape') {
            e.preventDefault()
            setDraft(name)
            done(false)
          }
        }}
        style={{ background: p.well, color: p.ink, borderColor: p.accentBorder }}
        className={
          variant === 'header'
            ? 'min-w-0 flex-1 rounded-md border px-1.5 py-px text-[12px] font-semibold outline-none'
            : 'w-[60px] rounded-full border px-1.5 py-px text-center text-[10px] font-semibold outline-none'
        }
      />
    )
  }
  return (
    <span
      data-pin-name-tag
      title={name}
      onDoubleClick={(e) => {
        e.stopPropagation()
        setDraft(name)
        setEditing(true)
      }}
      style={variant === 'header' ? { color: p.ink } : { background: p.well, color: p.body }}
      className={
        variant === 'header'
          ? 'block min-w-0 flex-1 cursor-text truncate text-left text-[12px] font-semibold'
          : 'block max-w-[60px] cursor-text truncate rounded-full px-1.5 py-px text-center text-[10px] font-semibold'
      }
    >
      {name}
    </span>
  )
}

import { getKeepOuts, pushOutOfKeepOut } from '../core/keep-out'
import { createSnapIndex, snapRect } from '../core/whiteboard-snap'
import {
  getHandlerResizeOrigin,
  getResizeScale,
  resizeRect,
  type Handler
} from '../penpot-mpl/resize-handles'
import {
  BOTTOM_SAFE,
  SNAP_PX,
  TOP_SAFE,
  WIN_MAX_FRACTION,
  WIN_MIN,
  clampSquare,
  clampWindow,
  type Box,
  type Pt,
  type Viewport
} from '../core/pinned-sessions'

export function keepOutBoxes(): Box[] {
  return getKeepOuts().map((z) => ({
    x: z.left,
    y: z.top,
    w: z.right - z.left,
    h: z.bottom - z.top
  }))
}

export function clearOfKeepOut(b: Box): Box {
  const r = pushOutOfKeepOut({ left: b.x, top: b.y, right: b.x + b.w, bottom: b.y + b.h }, 8)
  return { x: Math.round(r.left), y: Math.round(r.top), w: b.w, h: b.h }
}

export function snapSquareMove(
  start: Box,
  dx: number,
  dy: number,
  others: readonly Box[],
  vp: Viewport,
  disabled = false
): Pt {
  const area: Box = { x: 0, y: TOP_SAFE, w: vp.w, h: vp.h - TOP_SAFE - BOTTOM_SAFE }
  const index = createSnapIndex([...others, area])
  const moved: Box = { ...start, x: start.x + dx, y: start.y + dy }
  const r = snapRect(moved, index, 1, { threshold: SNAP_PX, disabled })
  return clampSquare({ x: moved.x + r.dx, y: moved.y + r.dy }, vp)
}

type AxisFit = { a: number; b: number }

function fitAxis(
  a: number,
  b: number,
  lo: number,
  hi: number,
  min: number,
  max: number,
  movesA: boolean,
  movesB: boolean
): AxisFit {
  let na = Math.max(a, lo)
  let nb = Math.min(b, hi)
  const target = Math.min(Math.max(nb - na, min), max)
  if (nb - na !== target) {
    if (movesA && !movesB) {
      na = nb - target
    } else if (movesB && !movesA) {
      nb = na + target
    } else {
      const mid = (na + nb) / 2
      na = mid - target / 2
      nb = mid + target / 2
    }
  }
  if (na < lo) {
    nb += lo - na
    na = lo
  }
  if (nb > hi) {
    na -= nb - hi
    nb = hi
  }
  return { a: na, b: nb }
}

type Bounds = { lo: number; hi: number }

function maxScaleOnAxis(a: number, b: number, o: number, bounds: Bounds): number {
  let m = Infinity
  if (a < o) {
    m = Math.min(m, (o - bounds.lo) / (o - a))
  }
  if (b > o) {
    m = Math.min(m, (bounds.hi - o) / (b - o))
  }
  return m
}

function resizeLocked(start: Box, handler: Handler, from: Pt, to: Pt, vp: Viewport): Box {
  const rect = { x: start.x, y: start.y, width: start.w, height: start.h }
  const raw = getResizeScale(rect, handler, from, to, true).x
  const o = getHandlerResizeOrigin(rect, handler)
  const maxW = Math.max(WIN_MIN.w, vp.w * WIN_MAX_FRACTION)
  const maxH = Math.max(WIN_MIN.h, (vp.h - TOP_SAFE - BOTTOM_SAFE) * WIN_MAX_FRACTION)
  const sMin = Math.max(WIN_MIN.w / start.w, WIN_MIN.h / start.h)
  const sMax = Math.min(
    maxW / start.w,
    maxH / start.h,
    maxScaleOnAxis(start.x, start.x + start.w, o.x, { lo: 0, hi: vp.w }),
    maxScaleOnAxis(start.y, start.y + start.h, o.y, { lo: TOP_SAFE, hi: vp.h - BOTTOM_SAFE })
  )
  const s = Math.max(sMin, Math.min(Math.max(0, raw), sMax))
  const w = Math.round(start.w * s)
  const h = Math.round(start.h * s)
  return clampWindow(
    { x: Math.round(o.x + (start.x - o.x) * s), y: Math.round(o.y + (start.y - o.y) * s), w, h },
    vp
  )
}

export function resizeWindowByHandle(
  start: Box,
  handler: Handler,
  from: Pt,
  to: Pt,
  vp: Viewport,
  lock = false
): Box {
  if (lock) {
    return resizeLocked(start, handler, from, to, vp)
  }
  const r = {
    ...resizeRect({ x: start.x, y: start.y, width: start.w, height: start.h }, handler, from, to)
  }
  const scale = getResizeScale(
    { x: start.x, y: start.y, width: start.w, height: start.h },
    handler,
    from,
    to
  )
  if (scale.x < 0) {
    r.x = handler.includes('left') ? start.x + start.w : start.x
    r.width = 0
  }
  if (scale.y < 0) {
    r.y = handler.includes('top') ? start.y + start.h : start.y
    r.height = 0
  }
  const maxW = Math.max(WIN_MIN.w, vp.w * WIN_MAX_FRACTION)
  const maxH = Math.max(WIN_MIN.h, (vp.h - TOP_SAFE - BOTTOM_SAFE) * WIN_MAX_FRACTION)
  const x = fitAxis(
    r.x,
    r.x + r.width,
    0,
    vp.w,
    WIN_MIN.w,
    maxW,
    handler.includes('left'),
    handler.includes('right')
  )
  const y = fitAxis(
    r.y,
    r.y + r.height,
    TOP_SAFE,
    vp.h - BOTTOM_SAFE,
    WIN_MIN.h,
    maxH,
    handler.includes('top'),
    handler.includes('bottom')
  )
  return {
    x: Math.round(x.a),
    y: Math.round(y.a),
    w: Math.round(x.b - x.a),
    h: Math.round(y.b - y.a)
  }
}

import React, { useEffect, useRef, useState } from 'react'
import { createPortal } from 'react-dom'
import { isAgentSession } from '../core/agent-identity'
import { openAsksForAgent } from '../core/ask-pins'
import { subscribeKeepOut } from '../core/keep-out'
import { SQUARE_H, SQUARE_W, type Box, type PinnedSession } from '../core/pinned-sessions'
import { resolveAgentGoalId, type SpaceAgent, type SpaceState } from '../core/space'
import { getBullseyeTheme } from '../core/theme'
import { useSpaceCanvasHost } from '../host-adapter'
import { ensurePinStyle } from './pin-click'
import { clearOfKeepOut, keepOutBoxes } from './pinned-geometry'
import { PinnedSquare } from './pinned-square'
import {
  currentViewport,
  dispatchPinned,
  getPinnedState,
  onPinnedToast,
  requestPinFocus,
  usePinnedState
} from './pinned-store'
import { PinnedWindow } from './pinned-window'

export const PIN_LAYER_Z = 49
const TOAST_MS = 2400

export type PinnedSessionsLayerProps = {
  agents: readonly SpaceAgent[]
  space?: SpaceState
  dark?: boolean
  onActivate?: (tabId: string) => void
  onRename?: (pin: PinnedSession, agent: SpaceAgent | null, name: string) => void
}

export function PinnedSessionsLayer({
  agents,
  space,
  dark = true,
  onActivate,
  onRename
}: PinnedSessionsLayerProps): React.JSX.Element | null {
  const host = useSpaceCanvasHost()
  const state = usePinnedState()
  const p = getBullseyeTheme(dark)
  const [toast, setToast] = useState<string | null>(null)
  const squareButtons = useRef(new Map<string, HTMLButtonElement | null>())

  useEffect(ensurePinStyle, [])

  useEffect(() => {
    let timer: ReturnType<typeof setTimeout> | undefined
    const off = onPinnedToast((text) => {
      setToast(text)
      clearTimeout(timer)
      timer = setTimeout(() => setToast(null), TOAST_MS)
    })
    return () => {
      off()
      clearTimeout(timer)
    }
  }, [])

  useEffect(
    () =>
      subscribeKeepOut(() => {
        for (const pin of getPinnedState().pins) {
          const vp = currentViewport()
          if (pin.open) {
            dispatchPinned({
              type: 'setWindow',
              tabId: pin.tabId,
              box: clearOfKeepOut(pin.win),
              vp
            })
          } else {
            const cleared = clearOfKeepOut({
              x: pin.square.x,
              y: pin.square.y,
              w: SQUARE_W,
              h: SQUARE_H
            })
            dispatchPinned({
              type: 'moveSquare',
              tabId: pin.tabId,
              to: { x: cleared.x, y: cleared.y },
              vp
            })
          }
        }
      }),
    []
  )

  if (typeof document === 'undefined' || (state.pins.length === 0 && !toast)) {
    return null
  }

  const squareRects = (except: string): Box[] =>
    state.pins
      .filter((pin) => pin.tabId !== except && !pin.open)
      .map((pin) => ({ x: pin.square.x, y: pin.square.y, w: SQUARE_W, h: SQUARE_H }))

  const closeWindow = (pin: PinnedSession): void => {
    dispatchPinned({ type: 'close', tabId: pin.tabId })
    setTimeout(() => squareButtons.current.get(pin.tabId)?.focus(), 0)
  }

  const openFull = (pin: PinnedSession): void => {
    onActivate?.(pin.tabId)
    host.onOpenSession?.(pin.tabId, pin.kind === 'terminal' ? 'orca-terminal' : 'orca-agent')
    dispatchPinned({ type: 'close', tabId: pin.tabId })
  }

  const validGoals = space ? new Set(space.goals.map((g) => g.id)) : new Set<string>()

  return createPortal(
    <div
      data-pinned-sessions-layer
      style={{ pointerEvents: 'none', position: 'fixed', inset: 0, zIndex: PIN_LAYER_Z }}
    >
      {state.pins.map((pin) => {
        const agent = agents.find((a) => a.id === pin.tabId || a.unifiedTabId === pin.tabId) ?? null
        const bodyAgent: SpaceAgent | null =
          agent ??
          (pin.kind === 'agent' || pin.kind === 'terminal'
            ? { id: pin.tabId, name: pin.name, agent: null, kind: pin.kind }
            : null)
        const goalId = space && bodyAgent ? resolveAgentGoalId(space, bodyAgent, validGoals) : null
        const goal = goalId && space ? (space.goals.find((g) => g.id === goalId) ?? null) : null
        const canChat = bodyAgent !== null && isAgentSession(bodyAgent)
        const chat = pin.view === 'chat' ? true : pin.view === 'terminal' ? false : canChat
        const hasAskCard = Boolean(bodyAgent && openAsksForAgent(goal, bodyAgent).length > 0)
        const needsYouCard = Boolean(agent?.attention) && !hasAskCard

        return pin.open ? (
          <PinnedWindow
            key={pin.tabId}
            pin={pin}
            agent={agent}
            bodyAgent={bodyAgent}
            dark={dark}
            leaving={false}
            onSetBox={(box) =>
              dispatchPinned({
                type: 'setWindow',
                tabId: pin.tabId,
                box: clearOfKeepOut(box),
                vp: currentViewport()
              })
            }
            onCollapse={() => closeWindow(pin)}
            onOpenFull={() => openFull(pin)}
            onUnpin={() => {
              dispatchPinned({ type: 'unpin', tabId: pin.tabId })
              host.onPinSession?.(pin.tabId, false)
            }}
            onReset={() =>
              dispatchPinned({
                type: 'resetPosition',
                tabId: pin.tabId,
                vp: currentViewport(),
                keepOut: keepOutBoxes()
              })
            }
            onRaise={() => dispatchPinned({ type: 'raise', tabId: pin.tabId })}
            onRename={(name) => {
              dispatchPinned({ type: 'rename', tabId: pin.tabId, name })
              onRename?.(pin, agent, name)
            }}
            goal={goal}
            onAnswerAsk={
              goal && host.onAnswerAsk
                ? (ask, answer) => host.onAnswerAsk?.(goal.id, ask.id, answer)
                : undefined
            }
            chat={chat}
            canToggleView={bodyAgent !== null && (pin.kind === 'terminal' || pin.kind === 'agent')}
            onToggleView={() =>
              dispatchPinned({
                type: 'setView',
                tabId: pin.tabId,
                view: chat ? 'terminal' : 'chat'
              })
            }
            needsYouCard={needsYouCard}
          />
        ) : (
          <PinnedSquare
            key={pin.tabId}
            pin={pin}
            agent={agent}
            dark={dark}
            leaving={false}
            others={() => squareRects(pin.tabId)}
            onMove={(to) => {
              const cleared = clearOfKeepOut({ x: to.x, y: to.y, w: SQUARE_W, h: SQUARE_H })
              dispatchPinned({
                type: 'moveSquare',
                tabId: pin.tabId,
                to: { x: cleared.x, y: cleared.y },
                vp: currentViewport()
              })
            }}
            onOpen={() => {
              requestPinFocus(pin.tabId)
              dispatchPinned({
                type: 'open',
                tabId: pin.tabId,
                vp: currentViewport(),
                keepOut: keepOutBoxes()
              })
            }}
            onRename={(name) => {
              dispatchPinned({ type: 'rename', tabId: pin.tabId, name })
              onRename?.(pin, agent, name)
            }}
            onOpenFull={() => openFull(pin)}
            onReset={() =>
              dispatchPinned({
                type: 'resetPosition',
                tabId: pin.tabId,
                vp: currentViewport(),
                keepOut: keepOutBoxes()
              })
            }
            onUnpin={() => {
              dispatchPinned({ type: 'unpin', tabId: pin.tabId })
              host.onPinSession?.(pin.tabId, false)
            }}
            onEscape={() => {
              const top = state.pins.filter((q) => q.open).sort((x, y) => y.z - x.z)[0]
              if (top) {
                closeWindow(top)
              }
            }}
            buttonRef={(node) => {
              squareButtons.current.set(pin.tabId, node)
            }}
          />
        )
      })}
      {toast ? (
        <div
          role="status"
          data-pinned-toast
          data-tone="warning"
          aria-live="polite"
          style={{
            pointerEvents: 'none',
            position: 'fixed',
            bottom: 24,
            left: '50%',
            transform: 'translateX(-50%)',
            background: p.ink,
            color: p.card,
            boxShadow: p.elevation
          }}
          className="rounded-full px-3 py-1.5 text-[12px] font-semibold"
        >
          {toast}
        </div>
      ) : null}
    </div>,
    document.body
  )
}

import React, { useEffect, useRef, useState } from 'react'
import { passedDragThreshold } from '../penpot-mpl/drag-threshold'
import { SQUARE_H, SQUARE_W, type Box, type PinnedSession, type Pt } from '../core/pinned-sessions'
import type { SpaceAgent } from '../core/space'
import { getBullseyeTheme } from '../core/theme'
import { MiniSpacewareSprite, SPACEWARE_ISLAND_PALETTE } from '../sprites/space-sprite'
import { spriteRoleOf } from '../sprites/space-sprite-accessory'
import {
  CLICK_MAX_MS,
  CLICK_SLOP_PX,
  DOUBLE_CLICK_MS,
  isDoubleClick,
  pinStatus,
  pressedOnTag,
  type Release
} from './pin-click'
import { PinMenu, pinMenuItems, usePinMenu } from './pin-menu'
import { PinNameTag } from './pin-name-tag'
import { snapSquareMove } from './pinned-geometry'
import { currentViewport } from './pinned-store'

export const TAG_CLICK_MS = DOUBLE_CLICK_MS

export function PinnedSquare({
  pin,
  agent,
  dark,
  leaving,
  others,
  onMove,
  onOpen,
  onRename,
  onOpenFull,
  onReset,
  onUnpin,
  onEscape,
  buttonRef
}: {
  pin: PinnedSession
  agent: SpaceAgent | null
  dark: boolean
  leaving: boolean
  others: () => Box[]
  onMove: (to: Pt) => void
  onOpen: () => void
  onRename: (name: string) => void
  onOpenFull: () => void
  onReset: () => void
  onUnpin: () => void
  onEscape?: () => void
  buttonRef?: React.Ref<HTMLButtonElement>
}): React.JSX.Element {
  const p = getBullseyeTheme(dark)
  const [live, setLive] = useState<Pt | null>(null)
  const [editing, setEditingState] = useState(false)
  const tagTimer = useRef<ReturnType<typeof setTimeout> | null>(null)
  const setEditing = (on: boolean): void => {
    if (tagTimer.current) {
      clearTimeout(tagTimer.current)
      tagTimer.current = null
    }
    setEditingState(on)
  }
  useEffect(
    () => () => {
      if (tagTimer.current) {
        clearTimeout(tagTimer.current)
      }
    },
    []
  )
  const drag = useRef<{
    id: number
    from: Pt
    start: Pt
    moved: boolean
    at: number
    last: Pt | null
    onTag: boolean
  } | null>(null)
  const pos = live ?? pin.square
  const attention = Boolean(agent?.attention)
  const busy = Boolean(agent?.busy) && !attention
  const menu = usePinMenu()
  const faceRef = useRef<HTMLButtonElement | null>(null)
  const lastRelease = useRef<Release | null>(null)

  const clearTagTimer = (): void => {
    if (tagTimer.current) {
      clearTimeout(tagTimer.current)
      tagTimer.current = null
    }
  }

  const down = (e: React.PointerEvent<HTMLDivElement>): void => {
    if (e.button !== 0 || editing || e.ctrlKey) {
      return
    }
    clearTagTimer()
    drag.current = {
      id: e.pointerId,
      from: { x: e.clientX, y: e.clientY },
      start: pin.square,
      moved: false,
      at: Date.now(),
      last: null,
      onTag: pressedOnTag(e.target)
    }
    try {
      e.currentTarget.setPointerCapture?.(e.pointerId)
    } catch {
      // ok: jsdom / detached nodes lack setPointerCapture
      // ignore
    }
  }

  const move = (e: React.PointerEvent<HTMLDivElement>): void => {
    const d = drag.current
    if (!d) {
      return
    }
    if (e.buttons === 0 && e.pointerType === 'mouse') {
      drag.current = null
      setLive(null)
      return
    }
    const now = { x: e.clientX, y: e.clientY }
    if (!d.moved && !passedDragThreshold(d.from, now, CLICK_SLOP_PX)) {
      return
    }
    d.moved = true
    lastRelease.current = null
    const box: Box = { x: d.start.x, y: d.start.y, w: SQUARE_W, h: SQUARE_H }
    d.last = snapSquareMove(
      box,
      now.x - d.from.x,
      now.y - d.from.y,
      others(),
      currentViewport(),
      e.metaKey
    )
    setLive(d.last)
  }

  const up = (e: React.PointerEvent<HTMLDivElement>): void => {
    const d = drag.current
    drag.current = null
    if (!d) {
      return
    }
    if (d.moved) {
      if (d.last) {
        onMove(d.last)
      }
    } else if (Date.now() - d.at <= CLICK_MAX_MS) {
      if (d.onTag && !(e.target as HTMLElement).closest('input')) {
        const now: Release = { t: Date.now(), pt: { x: e.clientX, y: e.clientY }, onTag: true }
        if (isDoubleClick(lastRelease.current, now)) {
          lastRelease.current = null
          setEditing(true)
        } else {
          lastRelease.current = now
          tagTimer.current = setTimeout(() => {
            tagTimer.current = null
            lastRelease.current = null
            onOpen()
          }, TAG_CLICK_MS)
        }
      } else if (!d.onTag) {
        onOpen()
      }
    }
    setLive(null)
  }

  return (
    <div
      data-pinned-square={pin.tabId}
      data-attention={attention ? 'true' : 'false'}
      data-face={attention ? 'needs-you' : busy ? 'busy' : 'sleeping'}
      data-status={pinStatus(agent)}
      data-leaving={leaving ? 'true' : 'false'}
      onContextMenu={menu.handlers.onContextMenu}
      onPointerDown={down}
      onPointerMove={move}
      onPointerUp={up}
      onPointerCancel={() => {
        drag.current = null
        setLive(null)
      }}
      onKeyDown={(e) => {
        menu.handlers.onKeyDown(e)
        if (e.key === 'Escape') {
          onEscape?.()
        }
      }}
      onLostPointerCapture={() => {
        if (drag.current && !drag.current.moved) {
          drag.current = null
        }
      }}
      style={{
        left: pos.x,
        top: pos.y,
        width: SQUARE_W,
        height: SQUARE_H,
        background: p.card,
        borderColor: attention ? p.bad : p.border,
        zIndex: 1000,
        boxShadow: attention ? `0 0 0 2px ${p.badBorder}, ${p.elevation}` : p.elevation,
        touchAction: 'none'
      }}
      className={`orca-pin-glide pointer-events-auto fixed flex select-none flex-col items-center justify-between rounded-[16px] border px-1 pb-1.5 pt-2 ${
        leaving ? 'orca-pin-leaving' : ''
      } ${live ? 'cursor-grabbing' : 'cursor-grab'}`}
    >
      <button
        ref={(node) => {
          faceRef.current = node
          if (typeof buttonRef === 'function') {
            buttonRef(node)
          } else if (buttonRef) {
            ;(buttonRef as React.MutableRefObject<HTMLButtonElement | null>).current = node
          }
        }}
        type="button"
        data-pin-open={pin.tabId}
        aria-label={`${pin.name}, pinned session`}
        aria-expanded={false}
        onClick={(e) => {
          if (e.detail === 0) {
            onOpen()
          }
        }}
        onKeyDown={(e) => {
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault()
            onOpen()
          } else if (e.key === 'F2') {
            e.preventDefault()
            setEditing(true)
          }
        }}
        className="flex h-[48px] w-full items-center justify-center rounded-[10px] outline-none focus-visible:ring-2 focus-visible:ring-offset-0"
        style={{ ['--tw-ring-color' as string]: p.accent }}
      >
        <span
          data-pin-face-art
          style={
            dark
              ? undefined
              : {
                  filter: `drop-shadow(0 0 0.75px ${SPACEWARE_ISLAND_PALETTE.bodyStrokeStrong}) drop-shadow(0 0 0.5px rgba(0,0,0,0.45))`
                }
          }
          className="inline-block origin-center scale-[2]"
          aria-hidden="true"
        >
          <MiniSpacewareSprite
            busy={busy}
            attention={attention}
            awake={busy || attention}
            role={agent ? spriteRoleOf({ name: agent.name, role: agent.role }) : undefined}
          />
        </span>
      </button>
      <PinNameTag
        name={pin.name}
        p={p}
        onCommit={onRename}
        editing={editing}
        setEditing={setEditing}
      />
      <PinMenu
        at={menu.at}
        label={`${pin.name} pin menu`}
        dark={dark}
        onClose={menu.close}
        returnFocus={() => faceRef.current}
        items={pinMenuItems({
          onOpenFull,
          onRename: () => setEditing(true),
          onReset,
          onUnpin
        })}
      />
    </div>
  )
}

import { useSyncExternalStore } from 'react'
import { keepOutBoxes } from './pinned-geometry'
import {
  EMPTY_PINNED,
  PINNED_STORAGE_KEY,
  canPin,
  isPinnable,
  isPinned,
  parsePinned,
  pinnedReducer,
  serializePinned,
  type PinInput,
  type PinnedAction,
  type PinnedState,
  type Viewport
} from '../core/pinned-sessions'

let state: PinnedState | null = null
const listeners = new Set<() => void>()
const toastListeners = new Set<(text: string) => void>()

function load(): PinnedState {
  try {
    if (typeof window === 'undefined') {
      return EMPTY_PINNED
    }
    return parsePinned(window.localStorage.getItem(PINNED_STORAGE_KEY))
  } catch {
    // ok: private mode or restricted localStorage safely returns EMPTY_PINNED
    return EMPTY_PINNED
  }
}

let listeningStorage = false

function onStorage(event: StorageEvent): void {
  if (event.key !== null && event.key !== PINNED_STORAGE_KEY) {
    return
  }
  state = event.key === null ? load() : parsePinned(event.newValue)
  listeners.forEach((l) => l())
}

export function getPinnedState(): PinnedState {
  if (state === null) {
    state = load()
    if (!listeningStorage && typeof window !== 'undefined') {
      listeningStorage = true
      window.addEventListener('storage', onStorage)
    }
  }
  return state
}

export function dispatchPinned(action: PinnedAction): void {
  const prev = getPinnedState()
  const next = pinnedReducer(prev, action)
  if (next === prev) {
    return
  }
  state = next
  try {
    window.localStorage.setItem(PINNED_STORAGE_KEY, serializePinned(next))
  } catch {
    // ok: storage quota errors do not break in-memory pinned state
    // continue with in-memory state
  }
  listeners.forEach((l) => l())
}

export function subscribePinned(l: () => void): () => void {
  listeners.add(l)
  return () => listeners.delete(l)
}

export function usePinnedState(): PinnedState {
  return useSyncExternalStore(subscribePinned, getPinnedState, getPinnedState)
}

export function onPinnedToast(l: (text: string) => void): () => void {
  toastListeners.add(l)
  return () => toastListeners.delete(l)
}

export function currentViewport(): Viewport {
  if (typeof window === 'undefined') {
    return { w: 1280, h: 800 }
  }
  return { w: window.innerWidth || 1280, h: window.innerHeight || 800 }
}

export function pinSession(input: PinInput): boolean {
  const s = getPinnedState()
  if (isPinned(s, input.tabId)) {
    return true
  }
  if (!isPinnable(input.kind)) {
    return false
  }
  if (!canPin(s)) {
    toastListeners.forEach((l) => l('6 pins max'))
    return false
  }
  dispatchPinned({ type: 'pin', input, vp: currentViewport(), keepOut: keepOutBoxes() })
  return true
}

export function unpinSession(tabId: string): void {
  dispatchPinned({ type: 'unpin', tabId })
}

export function resetPinnedStoreForTests(): void {
  if (listeningStorage && typeof window !== 'undefined') {
    window.removeEventListener('storage', onStorage)
    listeningStorage = false
  }
  state = null
  listeners.clear()
  toastListeners.clear()
}

let focusRequest: string | null = null
export function requestPinFocus(tabId: string): void {
  focusRequest = tabId
}
export function consumePinFocus(tabId: string): boolean {
  if (focusRequest !== tabId) {
    return false
  }
  focusRequest = null
  return true
}

import React, { useEffect, useRef, useState } from 'react'
import { ArrowLeftRight, ExternalLink, Minimize2, PinOff } from 'lucide-react'
import { passedDragThreshold, passedResizeThreshold } from '../penpot-mpl/drag-threshold'
import { HANDLERS, type Handler } from '../penpot-mpl/resize-handles'
import { openAsksForAgent } from '../core/ask-pins'
import { isImeOwnedKeyboardEvent } from '../core/ime-guard'
import { clampWindow, type Box, type PinnedSession, type Pt } from '../core/pinned-sessions'
import type { SpaceAgent, SpaceAsk, SpaceGoal } from '../core/space'
import { getBullseyeTheme } from '../core/theme'
import { useSpaceCanvasHost } from '../host-adapter'
import { MiniSpacewareSprite } from '../sprites/space-sprite'
import { spriteRoleOf } from '../sprites/space-sprite-accessory'
import { CLICK_SLOP_PX, isDoubleClick, pinStatus, pressedOnTag, type Release } from './pin-click'
import { PinMenu, pinMenuItems, usePinMenu } from './pin-menu'
import { PinNameTag } from './pin-name-tag'
import { resizeWindowByHandle } from './pinned-geometry'
import { consumePinFocus, currentViewport } from './pinned-store'

const HEADER_H = 36

function handleStyle(h: Handler): React.CSSProperties {
  const S = 8
  const C = 14
  const side: Record<Handler, React.CSSProperties> = {
    top: { left: C, right: C, top: -S / 2, height: S, cursor: 'ns-resize' },
    bottom: { left: C, right: C, bottom: -S / 2, height: S, cursor: 'ns-resize' },
    left: { top: C, bottom: C, left: -S / 2, width: S, cursor: 'ew-resize' },
    right: { top: C, bottom: C, right: -S / 2, width: S, cursor: 'ew-resize' },
    'top-left': { top: -S / 2, left: -S / 2, width: C, height: C, cursor: 'nwse-resize' },
    'bottom-right': { bottom: -S / 2, right: -S / 2, width: C, height: C, cursor: 'nwse-resize' },
    'top-right': { top: -S / 2, right: -S / 2, width: C, height: C, cursor: 'nesw-resize' },
    'bottom-left': { bottom: -S / 2, left: -S / 2, width: C, height: C, cursor: 'nesw-resize' }
  }
  return side[h]
}

type Gesture =
  | { kind: 'move'; id: number; from: Pt; start: Box; last: Box | null; onTag: boolean; at: number }
  | {
      kind: 'resize'
      id: number
      handler: Handler
      from: Pt
      start: Box
      last: Box | null
      started: boolean
    }

export function PinnedWindow({
  pin,
  agent,
  bodyAgent,
  dark,
  leaving,
  onSetBox,
  onCollapse,
  onOpenFull,
  onUnpin,
  onReset,
  onRaise,
  onRename,
  goal,
  onAnswerAsk,
  chat,
  canToggleView,
  onToggleView,
  needsYouCard,
  windowRef
}: {
  pin: PinnedSession
  agent: SpaceAgent | null
  bodyAgent: SpaceAgent | null
  dark: boolean
  leaving: boolean
  onSetBox: (box: Box) => void
  onCollapse: () => void
  onOpenFull: () => void
  onUnpin: () => void
  onReset: () => void
  onRaise: () => void
  onRename: (name: string) => void
  goal: SpaceGoal | null
  onAnswerAsk?: (ask: SpaceAsk, answer: 'yes' | 'no') => void
  chat: boolean
  canToggleView: boolean
  onToggleView: () => void
  needsYouCard: boolean
  windowRef?: React.Ref<HTMLDivElement>
}): React.JSX.Element {
  const host = useSpaceCanvasHost()
  const p = getBullseyeTheme(dark)
  const [live, setLive] = useState<Box | null>(null)
  const [editingName, setEditingName] = useState(false)
  const gesture = useRef<Gesture | null>(null)
  const menu = usePinMenu()
  const rootRef = useRef<HTMLDivElement | null>(null)
  const box = live ?? pin.win
  const attention = Boolean(agent?.attention)
  const busy = Boolean(agent?.busy) && !attention
  const openAsks = bodyAgent ? openAsksForAgent(goal, bodyAgent) : []

  useEffect(() => {
    if (consumePinFocus(pin.tabId)) {
      rootRef.current?.focus({ preventScroll: true })
    }
  }, [pin.tabId])

  const begin = (kind: Gesture['kind'], e: React.PointerEvent, handler?: Handler): void => {
    if (e.button !== 0) {
      return
    }
    e.stopPropagation()
    onRaise()
    const base = {
      id: e.pointerId,
      from: { x: e.clientX, y: e.clientY },
      start: pin.win,
      last: null
    }
    gesture.current =
      kind === 'move'
        ? { kind, ...base, onTag: pressedOnTag(e.target), at: Date.now() }
        : { kind, handler: handler as Handler, started: false, ...base }
    try {
      ;(e.currentTarget as HTMLElement).setPointerCapture?.(e.pointerId)
    } catch {
      // ok: jsdom lacks setPointerCapture
      // ignore
    }
  }

  const step = (e: React.PointerEvent): void => {
    const g = gesture.current
    if (!g) {
      return
    }
    const vp = currentViewport()
    const at = { x: e.clientX, y: e.clientY }
    if (g.kind === 'move') {
      if (!g.last && !passedDragThreshold(g.from, at, CLICK_SLOP_PX)) {
        return
      }
      g.last = clampWindow(
        { ...g.start, x: g.start.x + at.x - g.from.x, y: g.start.y + at.y - g.from.y },
        vp
      )
    } else {
      g.started = g.started || passedResizeThreshold(g.from, at)
      if (!g.started) {
        return
      }
      g.last = resizeWindowByHandle(g.start, g.handler, g.from, at, vp, e.shiftKey)
    }
    setLive(g.last)
  }

  const lastRelease = useRef<Release | null>(null)
  const end = (e: React.PointerEvent): void => {
    const g = gesture.current
    gesture.current = null
    if (g?.last) {
      onSetBox(g.last)
    } else if (g?.kind === 'move') {
      const now: Release = { t: Date.now(), pt: { x: e.clientX, y: e.clientY }, onTag: g.onTag }
      if (isDoubleClick(lastRelease.current, now)) {
        lastRelease.current = null
        if (now.onTag && g.onTag) {
          setEditingName(true)
        } else {
          onCollapse()
        }
      } else {
        lastRelease.current = now
      }
    }
    setLive(null)
  }

  const headerBtn =
    'flex size-6 cursor-pointer items-center justify-center rounded-md outline-none hover:bg-[var(--pin-hover)] focus-visible:ring-2'

  const customBody = host.renderPinnedSessionBody?.(pin, bodyAgent, {
    dark,
    chat,
    onOpenFull,
    onAnswerAsk
  })

  return (
    <div
      ref={(node) => {
        rootRef.current = node
        if (typeof windowRef === 'function') {
          windowRef(node)
        } else if (windowRef) {
          ;(windowRef as React.MutableRefObject<HTMLDivElement | null>).current = node
        }
      }}
      role="dialog"
      aria-label={`${pin.name}, pinned session window`}
      tabIndex={-1}
      data-pinned-window={pin.tabId}
      data-attention={attention ? 'true' : 'false'}
      data-status={pinStatus(agent)}
      onPointerDown={onRaise}
      onKeyDown={(e) => {
        if ((e.target as HTMLElement).closest('[data-pinned-header]')) {
          menu.handlers.onKeyDown(e)
        }
        if (e.key === 'F2' && !(e.target as HTMLElement).closest('input, textarea')) {
          e.preventDefault()
          setEditingName(true)
        }
        const t = e.target as HTMLElement
        if (
          e.key === 'Escape' &&
          !e.defaultPrevented &&
          !isImeOwnedKeyboardEvent(e) &&
          !t.closest('input, textarea, select, [contenteditable=""], [contenteditable="true"]') &&
          !rootRef.current?.querySelector('[aria-expanded="true"]:not([data-inline-disclosure])')
        ) {
          e.stopPropagation()
          onCollapse()
        }
      }}
      style={{
        left: box.x,
        top: box.y,
        width: box.w,
        height: box.h,
        background: p.card,
        color: p.body,
        borderColor: attention ? p.bad : p.borderStrong,
        boxShadow: p.elevation,
        zIndex: 10 + pin.z,
        ['--pin-hover' as string]: p.hover,
        transformOrigin: 'top left'
      }}
      className={`orca-pin-glide pointer-events-auto fixed flex flex-col overflow-visible rounded-[14px] border outline-none ${leaving ? 'orca-pin-leaving' : ''}`}
      data-leaving={leaving ? 'true' : 'false'}
    >
      <div
        data-pinned-header
        onContextMenu={menu.handlers.onContextMenu}
        onPointerDown={(e) => {
          const t = e.target as HTMLElement
          if (!t.closest('button') && !t.closest('input')) {
            begin('move', e)
          }
        }}
        onPointerMove={step}
        onPointerUp={end}
        onPointerCancel={end}
        style={{ height: HEADER_H, background: p.well, borderColor: p.border, touchAction: 'none' }}
        className="flex shrink-0 cursor-grab select-none items-center gap-1.5 rounded-t-[13px] border-b px-2"
      >
        <button
          type="button"
          data-pin-face
          aria-label="Back to square"
          title="Back to square"
          onClick={onCollapse}
          className={headerBtn}
        >
          <MiniSpacewareSprite
            busy={busy}
            attention={attention}
            awake
            role={agent ? spriteRoleOf({ name: agent.name, role: agent.role }) : undefined}
          />
        </button>
        <PinNameTag
          name={pin.name}
          p={p}
          variant="header"
          onCommit={onRename}
          editing={editingName}
          setEditing={setEditingName}
        />
        {canToggleView ? (
          <button
            type="button"
            data-pin-view-toggle
            aria-label={chat ? 'Switch to Terminal view' : 'Switch to Chat view'}
            title={chat ? 'Chat view · switch to Terminal' : 'Terminal view · switch to Chat'}
            onClick={onToggleView}
            className={`${headerBtn} w-auto gap-1 px-1.5 text-[10px] font-semibold`}
          >
            <ArrowLeftRight size={12} aria-hidden="true" />
            <span>{chat ? 'Chat' : 'Terminal'}</span>
          </button>
        ) : null}
        <button
          type="button"
          data-pin-open-full
          aria-label="Open full"
          title="Open full"
          onClick={onOpenFull}
          className={headerBtn}
        >
          <ExternalLink size={14} aria-hidden="true" />
        </button>
        <button
          type="button"
          data-pin-collapse
          aria-label="Collapse to square"
          title="Collapse to square"
          onClick={onCollapse}
          className={headerBtn}
        >
          <Minimize2 size={14} aria-hidden="true" />
        </button>
        <button
          type="button"
          data-pin-unpin
          aria-label="Unpin"
          title="Unpin"
          onClick={onUnpin}
          className={headerBtn}
        >
          <PinOff size={14} aria-hidden="true" />
        </button>
      </div>
      {needsYouCard ? (
        <div
          data-pin-needs-you
          role="status"
          style={{ background: p.badSoft, borderColor: p.badBorder, color: p.badText }}
          className="flex shrink-0 items-center gap-2 border-b px-3 py-1.5 text-[12px] font-semibold"
        >
          <span className="min-w-0 flex-1 truncate">Needs you — Open full to answer</span>
          <button
            type="button"
            data-pin-needs-you-open
            onClick={onOpenFull}
            style={{ borderColor: p.badBorder }}
            className="shrink-0 cursor-pointer rounded-md border px-2 py-0.5 text-[11px]"
          >
            Open full
          </button>
        </div>
      ) : null}
      <div className="flex min-h-0 flex-1 flex-col overflow-hidden rounded-b-[13px]">
        {customBody !== undefined ? (
          customBody
        ) : (
          <div className="flex flex-1 flex-col justify-between gap-3 p-3 text-xs">
            <div className="space-y-2">
              <div style={{ color: p.muted }} className="text-[11px]">
                {bodyAgent?.activity || 'Pinned live session'}
              </div>
              {openAsks.map((ask) => (
                <div
                  key={ask.id}
                  data-pin-ask-card={ask.id}
                  style={{ background: p.badSoft, borderColor: p.badBorder, color: p.badText }}
                  className="rounded-lg border p-2.5"
                >
                  <p className="mb-2 text-[12px] font-medium">{ask.text}</p>
                  {onAnswerAsk ? (
                    <div className="flex items-center gap-2">
                      <button
                        type="button"
                        onClick={() => onAnswerAsk(ask, 'yes')}
                        className="cursor-pointer rounded bg-emerald-500/20 px-2.5 py-1 text-[11px] font-semibold text-emerald-300"
                      >
                        Yes · Approve
                      </button>
                      <button
                        type="button"
                        onClick={() => onAnswerAsk(ask, 'no')}
                        className="cursor-pointer rounded bg-rose-500/20 px-2.5 py-1 text-[11px] font-semibold text-rose-300"
                      >
                        No
                      </button>
                    </div>
                  ) : null}
                </div>
              ))}
            </div>
            <button
              type="button"
              onClick={onOpenFull}
              style={{ borderColor: p.borderStrong, color: p.ink }}
              className="w-full cursor-pointer rounded-lg border py-1.5 text-center text-[11px] font-semibold hover:bg-white/5"
            >
              Open full session
            </button>
          </div>
        )}
      </div>
      <PinMenu
        at={menu.at}
        label={`${pin.name} pin menu`}
        dark={dark}
        onClose={menu.close}
        returnFocus={() => rootRef.current}
        items={pinMenuItems({
          onOpenFull,
          onRename: () => setEditingName(true),
          onReset,
          onUnpin
        })}
      />
      {HANDLERS.map((h) => (
        <div
          key={h}
          data-resize-handle={h}
          onPointerDown={(e) => begin('resize', e, h)}
          onPointerMove={step}
          onPointerUp={end}
          onPointerCancel={end}
          style={{ position: 'absolute', touchAction: 'none', ...handleStyle(h) }}
        />
      ))}
    </div>
  )
}

/**
 * Centralized environment settings reader for `@xlabs/space-canvas`.
 * Per `evergreen-code-baseline`, `process.env` is only read inside `settings.ts`.
 */
export type SpaceCanvasSettings = {
  agentLooksDir?: string
  vaultDir?: string
  defaultProjectSlug?: string
}

export function readSpaceCanvasSettings(): SpaceCanvasSettings {
  const env =
    typeof globalThis !== 'undefined' &&
    'process' in globalThis &&
    typeof (globalThis as { process?: { env?: Record<string, string | undefined> } }).process
      ?.env === 'object'
      ? (globalThis as { process: { env: Record<string, string | undefined> } }).process.env
      : undefined
  return {
    ...(env?.AGENT_LOOKS_DIR ? { agentLooksDir: env.AGENT_LOOKS_DIR } : {}),
    ...(env?.XLABS_VAULT_DIR ? { vaultDir: env.XLABS_VAULT_DIR } : {}),
    ...(env?.XLABS_DEFAULT_PROJECT ? { defaultProjectSlug: env.XLABS_DEFAULT_PROJECT } : {})
  }
}

import { useCallback, useEffect, useRef, useState } from 'react'
import type { AgentRoleId } from './generated/a01-roles'
import type { C02ProjectSummary, DraggableSessionSummary } from './core/canvas-nodes'
import { BENCH_KEY, type Point, type SpaceLevel } from './core/space'

export type DragItem =
  | { kind: 'bot'; botId: string }
  | { kind: 'spawn'; spawnerId: string }
  | { kind: 'space'; level: SpaceLevel }
  | { kind: 'session'; session: DraggableSessionSummary }
  | { kind: 'a01-role'; roleId: AgentRoleId }
  | { kind: 'project'; project: C02ProjectSummary }

export type DropTarget =
  | { kind: 'tile'; key: string }
  | { kind: 'bench' }
  | { kind: 'palette-remove' }
  | { kind: 'canvas' }
  | null

export type DragState = {
  item: DragItem
  point: Point
  over: DropTarget
} | null

function sameDropTarget(a: DropTarget, b: DropTarget): boolean {
  if (a === b) {
    return true
  }
  if (!a || !b || a.kind !== b.kind) {
    return false
  }
  if (a.kind === 'tile' && b.kind === 'tile') {
    return a.key === b.key
  }
  return true
}

function canDropDirectlyOnCanvas(item: DragItem): boolean {
  return (
    item.kind === 'space' ||
    item.kind === 'spawn' ||
    item.kind === 'session' ||
    item.kind === 'a01-role' ||
    item.kind === 'project'
  )
}

function findDropTarget(item: DragItem, clientX: number, clientY: number): DropTarget {
  if (typeof document.elementsFromPoint !== 'function') {
    return canDropDirectlyOnCanvas(item) ? { kind: 'canvas' } : null
  }
  const stack = document.elementsFromPoint(clientX, clientY)
  for (const element of stack) {
    if (item.kind === 'bot' && element.hasAttribute('data-space-remove')) {
      return { kind: 'palette-remove' }
    }
    if (
      element.hasAttribute('data-space-palette') ||
      element.hasAttribute('data-space-dock') ||
      element.hasAttribute('data-space-drawer')
    ) {
      return null
    }
    if (item.kind === 'bot' || item.kind === 'spawn') {
      const tileKey = element.getAttribute('data-space-tile')
      if (tileKey) {
        return { kind: 'tile', key: tileKey }
      }
      if (element.hasAttribute('data-space-bench')) {
        return { kind: 'bench' }
      }
    }
  }
  if (
    canDropDirectlyOnCanvas(item) &&
    stack.some((element) => element.hasAttribute('data-space-canvas'))
  ) {
    return { kind: 'canvas' }
  }
  return null
}

export function isOverTile(drag: DragState, key: string): boolean {
  if (!drag?.over) {
    return false
  }
  if (drag.over.kind === 'tile' && drag.over.key === key) {
    return true
  }
  return drag.over.kind === 'bench' && key === BENCH_KEY
}

export function useSpaceDrag(onDrop: (item: DragItem, over: DropTarget, point: Point) => void): {
  drag: DragState
  ghostRef: React.RefObject<HTMLDivElement | null>
  startDrag: (item: DragItem) => (event: React.PointerEvent) => void
} {
  const [drag, setDrag] = useState<DragState>(null)
  const ghostRef = useRef<HTMLDivElement | null>(null)
  const onDropRef = useRef(onDrop)
  onDropRef.current = onDrop

  const startDrag = useCallback(
    (item: DragItem) => (event: React.PointerEvent) => {
      if (event.button !== 0) {
        return
      }
      const origin = { x: event.clientX, y: event.clientY }
      let started = false
      let rafId = 0
      let latestX = event.clientX
      let latestY = event.clientY
      let lastOver: DropTarget = null

      const onMove = (move: PointerEvent): void => {
        latestX = move.clientX
        latestY = move.clientY
        if (!started) {
          if (Math.hypot(latestX - origin.x, latestY - origin.y) < 5) {
            return
          }
          started = true
          lastOver = findDropTarget(item, latestX, latestY)
          setDrag({
            item,
            point: { x: latestX, y: latestY },
            over: lastOver
          })
          return
        }
        if (ghostRef.current) {
          ghostRef.current.style.transform = `translate3d(${latestX + 14}px, ${latestY + 14}px, 0)`
        }
        if (rafId !== 0) {
          return
        }
        rafId = window.requestAnimationFrame(() => {
          rafId = 0
          const nextOver = findDropTarget(item, latestX, latestY)
          if (!sameDropTarget(lastOver, nextOver)) {
            lastOver = nextOver
            setDrag({
              item,
              point: { x: latestX, y: latestY },
              over: nextOver
            })
          }
        })
      }

      const onUp = (up: PointerEvent): void => {
        window.removeEventListener('pointermove', onMove)
        window.removeEventListener('pointerup', onUp)
        if (rafId !== 0) {
          window.cancelAnimationFrame(rafId)
          rafId = 0
        }
        setDrag(null)
        if (!started) {
          return
        }
        const over = findDropTarget(item, up.clientX, up.clientY)
        onDropRef.current(item, over, { x: up.clientX, y: up.clientY })
      }

      window.addEventListener('pointermove', onMove)
      window.addEventListener('pointerup', onUp)
    },
    []
  )

  useEffect(() => {
    if (!drag) {
      return
    }
    const onKey = (event: KeyboardEvent): void => {
      if (event.key === 'Escape') {
        setDrag(null)
      }
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [drag])

  return { drag, ghostRef, startDrag }
}

import React from 'react'
import { isImageEmoji } from './core/space'

export const MAX_SPACE_ICON_FILE_BYTES = 5 * 1024 * 1024
export const MAX_SPACE_ICON_RAW_BYTES = 30_000

export function SpaceEmojiGraphic({
  value,
  className = 'size-5'
}: {
  value: string
  className?: string
}): React.JSX.Element {
  if (isImageEmoji(value)) {
    return (
      <img
        src={value}
        alt=""
        draggable={false}
        className={`${className} rounded-sm object-contain select-none`}
      />
    )
  }
  return <span className="leading-none select-none">{value}</span>
}

export async function readCustomEmojiFile(file: File): Promise<string> {
  if (!file.type.startsWith('image/')) {
    throw new Error('Not an image file')
  }
  if (file.size > MAX_SPACE_ICON_FILE_BYTES) {
    throw new Error('Image is over 5 MB')
  }
  if (file.type === 'image/svg+xml' && file.size > MAX_SPACE_ICON_RAW_BYTES) {
    throw new Error('SVG icon is over 30 KB')
  }
  return await new Promise<string>((resolve, reject) => {
    const reader = new FileReader()
    reader.onerror = () => reject(new Error('Could not read file'))
    reader.onload = () => {
      const rawDataUrl = typeof reader.result === 'string' ? reader.result : ''
      if (!rawDataUrl) {
        reject(new Error('Empty image'))
        return
      }
      if (
        (file.type === 'image/svg+xml' || file.type === 'image/gif') &&
        rawDataUrl.length <= MAX_SPACE_ICON_RAW_BYTES
      ) {
        resolve(rawDataUrl)
        return
      }
      const img = new Image()
      img.onerror = () => reject(new Error('Could not decode image'))
      img.onload = () => {
        const maxDim = 64
        const scale = Math.min(1, maxDim / Math.max(img.width || 64, img.height || 64))
        const w = Math.max(16, Math.round((img.width || 64) * scale))
        const h = Math.max(16, Math.round((img.height || 64) * scale))
        const canvas = document.createElement('canvas')
        canvas.width = w
        canvas.height = h
        const ctx = canvas.getContext('2d')
        if (!ctx) {
          reject(new Error('Could not decode image'))
          return
        }
        ctx.drawImage(img, 0, 0, w, h)
        const webp = canvas.toDataURL('image/webp', 0.88)
        resolve(webp.startsWith('data:image/webp') ? webp : canvas.toDataURL('image/png'))
      }
      img.src = rawDataUrl
    }
    reader.readAsDataURL(file)
  })
}

import React from 'react'
import type { View } from './core/space'
import type { SnapGuide } from './core/whiteboard-snap'

const STROKE = 'var(--op-snap-guide, #ec4899)'
const LABEL_TEXT = 'var(--op-snap-guide-text, #ffffff)'
const TICK = 5
const PILL_H = 16
const CHAR_W = 6.5

export type SpaceSnapGuidesProps = { guides: readonly SnapGuide[]; view: View }

function sx(x: number, view: View): number {
  return x * view.scale + view.x
}

function sy(y: number, view: View): number {
  return y * view.scale + view.y
}

export function formatGap(gap: number): string {
  const rounded = Math.round(gap)
  return Math.abs(gap - rounded) < 0.05 ? String(rounded) : gap.toFixed(1)
}

function LineGuide({
  g,
  view
}: {
  g: Extract<SnapGuide, { kind: 'line' }>
  view: View
}): React.JSX.Element {
  const p =
    g.axis === 'x'
      ? { x1: sx(g.at, view), x2: sx(g.at, view), y1: sy(g.from, view), y2: sy(g.to, view) }
      : { x1: sx(g.from, view), x2: sx(g.to, view), y1: sy(g.at, view), y2: sy(g.at, view) }
  return <line data-snap-guide="line" data-axis={g.axis} {...p} stroke={STROKE} strokeWidth={1} />
}

function GapGuide({
  g,
  view
}: {
  g: Extract<SnapGuide, { kind: 'gap' }>
  view: View
}): React.JSX.Element {
  const label = formatGap(g.gap)
  const pillW = label.length * CHAR_W + 10
  const a = g.axis === 'x' ? sx(g.from, view) : sy(g.from, view)
  const b = g.axis === 'x' ? sx(g.to, view) : sy(g.to, view)
  const c = g.axis === 'x' ? sy(g.cross, view) : sx(g.cross, view)
  const at = (main: number, cross: number): { x: number; y: number } =>
    g.axis === 'x' ? { x: main, y: cross } : { x: cross, y: main }
  const seg = (
    m1: number,
    c1: number,
    m2: number,
    c2: number
  ): { x1: number; y1: number; x2: number; y2: number } => {
    const p1 = at(m1, c1)
    const p2 = at(m2, c2)
    return { x1: p1.x, y1: p1.y, x2: p2.x, y2: p2.y }
  }
  const mid = at((a + b) / 2, c)
  const pill =
    g.axis === 'x'
      ? { x: mid.x - pillW / 2, y: mid.y - PILL_H - 4 }
      : { x: mid.x + 6, y: mid.y - PILL_H / 2 }
  return (
    <g data-snap-guide="gap" data-axis={g.axis}>
      <line {...seg(a, c - TICK, a, c + TICK)} stroke={STROKE} strokeWidth={1} />
      <line {...seg(b, c - TICK, b, c + TICK)} stroke={STROKE} strokeWidth={1} />
      <line {...seg(a, c, b, c)} stroke={STROKE} strokeWidth={1} />
      <rect x={pill.x} y={pill.y} width={pillW} height={PILL_H} rx={4} fill={STROKE} />
      <text
        x={pill.x + pillW / 2}
        y={pill.y + PILL_H / 2}
        fill={LABEL_TEXT}
        fontSize={11}
        fontFamily="var(--op-font, ui-sans-serif, system-ui, sans-serif)"
        textAnchor="middle"
        dominantBaseline="central"
      >
        {label}
      </text>
    </g>
  )
}

export function SpaceSnapGuides({ guides, view }: SpaceSnapGuidesProps): React.JSX.Element | null {
  if (guides.length === 0) {
    return null
  }
  return (
    <svg
      data-space-snap-guides=""
      aria-hidden="true"
      style={{
        position: 'absolute',
        inset: 0,
        width: '100%',
        height: '100%',
        pointerEvents: 'none',
        overflow: 'visible',
        zIndex: 42
      }}
    >
      {guides.map((g, i) =>
        g.kind === 'line' ? (
          <LineGuide key={`l${g.axis}${g.at}`} g={g} view={view} />
        ) : (
          <GapGuide key={`g${g.axis}${g.from}:${g.to}:${g.cross}:${i}`} g={g} view={view} />
        )
      )}
    </svg>
  )
}

import React, { useCallback, useRef, useState } from 'react'
import {
  createProjectCanvasNode,
  createSessionCanvasNode,
  patchCanvasNode,
  removeCanvasNode,
  upsertCanvasNode,
  type SpaceCanvasNode
} from './core/canvas-nodes'
import {
  BENCH_KEY,
  DEFAULT_SPACE_MODEL_ID,
  MAX_ARROWS,
  MAX_STICKIES,
  emptyWhiteboardHistory,
  newSpaceId,
  normalizeArrow,
  normalizeGoal,
  normalizeStickyNote,
  recordWhiteboardHistory,
  stepWhiteboardHistory,
  toCanvas,
  type Point,
  type SpaceAgent,
  type SpaceGoal,
  type SpaceLayout,
  type SpaceState,
  type SpaceStickyNote,
  type StickyColor,
  type WhiteboardHistory
} from './core/space'
import { remapCopiedGroups } from './core/whiteboard-groups'
import { AGENT_ROLE_ACCESSORIES } from './generated/a01-roles'
import type { SpaceCanvasHostAdapter } from './host-adapter'
import type { PendingA01Spawn } from './nodes/A01SpawnPopover'
import { PinnedSessionsLayer } from './pinned-sessions'
import {
  SpaceCanvas,
  type EndWhiteboardTransaction,
  type WhiteboardBatchAdd,
  type WhiteboardBatchAddResult
} from './space-canvas'
import { useSpaceDrag, type DragItem, type DropTarget } from './space-drag'
import type { ToolbarToolMode } from './whiteboard-toolbar'

/**
 * Batteries-included stateful/controlled wrapper over `<SpaceCanvas />`.
 * Wires Undo/Redo (`WhiteboardHistory`), transactions, pointer drag-and-drop (`useSpaceDrag`),
 * Sticky/Shape/Text/Arrow CRUD, Session/Agent/Project node CRUD, and Pinned Floating Face Squares.
 */
export function SpaceWhiteboard({
  space,
  onChangeSpace,
  agents = [],
  host,
  dark = true,
  showProjectHeader = true,
  showPinnedLayer = true,
  onSelectAgent,
  onOpenGoal,
  className = 'relative flex h-full w-full flex-col overflow-hidden'
}: {
  space: SpaceState
  onChangeSpace: (updater: SpaceState | ((prev: SpaceState) => SpaceState)) => void
  agents?: readonly SpaceAgent[]
  host?: SpaceCanvasHostAdapter
  dark?: boolean
  showProjectHeader?: boolean
  showPinnedLayer?: boolean
  onSelectAgent?: (agentId: string) => void
  onOpenGoal?: (goal: SpaceGoal) => void
  className?: string
}): React.JSX.Element {
  const containerRef = useRef<HTMLDivElement | null>(null)
  const spaceRef = useRef(space)
  spaceRef.current = space

  const [history, setHistory] = useState<WhiteboardHistory>(emptyWhiteboardHistory)
  const historyRef = useRef(history)
  historyRef.current = history
  const [toolMode, setToolMode] = useState<ToolbarToolMode>('select')
  const [selectedModelId, setSelectedModelId] = useState<string>(DEFAULT_SPACE_MODEL_ID)
  const [selectedGoalId, setSelectedGoalId] = useState<string | null>(null)
  const [inspectedAgentId, setInspectedAgentId] = useState<string | null>(null)
  const [pendingEditStickyId, setPendingEditStickyId] = useState<string | null>(null)
  const [pendingSpawnRequest, setPendingSpawnRequest] = useState<PendingA01Spawn | null>(null)

  const txnDepthRef = useRef(0)
  const txnRecordedRef = useRef(false)

  const pushHistory = useCallback((coalesceStickyId?: string): void => {
    const inTxn = txnDepthRef.current > 0
    if (inTxn && txnRecordedRef.current) {
      return
    }
    if (inTxn) {
      txnRecordedRef.current = true
    }
    const nextHistory = recordWhiteboardHistory(
      historyRef.current,
      spaceRef.current,
      Date.now(),
      coalesceStickyId
    )
    historyRef.current = nextHistory
    setHistory(nextHistory)
  }, [])

  const mutate = useCallback(
    (fn: (prev: SpaceState) => SpaceState, opts?: { coalesceStickyId?: string }): void => {
      pushHistory(opts?.coalesceStickyId)
      const prev = spaceRef.current
      const computed = { ...fn(prev), rev: (prev.rev ?? 0) + 1 }
      spaceRef.current = computed
      onChangeSpace(computed)
    },
    [onChangeSpace, pushHistory]
  )

  const onWhiteboardTransaction = useCallback((fn?: () => void): EndWhiteboardTransaction => {
    txnDepthRef.current += 1
    let active = true
    const end = (): void => {
      if (!active) {
        return
      }
      active = false
      txnDepthRef.current = Math.max(0, txnDepthRef.current - 1)
      if (txnDepthRef.current === 0) {
        txnRecordedRef.current = false
      }
    }
    if (fn) {
      try {
        fn()
      } finally {
        end()
      }
    }
    return end
  }, [])

  const handleUndo = useCallback((): void => {
    const stepped = stepWhiteboardHistory(historyRef.current, spaceRef.current, 'undo')
    if (!stepped) {
      return
    }
    historyRef.current = stepped.history
    spaceRef.current = stepped.space
    setHistory(stepped.history)
    onChangeSpace(stepped.space)
  }, [onChangeSpace])

  const handleRedo = useCallback((): void => {
    const stepped = stepWhiteboardHistory(historyRef.current, spaceRef.current, 'redo')
    if (!stepped) {
      return
    }
    historyRef.current = stepped.history
    spaceRef.current = stepped.space
    setHistory(stepped.history)
    onChangeSpace(stepped.space)
  }, [onChangeSpace])

  const screenToCanvasPoint = useCallback((screenPt: Point): Point => {
    const canvasEl = containerRef.current?.querySelector<HTMLElement>('[data-space-canvas]')
    if (!canvasEl) {
      return { x: 180, y: 140 }
    }
    const rect = canvasEl.getBoundingClientRect()
    const vx = Number(canvasEl.getAttribute('data-view-x') ?? 0)
    const vy = Number(canvasEl.getAttribute('data-view-y') ?? 0)
    const vs = Number(canvasEl.getAttribute('data-view-scale') ?? 1)
    return toCanvas(
      { x: screenPt.x - rect.left, y: screenPt.y - rect.top },
      { x: vx, y: vy, scale: vs || 1 }
    )
  }, [])

  const handlePointerDrop = useCallback(
    (item: DragItem, over: DropTarget, point: Point): void => {
      if (!over) {
        return
      }
      if (item.kind === 'bot') {
        if (over.kind === 'tile') {
          mutate((s) => ({
            ...s,
            placements: { ...s.placements, [item.botId]: over.key }
          }))
        } else if (over.kind === 'bench' || over.kind === 'palette-remove') {
          mutate((s) => {
            const next = { ...s.placements }
            delete next[item.botId]
            return { ...s, placements: next }
          })
        }
        return
      }
      const canvasPt = screenToCanvasPoint(point)
      if (item.kind === 'space' && over.kind === 'canvas') {
        const created = normalizeGoal({
          id: newSpaceId('goal'),
          title: 'New Space',
          level: item.level,
          layout: {
            x: Math.round(canvasPt.x - 170),
            y: Math.round(canvasPt.y - 110),
            w: 360,
            h: 240
          },
          createdAt: Date.now(),
          updatedAt: Date.now()
        })
        mutate((s) => ({ ...s, goals: [...s.goals, created] }))
        setSelectedGoalId(created.id)
        return
      }
      if (item.kind === 'session' && over.kind === 'canvas') {
        const node = createSessionCanvasNode(
          {
            ...item.session,
            projectSlug:
              item.session.projectSlug ?? spaceRef.current.projectSlug ?? host?.activeProjectSlug
          },
          { x: canvasPt.x - 160, y: canvasPt.y - 88 },
          newSpaceId
        )
        mutate((s) => ({ ...s, nodes: upsertCanvasNode(s.nodes, node) }))
        return
      }
      if (item.kind === 'project' && over.kind === 'canvas') {
        const node = createProjectCanvasNode(
          item.project,
          { x: canvasPt.x - 162, y: canvasPt.y - 98 },
          newSpaceId
        )
        mutate((s) => ({ ...s, nodes: upsertCanvasNode(s.nodes, node) }))
        return
      }
      if (item.kind === 'a01-role' && over.kind === 'canvas') {
        setPendingSpawnRequest({
          roleId: item.roleId,
          position: { x: Math.round(canvasPt.x - 156), y: Math.round(canvasPt.y - 92) }
        })
      }
    },
    [host?.activeProjectSlug, mutate, screenToCanvasPoint]
  )

  const { drag, ghostRef, startDrag } = useSpaceDrag(handlePointerDrop)

  const handleAddStickyNote = useCallback(
    (
      point?: Point,
      color: StickyColor = 'amber',
      kind: 'note' | 'text' | 'shape' = 'note',
      initialText = '',
      options?: Partial<SpaceStickyNote>
    ): string => {
      const id = newSpaceId('sticky')
      const sticky = normalizeStickyNote({
        id,
        text: initialText,
        color,
        kind,
        x: point?.x ?? 180,
        y: point?.y ?? 140,
        w: options?.w ?? (kind === 'shape' ? 180 : 220),
        h: options?.h ?? (kind === 'shape' ? 100 : 160),
        ...options,
        createdAt: Date.now()
      })
      if (sticky) {
        mutate((s) => ({
          ...s,
          stickies: [...(s.stickies ?? []), sticky].slice(0, MAX_STICKIES)
        }))
      }
      return id
    },
    [mutate]
  )

  const handleBatchAddWhiteboard = useCallback(
    (items: WhiteboardBatchAdd): WhiteboardBatchAddResult => {
      const stickyIds: string[] = []
      const arrowIds: string[] = []
      let droppedStickies = 0
      let droppedArrows = 0
      const keyMap = new Map<string, string>()

      mutate((s) => {
        const curStickies = [...(s.stickies ?? [])]
        const curArrows = [...(s.arrows ?? [])]
        for (const raw of items.stickies ?? []) {
          if (curStickies.length >= MAX_STICKIES) {
            droppedStickies += 1
            continue
          }
          const minted = newSpaceId('sticky')
          if (raw.id) {
            keyMap.set(raw.id, minted)
          }
          const built = normalizeStickyNote({ ...raw, id: minted, createdAt: Date.now() })
          if (built) {
            curStickies.push(built)
            stickyIds.push(minted)
          }
        }
        for (const raw of items.arrows ?? []) {
          if (curArrows.length >= MAX_ARROWS) {
            droppedArrows += 1
            continue
          }
          const minted = newSpaceId('arrow')
          const built = normalizeArrow({
            ...raw,
            id: minted,
            fromId: raw.fromId ? (keyMap.get(raw.fromId) ?? raw.fromId) : undefined,
            toId: raw.toId ? (keyMap.get(raw.toId) ?? raw.toId) : undefined,
            createdAt: Date.now()
          })
          if (built) {
            curArrows.push(built)
            arrowIds.push(minted)
          }
        }
        return { ...s, stickies: curStickies, arrows: curArrows }
      })
      return { stickyIds, arrowIds, droppedStickies, droppedArrows }
    },
    [mutate]
  )

  return (
    <div ref={containerRef} className={className}>
      <SpaceCanvas
        agents={agents}
        space={space}
        host={host}
        dark={dark}
        showProjectHeader={showProjectHeader}
        selectedGoalId={selectedGoalId}
        inspectedAgentId={inspectedAgentId}
        drag={drag}
        toolMode={toolMode}
        onChangeToolMode={setToolMode}
        selectedModelId={selectedModelId}
        onSelectModelId={setSelectedModelId}
        onStartDrag={startDrag}
        onSelectAgent={(id) => {
          setInspectedAgentId(id)
          onSelectAgent?.(id)
        }}
        onOpenGoal={(goal) => {
          setSelectedGoalId(goal.id)
          onOpenGoal?.(goal)
        }}
        onCreateSpaceAt={(level, pointOrLayout) => {
          const layout: SpaceLayout =
            pointOrLayout && 'w' in pointOrLayout
              ? pointOrLayout
              : {
                  x: Math.round((pointOrLayout?.x ?? 200) - 170),
                  y: Math.round((pointOrLayout?.y ?? 140) - 110),
                  w: 360,
                  h: 240
                }
          const goal = normalizeGoal({
            id: newSpaceId('goal'),
            title: 'New Space',
            level,
            layout,
            createdAt: Date.now(),
            updatedAt: Date.now()
          })
          mutate((s) => ({ ...s, goals: [...s.goals, goal] }))
          setSelectedGoalId(goal.id)
          return goal
        }}
        onRenameGoal={(goalId, title) =>
          mutate((s) => ({
            ...s,
            goals: s.goals.map((g) =>
              g.id === goalId ? { ...g, title, updatedAt: Date.now() } : g
            )
          }))
        }
        onChangeGoalEmoji={(goalId, emoji) =>
          mutate((s) => ({
            ...s,
            goals: s.goals.map((g) =>
              g.id === goalId ? { ...g, emoji, updatedAt: Date.now() } : g
            )
          }))
        }
        onUpdateGoal={(goalId, patch) =>
          mutate((s) => ({
            ...s,
            goals: s.goals.map((g) =>
              g.id === goalId ? { ...g, ...patch, updatedAt: Date.now() } : g
            )
          }))
        }
        onRegisterCustomEmoji={(emoji) =>
          mutate((s) => ({
            ...s,
            customEmojis: [...new Set([emoji, ...(s.customEmojis ?? [])])].slice(0, 48)
          }))
        }
        onGoalMenu={(goal) => setSelectedGoalId(goal.id)}
        onContextCreate={(_screenPt, canvasPt) => {
          const id = handleAddStickyNote(canvasPt, 'amber', 'note', '')
          setPendingEditStickyId(id)
        }}
        onMoveTile={(key, layout) => {
          if (key === BENCH_KEY) {
            mutate((s) => ({ ...s, bench: layout }))
            return
          }
          mutate((s) => ({
            ...s,
            goals: s.goals.map((g) => (g.id === key ? { ...g, layout } : g))
          }))
        }}
        onAddStickyNote={handleAddStickyNote}
        onUpdateStickyNote={(id, patch) => {
          const isTextOnly = Object.keys(patch).every((k) => k === 'text')
          mutate(
            (s) => ({
              ...s,
              stickies: (s.stickies ?? []).map((n) => (n.id === id ? { ...n, ...patch } : n))
            }),
            isTextOnly ? { coalesceStickyId: id } : undefined
          )
        }}
        onDeleteStickyNote={(id) =>
          mutate((s) => ({
            ...s,
            stickies: (s.stickies ?? []).filter((n) => n.id !== id),
            arrows: (s.arrows ?? []).filter((a) => a.fromId !== id && a.toId !== id)
          }))
        }
        onBatchUpdateStickyNotes={(patches) =>
          mutate((s) => ({
            ...s,
            stickies: (s.stickies ?? []).map((n) =>
              patches[n.id] ? { ...n, ...patches[n.id] } : n
            )
          }))
        }
        onBatchDeleteStickyNotes={(ids) => {
          const drop = new Set(ids)
          mutate((s) => ({
            ...s,
            stickies: (s.stickies ?? []).filter((n) => !drop.has(n.id)),
            arrows: (s.arrows ?? []).filter(
              (a) => !(a.fromId && drop.has(a.fromId)) && !(a.toId && drop.has(a.toId))
            )
          }))
        }}
        onDuplicateStickyNote={(id, delta = { x: 24, y: 24 }) => {
          const src = spaceRef.current.stickies?.find((n) => n.id === id)
          if (!src) {
            return null
          }
          const copyId = newSpaceId('sticky')
          const copy: SpaceStickyNote = {
            ...src,
            id: copyId,
            locked: false,
            x: Math.round(src.x + delta.x),
            y: Math.round(src.y + delta.y),
            createdAt: Date.now()
          }
          mutate((s) => ({
            ...s,
            stickies: [...(s.stickies ?? []), copy].slice(0, MAX_STICKIES)
          }))
          return copyId
        }}
        onBatchDuplicateStickyNotes={(ids, delta = { x: 24, y: 24 }) => {
          const srcList = (spaceRef.current.stickies ?? []).filter((n) => ids.includes(n.id))
          if (srcList.length === 0) {
            return []
          }
          const remapped = remapCopiedGroups(srcList, () => newSpaceId('grp'))
          const copies = remapped.map((item) => ({
            ...item,
            id: newSpaceId('sticky'),
            locked: false,
            x: Math.round(item.x + delta.x),
            y: Math.round(item.y + delta.y),
            createdAt: Date.now()
          }))
          mutate((s) => ({
            ...s,
            stickies: [...(s.stickies ?? []), ...copies].slice(0, MAX_STICKIES)
          }))
          return copies.map((c) => c.id)
        }}
        onAddArrow={(arrow) => {
          const built = normalizeArrow({
            ...arrow,
            id: newSpaceId('arrow'),
            createdAt: Date.now()
          })
          if (built) {
            mutate((s) => ({
              ...s,
              arrows: [...(s.arrows ?? []), built].slice(0, MAX_ARROWS)
            }))
          }
        }}
        onUpdateArrow={(id, patch) =>
          mutate((s) => ({
            ...s,
            arrows: (s.arrows ?? []).map((a) => (a.id === id ? { ...a, ...patch } : a))
          }))
        }
        onDeleteArrow={(id) =>
          mutate((s) => ({
            ...s,
            arrows: (s.arrows ?? []).filter((a) => a.id !== id)
          }))
        }
        onAddNode={(node: SpaceCanvasNode) =>
          mutate((s) => ({ ...s, nodes: upsertCanvasNode(s.nodes, node) }))
        }
        onUpdateNode={(nodeId, patch) =>
          mutate((s) => ({ ...s, nodes: patchCanvasNode(s.nodes, nodeId, patch) }))
        }
        onDeleteNode={(nodeId) =>
          mutate((s) => ({
            ...s,
            nodes: removeCanvasNode(s.nodes, nodeId),
            arrows: (s.arrows ?? []).filter((a) => a.fromId !== nodeId && a.toId !== nodeId)
          }))
        }
        onSelectSpaceProject={(projectSlug) => mutate((s) => ({ ...s, projectSlug }))}
        pendingSpawnRequest={pendingSpawnRequest}
        onConsumePendingSpawnRequest={() => setPendingSpawnRequest(null)}
        onWhiteboardTransaction={onWhiteboardTransaction}
        onBatchAddWhiteboard={handleBatchAddWhiteboard}
        canUndo={history.past.length > 0}
        canRedo={history.future.length > 0}
        onUndo={handleUndo}
        onRedo={handleRedo}
        pendingEditStickyId={pendingEditStickyId}
        onConsumePendingEditSticky={() => setPendingEditStickyId(null)}
      />

      {drag && (
        <div
          ref={ghostRef}
          style={{
            transform: `translate3d(${drag.point.x + 14}px, ${drag.point.y + 14}px, 0)`
          }}
          className="pointer-events-none fixed top-0 left-0 z-50 rounded-xl border border-indigo-400/50 bg-zinc-900/95 px-2.5 py-1.5 text-[11px] font-semibold text-white shadow-xl"
        >
          {drag.item.kind === 'a01-role'
            ? `Spawn ${AGENT_ROLE_ACCESSORIES[drag.item.roleId].label}`
            : drag.item.kind === 'session'
              ? `Session · ${drag.item.session.title}`
              : drag.item.kind === 'project'
                ? `C02 · ${drag.item.project.title}`
                : drag.item.kind === 'space'
                  ? `New ${drag.item.level} Space`
                  : 'Move Agent'}
        </div>
      )}

      {showPinnedLayer && (
        <PinnedSessionsLayer
          agents={agents}
          space={space}
          dark={dark}
          onActivate={(tabId: string) => host?.onOpenSession?.(tabId, 'orca-agent')}
        />
      )}
    </div>
  )
}

import React, { useEffect } from 'react'

export type PresenceSubagentStatus = 'working' | 'waiting' | 'done'

export type PresenceSubagent = {
  id: string
  role: string
  status: PresenceSubagentStatus
  harness?: string
  updatedAt?: number
}

export type PresenceSplitPane = {
  id: number
  title?: string
  active?: boolean
  busy?: boolean
}

export type PresenceSplitInfo = {
  paneCount: number
  direction: 'horizontal' | 'vertical'
  panes: PresenceSplitPane[]
}

export type AgentPresenceFields = {
  subagents?: readonly PresenceSubagent[] | null
  splitInfo?: PresenceSplitInfo | null
}

const EMPTY_SUBAGENTS: readonly PresenceSubagent[] = []
export const AGENT_PRESENCE_STYLE_ID = 'xlabs-space-agent-presence-style'

const AGENT_PRESENCE_CSS = [
  '@keyframes xlabsSubagentBob{0%,100%{transform:translate3d(0,0,0)}50%{transform:translate3d(0,-2.2px,0)}}',
  '@keyframes xlabsSubagentStemPulse{0%{transform:translate3d(0,-10px,0);opacity:0}28%{opacity:.95}75%{opacity:.85}100%{transform:translate3d(0,38px,0);opacity:0}}',
  '@keyframes xlabsSubagentDotWave{0%,80%,100%{opacity:.28;transform:translate3d(0,0,0)}40%{opacity:1;transform:translate3d(0,-1px,0)}}',
  '@keyframes xlabsSubagentWaitPulse{0%,100%{opacity:.55;transform:scale(.92)}50%{opacity:1;transform:scale(1.18)}}',
  '.xlabs-subagent-bob{animation:xlabsSubagentBob 1.8s ease-in-out infinite;will-change:transform}',
  '.xlabs-subagent-stem-pulse{animation:xlabsSubagentStemPulse 1.65s cubic-bezier(.22,1,.36,1) infinite;will-change:transform,opacity}',
  '.xlabs-subagent-dot-1{animation:xlabsSubagentDotWave 1.2s ease-in-out infinite}',
  '.xlabs-subagent-dot-2{animation:xlabsSubagentDotWave 1.2s ease-in-out infinite .18s}',
  '.xlabs-subagent-dot-3{animation:xlabsSubagentDotWave 1.2s ease-in-out infinite .36s}',
  '.xlabs-subagent-wait-dot{animation:xlabsSubagentWaitPulse 1.3s ease-in-out infinite}',
  '@media (prefers-reduced-motion:reduce){.xlabs-subagent-bob,.xlabs-subagent-stem-pulse,.xlabs-subagent-dot-1,.xlabs-subagent-dot-2,.xlabs-subagent-dot-3,.xlabs-subagent-wait-dot{animation:none!important}}'
].join('\n')

export function ensureAgentPresenceStyles(): void {
  if (typeof document === 'undefined') {
    return
  }
  let node = document.getElementById(AGENT_PRESENCE_STYLE_ID)
  if (!node) {
    node = document.createElement('style')
    node.id = AGENT_PRESENCE_STYLE_ID
    document.head.appendChild(node)
  }
  if (node.textContent !== AGENT_PRESENCE_CSS) {
    node.textContent = AGENT_PRESENCE_CSS
  }
}

export function readAgentSubagents(
  agent: AgentPresenceFields | null | undefined
): readonly PresenceSubagent[] {
  const list = agent?.subagents
  return Array.isArray(list) && list.length > 0 ? list : EMPTY_SUBAGENTS
}

export function readAgentSplitInfo(
  agent: AgentPresenceFields | null | undefined
): PresenceSplitInfo | null {
  const info = agent?.splitInfo
  return info && typeof info.paneCount === 'number' && info.paneCount >= 2 ? info : null
}

function compactRoleLabel(role: string): string {
  const trimmed = role.trim()
  if (!trimmed) {
    return 'Subagent'
  }
  return trimmed.length > 18 ? `${trimmed.slice(0, 17).trimEnd()}…` : trimmed
}

